/**
 * Pure-function condition evaluator and binding-context resolver.
 *
 * Conditions reference attributes via dotted paths against three roots:
 *   - user.*      — every Subject field, including user.attributes.<key>
 *   - resource.*  — every Resource field, including resource.attributes.<key>
 *   - env.*       — every Env field
 *
 * String operands may contain ${path} substitutions resolved from the same
 * binding context; this lets a policy say `resource.ownerId === ${user.id}`
 * for the classic "owner can edit" pattern without bespoke conditions.
 */

import type {
	AttributeValue,
	Condition,
	Env,
	Resource,
	Subject,
} from "./types";

export interface BindingContext {
	user: Subject;
	resource?: Resource;
	env?: Env;
}

/**
 * Resolve a dotted path against the binding context.
 * Returns `undefined` when any segment is missing — the caller decides whether
 * that should fail the condition (default: yes).
 */
export function resolvePath(
	path: string,
	ctx: BindingContext,
): AttributeValue | undefined {
	const parts = path.split(".");
	const root = parts[0];
	if (root === "user") return walk(parts.slice(1), ctx.user);
	if (root === "resource")
		return ctx.resource ? walk(parts.slice(1), ctx.resource) : undefined;
	if (root === "env")
		return ctx.env ? walk(parts.slice(1), ctx.env) : undefined;
	return undefined;
}

function walk(
	parts: readonly string[],
	root: object | undefined,
): AttributeValue | undefined {
	let cur: unknown = root;
	for (const p of parts) {
		if (cur === null || cur === undefined) return undefined;
		if (typeof cur !== "object") return undefined;
		cur = (cur as Record<string, unknown>)[p];
	}
	return cur as AttributeValue | undefined;
}

const SUB_RE = /\$\{([a-zA-Z0-9_.]+)\}/g;

/** Substitute ${path} occurrences inside a string literal. */
export function substituteString(src: string, ctx: BindingContext): string {
	return src.replace(SUB_RE, (_, path: string) => {
		const v = resolvePath(path, ctx);
		if (v === undefined || v === null) return "";
		return String(v);
	});
}

/** Evaluate a condition tree. Missing-attribute on the left fails the leaf. */
export function evaluateCondition(c: Condition, ctx: BindingContext): boolean {
	switch (c.op) {
		case "stringEquals": {
			const left = resolvePath(c.left, ctx);
			if (left === undefined || left === null) return false;
			return String(left) === substituteString(c.right, ctx);
		}
		case "stringIn": {
			const left = resolvePath(c.left, ctx);
			if (left === undefined || left === null) return false;
			const target = String(left);
			return c.right.some((r) => substituteString(r, ctx) === target);
		}
		case "stringStartsWith": {
			const left = resolvePath(c.left, ctx);
			if (left === undefined || left === null) return false;
			return String(left).startsWith(substituteString(c.right, ctx));
		}
		case "numberLessThan": {
			const left = resolvePath(c.left, ctx);
			if (typeof left !== "number") return false;
			return left < c.right;
		}
		case "numberGreaterThan": {
			const left = resolvePath(c.left, ctx);
			if (typeof left !== "number") return false;
			return left > c.right;
		}
		case "bool": {
			const left = resolvePath(c.left, ctx);
			if (typeof left !== "boolean") return false;
			return left === c.right;
		}
		case "attributeExists": {
			const left = resolvePath(c.left, ctx);
			return left !== undefined && left !== null;
		}
		case "not":
			return !evaluateCondition(c.condition, ctx);
		case "anyOf":
			return c.conditions.some((sub) => evaluateCondition(sub, ctx));
		case "allOf":
			return c.conditions.every((sub) => evaluateCondition(sub, ctx));
	}
}

src/access/d1-access-page-store.ts.source:
/**
 * D1 read path for the /ap-admin/access page model. Lives here (filename
 * prefix `d1-`) so the SQL-containment arch rule keeps `.prepare()` confined
 * to the adapter layer.
 */

import type { D1DatabaseLike } from "../d1-database";
import type { RolePolicyRecord, RoleRecord } from "./repository";
import type { Condition, Effect } from "./types";

export interface AccessTabData {
	roles: RoleRecord[];
	userRoleMap: Record<number, string[]>;
	userDirectGrantCounts: Record<number, number>;
	rolePoliciesMap: Record<string, RolePolicyRecord[]>;
	activeAdminCount: number;
}

export async function loadAccessTabDataFromD1(
	db: D1DatabaseLike,
): Promise<AccessTabData> {
	const [
		roleRows,
		assignmentRows,
		grantCountRows,
		rolePolicyRows,
		adminCountRow,
	] = await Promise.all([
		db
			.prepare(
				"SELECT id, name, description, is_system, created_at, updated_at FROM access_roles ORDER BY name",
			)
			.all<{
				id: string;
				name: string;
				description: string;
				is_system: number;
				created_at: string;
				updated_at: string;
			}>(),
		db
			.prepare("SELECT user_id, role_id FROM access_user_roles")
			.all<{ user_id: number; role_id: string }>(),
		db
			.prepare(
				"SELECT user_id, COUNT(*) AS n FROM access_user_policies GROUP BY user_id",
			)
			.all<{ user_id: number; n: number }>(),
		db
			.prepare(
				"SELECT id, role_id, effect, action, condition_json, priority FROM access_role_policies ORDER BY role_id, priority DESC, id",
			)
			.all<{
				id: string;
				role_id: string;
				effect: Effect;
				action: string;
				condition_json: string | null;
				priority: number;
			}>(),
		db
			.prepare(
				"SELECT COUNT(*) AS n FROM admin_users WHERE active = 1 AND is_admin = 1",
			)
			.first<{ n: number }>(),
	]);

	const roles: RoleRecord[] = (roleRows.results ?? []).map((r) => ({
		id: r.id,
		name: r.name,
		description: r.description,
		isSystem: r.is_system === 1,
		createdAt: r.created_at,
		updatedAt: r.updated_at,
	}));

	const userRoleMap: Record<number, string[]> = {};
	for (const row of assignmentRows.results ?? []) {
		const list = userRoleMap[row.user_id] ?? [];
		list.push(row.role_id);
		userRoleMap[row.user_id] = list;
	}

	const userDirectGrantCounts: Record<number, number> = {};
	for (const row of grantCountRows.results ?? []) {
		userDirectGrantCounts[row.user_id] = row.n;
	}

	const rolePoliciesMap: Record<string, RolePolicyRecord[]> = {};
	for (const row of rolePolicyRows.results ?? []) {
		const list = rolePoliciesMap[row.role_id] ?? [];
		let condition: Condition | null = null;
		if (row.condition_json) {
			try {
				condition = JSON.parse(row.condition_json) as Condition;
			} catch {
				condition = null;
			}
		}
		list.push({
			id: row.id,
			roleId: row.role_id,
			effect: row.effect,
			action: row.action,
			condition,
			priority: row.priority,
		});
		rolePoliciesMap[row.role_id] = list;
	}

	return {
		roles,
		userRoleMap,
		userDirectGrantCounts,
		rolePoliciesMap,
		activeAdminCount: adminCountRow?.n ?? 0,
	};
}

