src/admin-action-publish.ts.source:
/**
 * Publish action — triggers a new static production build via the configured deploy hook.
 *
 * Each platform uses a different webhook mechanism:
 * - GitHub Actions: repository_dispatch event
 * - Cloudflare Pages: POST to deploy hook URL
 * - Vercel: POST to deploy hook URL
 * - Netlify: POST to build hook URL
 * - Render: POST to deploy hook URL
 */

import { withLocalStoreFallback } from "./admin-store-dispatch";
import { recordD1Audit } from "./d1-audit";
import type { Actor } from "./persistence-types";

export interface PublishTriggerResult {
	ok: boolean;
	buildId?: string;
	statusUrl?: string;
	error?: string;
}

export type DeployHookType =
	| "cloudflare-pages"
	| "vercel"
	| "netlify"
	| "render"
	| "github-actions";

export interface DeployHookConfig {
	type: DeployHookType;
	/** Environment variables map (from process.env or explicit) */
	env: Record<string, string | undefined>;
}

async function triggerCloudflarePages(
	env: Record<string, string | undefined>,
): Promise<PublishTriggerResult> {
	const hookUrl = env.CF_PAGES_DEPLOY_HOOK_URL;
	if (!hookUrl) {
		return { ok: false, error: "CF_PAGES_DEPLOY_HOOK_URL is not set" };
	}

	const res = await fetch(hookUrl, { method: "POST" });
	if (!res.ok) {
		return {
			ok: false,
			error: `Cloudflare Pages deploy hook returned ${res.status}`,
		};
	}

	const data = (await res.json().catch(() => ({}))) as Record<string, unknown>;
	return {
		ok: true,
		buildId: typeof data.id === "string" ? data.id : undefined,
	};
}

async function triggerVercel(
	env: Record<string, string | undefined>,
): Promise<PublishTriggerResult> {
	const hookUrl = env.VERCEL_DEPLOY_HOOK_URL;
	if (!hookUrl) {
		return { ok: false, error: "VERCEL_DEPLOY_HOOK_URL is not set" };
	}

	const res = await fetch(hookUrl, { method: "POST" });
	if (!res.ok) {
		return { ok: false, error: `Vercel deploy hook returned ${res.status}` };
	}

	const data = (await res.json().catch(() => ({}))) as Record<string, unknown>;
	const job = (data.job ?? {}) as Record<string, unknown>;
	return {
		ok: true,
		buildId: typeof job.id === "string" ? job.id : undefined,
	};
}

async function triggerNetlify(
	env: Record<string, string | undefined>,
): Promise<PublishTriggerResult> {
	const hookUrl = env.NETLIFY_BUILD_HOOK_URL;
	if (!hookUrl) {
		return { ok: false, error: "NETLIFY_BUILD_HOOK_URL is not set" };
	}

	const res = await fetch(hookUrl, { method: "POST", body: "{}" });
	if (!res.ok) {
		return { ok: false, error: `Netlify build hook returned ${res.status}` };
	}

	return { ok: true };
}

async function triggerRender(
	env: Record<string, string | undefined>,
): Promise<PublishTriggerResult> {
	const hookUrl = env.RENDER_DEPLOY_HOOK_URL;
	if (!hookUrl) {
		return { ok: false, error: "RENDER_DEPLOY_HOOK_URL is not set" };
	}

	const res = await fetch(hookUrl, { method: "POST" });
	if (!res.ok) {
		return { ok: false, error: `Render deploy hook returned ${res.status}` };
	}

	return { ok: true };
}

async function triggerGitHubActions(
	env: Record<string, string | undefined>,
): Promise<PublishTriggerResult> {
	const token = env.GH_TOKEN;
	const repo = env.GH_REPO; // format: "owner/repo"

	if (!token || !repo) {
		return {
			ok: false,
			error: "GH_TOKEN and GH_REPO must both be set for GitHub Actions deploy",
		};
	}

	const [owner, repoName] = repo.split("/");
	if (!owner || !repoName) {
		return { ok: false, error: 'GH_REPO must be in "owner/repo" format' };
	}

	const url = `https://api.github.com/repos/${owner}/${repoName}/dispatches`;
	const res = await fetch(url, {
		method: "POST",
		headers: {
			Authorization: `Bearer ${token}`,
			Accept: "application/vnd.github.v3+json",
			"Content-Type": "application/json",
			"X-GitHub-Api-Version": "2022-11-28",
		},
		body: JSON.stringify({ event_type: "astropress-publish" }),
	});

	if (res.status === 204) {
		return { ok: true };
	}

	return { ok: false, error: `GitHub Actions dispatch returned ${res.status}` };
}

/**
 * Trigger a static production build using the configured deploy hook.
 */
export async function triggerPublish(
	config: DeployHookConfig,
): Promise<PublishTriggerResult> {
	switch (config.type) {
		case "cloudflare-pages":
			return triggerCloudflarePages(config.env);
		case "vercel":
			return triggerVercel(config.env);
		case "netlify":
			return triggerNetlify(config.env);
		case "render":
			return triggerRender(config.env);
		case "github-actions":
			return triggerGitHubActions(config.env);
		default:
			return { ok: false, error: `Unknown deploy hook type: ${config.type}` };
	}
}

export interface PublishAuditPayload {
	hookType: DeployHookType;
	result: PublishTriggerResult;
}

/**
 * Persist a trusted audit record describing a publish trigger. The dashboard
 * surfaces the latest record so editors can see the most recent build status
 * without trusting query-string state from the redirect.
 */
export async function recordPublishAudit(
	locals: App.Locals | null | undefined,
	actor: Actor,
	payload: PublishAuditPayload,
): Promise<void> {
	const { hookType, result } = payload;
	const action = result.ok ? "deployment.trigger" : "deployment.failure";
	const summary = result.ok
		? `Triggered ${hookType} publish${result.buildId ? ` (build ${result.buildId})` : ""}.`
		: `${hookType} publish failed: ${result.error ?? "Unknown error"}`;
	const resourceId = result.buildId ?? hookType;

	await withLocalStoreFallback(
		locals,
		async () => {
			await recordD1Audit(
				locals,
				actor,
				action,
				"deployment",
				resourceId,
				summary,
			);
		},
		async (store) => {
			await store.recordAuditEvent({
				userEmail: actor.email,
				action,
				resourceType: "deployment",
				resourceId,
				summary,
			});
		},
	);
}

/**
 * Resolve the deploy hook config from the process environment.
 * Returns null if no deploy hook is configured.
 */
export function resolveDeployHookFromEnv(
	env: Record<string, string | undefined> = process.env as Record<
		string,
		string | undefined
	>,
): DeployHookConfig | null {
	if (env.CF_PAGES_DEPLOY_HOOK_URL) {
		return { type: "cloudflare-pages", env };
	}
	if (env.VERCEL_DEPLOY_HOOK_URL) {
		return { type: "vercel", env };
	}
	if (env.NETLIFY_BUILD_HOOK_URL) {
		return { type: "netlify", env };
	}
	if (env.RENDER_DEPLOY_HOOK_URL) {
		return { type: "render", env };
	}
	if (env.GH_TOKEN && env.GH_REPO) {
		return { type: "github-actions", env };
	}
	return null;
}

src/admin-action-utils.ts.source:
import type { APIRoute } from "astro";
import { logAccessDeny } from "./access/audit-deny.js";
import { getAccessContext } from "./access/index.js";
import { isAuthUserAdmin } from "./platform-contracts.js";
import {
	getRuntimeCsrfToken,
	getRuntimeSessionUser,
} from "./runtime-admin-auth";
import { getLoginSecurityConfig, getRuntimeEnv } from "./runtime-env.js";
import { createLogger } from "./runtime-logger.js";
import {
	createAstropressSecureRedirect,
	isTrustedRequestOrigin,
} from "./security-headers.js";

const logger = createLogger("admin-action");

const LEGACY_SESSION_COOKIE = "ff_admin_session";
const LOCAL_SESSION_COOKIE = "astropress_admin_session";
const SECURE_SESSION_COOKIE = "__Host-astropress_admin_session";

type AdminActionContext = Parameters<NonNullable<APIRoute>>[0];
type AdminSessionUser = NonNullable<
	Awaited<ReturnType<typeof getRuntimeSessionUser>>
>;

type GuardOptions = {
	failurePath: string;
	loginPath?: string;
	requireAdmin?: boolean;
	/**
	 * ABAC action ID required to run this handler. When set, the access
	 * engine evaluates `can(requireAction)` against the session subject;
	 * a deny short-circuits the request with `actionRequiredMessage` (or
	 * the engine's reason). Admins bypass evaluation by definition.
	 */
	requireAction?: string;
	invalidCsrfMessage?: string;
	invalidOriginMessage?: string;
	adminRequiredMessage?: string;
	actionDeniedMessage?: string;
	unexpectedMessage?: string;
};

type GuardResult =
	| { ok: true; sessionUser: AdminSessionUser; formData: FormData }
	| { ok: false; response: Response };

type ActionContext = {
	sessionUser: AdminSessionUser;
	actor: { email: string; role: AdminSessionUser["role"]; name: string };
	formData: FormData;
	locals: AdminActionContext["locals"];
	request: Request;
	fail: (message: string, overridePath?: string) => Response;
	redirect: (location: string, status?: number) => Response;
};

export function actionRedirect(location: string, status = 302): Response {
	return createAstropressSecureRedirect(location, status, {
		forceHsts: location.startsWith("https://"),
	});
}

export function actionErrorRedirect(path: string, message: string): Response {
	const url = new URL(path, "https://astropress.invalid");
	url.searchParams.set("error", "1");
	url.searchParams.set("message", message);
	return actionRedirect(url.pathname + url.search);
}

export async function requireAdminFormAction(
	context: AdminActionContext,
	options: GuardOptions,
): Promise<GuardResult> {
	const secureCookies = getLoginSecurityConfig(context.locals).secureCookies;
	const sessionCookieName = secureCookies
		? SECURE_SESSION_COOKIE
		: LOCAL_SESSION_COOKIE;
	const sessionToken =
		context.cookies.get(sessionCookieName)?.value ??
		context.cookies.get(LEGACY_SESSION_COOKIE)?.value;
	const harnessSessionUser =
		getRuntimeEnv("PLAYWRIGHT_E2E_MODE") === "admin-harness"
			? context.locals.adminUser
			: null;
	const sessionUser =
		(await getRuntimeSessionUser(sessionToken, context.locals)) ??
		harnessSessionUser;

	if (!sessionUser) {
		return {
			ok: false,
			response: actionRedirect(options.loginPath ?? "/ap-admin/login"),
		};
	}

	if (options.requireAdmin && !isAuthUserAdmin(sessionUser)) {
		return {
			ok: false,
			response: actionErrorRedirect(
				options.failurePath,
				options.adminRequiredMessage ??
					"This action requires an admin account.",
			),
		};
	}

	if (options.requireAction) {
		const access = await getAccessContext({ locals: context.locals });
		const decision = access?.can(options.requireAction);
		if (!decision || decision.decision === "deny") {
			if (decision) {
				await logAccessDeny(context.locals, {
					subjectEmail: access?.subject.email ?? sessionUser.email,
					action: options.requireAction,
					decision,
				});
			}
			return {
				ok: false,
				response: actionErrorRedirect(
					options.failurePath,
					options.actionDeniedMessage ??
						decision?.reason ??
						"You do not have permission to perform this action.",
				),
			};
		}
	}

	if (!isTrustedRequestOrigin(context.request)) {
		return {
			ok: false,
			response: actionErrorRedirect(
				options.failurePath,
				options.invalidOriginMessage ?? "Invalid request origin",
			),
		};
	}

	const formData = await context.request.formData();
	const expectedToken =
		(await getRuntimeCsrfToken(sessionToken, context.locals)) ??
		(getRuntimeEnv("PLAYWRIGHT_E2E_MODE") === "admin-harness"
			? (context.locals.csrfToken ?? null)
			: null);
	const submittedToken = String(formData.get("_csrf") ?? "");

	if (!expectedToken || submittedToken !== expectedToken) {
		return {
			ok: false,
			response: actionErrorRedirect(
				options.failurePath,
				options.invalidCsrfMessage ?? "Invalid security token",
			),
		};
	}

	return { ok: true, sessionUser, formData };
}

export async function withAdminFormAction(
	context: AdminActionContext,
	options: GuardOptions,
	run: (action: ActionContext) => Promise<Response> | Response,
): Promise<Response> {
	const actionPath = new URL(context.request.url).pathname;
	try {
		const guarded = await requireAdminFormAction(context, options);
		if (!guarded.ok) {
			return guarded.response;
		}

		const { sessionUser, formData } = guarded;
		logger.info("admin action", {
			path: actionPath,
			actor: sessionUser.email,
			role: sessionUser.role,
		});
		return await run({
			sessionUser,
			actor: {
				email: sessionUser.email,
				role: sessionUser.role,
				name: sessionUser.name,
			},
			formData,
			locals: context.locals,
			request: context.request,
			fail: (message, overridePath) => {
				logger.warn("admin action failed", {
					path: actionPath,
					actor: sessionUser.email,
					message,
				});
				return actionErrorRedirect(
					overridePath ?? options.failurePath,
					message,
				);
			},
			redirect: actionRedirect,
		});
	} catch (err) {
		logger.error("admin action error", {
			path: actionPath,
			error: String(err),
		});
		return actionErrorRedirect(
			options.failurePath,
			options.unexpectedMessage ??
				"The requested change could not be completed. Reload the page and retry the action.",
		);
	}
}

