src/adapters/nhost.ts.source:
import {
	type AstropressHostedApiAdapterOptions,
	createAstropressHostedApiAdapter,
} from "../hosted-api-adapter";
import { createAstropressHostedPlatformAdapter } from "../hosted-platform-adapter";
import type { AstropressInMemoryPlatformAdapterOptions } from "../in-memory-platform-adapter";
import type { AstropressPlatformAdapter } from "../platform-contracts";
import { FULL_STACK_CAPABILITIES } from "./adapter-record-helpers";

export interface AstropressNhostHostedConfig {
	subdomain: string;
	region: string;
	adminSecret: string;
	apiBaseUrl: string;
	previewBaseUrl: string;
}

export type AstropressNhostAdapterOptions = Omit<
	AstropressInMemoryPlatformAdapterOptions,
	"capabilities"
> & {
	backingAdapter?: AstropressPlatformAdapter;
};

/**
 * Creates an Nhost adapter with full-stack capabilities.
 *
 * Nhost provides Postgres, Auth, Storage, and serverless Functions — a complete
 * backend for Astropress. The hosted adapter connects to Astropress functions
 * deployed on Nhost Functions.
 */
export function createAstropressNhostAdapter(
	options: AstropressNhostAdapterOptions = {},
) {
	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "nhost",
		defaultCapabilities: {
			...options.defaultCapabilities,
			...FULL_STACK_CAPABILITIES,
		},
	});
}

export interface AstropressNhostHostedAdapterOptions
	extends AstropressNhostAdapterOptions {
	config?: AstropressNhostHostedConfig;
	env?: Record<string, string | undefined>;
	fetchImpl?: AstropressHostedApiAdapterOptions["fetchImpl"];
}

export function readAstropressNhostHostedConfig(
	env: Record<string, string | undefined> = process.env,
): AstropressNhostHostedConfig {
	const subdomain = env.NHOST_SUBDOMAIN?.trim();
	const region = env.NHOST_REGION?.trim();
	const adminSecret = env.NHOST_ADMIN_SECRET?.trim();

	if (!subdomain || !region || !adminSecret) {
		throw new Error(
			"Nhost hosted config requires NHOST_SUBDOMAIN, NHOST_REGION, and NHOST_ADMIN_SECRET.",
		);
	}

	const base = `https://${subdomain}.${region}.nhost.run`;
	return {
		subdomain,
		region,
		adminSecret,
		apiBaseUrl: `${base}/v1/functions/astropress`,
		previewBaseUrl: `${base}/console`,
	};
}

export function createAstropressNhostHostedAdapter(
	options: AstropressNhostHostedAdapterOptions = {},
) {
	const config = options.config ?? readAstropressNhostHostedConfig(options.env);

	if (
		!options.backingAdapter &&
		!options.content &&
		!options.media &&
		!options.revisions &&
		!options.auth
	) {
		return createAstropressHostedApiAdapter({
			providerName: "nhost",
			apiBaseUrl: config.apiBaseUrl,
			accessToken: config.adminSecret,
			previewBaseUrl: config.previewBaseUrl,
			fetchImpl: options.fetchImpl,
			defaultCapabilities: {
				...options.defaultCapabilities,
				...FULL_STACK_CAPABILITIES,
				hostPanel: options.defaultCapabilities?.hostPanel ?? {
					mode: "link",
					url: config.previewBaseUrl,
					label: "Nhost Console",
				},
			},
		});
	}

	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "nhost",
		defaultCapabilities: {
			...options.defaultCapabilities,
			...FULL_STACK_CAPABILITIES,
		},
		preview: options.preview ?? {
			async create() {
				return {
					url: `${config.previewBaseUrl}/preview`,
				};
			},
		},
	});
}

src/adapters/pocketbase.ts.source:
import {
	type AstropressHostedApiAdapterOptions,
	createAstropressHostedApiAdapter,
} from "../hosted-api-adapter";
import { createAstropressHostedPlatformAdapter } from "../hosted-platform-adapter";
import type { AstropressInMemoryPlatformAdapterOptions } from "../in-memory-platform-adapter";
import type { AstropressPlatformAdapter } from "../platform-contracts";
import { FULL_STACK_CAPABILITIES } from "./adapter-record-helpers";

export interface AstropressPocketbaseHostedConfig {
	url: string;
	email: string;
	password: string;
	apiBaseUrl: string;
	previewBaseUrl: string;
}

export type AstropressPocketbaseAdapterOptions = Omit<
	AstropressInMemoryPlatformAdapterOptions,
	"capabilities"
> & {
	backingAdapter?: AstropressPlatformAdapter;
};

export function createAstropressPocketbaseAdapter(
	options: AstropressPocketbaseAdapterOptions = {},
) {
	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "pocketbase",
		defaultCapabilities: {
			...options.defaultCapabilities,
			...FULL_STACK_CAPABILITIES,
		},
	});
}

export interface AstropressPocketbaseHostedAdapterOptions
	extends AstropressPocketbaseAdapterOptions {
	config?: AstropressPocketbaseHostedConfig;
	env?: Record<string, string | undefined>;
	fetchImpl?: AstropressHostedApiAdapterOptions["fetchImpl"];
}

export function readAstropressPocketbaseHostedConfig(
	env: Record<string, string | undefined> = process.env,
): AstropressPocketbaseHostedConfig {
	const url = env.POCKETBASE_URL?.trim();
	const email = env.POCKETBASE_EMAIL?.trim();
	const password = env.POCKETBASE_PASSWORD?.trim();

	if (!url || !email || !password) {
		throw new Error(
			"PocketBase hosted config requires POCKETBASE_URL, POCKETBASE_EMAIL, and POCKETBASE_PASSWORD.",
		);
	}

	return {
		url,
		email,
		password,
		apiBaseUrl: `${url.replace(/\/$/, "")}/api/astropress`,
		previewBaseUrl: url.replace(/\/$/, ""),
	};
}

export function createAstropressPocketbaseHostedAdapter(
	options: AstropressPocketbaseHostedAdapterOptions = {},
) {
	const config =
		options.config ?? readAstropressPocketbaseHostedConfig(options.env);
	if (
		!options.backingAdapter &&
		!options.content &&
		!options.media &&
		!options.revisions &&
		!options.auth
	) {
		return createAstropressHostedApiAdapter({
			providerName: "pocketbase",
			apiBaseUrl: config.apiBaseUrl,
			accessToken: `${config.email}:${config.password}`,
			previewBaseUrl: `${config.previewBaseUrl}/preview`,
			fetchImpl: options.fetchImpl,
			defaultCapabilities: {
				...options.defaultCapabilities,
				...FULL_STACK_CAPABILITIES,
			},
		});
	}

	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "pocketbase",
		defaultCapabilities: {
			...options.defaultCapabilities,
			...FULL_STACK_CAPABILITIES,
		},
		preview: options.preview ?? {
			async create() {
				return {
					url: `${config.previewBaseUrl}/preview`,
				};
			},
		},
	});
}

