import type {
	AstropressPlatformAdapter,
	MediaAssetRecord,
	RevisionRecord,
} from "../platform-contracts";
import { normalizeProviderCapabilities } from "../platform-contracts";
import { registerHealthCheck } from "../runtime-health";
import { createAstropressSqliteAdminRuntime } from "../sqlite-admin-runtime";
import {
	type AstropressSqliteSeedToolkit,
	createDefaultAstropressSqliteSeedToolkit,
} from "../sqlite-bootstrap";
import {
	appendSqliteRevision,
	deleteSqliteContentRecord,
	getSqliteMedia,
	listSqliteContentRecords,
	putSqliteMedia,
	saveSqliteContentRecord,
} from "./sqlite-helpers.js";

export interface AstropressSqliteAdapterOptions {
	dbPath?: string;
	workspaceRoot?: string;
	seedToolkit?: AstropressSqliteSeedToolkit;
}

export function createAstropressSqliteAdapter(
	options: AstropressSqliteAdapterOptions = {},
): AstropressPlatformAdapter {
	const seedToolkit =
		options.seedToolkit ?? createDefaultAstropressSqliteSeedToolkit();
	const workspaceRoot = options.workspaceRoot ?? process.cwd();
	const dbPath =
		options.dbPath ?? seedToolkit.getDefaultAdminDbPath(workspaceRoot);
	let seeded = false;
	let database: ReturnType<
		AstropressSqliteSeedToolkit["openSeedDatabase"]
	> | null = null;

	function ensureDatabase() {
		if (!seeded) {
			seedToolkit.seedDatabase({ dbPath, workspaceRoot });
			seeded = true;
		}
		if (!database) {
			database = seedToolkit.openSeedDatabase(dbPath);
		}
		return database;
	}

	registerHealthCheck(() => {
		ensureDatabase().prepare("SELECT 1").get();
	});

	const actor = {
		email: "admin@example.com",
		role: "admin" as const,
		name: "Astropress SQLite",
	};
	const runtime = createAstropressSqliteAdminRuntime({
		getDatabase: ensureDatabase,
	});

	return {
		capabilities: normalizeProviderCapabilities({
			name: "sqlite",
			hostedAdmin: true,
			previewEnvironments: true,
			serverRuntime: true,
			database: true,
			objectStorage: false,
			gitSync: true,
		}),
		auth: {
			async signIn(email, password) {
				const user = await runtime.authenticatePersistedAdminUser(
					email,
					password,
				);
				if (!user) return null;
				const sessionId = runtime.sqliteAdminStore.auth.createSession(user, {});
				runtime.sqliteAdminStore.auth.recordSuccessfulLogin(user);
				return {
					id: sessionId,
					email: user.email,
					isAdmin: user.role === "admin",
				};
			},
			async signOut(sessionId) {
				const user = runtime.sqliteAdminStore.auth.getSessionUser(sessionId);
				runtime.sqliteAdminStore.auth.revokeSession(sessionId);
				if (user) runtime.sqliteAdminStore.auth.recordLogout(user);
			},
			async getSession(sessionId) {
				const user = runtime.sqliteAdminStore.auth.getSessionUser(sessionId);
				return user
					? {
							id: sessionId,
							email: user.email,
							isAdmin: user.role === "admin",
						}
					: null;
			},
		},
		content: {
			async list(kind) {
				return listSqliteContentRecords(runtime, ensureDatabase, kind);
			},
			async get(id) {
				const normalizedId = id.trim();
				if (!normalizedId) return null;
				const all = await this.list();
				return (
					all.find(
						(record) =>
							record.id === normalizedId || record.slug === normalizedId,
					) ?? null
				);
			},
			async save(record) {
				return saveSqliteContentRecord(runtime, record, actor);
			},
			async delete(id) {
				const existing = await this.get(id);
				if (!existing) return;
				deleteSqliteContentRecord(runtime, existing, actor);
			},
		},
		media: {
			async put(asset: MediaAssetRecord) {
				putSqliteMedia(ensureDatabase, asset, actor.email);
				return asset;
			},
			async get(id) {
				return getSqliteMedia(runtime, id);
			},
			async delete(id) {
				runtime.sqliteAdminStore.media.deleteMediaAsset(id, actor);
			},
		},
		revisions: {
			async list(recordId) {
				return (
					runtime.sqliteAdminStore.content.getContentRevisions(recordId) ?? []
				).map(
					(revision): RevisionRecord => ({
						id: revision.id,
						recordId: revision.slug,
						createdAt: revision.createdAt,
						actorId: revision.createdBy ?? null,
						summary: revision.revisionNote ?? null,
						snapshot: revision as unknown as Record<string, unknown>,
					}),
				);
			},
			async append(revision) {
				appendSqliteRevision(
					ensureDatabase,
					revision as {
						id: string;
						recordId: string;
						snapshot: Record<string, unknown>;
						summary?: string | null;
						createdAt: string;
						actorId?: string | null;
					},
					actor.email,
				);
				return revision;
			},
		},
	};
}

src/adapters/supabase.ts.source:
import {
	type AstropressHostedApiAdapterOptions,
	createAstropressHostedApiAdapter,
} from "../hosted-api-adapter";
import { createAstropressHostedPlatformAdapter } from "../hosted-platform-adapter";
import type { AstropressInMemoryPlatformAdapterOptions } from "../in-memory-platform-adapter";
import type { AstropressPlatformAdapter } from "../platform-contracts";
import { FULL_STACK_CAPABILITIES } from "./adapter-record-helpers";

export interface AstropressSupabaseHostedConfig {
	url: string;
	serviceRoleKey: string;
	apiBaseUrl: string;
}

export type AstropressSupabaseAdapterOptions = Omit<
	AstropressInMemoryPlatformAdapterOptions,
	"capabilities"
> & {
	backingAdapter?: AstropressPlatformAdapter;
};

export function createAstropressSupabaseAdapter(
	options: AstropressSupabaseAdapterOptions = {},
) {
	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "supabase",
	});
}

export interface AstropressSupabaseHostedAdapterOptions
	extends AstropressSupabaseAdapterOptions {
	config?: AstropressSupabaseHostedConfig;
	env?: Record<string, string | undefined>;
	fetchImpl?: AstropressHostedApiAdapterOptions["fetchImpl"];
}

export function readAstropressSupabaseHostedConfig(
	env: Record<string, string | undefined> = process.env,
): AstropressSupabaseHostedConfig {
	const url = env.SUPABASE_URL?.trim();
	const serviceRoleKey = env.SUPABASE_SERVICE_ROLE_KEY?.trim();

	if (!url || !serviceRoleKey) {
		throw new Error(
			"Supabase hosted config requires SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY.",
		);
	}

	return {
		url,
		serviceRoleKey,
		apiBaseUrl: `${url.replace(/\/$/, "")}/functions/v1/astropress`,
	};
}

export function createAstropressSupabaseHostedAdapter(
	options: AstropressSupabaseHostedAdapterOptions = {},
) {
	const config =
		options.config ?? readAstropressSupabaseHostedConfig(options.env);
	if (
		!options.backingAdapter &&
		!options.content &&
		!options.media &&
		!options.revisions &&
		!options.auth
	) {
		return createAstropressHostedApiAdapter({
			providerName: "supabase",
			apiBaseUrl: config.apiBaseUrl,
			accessToken: config.serviceRoleKey,
			previewBaseUrl: `${config.url.replace(/\/$/, "")}/preview`,
			fetchImpl: options.fetchImpl,
			defaultCapabilities: {
				...options.defaultCapabilities,
				...FULL_STACK_CAPABILITIES,
			},
		});
	}
	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "supabase",
		defaultCapabilities: {
			...options.defaultCapabilities,
			...FULL_STACK_CAPABILITIES,
		},
		preview: options.preview ?? {
			async create() {
				return {
					url: `${config.url.replace(/\/$/, "")}/preview`,
				};
			},
		},
	});
}

