import { createAstropressHostedPlatformAdapter } from "../hosted-platform-adapter";
import type { AstropressInMemoryPlatformAdapterOptions } from "../in-memory-platform-adapter";
import type { AstropressPlatformAdapter } from "../platform-contracts";

export interface AstropressTursoHostedConfig {
	databaseUrl: string;
	authToken: string;
	apiBaseUrl: string;
}

export type AstropressTursoAdapterOptions = Omit<
	AstropressInMemoryPlatformAdapterOptions,
	"capabilities"
> & {
	backingAdapter?: AstropressPlatformAdapter;
};

/**
 * Creates a Turso (LibSQL) adapter with database-only capabilities.
 *
 * Turso is a distributed SQLite-wire database — it does not provide object storage,
 * a hosted admin panel, or preview environments. Pair Turso with a server-side host
 * (Vercel, Netlify, Fly.io) for the app and a storage service for media uploads.
 */
export function createAstropressTursoAdapter(
	options: AstropressTursoAdapterOptions = {},
) {
	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "turso",
		defaultCapabilities: {
			hostedAdmin: false,
			previewEnvironments: false,
			serverRuntime: true,
			database: true,
			objectStorage: false,
			gitSync: false,
			...options.defaultCapabilities,
		},
	});
}

export interface AstropressTursoHostedAdapterOptions
	extends AstropressTursoAdapterOptions {
	config?: AstropressTursoHostedConfig;
	env?: Record<string, string | undefined>;
}

export function readAstropressTursoHostedConfig(
	env: Record<string, string | undefined> = process.env,
): AstropressTursoHostedConfig {
	const databaseUrl = env.TURSO_DATABASE_URL?.trim();

	if (!databaseUrl) {
		throw new Error(
			"Turso hosted config requires TURSO_DATABASE_URL (your Turso database URL).",
		);
	}

	if (
		!databaseUrl.startsWith("libsql://") &&
		!databaseUrl.startsWith("https://")
	) {
		throw new Error(
			"Turso TURSO_DATABASE_URL must be a libsql:// or https:// connection string.",
		);
	}

	const authToken = env.TURSO_AUTH_TOKEN?.trim();

	if (!authToken) {
		throw new Error("Turso hosted config requires TURSO_AUTH_TOKEN.");
	}

	const dbName =
		databaseUrl
			.replace(/^libsql:\/\//, "")
			.replace(/^https:\/\//, "")
			.split(".")[0] ?? "";
	const apiBaseUrl = `https://app.turso.tech/databases/${dbName}`;

	return { databaseUrl, authToken, apiBaseUrl };
}

export function createAstropressTursoHostedAdapter(
	options: AstropressTursoHostedAdapterOptions = {},
) {
	const config = options.config ?? readAstropressTursoHostedConfig(options.env);

	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "turso",
		defaultCapabilities: {
			...options.defaultCapabilities,
			hostedAdmin: false,
			previewEnvironments: false,
			serverRuntime: true,
			database: true,
			objectStorage: false,
			gitSync: false,
			hostPanel: options.defaultCapabilities?.hostPanel ?? {
				mode: "link",
				url: config.apiBaseUrl,
				label: "Turso Dashboard",
			},
		},
	});
}

src/admin-action-mailchimp-import.ts.source:
import type { APIContext } from "astro";
import { getNewsletterConfig } from "./runtime-env";
import { createLogger } from "./runtime-logger";

const logger = createLogger("MailchimpImport");

export interface MailchimpImportResult {
	ok: boolean;
	imported: number;
	skipped: number;
	error?: string;
}

/**
 * Parses a Mailchimp audience CSV export.
 * Required column: "Email Address"
 * Optional columns: "First Name", "Last Name"
 * Returns cleaned subscriber records ready for Listmonk bulk import.
 */
function parseMailchimpCsv(
	csv: string,
): Array<{ email: string; name: string }> {
	const lines = csv.trim().split(/\r?\n/);
	if (lines.length < 2) return [];

	const headers = lines[0]
		?.split(",")
		.map((h) => h.replace(/^"|"$/g, "").trim());
	const emailIdx = headers.findIndex(
		(h) => h.toLowerCase() === "email address",
	);
	const firstIdx = headers.findIndex((h) => h.toLowerCase() === "first name");
	const lastIdx = headers.findIndex((h) => h.toLowerCase() === "last name");

	if (emailIdx === -1) return [];

	const records: Array<{ email: string; name: string }> = [];
	for (let i = 1; i < lines.length; i++) {
		const cols = lines[i]
			?.split(",")
			.map((c) => c.replace(/^"|"$/g, "").trim());
		const email = cols[emailIdx] ?? "";
		if (!email || !email.includes("@")) continue;
		const first = firstIdx !== -1 ? (cols[firstIdx] ?? "") : "";
		const last = lastIdx !== -1 ? (cols[lastIdx] ?? "") : "";
		const name = [first, last].filter(Boolean).join(" ") || email;
		records.push({ email, name });
	}
	return records;
}

export async function runMailchimpImport(
	csvText: string,
	locals: APIContext["locals"],
): Promise<MailchimpImportResult> {
	const cfg = getNewsletterConfig(locals);

	if (
		cfg.mode !== "listmonk" ||
		!cfg.listmonkApiUrl ||
		!cfg.listmonkApiUsername ||
		!cfg.listmonkApiPassword ||
		!cfg.listmonkListId
	) {
		return {
			ok: false,
			imported: 0,
			skipped: 0,
			error:
				"Listmonk is not configured. Set NEWSLETTER_DELIVERY, LISTMONK_API_URL, LISTMONK_API_USERNAME, LISTMONK_API_PASSWORD, and LISTMONK_LIST_ID.",
		};
	}

	const records = parseMailchimpCsv(csvText);
	if (records.length === 0) {
		return {
			ok: false,
			imported: 0,
			skipped: 0,
			error:
				'No valid subscriber rows found. Make sure the file has an "Email Address" column.',
		};
	}

	const auth = btoa(`${cfg.listmonkApiUsername}:${cfg.listmonkApiPassword}`);
	const listId = Number(cfg.listmonkListId);

	// Listmonk bulk import: POST /api/subscribers/import with CSV records string
	const csvBody = [
		"email,name",
		...records.map((r) => `${r.email},${r.name}`),
	].join("\n");

	try {
		const res = await fetch(`${cfg.listmonkApiUrl}/api/subscribers/import`, {
			method: "POST",
			headers: {
				Authorization: `Basic ${auth}`,
				"Content-Type": "application/json",
			},
			body: JSON.stringify({
				mode: "subscribe",
				subscription_status: "confirmed",
				delims: ",",
				lists: [listId],
				records: csvBody,
			}),
		});

		if (!res.ok) {
			const body = await res.text();
			logger.error("Listmonk bulk import error", { status: res.status, body });
			return {
				ok: false,
				imported: 0,
				skipped: 0,
				error: `Listmonk returned ${res.status}. Check your credentials.`,
			};
		}

		logger.info("Mailchimp import completed", { count: records.length });
		return { ok: true, imported: records.length, skipped: 0 };
	} catch (err) {
		logger.error("Mailchimp import network error", { err });
		return {
			ok: false,
			imported: 0,
			skipped: 0,
			error: "Network error reaching Listmonk. Check LISTMONK_API_URL.",
		};
	}
}

src/admin-action-user-purge.ts.source:
/**
 * User data purge action (GDPR right of erasure).
 *
 * Admin-only. Accepts a JSON body `{ "email": "..." }` and:
 * - Revokes all active sessions for the user
 * - Anonymises audit log entries (replaces actor email with "[deleted]")
 * - Deletes comments by that email
 * - Deletes contact form submissions by that email
 * - Suspends the admin user account (or deletes it if requested)
 *
 * Returns a JSON export of all deleted/anonymised records for the operator's
 * own data-subject-request records.
 */

import { withLocalStoreFallback } from "./admin-store-dispatch";
import { createD1PurgeOps } from "./d1-purge";

export interface UserPurgeResult {
	ok: boolean;
	email: string;
	revokedSessions: number;
	anonymisedAuditEvents: number;
	deletedComments: number;
	deletedContactSubmissions: number;
	adminUserAction: "suspended" | "deleted" | "not_found";
	error?: string;
}

/**
 * Purge all personal data for a given email address.
 *
 * Dispatches to D1 (Cloudflare) or SQLite (local) based on the request context.
 *
 * @param email   The email address of the data subject.
 * @param locals  Astro App.Locals (used to access the database binding).
 * @param options Optional flags: `{ deleteAccount: true }` to permanently
 *                delete the admin user record instead of suspending it.
 */
export async function purgeUserData(
	email: string,
	locals: App.Locals,
	options: { deleteAccount?: boolean } = {},
): Promise<UserPurgeResult> {
	if (!email || !email.includes("@")) {
		return {
			ok: false,
			email,
			revokedSessions: 0,
			anonymisedAuditEvents: 0,
			deletedComments: 0,
			deletedContactSubmissions: 0,
			adminUserAction: "not_found",
			error: "Invalid email address",
		};
	}

	return withLocalStoreFallback(
		locals,
		async (db) => createD1PurgeOps(db).purgeUserData(email, options),
		async (store) => {
			if (store.purgeUserData) {
				return store.purgeUserData(email, options);
			}
			// Fallback: return zero counts if local store doesn't wire purge ops
			return {
				ok: true,
				email,
				revokedSessions: 0,
				anonymisedAuditEvents: 0,
				deletedComments: 0,
				deletedContactSubmissions: 0,
				adminUserAction: (options.deleteAccount
					? "deleted"
					: "suspended") as UserPurgeResult["adminUserAction"],
			};
		},
	);
}

