import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";

import { resolveAstropressProjectEnvContract } from "./project-env.js";

export interface AstropressContentServicesBootstrapInput {
	workspaceRoot: string;
	env?: Record<string, string | undefined>;
}

export interface AstropressContentServicesVerifyInput {
	workspaceRoot: string;
	env?: Record<string, string | undefined>;
}

export interface AstropressContentServicesOperationReport {
	contentServices: string;
	supportLevel: "configured" | "missing-config" | "static";
	serviceOrigin: string | null;
	requiredEnvKeys: string[];
	missingEnvKeys: string[];
	manifestFile?: string;
}

function requiredEnvKeysForContentServices(contentServices: string) {
	switch (contentServices) {
		case "cloudflare":
			return [
				"ASTROPRESS_SERVICE_ORIGIN",
				"CLOUDFLARE_ACCOUNT_ID",
				"CLOUDFLARE_API_TOKEN",
			];
		case "supabase":
			return [
				"ASTROPRESS_SERVICE_ORIGIN",
				"SUPABASE_URL",
				"SUPABASE_SERVICE_ROLE_KEY",
			];
		case "appwrite":
			return [
				"ASTROPRESS_SERVICE_ORIGIN",
				"APPWRITE_ENDPOINT",
				"APPWRITE_PROJECT_ID",
				"APPWRITE_API_KEY",
			];
		case "pocketbase":
			return [
				"ASTROPRESS_SERVICE_ORIGIN",
				"POCKETBASE_URL",
				"POCKETBASE_EMAIL",
				"POCKETBASE_PASSWORD",
			];
		case "nhost":
			return [
				"ASTROPRESS_SERVICE_ORIGIN",
				"NHOST_SUBDOMAIN",
				"NHOST_REGION",
				"NHOST_ADMIN_SECRET",
			];
		case "neon":
			return ["ASTROPRESS_SERVICE_ORIGIN", "NEON_DATABASE_URL"];
		case "turso":
			return [
				"ASTROPRESS_SERVICE_ORIGIN",
				"TURSO_DATABASE_URL",
				"TURSO_AUTH_TOKEN",
			];
		default:
			return [];
	}
}

function missingEnvKeysForContentServices(
	contentServices: string,
	env: Record<string, string | undefined>,
	requiredEnvKeys: string[],
): string[] {
	if (contentServices !== "neon") {
		return requiredEnvKeys.filter((key) => !env[key]?.trim());
	}

	return requiredEnvKeys.filter((key) => {
		if (key !== "NEON_DATABASE_URL") {
			return !env[key]?.trim();
		}
		return !(env.NEON_DATABASE_URL?.trim() || env.DATABASE_URL?.trim());
	});
}

function createOperationReport(
	contentServices: string,
	env: Record<string, string | undefined>,
	manifestFile?: string,
): AstropressContentServicesOperationReport {
	const contract = resolveAstropressProjectEnvContract(env);
	const requiredEnvKeys = requiredEnvKeysForContentServices(contentServices);
	const missingEnvKeys = missingEnvKeysForContentServices(
		contentServices,
		env,
		requiredEnvKeys,
	);
	return {
		contentServices,
		supportLevel:
			contentServices === "none"
				? "static"
				: missingEnvKeys.length === 0
					? "configured"
					: "missing-config",
		serviceOrigin: contract.serviceOrigin,
		requiredEnvKeys,
		missingEnvKeys,
		manifestFile,
	};
}

export async function bootstrapAstropressContentServices(
	input: AstropressContentServicesBootstrapInput,
): Promise<AstropressContentServicesOperationReport> {
	const env = input.env ?? process.env;
	const contract = resolveAstropressProjectEnvContract(env);
	const workspaceRoot = resolve(input.workspaceRoot);
	const manifestFile = join(
		workspaceRoot,
		".astropress",
		"services",
		`${contract.contentServices}.json`,
	);

	await mkdir(dirname(manifestFile), { recursive: true });

	const report = createOperationReport(
		contract.contentServices,
		env,
		manifestFile,
	);
	const manifest = {
		generatedAt: new Date().toISOString(),
		contentServices: contract.contentServices,
		serviceOrigin: contract.serviceOrigin,
		requiredEnvKeys: report.requiredEnvKeys,
		missingEnvKeys: report.missingEnvKeys,
		status: report.supportLevel,
	};
	await writeFile(
		manifestFile,
		`${JSON.stringify(manifest, null, 2)}\n`,
		"utf8",
	);

	return report;
}

export async function verifyAstropressContentServices(
	input: AstropressContentServicesVerifyInput,
): Promise<AstropressContentServicesOperationReport> {
	const env = input.env ?? process.env;
	const contract = resolveAstropressProjectEnvContract(env);
	const workspaceRoot = resolve(input.workspaceRoot);
	const manifestFile = join(
		workspaceRoot,
		".astropress",
		"services",
		`${contract.contentServices}.json`,
	);

	try {
		await readFile(manifestFile, "utf8");
		return createOperationReport(contract.contentServices, env, manifestFile);
	} catch {
		return createOperationReport(contract.contentServices, env);
	}
}

src/crypto-primitives.ts.source:
import { argon2id } from "@noble/hashes/argon2.js";
import { kmac256 } from "@noble/hashes/sha3-addons.js";
import { ml_dsa65 } from "@noble/post-quantum/ml-dsa.js";

const textEncoder = new TextEncoder();

const ARGON2_PREFIX = "v3:argon2id";
const ARGON2_MEMORY_KIB = 19_456;
const ARGON2_ITERATIONS = 2;
const ARGON2_LANES = 1;
const ARGON2_HASH_LENGTH = 32;
const DEFAULT_SALT_LENGTH = 16;
const DEFAULT_KMAC_LENGTH = 32;

function encodeUtf8(value: string) {
	return textEncoder.encode(value);
}

function base64ToBytes(value: string) {
	const binary = atob(value);
	const bytes = new Uint8Array(binary.length);
	for (let index = 0; index < binary.length; index += 1) {
		bytes[index] = binary.charCodeAt(index);
	}
	return bytes;
}

export function bytesToBase64(bytes: Uint8Array) {
	let binary = "";
	for (const byte of bytes) {
		binary += String.fromCharCode(byte);
	}
	return btoa(binary);
}

export function bytesToHex(bytes: Uint8Array) {
	return Array.from(bytes)
		.map((byte) => byte.toString(16).padStart(2, "0"))
		.join("");
}

export function constantTimeEqual(left: Uint8Array, right: Uint8Array) {
	if (left.length !== right.length) {
		return false;
	}

	let mismatch = 0;
	for (let index = 0; index < left.length; index += 1) {
		mismatch |= left[index] ^ right[index];
	}
	return mismatch === 0;
}

function randomBytes(length: number) {
	return crypto.getRandomValues(new Uint8Array(length));
}

function kmacContext(purpose: string) {
	return encodeUtf8(`astropress:${purpose}`);
}

export function createKmacDigest(
	value: string,
	secret: string,
	purpose: string,
	dkLen = DEFAULT_KMAC_LENGTH,
) {
	const digest = kmac256(encodeUtf8(secret), encodeUtf8(value), {
		dkLen,
		personalization: kmacContext(purpose),
	});
	return bytesToHex(digest);
}

export function hashPasswordArgon2id(
	password: string,
	options: {
		saltLength?: number;
		iterations?: number;
		memoryKiB?: number;
		parallelism?: number;
	} = {},
) {
	const salt = randomBytes(options.saltLength ?? DEFAULT_SALT_LENGTH);
	const iterations = options.iterations ?? ARGON2_ITERATIONS;
	const memoryKiB = options.memoryKiB ?? ARGON2_MEMORY_KIB;
	const parallelism = options.parallelism ?? ARGON2_LANES;
	const digest = argon2id(encodeUtf8(password), salt, {
		t: iterations,
		m: memoryKiB,
		p: parallelism,
		dkLen: ARGON2_HASH_LENGTH,
	});
	return `${ARGON2_PREFIX}$${iterations}$${memoryKiB}$${parallelism}$${bytesToBase64(salt)}$${bytesToBase64(digest)}`;
}

export function isArgon2idHash(storedHash: string) {
	return storedHash.startsWith(`${ARGON2_PREFIX}$`);
}

export function verifyArgon2idPassword(password: string, storedHash: string) {
	try {
		if (!isArgon2idHash(storedHash)) {
			return false;
		}

		const [
			prefix,
			iterationsText,
			memoryText,
			parallelismText,
			saltBase64,
			hashBase64,
		] = storedHash.split("$");
		if (
			prefix !== ARGON2_PREFIX ||
			!iterationsText ||
			!memoryText ||
			!parallelismText ||
			!saltBase64 ||
			!hashBase64
		) {
			return false;
		}

		const iterations = Number.parseInt(iterationsText, 10);
		const memoryKiB = Number.parseInt(memoryText, 10);
		const parallelism = Number.parseInt(parallelismText, 10);
		if (!iterations || !memoryKiB || !parallelism) {
			return false;
		}

		const salt = base64ToBytes(saltBase64);
		const expected = base64ToBytes(hashBase64);
		const actual = argon2id(encodeUtf8(password), salt, {
			t: iterations,
			m: memoryKiB,
			p: parallelism,
			dkLen: expected.length,
		});
		return constantTimeEqual(actual, expected);
	} catch {
		return false;
	}
}

export interface MlDsaVerificationKey {
	algorithm: "ML-DSA-65";
	keyId: string;
	publicKey: string;
	encoding: "base64";
}

export function createMlDsaKeyPair(keyId: string, seed = randomBytes(32)) {
	const keys = ml_dsa65.keygen(seed);
	return {
		keyId,
		publicKey: keys.publicKey,
		secretKey: keys.secretKey,
		verification: {
			algorithm: "ML-DSA-65" as const,
			keyId,
			publicKey: bytesToBase64(keys.publicKey),
			encoding: "base64" as const,
		},
	};
}

export function signMlDsaMessage(message: string, secretKeyBase64: string) {
	return bytesToBase64(
		ml_dsa65.sign(encodeUtf8(message), base64ToBytes(secretKeyBase64)),
	);
}

export function verifyMlDsaMessage(
	message: string,
	signatureBase64: string,
	publicKeyBase64: string,
) {
	return ml_dsa65.verify(
		base64ToBytes(signatureBase64),
		encodeUtf8(message),
		base64ToBytes(publicKeyBase64),
	);
}

export function secretKeyToBase64(secretKey: Uint8Array) {
	return bytesToBase64(secretKey);
}

