import type { D1DatabaseLike } from "./d1-database";
import {
	createD1ContentReadPart,
	createD1SchedulingPart,
} from "./d1-store-content";
import {
	createD1OperationsMutationPart,
	createD1OperationsReadPart,
} from "./d1-store-operations";
import {
	createD1AuthorsMutationPart,
	createD1AuthorsReadPart,
	createD1TaxonomiesMutationPart,
	createD1TaxonomiesReadPart,
} from "./d1-store-taxonomies";
import type {
	AuditEvent,
	AuthorRecord,
	CommentRecord,
	CommentStatus,
	ContactSubmission,
	ContentOverride,
	ContentRecord,
	ContentRevision,
	ManagedAdminUser,
	MediaAsset,
	RecordAuditEventInput,
	RedirectRule,
	TaxonomyTerm,
	TestimonialStatus,
	TestimonialSubmission,
	TestimonialSubmissionInput,
} from "./persistence-types";
import type { SiteSettings } from "./site-settings";

// Re-export types so existing consumers don't need to change imports
export type {
	AuthorRecord,
	AuditEvent,
	CommentRecord,
	CommentStatus,
	ContactSubmission,
	ContentOverride,
	ContentRecord,
	ContentRevision,
	ManagedAdminUser,
	MediaAsset,
	RedirectRule,
	TaxonomyTerm,
	SiteSettings,
	TestimonialSubmission,
	TestimonialSubmissionInput,
	TestimonialStatus,
};

export interface D1AdminReadStore {
	audit: {
		getAuditEvents(): Promise<AuditEvent[]>;
		recordAuditEvent(input: RecordAuditEventInput): Promise<void>;
	};
	users: {
		listAdminUsers(): Promise<ManagedAdminUser[]>;
	};
	authors: {
		listAuthors(): Promise<AuthorRecord[]>;
	};
	taxonomies: {
		listCategories(): Promise<TaxonomyTerm[]>;
		listTags(): Promise<TaxonomyTerm[]>;
	};
	redirects: {
		getRedirectRules(): Promise<RedirectRule[]>;
	};
	comments: {
		getComments(): Promise<CommentRecord[]>;
		getApprovedCommentsForRoute(route: string): Promise<CommentRecord[]>;
	};
	content: {
		listContentStates(): Promise<ContentRecord[]>;
		getContentState(slug: string): Promise<ContentRecord | null>;
		getContentRevisions(slug: string): Promise<ContentRevision[] | null>;
		schedulePublish(id: string, scheduledAt: string): Promise<void>;
		listScheduled(): Promise<
			Array<{ id: string; slug: string; title: string; scheduledAt: string }>
		>;
		cancelScheduledPublish(id: string): Promise<void>;
		runScheduledPublishes(): Promise<number>;
	};
	submissions: {
		getContactSubmissions(): Promise<ContactSubmission[]>;
		getTestimonials(
			status?: TestimonialStatus,
		): Promise<TestimonialSubmission[]>;
	};
	translations: {
		getEffectiveTranslationState(
			route: string,
			fallback?: string,
		): Promise<string>;
	};
	settings: {
		getSettings(): Promise<SiteSettings>;
	};
	rateLimits: {
		checkRateLimit(
			key: string,
			max: number,
			windowMs: number,
		): Promise<boolean>;
		peekRateLimit(key: string, max: number, windowMs: number): Promise<boolean>;
		recordFailedAttempt(
			key: string,
			max: number,
			windowMs: number,
		): Promise<void>;
	};
	media: {
		listMediaAssets(): Promise<MediaAsset[]>;
	};
}

export interface D1AdminMutationStore {
	authors: {
		createAuthor(input: { name: string; slug?: string; bio?: string }): Promise<
			{ ok: true } | { ok: false; error: string }
		>;
		updateAuthor(input: {
			id: number;
			name: string;
			slug?: string;
			bio?: string;
		}): Promise<{ ok: true } | { ok: false; error: string }>;
		deleteAuthor(
			id: number,
		): Promise<{ ok: true } | { ok: false; error: string }>;
	};
	taxonomies: {
		createCategory(input: {
			name: string;
			slug?: string;
			description?: string;
		}): Promise<{ ok: true } | { ok: false; error: string }>;
		updateCategory(input: {
			id: number;
			name: string;
			slug?: string;
			description?: string;
		}): Promise<{ ok: true } | { ok: false; error: string }>;
		deleteCategory(
			id: number,
		): Promise<{ ok: true } | { ok: false; error: string }>;
		createTag(input: {
			name: string;
			slug?: string;
			description?: string;
		}): Promise<{ ok: true } | { ok: false; error: string }>;
		updateTag(input: {
			id: number;
			name: string;
			slug?: string;
			description?: string;
		}): Promise<{ ok: true } | { ok: false; error: string }>;
		deleteTag(id: number): Promise<{ ok: true } | { ok: false; error: string }>;
	};
	submissions: {
		submitContact(input: {
			name: string;
			email: string;
			message: string;
			submittedAt: string;
		}): Promise<{
			ok: true;
			submission: ContactSubmission;
		}>;
		submitTestimonial(
			input: TestimonialSubmissionInput,
		): Promise<{ ok: true; id: string }>;
		moderateTestimonial(
			id: string,
			status: TestimonialStatus,
			actorEmail: string,
		): Promise<{ ok: true } | { ok: false; error: string }>;
	};
	comments: {
		submitPublicComment(input: {
			author: string;
			email: string;
			body: string;
			route: string;
			submittedAt: string;
		}): Promise<{
			ok: true;
			comment: CommentRecord;
		}>;
	};
	rateLimits: {
		checkRateLimit(
			key: string,
			max: number,
			windowMs: number,
		): Promise<boolean>;
		peekRateLimit(key: string, max: number, windowMs: number): Promise<boolean>;
		recordFailedAttempt(
			key: string,
			max: number,
			windowMs: number,
		): Promise<void>;
	};
}

export function createD1AdminReadStore(db: D1DatabaseLike): D1AdminReadStore {
	return {
		...createD1OperationsReadPart(db),
		authors: createD1AuthorsReadPart(db),
		taxonomies: createD1TaxonomiesReadPart(db),
		content: { ...createD1ContentReadPart(db), ...createD1SchedulingPart(db) },
	};
}

export function createD1AdminMutationStore(
	db: D1DatabaseLike,
): D1AdminMutationStore {
	return {
		authors: createD1AuthorsMutationPart(db),
		taxonomies: createD1TaxonomiesMutationPart(db),
		...createD1OperationsMutationPart(db),
	};
}

src/d1-audit.ts.source:
import { peekCmsConfig } from "./config";
import { buildAuditEntry } from "./persistence-commons";
import type { Actor } from "./persistence-types";
import { getCloudflareBindings } from "./runtime-env";

export async function recordD1Audit(
	locals: App.Locals | null | undefined,
	actor: Actor,
	action: string,
	resourceType: string,
	resourceId: string,
	summary: string,
): Promise<void> {
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		return;
	}

	const entry = buildAuditEntry({
		actor,
		action,
		resourceType,
		resourceId,
		summary,
	});

	// D1 schema predates the `details` column — only 5 values bind here.
	await db
		.prepare(
			`INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary)
       VALUES (?, ?, ?, ?, ?)`,
		)
		.bind(
			entry.userEmail,
			entry.action,
			entry.resourceType,
			entry.resourceId,
			entry.summary,
		)
		.run();

	const retentionDays = peekCmsConfig()?.auditRetentionDays ?? 90;
	if (retentionDays > 0) {
		await db
			.prepare(
				`DELETE FROM audit_events WHERE created_at < datetime('now', '-' || ? || ' days')`,
			)
			.bind(retentionDays)
			.run();
	}
}

src/d1-locks.ts.source:
import type { D1DatabaseLike } from "./d1-database";

export interface ContentLockResult {
	ok: true;
	lockToken: string;
	expiresAt: string;
}

export interface ContentLockConflict {
	ok: false;
	conflict: true;
	lockedByEmail: string;
	lockedByName: string;
	expiresAt: string;
}

const LOCK_TTL_MINUTES = 5;

function lockExpiresAt(): string {
	const d = new Date();
	d.setMinutes(d.getMinutes() + LOCK_TTL_MINUTES);
	return d.toISOString();
}

export function createD1LocksOps(db: D1DatabaseLike) {
	async function expireStale() {
		await db
			.prepare("DELETE FROM content_locks WHERE expires_at <= ?")
			.bind(new Date().toISOString())
			.run();
	}

	return {
		async acquireLock(
			slug: string,
			email: string,
			name: string,
		): Promise<ContentLockResult | ContentLockConflict> {
			await expireStale();
			const existing = await db
				.prepare(
					"SELECT locked_by_email, locked_by_name, expires_at FROM content_locks WHERE slug = ? LIMIT 1",
				)
				.bind(slug)
				.first<{
					locked_by_email: string;
					locked_by_name: string;
					expires_at: string;
				}>();

			if (existing && existing.locked_by_email !== email) {
				return {
					ok: false,
					conflict: true,
					lockedByEmail: existing.locked_by_email,
					lockedByName: existing.locked_by_name,
					expiresAt: existing.expires_at,
				};
			}

			const lockToken = crypto.randomUUID();
			const expiresAt = lockExpiresAt();
			await db
				.prepare(
					`INSERT INTO content_locks (slug, locked_by_email, locked_by_name, lock_token, expires_at)
           VALUES (?, ?, ?, ?, ?)
           ON CONFLICT(slug) DO UPDATE SET
             locked_by_email = excluded.locked_by_email,
             locked_by_name = excluded.locked_by_name,
             lock_token = excluded.lock_token,
             expires_at = excluded.expires_at`,
				)
				.bind(slug, email, name, lockToken, expiresAt)
				.run();
			return { ok: true, lockToken, expiresAt };
		},

		async refreshLock(slug: string, lockToken: string): Promise<boolean> {
			const expiresAt = lockExpiresAt();
			const result = await db
				.prepare(
					"UPDATE content_locks SET expires_at = ? WHERE slug = ? AND lock_token = ?",
				)
				.bind(expiresAt, slug, lockToken)
				.run();
			return (result.meta?.changes ?? 0) > 0;
		},

		async releaseLock(slug: string, lockToken: string): Promise<boolean> {
			const result = await db
				.prepare("DELETE FROM content_locks WHERE slug = ? AND lock_token = ?")
				.bind(slug, lockToken)
				.run();
			return (result.meta?.changes ?? 0) > 0;
		},
	};
}

src/d1-migrate-ops.ts.source:
import { existsSync, readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import type { D1DatabaseLike } from "./d1-database.js";

export interface D1MigrateInput {
	db: D1DatabaseLike;
	migrationsDir: string;
	dryRun?: boolean;
}

export interface D1MigrateReport {
	migrationsDir: string;
	applied: string[];
	skipped: string[];
	dryRun: boolean;
}

export type D1RollbackStatus =
	| "rolled_back"
	| "no_rollback_sql"
	| "no_migrations"
	| "dry_run";

export interface D1RollbackReport {
	migrationName: string | null;
	status: D1RollbackStatus;
	dryRun: boolean;
}

/**
 * Split a SQL string into individual statements by top-level semicolons.
 * Skips empty segments and SQL comment-only segments.
 */
function splitSqlStatements(sql: string): string[] {
	return sql
		.split(";")
		.map((s) => s.trim())
		.filter((s) => s.length > 0 && !s.startsWith("--") && !/^\/\*/.test(s));
}

/**
 * Ensures the `schema_migrations` table exists in D1 and returns the set of
 * already-applied migration names.
 */
async function bootstrapD1MigrationsTable(
	db: D1DatabaseLike,
): Promise<Set<string>> {
	await db.batch([
		db.prepare(`CREATE TABLE IF NOT EXISTS schema_migrations (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL UNIQUE,
      applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      rollback_sql TEXT
    )`),
	]);

	const result = await db
		.prepare("SELECT name FROM schema_migrations")
		.all<{ name: string }>();
	return new Set(result.results.map((r) => r.name));
}

/**
 * Applies pending schema migrations to a Cloudflare D1 database.
 *
 * Migration files must be named with a numeric prefix (e.g. `0001_add_column.sql`).
 * They are applied in lexicographic order. Applied migrations are recorded in
 * `schema_migrations` so they are never re-run.
 *
 * Companion `.down.sql` files are read alongside each migration and stored as
 * `rollback_sql` in `schema_migrations`, enabling `rollbackD1LastMigration`.
 *
 * In `dryRun` mode no writes are performed — the function returns what would have
 * been applied.
 */
export async function runD1Migrations(
	input: D1MigrateInput,
): Promise<D1MigrateReport> {
	const { db, migrationsDir, dryRun = false } = input;
	const applied: string[] = [];
	const skipped: string[] = [];

	if (!existsSync(migrationsDir)) {
		return { migrationsDir, applied, skipped, dryRun };
	}

	const migrationFiles = readdirSync(migrationsDir)
		.filter((f) => f.endsWith(".sql") && !f.endsWith(".down.sql"))
		.sort();

	if (migrationFiles.length === 0) {
		return { migrationsDir, applied, skipped, dryRun };
	}

	const alreadyApplied = await bootstrapD1MigrationsTable(db);

	for (const file of migrationFiles) {
		if (alreadyApplied.has(file)) {
			skipped.push(file);
			continue;
		}

		const sql = readFileSync(path.join(migrationsDir, file), "utf8");
		const statements = splitSqlStatements(sql);

		const downFilePath = path.join(
			migrationsDir,
			file.replace(/\.sql$/, ".down.sql"),
		);
		const rollbackSql = existsSync(downFilePath)
			? readFileSync(downFilePath, "utf8")
			: null;

		if (!dryRun) {
			const batch = [
				...statements.map((stmt) => db.prepare(stmt)),
				db
					.prepare(
						"INSERT INTO schema_migrations (name, rollback_sql) VALUES (?, ?)",
					)
					.bind(file, rollbackSql),
			];
			await db.batch(batch);
		}

		applied.push(file);
	}

	return { migrationsDir, applied, skipped, dryRun };
}

/**
 * Rolls back the most recently applied D1 migration using its stored `rollback_sql`.
 *
 * Executes the rollback SQL as a batch and removes the migration record. If the
 * last migration has no rollback SQL, returns `status: "no_rollback_sql"` without
 * modifying the database.
 */
export async function rollbackD1LastMigration(
	db: D1DatabaseLike,
	{ dryRun = false }: { dryRun?: boolean } = {},
): Promise<D1RollbackReport> {
	let last: { name: string; rollback_sql: string | null } | null = null;

	try {
		last = await db
			.prepare(
				"SELECT name, rollback_sql FROM schema_migrations ORDER BY id DESC LIMIT 1",
			)
			.first<{ name: string; rollback_sql: string | null }>();
	} catch {
		return { migrationName: null, status: "no_migrations", dryRun };
	}

	if (!last) return { migrationName: null, status: "no_migrations", dryRun };
	if (!last.rollback_sql)
		return { migrationName: last.name, status: "no_rollback_sql", dryRun };

	if (dryRun)
		return { migrationName: last.name, status: "dry_run", dryRun: true };

	const rollbackStatements = splitSqlStatements(last.rollback_sql);
	await db.batch([
		...rollbackStatements.map((stmt) => db.prepare(stmt)),
		db.prepare("DELETE FROM schema_migrations WHERE name = ?").bind(last.name),
	]);

	return { migrationName: last.name, status: "rolled_back", dryRun: false };
}

