src/d1-store-operations-helpers.ts.source:
import type { D1DatabaseLike } from "./d1-database";
import {
	type PersistedAdminUserRow,
	type PersistedAuditEventRow,
	SQL_LIST_ADMIN_USERS_WITH_INVITE,
	SQL_LIST_AUDIT_EVENTS,
	deriveAdminUserStatus,
	mapPersistedAdminUserRow,
	mapPersistedAuditEvent,
} from "./persistence-commons";
import type {
	AuditEvent,
	CommentRecord,
	CommentStatus,
	ContactSubmission,
	ManagedAdminUser,
	MediaAsset,
	RedirectRule,
	TestimonialSource,
	TestimonialStatus,
	TestimonialSubmission,
	TestimonialSubmissionInput,
} from "./persistence-types";
import type { SiteSettings } from "./site-settings";

export { deriveAdminUserStatus };

export type CommentPolicy = "legacy-readonly" | "disabled" | "open-moderated";

export type AuditEventRow = PersistedAuditEventRow;

export type AdminUserRow = PersistedAdminUserRow;

export type CommentRow = {
	id: string;
	author: string;
	email: string | null;
	body: string | null;
	route: string;
	status: CommentStatus;
	policy: CommentPolicy;
	submitted_at: string;
};

export type TestimonialRow = {
	id: string;
	name: string;
	email: string;
	company: string | null;
	role: string | null;
	before_state: string | null;
	transformation: string | null;
	specific_result: string | null;
	consent_to_publish: number;
	status: string;
	source: string;
	submitted_at: string;
	approved_at: string | null;
};

export type MediaRow = {
	id: string;
	source_url: string | null;
	local_path: string;
	r2_key: string | null;
	mime_type: string | null;
	width: number | null;
	height: number | null;
	file_size: number | null;
	alt_text: string | null;
	title: string | null;
	uploaded_at: string;
	uploaded_by: string | null;
};

export type SettingsRow = {
	site_title: string;
	site_tagline: string;
	donation_url: string;
	newsletter_enabled: number;
	comments_default_policy: SiteSettings["commentsDefaultPolicy"];
	admin_slug: string;
};

/* ── Constants ── */

export const SQL_AUDIT_EVENTS = SQL_LIST_AUDIT_EVENTS;
export const SQL_ADMIN_USERS = SQL_LIST_ADMIN_USERS_WITH_INVITE;

export const SQL_REDIRECT_RULES = `SELECT source_path, target_path, status_code FROM redirect_rules
   WHERE deleted_at IS NULL ORDER BY source_path ASC`;

export const SQL_COMMENTS = `SELECT id, author, email, body, route, status, policy, submitted_at FROM comments
   ORDER BY CASE status WHEN 'pending' THEN 0 WHEN 'approved' THEN 1 ELSE 2 END,
     datetime(submitted_at) DESC, id DESC`;

export const SQL_CONTACT_SUBMISSIONS = `SELECT id, name, email, message, submitted_at FROM contact_submissions
   ORDER BY datetime(submitted_at) DESC, id DESC`;

export const SQL_TESTIMONIALS = `SELECT id, name, email, company, role, before_state, transformation,
          specific_result, consent_to_publish, status, source, submitted_at, approved_at
   FROM testimonial_submissions WHERE (? IS NULL OR status = ?)
   ORDER BY submitted_at DESC, id DESC`;

export const SQL_TRANSLATION_STATE =
	"SELECT state FROM translation_overrides WHERE route = ? LIMIT 1";

export const SQL_SITE_SETTINGS = `SELECT site_title, site_tagline, donation_url, newsletter_enabled,
          comments_default_policy, admin_slug
   FROM site_settings WHERE id = 1 LIMIT 1`;

export const SQL_MEDIA_ASSETS = `SELECT id, source_url, local_path, r2_key, mime_type, width, height,
          file_size, alt_text, title, uploaded_at, uploaded_by
   FROM media_assets WHERE deleted_at IS NULL
   ORDER BY datetime(uploaded_at) DESC, id DESC`;

export const TESTIMONIAL_INSERT_SQL = `INSERT INTO testimonial_submissions
     (id, name, email, company, role, before_state, transformation,
      specific_result, consent_to_publish, status, source, submitted_at)
   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?)`;

export const CONTACT_INSERT_SQL = `INSERT INTO contact_submissions (id, name, email, message, submitted_at)
   VALUES (?, ?, ?, ?, ?)`;

export const COMMENT_INSERT_SQL = `INSERT INTO comments (id, author, email, body, route, status, policy, submitted_at)
   VALUES (?, ?, ?, ?, ?, ?, ?, ?)`;

/* ── Row-mapping helpers ── */

export function mapAuditEventRow(row: AuditEventRow): AuditEvent {
	return mapPersistedAuditEvent({ row, idPrefix: "d1-audit-" });
}

export const deriveUserStatus = deriveAdminUserStatus;

export const mapAdminUserRow = mapPersistedAdminUserRow;

export function mapCommentRow(row: CommentRow): CommentRecord {
	return {
		id: row.id,
		author: row.author,
		email: row.email ?? undefined,
		body: row.body ?? undefined,
		route: row.route,
		status: row.status,
		policy: row.policy,
		submittedAt: row.submitted_at,
	};
}

export function mapTestimonialRow(row: TestimonialRow): TestimonialSubmission {
	return {
		id: row.id,
		name: row.name,
		email: row.email,
		company: row.company ?? undefined,
		role: row.role ?? undefined,
		beforeState: row.before_state ?? undefined,
		transformation: row.transformation ?? undefined,
		specificResult: row.specific_result ?? undefined,
		consentToPublish: row.consent_to_publish === 1,
		status: row.status as TestimonialStatus,
		source: row.source as TestimonialSource,
		submittedAt: row.submitted_at,
		approvedAt: row.approved_at ?? undefined,
	};
}

export function mapSettingsRow(row: SettingsRow): SiteSettings {
	return {
		siteTitle: row.site_title,
		siteTagline: row.site_tagline,
		donationUrl: row.donation_url,
		newsletterEnabled: row.newsletter_enabled === 1,
		commentsDefaultPolicy: row.comments_default_policy,
		adminSlug: row.admin_slug ?? "ap-admin",
	};
}

export function mapMediaRow(row: MediaRow): MediaAsset {
	return {
		id: row.id,
		sourceUrl: row.source_url,
		localPath: row.local_path,
		r2Key: row.r2_key,
		mimeType: row.mime_type,
		width: row.width,
		height: row.height,
		fileSize: row.file_size,
		altText: row.alt_text ?? "",
		title: row.title ?? "",
		uploadedAt: row.uploaded_at,
		uploadedBy: row.uploaded_by ?? "",
	};
}

export function mapContactRow(row: {
	id: string;
	name: string;
	email: string;
	message: string;
	submitted_at: string;
}): ContactSubmission {
	return {
		id: row.id,
		name: row.name,
		email: row.email,
		message: row.message,
		submittedAt: row.submitted_at,
	};
}

export function mapRedirectRow(row: {
	source_path: string;
	target_path: string;
	status_code: 301 | 302;
}): RedirectRule {
	return {
		sourcePath: row.source_path,
		targetPath: row.target_path,
		statusCode: row.status_code,
	};
}

/* ── Bind-param helpers ── */

export function testimonialInputBindParams(
	id: string,
	input: TestimonialSubmissionInput,
) {
	return [
		id,
		input.name,
		input.email,
		input.company ?? null,
		input.role ?? null,
		input.beforeState ?? null,
		input.transformation ?? null,
		input.specificResult ?? null,
		input.consentToPublish ? 1 : 0,
		input.source,
		input.submittedAt,
	] as const;
}

export function buildCommentBindParams(
	comment: CommentRecord,
	submittedAt: string,
) {
	return [
		comment.id,
		comment.author,
		comment.email ?? null,
		comment.body ?? null,
		comment.route,
		comment.status,
		comment.policy,
		submittedAt,
	] as const;
}

export function bindTestimonialFilter(
	db: D1DatabaseLike,
	status: TestimonialStatus | null | undefined,
) {
	const val = status ?? null;
	return db.prepare(SQL_TESTIMONIALS).bind(val, val);
}

export function buildApprovedAtExpr(status: TestimonialStatus): string {
	const approvedStatuses: TestimonialStatus[] = ["approved", "featured"];
	return approvedStatuses.includes(status)
		? "CASE WHEN approved_at IS NULL THEN CURRENT_TIMESTAMP ELSE approved_at END"
		: "approved_at";
}

export function buildModerateSql(
	db: D1DatabaseLike,
	status: TestimonialStatus,
	id: string,
) {
	const approvedAtExpr = buildApprovedAtExpr(status);
	const sql = `UPDATE testimonial_submissions SET status = ?, approved_at = ${approvedAtExpr} WHERE id = ?`;
	return db.prepare(sql).bind(status, id).run();
}

src/d1-store-taxonomies.ts.source:
import { slugify } from "./admin-normalizers";
import type { D1AdminMutationStore, D1AdminReadStore } from "./d1-admin-store";
import type { D1DatabaseLike } from "./d1-database";
import type { AuthorRecord, TaxonomyTerm } from "./persistence-types";

export function createD1AuthorsReadPart(
	db: D1DatabaseLike,
): D1AdminReadStore["authors"] {
	return {
		async listAuthors(): Promise<AuthorRecord[]> {
			const rows = (
				await db
					.prepare(
						`
              SELECT id, slug, name, bio, created_at, updated_at
              FROM authors
              WHERE deleted_at IS NULL
              ORDER BY name COLLATE NOCASE ASC, id ASC
            `,
					)
					.all<{
						id: number;
						slug: string;
						name: string;
						bio: string | null;
						created_at: string;
						updated_at: string;
					}>()
			).results;

			return rows.map((row) => ({
				id: row.id,
				slug: row.slug,
				name: row.name,
				bio: row.bio ?? undefined,
				createdAt: row.created_at,
				updatedAt: row.updated_at,
			}));
		},
	};
}

export function createD1TaxonomiesReadPart(
	db: D1DatabaseLike,
): D1AdminReadStore["taxonomies"] {
	return {
		async listCategories(): Promise<TaxonomyTerm[]> {
			const rows = (
				await db
					.prepare(
						`
              SELECT id, slug, name, description, created_at, updated_at
              FROM categories
              WHERE deleted_at IS NULL
              ORDER BY name COLLATE NOCASE ASC, id ASC
            `,
					)
					.all<{
						id: number;
						slug: string;
						name: string;
						description: string | null;
						created_at: string;
						updated_at: string;
					}>()
			).results;

			return rows.map((row) => ({
				id: row.id,
				kind: "category" as const,
				slug: row.slug,
				name: row.name,
				description: row.description ?? undefined,
				createdAt: row.created_at,
				updatedAt: row.updated_at,
			}));
		},
		async listTags(): Promise<TaxonomyTerm[]> {
			const rows = (
				await db
					.prepare(
						`
              SELECT id, slug, name, description, created_at, updated_at
              FROM tags
              WHERE deleted_at IS NULL
              ORDER BY name COLLATE NOCASE ASC, id ASC
            `,
					)
					.all<{
						id: number;
						slug: string;
						name: string;
						description: string | null;
						created_at: string;
						updated_at: string;
					}>()
			).results;

			return rows.map((row) => ({
				id: row.id,
				kind: "tag" as const,
				slug: row.slug,
				name: row.name,
				description: row.description ?? undefined,
				createdAt: row.created_at,
				updatedAt: row.updated_at,
			}));
		},
	};
}

export function createD1AuthorsMutationPart(
	db: D1DatabaseLike,
): D1AdminMutationStore["authors"] {
	return {
		async createAuthor(input) {
			const name = input.name.trim();
			const slug = slugify(input.slug?.trim() || name);
			if (!name || !slug) {
				return {
					ok: false as const,
					error: "Author name and slug are required.",
				};
			}

			try {
				await db
					.prepare("INSERT INTO authors (slug, name, bio) VALUES (?, ?, ?)")
					.bind(slug, name, input.bio?.trim() ?? "")
					.run();
			} catch {
				return {
					ok: false as const,
					error: "That author name or slug is already in use.",
				};
			}

			return { ok: true as const };
		},
		async updateAuthor(input) {
			const name = input.name.trim();
			const slug = slugify(input.slug?.trim() || name);
			if (!input.id || !name || !slug) {
				return {
					ok: false as const,
					error: "Author id, name, and slug are required.",
				};
			}

			try {
				await db
					.prepare(
						"UPDATE authors SET slug = ?, name = ?, bio = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND deleted_at IS NULL",
					)
					.bind(slug, name, input.bio?.trim() ?? "", input.id)
					.run();
			} catch {
				return {
					ok: false as const,
					error: "That author name or slug is already in use.",
				};
			}

			return { ok: true as const };
		},
		async deleteAuthor(id) {
			await db
				.prepare(
					"UPDATE authors SET deleted_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND deleted_at IS NULL",
				)
				.bind(id)
				.run();
			return { ok: true as const };
		},
	};
}

function validateTaxonomyInput(
	input: { name: string; slug?: string; id?: number },
	kind: "category" | "tag",
	requireId: boolean,
): { ok: true; name: string; slug: string } | { ok: false; error: string } {
	const name = input.name.trim();
	const slug = slugify(input.slug?.trim() || name);
	if (requireId && !input.id) {
		return { ok: false, error: `${kind} id, name, and slug are required.` };
	}
	if (!name || !slug) {
		return { ok: false, error: `${kind} name and slug are required.` };
	}
	return { ok: true, name, slug };
}

async function upsertTaxonomyTerm(
	db: D1DatabaseLike,
	table: "categories" | "tags",
	kind: "category" | "tag",
	input: { name: string; slug?: string; description?: string; id?: number },
	mode: "create" | "update",
): Promise<{ ok: true } | { ok: false; error: string }> {
	const validated = validateTaxonomyInput(input, kind, mode === "update");
	if (!validated.ok) {
		return { ok: false as const, error: validated.error };
	}
	const desc = input.description?.trim() ?? "";
	try {
		if (mode === "create") {
			await db
				.prepare(
					`INSERT INTO ${table} (slug, name, description) VALUES (?, ?, ?)`,
				)
				.bind(validated.slug, validated.name, desc)
				.run();
		} else {
			await db
				.prepare(
					`UPDATE ${table} SET slug = ?, name = ?, description = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND deleted_at IS NULL`,
				)
				.bind(validated.slug, validated.name, desc, input.id)
				.run();
		}
	} catch {
		return {
			ok: false as const,
			error: `That ${kind} name or slug is already in use.`,
		};
	}
	return { ok: true as const };
}

export function createD1TaxonomiesMutationPart(
	db: D1DatabaseLike,
): D1AdminMutationStore["taxonomies"] {
	return {
		async createCategory(input) {
			return upsertTaxonomyTerm(db, "categories", "category", input, "create");
		},
		async updateCategory(input) {
			return upsertTaxonomyTerm(db, "categories", "category", input, "update");
		},
		async deleteCategory(id) {
			await db
				.prepare(
					"UPDATE categories SET deleted_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND deleted_at IS NULL",
				)
				.bind(id)
				.run();
			return { ok: true as const };
		},
		async createTag(input) {
			return upsertTaxonomyTerm(db, "tags", "tag", input, "create");
		},
		async updateTag(input) {
			return upsertTaxonomyTerm(db, "tags", "tag", input, "update");
		},
		async deleteTag(id) {
			await db
				.prepare(
					"UPDATE tags SET deleted_at = CURRENT_TIMESTAMP, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND deleted_at IS NULL",
				)
				.bind(id)
				.run();
			return { ok: true as const };
		},
	};
}

