export type AstropressDataServices =
	| "none"
	| "cloudflare"
	| "supabase"
	| "appwrite"
	| "pocketbase"
	| "neon"
	| "nhost"
	| "turso"
	| "custom";

export interface AstropressDataServiceTarget {
	id: AstropressDataServices;
	label: string;
	kind:
		| "none"
		| "full-stack-services"
		| "db-and-storage"
		| "database-only"
		| "app-platform"
		| "custom";
	providesDatabase: boolean;
	providesObjectStorage: boolean;
	providesAuth: boolean;
	notes: string;
}

const dataServiceTargets: Record<
	AstropressDataServices,
	AstropressDataServiceTarget
> = {
	none: {
		id: "none",
		label: "No Hosted Content Services",
		kind: "none",
		providesDatabase: false,
		providesObjectStorage: false,
		providesAuth: false,
		notes: "Static publishing path without a hosted Astropress admin backend.",
	},
	cloudflare: {
		id: "cloudflare",
		label: "Cloudflare D1 / R2 / Workers",
		kind: "full-stack-services",
		providesDatabase: true,
		providesObjectStorage: true,
		providesAuth: true,
		notes: "Astropress-managed edge/runtime path using Workers, D1, and R2.",
	},
	supabase: {
		id: "supabase",
		label: "Supabase",
		kind: "db-and-storage",
		providesDatabase: true,
		providesObjectStorage: true,
		providesAuth: true,
		notes:
			"Hosted database, storage, and service primitives. The Astro app still needs an app host.",
	},
	appwrite: {
		id: "appwrite",
		label: "Appwrite",
		kind: "full-stack-services",
		providesDatabase: true,
		providesObjectStorage: true,
		providesAuth: true,
		notes:
			"Backend services platform for data, auth, and storage behind a separate Astro host.",
	},
	pocketbase: {
		id: "pocketbase",
		label: "PocketBase",
		kind: "full-stack-services",
		providesDatabase: true,
		providesObjectStorage: true,
		providesAuth: true,
		notes:
			"Lightweight backend-in-one-box path. Treat as preview or self-hosted infrastructure.",
	},
	neon: {
		id: "neon",
		label: "Neon",
		kind: "database-only",
		providesDatabase: true,
		providesObjectStorage: false,
		providesAuth: false,
		notes:
			"Database-only service. Astropress still needs auth, storage, and runtime glue elsewhere.",
	},
	nhost: {
		id: "nhost",
		label: "Nhost",
		kind: "full-stack-services",
		providesDatabase: true,
		providesObjectStorage: true,
		providesAuth: true,
		notes:
			"Open-source BaaS built on Hasura, PostgreSQL, and MinIO. Provides database, object storage, and auth. Requires a separate Astro app host.",
	},
	turso: {
		id: "turso",
		label: "Turso (LibSQL)",
		kind: "database-only",
		providesDatabase: true,
		providesObjectStorage: false,
		providesAuth: false,
		notes:
			"Distributed SQLite-wire database (LibSQL). Auth and storage must be handled separately.",
	},
	custom: {
		id: "custom",
		label: "Custom Content Services",
		kind: "custom",
		providesDatabase: true,
		providesObjectStorage: true,
		providesAuth: true,
		notes: "Bring your own data, auth, media, and service implementation.",
	},
};

export function listAstropressDataServiceTargets(): AstropressDataServiceTarget[] {
	return Object.values(dataServiceTargets);
}

export function getAstropressDataServiceTarget(
	dataServices: AstropressDataServices,
): AstropressDataServiceTarget {
	return dataServiceTargets[dataServices];
}

src/db-migrate-ops.ts.source:
import { DatabaseSync } from "node:sqlite";
import {
	readAstropressSqliteSchemaSql,
	rollbackAstropressLastMigrationWithOptions,
	runAstropressMigrations,
} from "./sqlite-bootstrap.js";

export interface AstropressDbMigrateInput {
	dbPath: string;
	migrationsDir: string;
	dryRun?: boolean;
}

export interface AstropressDbMigrateReport {
	dbPath: string;
	migrationsDir: string;
	applied: string[];
	skipped: string[];
	dryRun: boolean;
}

export function runAstropressDbMigrationsForCli(
	input: AstropressDbMigrateInput,
): AstropressDbMigrateReport {
	const { dbPath, migrationsDir, dryRun = false } = input;

	if (dryRun) {
		// In dry-run mode, use an in-memory DB to simulate the migration without touching the real DB
		const memDb = new DatabaseSync(":memory:");
		memDb.exec(readAstropressSqliteSchemaSql());
		const result = runAstropressMigrations(memDb, migrationsDir);
		memDb.close();
		return { dbPath, migrationsDir, ...result, dryRun: true };
	}

	const db = new DatabaseSync(dbPath);
	const result = runAstropressMigrations(db, migrationsDir);
	db.close();
	return { dbPath, migrationsDir, ...result, dryRun: false };
}

export interface AstropressDbRollbackInput {
	dbPath: string;
	dryRun?: boolean;
}

export type AstropressDbRollbackStatus =
	| "rolled_back"
	| "no_rollback_sql"
	| "no_migrations"
	| "dry_run";

export interface AstropressDbRollbackReport {
	dbPath: string;
	migrationName: string | null;
	status: AstropressDbRollbackStatus;
	dryRun: boolean;
}

/**
 * Rolls back the last applied schema migration using its stored `rollback_sql`.
 *
 * Reads the most recently applied migration from `schema_migrations`, executes
 * its `rollback_sql`, then deletes the migration record. If no `rollback_sql`
 * was stored (i.e. the migration has no companion `.down.sql` file), returns
 * `status: "no_rollback_sql"` without modifying the database.
 */
export function rollbackAstropressLastMigration(
	input: AstropressDbRollbackInput,
): AstropressDbRollbackReport {
	const { dbPath, dryRun = false } = input;

	const db = new DatabaseSync(dbPath);

	try {
		const result = rollbackAstropressLastMigrationWithOptions(db, { dryRun });
		return { dbPath, ...result };
	} finally {
		db.close();
	}
}

