import {
	type AstropressPlatformAdapter,
	type AuthStore,
	type AuthUser,
	type ContentStore,
	type ContentStoreRecord,
	type MediaAssetRecord,
	type MediaStore,
	type ProviderCapabilities,
	type RevisionRecord,
	type RevisionStore,
	assertProviderContract,
	normalizeProviderCapabilities,
} from "./platform-contracts";

type AstropressFetch = typeof fetch;

export interface AstropressHostedApiAdapterOptions {
	providerName: ProviderCapabilities["name"];
	apiBaseUrl: string;
	accessToken?: string;
	previewBaseUrl?: string;
	defaultCapabilities?: Partial<Omit<ProviderCapabilities, "name">>;
	fetchImpl?: AstropressFetch;
}

function joinApiUrl(baseUrl: string, path: string) {
	return `${baseUrl.replace(/\/$/, "")}/${path.replace(/^\//, "")}`;
}

async function readJson<T>(response: Response): Promise<T> {
	if (!response.ok) {
		throw new Error(
			`Astropress hosted API request failed with ${response.status}.`,
		);
	}
	return (await response.json()) as T;
}

function createHeaders(accessToken?: string, extra?: Record<string, string>) {
	return {
		"content-type": "application/json",
		...(accessToken ? { authorization: `Bearer ${accessToken}` } : {}),
		...extra,
	};
}

export function createAstropressHostedApiAdapter(
	options: AstropressHostedApiAdapterOptions,
): AstropressPlatformAdapter {
	const fetchImpl = options.fetchImpl ?? fetch;
	const capabilities = normalizeProviderCapabilities({
		name: options.providerName,
		hostedAdmin: true,
		previewEnvironments: true,
		serverRuntime: true,
		database: true,
		objectStorage: true,
		gitSync: true,
		...options.defaultCapabilities,
	});

	const requestJson = async <T>(
		path: string,
		init: RequestInit = {},
	): Promise<T> => {
		const response = await fetchImpl(joinApiUrl(options.apiBaseUrl, path), {
			...init,
			headers: createHeaders(
				options.accessToken,
				init.headers as Record<string, string> | undefined,
			),
		});
		return readJson<T>(response);
	};

	const content: ContentStore = {
		async list(kind) {
			const query = kind ? `?kind=${encodeURIComponent(kind)}` : "";
			return requestJson<ContentStoreRecord[]>(`content${query}`);
		},
		async get(id) {
			return requestJson<ContentStoreRecord | null>(
				`content/${encodeURIComponent(id)}`,
			);
		},
		async save(record) {
			return requestJson<ContentStoreRecord>("content", {
				method: "POST",
				body: JSON.stringify(record),
			});
		},
		async delete(id) {
			await requestJson<{ ok: true }>(`content/${encodeURIComponent(id)}`, {
				method: "DELETE",
			});
		},
	};

	const media: MediaStore = {
		async put(asset) {
			return requestJson<MediaAssetRecord>("media", {
				method: "POST",
				body: JSON.stringify(asset),
			});
		},
		async get(id) {
			return requestJson<MediaAssetRecord | null>(
				`media/${encodeURIComponent(id)}`,
			);
		},
		async delete(id) {
			await requestJson<{ ok: true }>(`media/${encodeURIComponent(id)}`, {
				method: "DELETE",
			});
		},
	};

	const revisions: RevisionStore = {
		async list(recordId) {
			return requestJson<RevisionRecord[]>(
				`revisions?recordId=${encodeURIComponent(recordId)}`,
			);
		},
		async append(revision) {
			return requestJson<RevisionRecord>("revisions", {
				method: "POST",
				body: JSON.stringify(revision),
			});
		},
	};

	const auth: AuthStore = {
		async signIn(email, password) {
			return requestJson<AuthUser | null>("auth/sign-in", {
				method: "POST",
				body: JSON.stringify({ email, password }),
			});
		},
		async signOut(sessionId) {
			await requestJson<{ ok: true }>("auth/sign-out", {
				method: "POST",
				body: JSON.stringify({ sessionId }),
			});
		},
		async getSession(sessionId) {
			return requestJson<AuthUser | null>(
				`auth/session/${encodeURIComponent(sessionId)}`,
			);
		},
	};

	return assertProviderContract({
		capabilities,
		content,
		media,
		revisions,
		auth,
		preview: options.previewBaseUrl
			? {
					async create(input) {
						return {
							url: joinApiUrl(
								options.previewBaseUrl as string,
								`preview/${encodeURIComponent(input.recordId)}`,
							),
							expiresAt: input.expiresAt,
						};
					},
				}
			: undefined,
	});
}

src/hosted-platform-adapter.ts.source:
import {
	type AstropressInMemoryPlatformAdapterOptions,
	createAstropressInMemoryPlatformAdapter,
} from "./in-memory-platform-adapter";
import {
	type AstropressPlatformAdapter,
	type ProviderCapabilities,
	assertProviderContract,
	normalizeProviderCapabilities,
} from "./platform-contracts";

export interface AstropressHostedPlatformAdapterOptions
	extends Omit<AstropressInMemoryPlatformAdapterOptions, "capabilities"> {
	providerName: ProviderCapabilities["name"];
	defaultCapabilities?: Partial<Omit<ProviderCapabilities, "name">>;
	backingAdapter?: AstropressPlatformAdapter;
}

export function createAstropressHostedPlatformAdapter(
	options: AstropressHostedPlatformAdapterOptions,
): AstropressPlatformAdapter {
	const capabilities = {
		name: options.providerName,
		hostedAdmin: true,
		previewEnvironments: true,
		serverRuntime: true,
		database: true,
		objectStorage: true,
		gitSync: true,
		...options.defaultCapabilities,
	} satisfies Pick<ProviderCapabilities, "name"> &
		Partial<Omit<ProviderCapabilities, "name">>;

	const baseAdapter =
		options.backingAdapter ??
		createAstropressInMemoryPlatformAdapter({
			...options,
			capabilities,
		});

	return assertProviderContract({
		...baseAdapter,
		capabilities: normalizeProviderCapabilities({
			...baseAdapter.capabilities,
			...capabilities,
		}),
	});
}

src/html-optimization.ts.source:
/**
 * Add loading="lazy" to img tags that don't already have a loading attribute.
 * This optimizes performance by deferring off-viewport image loads.
 */
export function optimizeImageLoading(html: string): string {
	let firstImage = true;

	const IMG_TAG_RE = /<img([^>]{0,2048})>/g;
	return html.replace(IMG_TAG_RE, (match, attrs) => {
		// Skip if already has a loading attribute (lazy, eager, etc.)
		// Use a simple string check to avoid nested-quantifier ReDoS warnings
		if (/\bloading=/i.test(attrs)) {
			firstImage = false;
			return match;
		}

		// Don't lazy load images marked as high-priority (fetchpriority attribute)
		if (attrs.includes("fetchpriority")) {
			firstImage = false;
			return match;
		}

		// Don't lazy load the first image in the body (likely hero/LCP)
		if (firstImage) {
			firstImage = false;
			return match;
		}

		firstImage = false;
		// Add loading="lazy" to optimize off-viewport images
		return `<img${attrs} loading="lazy">`;
	});
}

src/html-sanitization.ts.source:
const allowedTags = new Set([
	"a",
	"b",
	"blockquote",
	"br",
	"code",
	"div",
	"em",
	"figcaption",
	"figure",
	"h1",
	"h2",
	"h3",
	"h4",
	"h5",
	"h6",
	"hr",
	"i",
	"img",
	"li",
	"ol",
	"p",
	"pre",
	"span",
	"strong",
	"sub",
	"sup",
	"table",
	"tbody",
	"td",
	"th",
	"thead",
	"tr",
	"u",
	"ul",
]);

const allowedAttributes = new Map<string, Set<string>>([
	["*", new Set(["class"])],
	["a", new Set(["href", "name", "target", "rel"])],
	[
		"img",
		new Set([
			"src",
			"srcset",
			"sizes",
			"alt",
			"title",
			"width",
			"height",
			"loading",
			"decoding",
			"fetchpriority",
		]),
	],
	["th", new Set(["colspan", "rowspan", "scope"])],
	["td", new Set(["colspan", "rowspan"])],
]);

const dropContentTags = new Set([
	"script",
	"style",
	"textarea",
	"option",
	"iframe",
]);
const urlAttributes = new Set(["href", "src"]);
const srcsetAttributes = new Set(["srcset"]);
const allowedSchemes = new Set(["http", "https", "mailto", "tel"]);

function isAllowedUrl(value: string) {
	const trimmed = value.trim();
	if (!trimmed || trimmed.startsWith("//")) {
		return false;
	}

	const schemeMatch = trimmed.match(/^([a-zA-Z][a-zA-Z0-9+.-]*):/);
	if (!schemeMatch) {
		return true;
	}

	return allowedSchemes.has(schemeMatch[1].toLowerCase());
}

function sanitizeSrcset(value: string) {
	const candidates = value
		.split(",")
		.map((candidate) => candidate.trim())
		.filter(Boolean)
		.filter((candidate) => {
			const [url] = candidate.split(/\s+/, 1);
			return Boolean(url) && isAllowedUrl(url);
		});

	return candidates.length > 0 ? candidates.join(", ") : null;
}

function sanitizeAttribute(
	tagName: string,
	attributeName: string,
	attributeValue: string,
) {
	const allowedForTag = allowedAttributes.get(tagName);
	const allowedGlobally = allowedAttributes.get("*");
	const isAllowed =
		allowedForTag?.has(attributeName) || allowedGlobally?.has(attributeName);

	if (!isAllowed) {
		return null;
	}

	const trimmedValue = attributeValue.trim();
	if (!trimmedValue && attributeName !== "class") {
		return null;
	}

	if (urlAttributes.has(attributeName)) {
		return isAllowedUrl(trimmedValue) ? trimmedValue : null;
	}

	if (srcsetAttributes.has(attributeName)) {
		return sanitizeSrcset(trimmedValue);
	}

	return trimmedValue;
}

export async function sanitizeHtml(html: string): Promise<string> {
	if (typeof globalThis.HTMLRewriter === "undefined") {
		return sanitizeHtmlLibrary(html, {
			allowedTags: [...allowedTags],
			allowedAttributes: Object.fromEntries(
				[...allowedAttributes.entries()].map(([tagName, attributes]) => [
					tagName,
					[...attributes],
				]),
			),
			allowedSchemes: [...allowedSchemes],
			allowProtocolRelative: false,
			nonBooleanAttributes: ["class"],
			transformTags: {
				a: (tagName, attribs) => ({
					tagName,
					attribs: {
						...attribs,
						rel: "noopener noreferrer",
					},
				}),
			},
		});
	}

	const rewriter = new HTMLRewriter().on("*", {
		element(el) {
			const tag = el.tagName.toLowerCase();

			if (dropContentTags.has(tag)) {
				el.remove();
				return;
			}

			if (!allowedTags.has(tag)) {
				el.removeAndKeepContent();
				return;
			}

			for (const [name, value] of el.attributes) {
				const sanitized = sanitizeAttribute(tag, name, value);
				if (sanitized === null) {
					el.removeAttribute(name);
				} else if (sanitized !== value) {
					el.setAttribute(name, sanitized);
				}
			}

			if (tag === "a") {
				el.setAttribute("rel", "noopener noreferrer");
			}
		},
	});

	return rewriter.transform(new Response(html)).text();
}
import sanitizeHtmlLibrary from "sanitize-html";

