import type { AstropressWordPressImportEntityCount } from "../platform-contracts";
import {
	countMatches,
	escapeRegExp,
	filenameFromUrl,
	getAttributeValue,
	getBlocks,
	getTagText,
	inferMimeType,
	normalizeContentStatus,
	normalizePathname,
	normalizeSlug,
	parseCategoryBlocks,
	safeArtifactFilename,
} from "./wordpress-xml-helpers";

export type ParsedAuthor = {
	id: string;
	login: string;
	email?: string;
	displayName: string;
};

export type ParsedTerm = {
	kind: "category" | "tag";
	slug: string;
	name: string;
};

export type ParsedRedirect = {
	id: string;
	sourcePath: string;
	targetPath: string;
	reason: string;
	recordId: string;
};

export type ParsedComment = {
	id: string;
	legacyId: string;
	recordId: string;
	authorName: string;
	authorEmail?: string;
	body: string;
	status: "approved" | "pending";
	createdAt?: string;
};

export type ParsedContentRecord = {
	id: string;
	legacyId: string;
	kind: "post" | "page";
	slug: string;
	title: string;
	body: string;
	excerpt?: string;
	status: "draft" | "published" | "archived";
	legacyUrl: string;
	publishedAt?: string;
	authorLogins: string[];
	categorySlugs: string[];
	tagSlugs: string[];
	oldSlugs: string[];
};

export type ParsedMediaAsset = {
	id: string;
	legacyId: string;
	slug: string;
	title: string;
	sourceUrl: string;
	legacyUrl: string;
	filename: string;
	mimeType: string;
	parentLegacyId?: string;
};

export type ParsedBundle = {
	authors: ParsedAuthor[];
	terms: ParsedTerm[];
	contentRecords: ParsedContentRecord[];
	mediaAssets: ParsedMediaAsset[];
	comments: ParsedComment[];
	redirects: ParsedRedirect[];
	entityCounts: AstropressWordPressImportEntityCount;
	remediationCandidates: string[];
	unsupportedPatterns: string[];
	warnings: string[];
};

export function detectUnsupportedPatterns(source: string) {
	const shortcodeMatches = countMatches(source, /\[[a-z][^\]]*\]/gi);
	const builderMatches = countMatches(
		source,
		/(elementor|vc_row|wp-block-|et_pb_|fusion_)/gi,
	);
	const unsupportedPatterns: string[] = [];
	const warnings: string[] = [];

	if (shortcodeMatches > 0) {
		unsupportedPatterns.push("shortcodes");
		warnings.push(
			"WordPress shortcodes were detected; staged content will need manual review.",
		);
	}
	if (builderMatches > 0) {
		unsupportedPatterns.push("page-builder-markup");
		warnings.push(
			"WordPress page-builder markup was detected; staged content will need manual cleanup.",
		);
	}

	return { shortcodeMatches, builderMatches, unsupportedPatterns, warnings };
}

export function parseWordPressExport(source: string): ParsedBundle {
	const authors: ParsedAuthor[] = getBlocks(source, "wp:author").map(
		(block, index) => ({
			id: getTagText(block, "wp:author_id") || `author-${index + 1}`,
			login: normalizeSlug(
				getTagText(block, "wp:author_login"),
				`author-${index + 1}`,
			),
			email: getTagText(block, "wp:author_email") || undefined,
			displayName:
				getTagText(block, "wp:author_display_name") ||
				getTagText(block, "wp:author_login") ||
				`Author ${index + 1}`,
		}),
	);

	const termsByKey = new Map<string, ParsedTerm>();
	const contentRecords: ParsedContentRecord[] = [];
	const mediaAssets: ParsedMediaAsset[] = [];
	const comments: ParsedComment[] = [];
	const redirects: ParsedRedirect[] = [];
	let skipped = 0;

	for (const [index, item] of getBlocks(source, "item").entries()) {
		const legacyId = getTagText(item, "wp:post_id") || `item-${index + 1}`;
		const postType = getTagText(item, "wp:post_type").toLowerCase();
		const postStatus = normalizeContentStatus(getTagText(item, "wp:status"));
		const title = getTagText(item, "title") || `Untitled ${legacyId}`;
		const legacyUrl = normalizePathname(
			getTagText(item, "link") || getTagText(item, "guid"),
			normalizeSlug(getTagText(item, "wp:post_name"), legacyId),
		);
		const slug = normalizeSlug(
			getTagText(item, "wp:post_name"),
			legacyUrl
				.replace(/^\/|\/$/g, "")
				.split("/")
				.at(-1) || legacyId,
		);
		const body = getTagText(item, "content:encoded");
		const excerpt = getTagText(item, "excerpt:encoded");
		const publishedAt =
			getTagText(item, "wp:post_date_gmt") ||
			getTagText(item, "wp:post_date") ||
			undefined;

		const oldSlugs = getBlocks(item, "wp:postmeta")
			.filter((meta) => getTagText(meta, "wp:meta_key") === "_wp_old_slug")
			.map((meta) =>
				normalizeSlug(getTagText(meta, "wp:meta_value"), "legacy"),
			);

		const categorySlugs: string[] = [];
		const tagSlugs: string[] = [];
		for (const category of parseCategoryBlocks(item)) {
			const domain = getAttributeValue(category.attributes, "domain");
			const slugValue = normalizeSlug(
				getAttributeValue(category.attributes, "nicename"),
				normalizeSlug(category.value, "term"),
			);
			if (domain === "category") {
				categorySlugs.push(slugValue);
				termsByKey.set(`category:${slugValue}`, {
					kind: "category",
					slug: slugValue,
					name: category.value || slugValue,
				});
			} else if (domain === "post_tag") {
				tagSlugs.push(slugValue);
				termsByKey.set(`tag:${slugValue}`, {
					kind: "tag",
					slug: slugValue,
					name: category.value || slugValue,
				});
			}
		}

		if (postType === "post" || postType === "page") {
			const creatorLogin = getTagText(item, "dc:creator");
			const matchedAuthor = creatorLogin
				? authors.find((a) => a.login === creatorLogin)
				: undefined;
			const authorLogins = matchedAuthor
				? [matchedAuthor.login]
				: authors.length > 0
					? [authors[0]?.login]
					: [];

			contentRecords.push({
				id: `${postType}-${legacyId}`,
				legacyId,
				kind: postType,
				slug,
				title,
				body,
				excerpt: excerpt || undefined,
				status: postStatus,
				legacyUrl,
				publishedAt,
				authorLogins,
				categorySlugs,
				tagSlugs,
				oldSlugs,
			});

			for (const oldSlug of oldSlugs) {
				const targetPath = legacyUrl;
				const sourcePath = legacyUrl.replace(
					new RegExp(`${escapeRegExp(slug)}/?$`),
					`${oldSlug}/`,
				);
				if (sourcePath !== targetPath) {
					redirects.push({
						id: `redirect-${legacyId}-${oldSlug}`,
						sourcePath,
						targetPath,
						reason: "wp_old_slug",
						recordId: `${postType}-${legacyId}`,
					});
				}
			}

			for (const [commentIndex, commentBlock] of getBlocks(
				item,
				"wp:comment",
			).entries()) {
				comments.push({
					id: `comment-${legacyId}-${commentIndex + 1}`,
					legacyId:
						getTagText(commentBlock, "wp:comment_id") ||
						`${legacyId}-${commentIndex + 1}`,
					recordId: `${postType}-${legacyId}`,
					authorName:
						getTagText(commentBlock, "wp:comment_author") || "Anonymous",
					authorEmail:
						getTagText(commentBlock, "wp:comment_author_email") || undefined,
					body: getTagText(commentBlock, "wp:comment_content"),
					status:
						getTagText(commentBlock, "wp:comment_approved") === "1"
							? "approved"
							: "pending",
					createdAt:
						getTagText(commentBlock, "wp:comment_date_gmt") ||
						getTagText(commentBlock, "wp:comment_date") ||
						undefined,
				});
			}
			continue;
		}

		if (postType === "attachment") {
			const sourceUrl =
				getTagText(item, "wp:attachment_url") || getTagText(item, "guid");
			const filename = safeArtifactFilename(
				filenameFromUrl(sourceUrl, `${slug || legacyId}.bin`),
				`${slug || legacyId}.bin`,
			);
			mediaAssets.push({
				id: `media-${legacyId}`,
				legacyId,
				slug,
				title,
				sourceUrl,
				legacyUrl,
				filename,
				mimeType: inferMimeType(filename),
				parentLegacyId: getTagText(item, "wp:post_parent") || undefined,
			});
			continue;
		}

		skipped += 1;
	}

	const unsupported = detectUnsupportedPatterns(
		contentRecords.map((r) => `${r.body}\n${r.excerpt ?? ""}`).join("\n"),
	);
	const remediationCandidates = contentRecords
		.filter((r) =>
			/\[[a-z][^\]]*\]|elementor|vc_row|wp-block-|et_pb_|fusion_/i.test(
				`${r.body}\n${r.excerpt ?? ""}`,
			),
		)
		.map((r) => r.id);

	return {
		authors,
		terms: [...termsByKey.values()],
		contentRecords,
		mediaAssets,
		comments,
		redirects,
		entityCounts: {
			posts: contentRecords.filter((r) => r.kind === "post").length,
			pages: contentRecords.filter((r) => r.kind === "page").length,
			attachments: mediaAssets.length,
			redirects: redirects.length,
			comments: comments.length,
			users: authors.length,
			categories: [...termsByKey.values()].filter((t) => t.kind === "category")
				.length,
			tags: [...termsByKey.values()].filter((t) => t.kind === "tag").length,
			skipped,
		},
		remediationCandidates,
		unsupportedPatterns: unsupported.unsupportedPatterns,
		warnings: unsupported.warnings,
	};
}

src/import/wordpress.ts.source:
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import type {
	AstropressWordPressImportArtifacts,
	AstropressWordPressImportInventory,
	AstropressWordPressImportPlan,
	AstropressWordPressImportReport,
	ImportSource,
} from "../platform-contracts";
import { downloadMediaToFile } from "./download-media.js";
import {
	applyImportToLocalRuntime,
	fileSizeOrNull,
} from "./wordpress-apply.js";
import {
	detectUnsupportedPatterns,
	parseWordPressExport,
} from "./wordpress-xml.js";
import type { ParsedBundle } from "./wordpress-xml.js";

export interface AstropressWordPressImportSourceOptions {
	sourceUrl?: string;
}

type DownloadState = {
	completed: string[];
	failed: Array<{ id: string; sourceUrl?: string; reason: string }>;
};

async function readDownloadState(
	downloadStateFile: string,
): Promise<DownloadState> {
	try {
		return JSON.parse(
			await readFile(downloadStateFile, "utf8"),
		) as DownloadState;
	} catch {
		return { completed: [], failed: [] };
	}
}

async function writeJsonArtifact(targetPath: string, value: unknown) {
	await writeFile(targetPath, `${JSON.stringify(value, null, 2)}\n`, "utf8");
}

async function downloadMediaAssets(
	mediaAssets: ParsedBundle["mediaAssets"],
	artifactDir: string,
	resumeFrom?: string,
) {
	const downloadsDir = path.join(artifactDir, "downloads");
	const downloadStateFile = path.join(artifactDir, "download-state.json");
	await mkdir(downloadsDir, { recursive: true });

	const state = await readDownloadState(resumeFrom || downloadStateFile);
	const completed = new Set(state.completed);
	const failed: DownloadState["failed"] = [...state.failed];
	let downloadedMedia = 0;

	for (const asset of mediaAssets) {
		const assetTarget = path.join(downloadsDir, path.basename(asset.filename));
		if (completed.has(asset.id) && (await fileSizeOrNull(assetTarget)) !== null)
			continue;
		try {
			await downloadMediaToFile(asset.sourceUrl, assetTarget);
			completed.add(asset.id);
			downloadedMedia += 1;
		} catch (error) {
			failed.push({
				id: asset.id,
				sourceUrl: asset.sourceUrl,
				reason:
					error instanceof Error
						? error.message
						: "Unknown media download error",
			});
		}
	}

	const normalizedState: DownloadState = {
		completed: [...completed].sort(),
		failed: failed.filter(
			(e, i, all) =>
				all.findIndex((c) => c.id === e.id && c.reason === e.reason) === i,
		),
	};
	await writeJsonArtifact(downloadStateFile, normalizedState);
	return {
		downloadStateFile,
		downloadedMedia,
		failedMedia: normalizedState.failed,
	};
}

async function parseImportInput(
	input: Parameters<ImportSource["importWordPress"]>[0],
) {
	if (!input.exportFile)
		throw new Error("WordPress import requires an `exportFile` path.");
	const source = await readFile(input.exportFile, "utf8");
	const bundle = parseWordPressExport(source);
	const inventory = buildInventory(input, bundle);
	return { source, bundle, inventory };
}

function buildInventory(
	input: { exportFile?: string; sourceUrl?: string },
	bundle: ParsedBundle,
): AstropressWordPressImportInventory {
	const unsupported = detectUnsupportedPatterns(
		bundle.contentRecords
			.map((r) => `${r.body}\n${r.excerpt ?? ""}`)
			.join("\n"),
	);
	return {
		exportFile: input.exportFile,
		sourceUrl: input.sourceUrl,
		detectedRecords: bundle.contentRecords.length + bundle.mediaAssets.length,
		detectedMedia: bundle.mediaAssets.length,
		detectedComments: bundle.comments.length,
		detectedUsers: bundle.authors.length,
		detectedShortcodes: unsupported.shortcodeMatches,
		detectedBuilderMarkers: unsupported.builderMatches,
		entityCounts: bundle.entityCounts,
		unsupportedPatterns: bundle.unsupportedPatterns,
		remediationCandidates: bundle.remediationCandidates,
		warnings: bundle.warnings,
	};
}

function buildImportPlan(
	inventory: AstropressWordPressImportInventory,
	overrides: Pick<
		AstropressWordPressImportPlan,
		| "includeComments"
		| "includeUsers"
		| "includeMedia"
		| "downloadMedia"
		| "applyLocal"
	> & {
		artifactDir?: string;
	} = {
		includeComments: true,
		includeUsers: true,
		includeMedia: true,
		downloadMedia: false,
		applyLocal: false,
	},
): AstropressWordPressImportPlan {
	const includeComments =
		overrides.includeComments ?? inventory.detectedComments > 0;
	const includeUsers = overrides.includeUsers ?? inventory.detectedUsers > 0;
	const includeMedia = overrides.includeMedia ?? inventory.detectedMedia > 0;
	const downloadMedia = includeMedia && (overrides.downloadMedia ?? false);
	const applyLocal = overrides.applyLocal ?? false;
	const manualTasks = [...inventory.warnings];

	if (inventory.remediationCandidates.length > 0) {
		manualTasks.push(
			"Review remediation-candidates.json for shortcode or page-builder cleanup before publishing staged content.",
		);
	}
	if (downloadMedia && !overrides.artifactDir) {
		manualTasks.push(
			"Media download was requested without an artifact directory; downloads will be skipped.",
		);
	}

	return {
		sourceUrl: inventory.sourceUrl,
		exportFile: inventory.exportFile,
		artifactDir: overrides.artifactDir,
		includeComments,
		includeUsers,
		includeMedia,
		downloadMedia: downloadMedia && Boolean(overrides.artifactDir),
		applyLocal,
		permalinkStrategy: "preserve-wordpress-links",
		resumeSupported: true,
		entityCounts: inventory.entityCounts,
		reviewRequired: inventory.unsupportedPatterns.length > 0,
		manualTasks: [...new Set(manualTasks)],
	};
}

async function stageArtifacts(
	artifactDir: string,
	inventory: AstropressWordPressImportInventory,
	plan: AstropressWordPressImportPlan,
	bundle: ParsedBundle,
	resumeFrom?: string,
): Promise<{
	artifacts: AstropressWordPressImportArtifacts;
	downloadedMedia: number;
	failedMedia: AstropressWordPressImportReport["failedMedia"];
}> {
	await mkdir(artifactDir, { recursive: true });

	const artifacts: AstropressWordPressImportArtifacts = {
		artifactDir,
		inventoryFile: path.join(artifactDir, "wordpress.inventory.json"),
		planFile: path.join(artifactDir, "wordpress.plan.json"),
		contentFile: path.join(artifactDir, "content-records.json"),
		mediaFile: path.join(artifactDir, "media-manifest.json"),
		commentFile: path.join(artifactDir, "comment-records.json"),
		userFile: path.join(artifactDir, "user-records.json"),
		redirectFile: path.join(artifactDir, "redirect-records.json"),
		taxonomyFile: path.join(artifactDir, "taxonomy-records.json"),
		remediationFile: path.join(artifactDir, "remediation-candidates.json"),
		downloadStateFile: path.join(artifactDir, "download-state.json"),
	};

	await writeJsonArtifact(artifacts.inventoryFile, inventory);
	await writeJsonArtifact(artifacts.planFile, plan);
	await writeJsonArtifact(artifacts.contentFile, bundle.contentRecords);
	await writeJsonArtifact(artifacts.mediaFile, bundle.mediaAssets);
	await writeJsonArtifact(artifacts.commentFile, bundle.comments);
	await writeJsonArtifact(artifacts.userFile, bundle.authors);
	await writeJsonArtifact(artifacts.redirectFile, bundle.redirects);
	await writeJsonArtifact(artifacts.taxonomyFile, bundle.terms);
	await writeJsonArtifact(
		artifacts.remediationFile,
		bundle.remediationCandidates,
	);

	if (!plan.downloadMedia) {
		await writeJsonArtifact(artifacts.downloadStateFile, {
			completed: [],
			failed: [],
		} satisfies DownloadState);
		return { artifacts, downloadedMedia: 0, failedMedia: [] };
	}

	const downloadOutcome = await downloadMediaAssets(
		bundle.mediaAssets,
		artifactDir,
		resumeFrom,
	);
	artifacts.downloadStateFile = downloadOutcome.downloadStateFile;
	return {
		artifacts,
		downloadedMedia: downloadOutcome.downloadedMedia,
		failedMedia: downloadOutcome.failedMedia,
	};
}

function resolveImportOverrides(input: {
	includeComments?: boolean;
	includeUsers?: boolean;
	includeMedia?: boolean;
	downloadMedia?: boolean;
	artifactDir?: string;
	applyLocal?: boolean;
}) {
	return {
		includeComments: input.includeComments ?? true,
		includeUsers: input.includeUsers ?? true,
		includeMedia: input.includeMedia ?? true,
		downloadMedia: input.downloadMedia ?? false,
		artifactDir: input.artifactDir,
		applyLocal: input.applyLocal ?? false,
	};
}

function resolveImportStatus(
	plan: AstropressWordPressImportPlan,
	failedMedia: AstropressWordPressImportReport["failedMedia"],
): AstropressWordPressImportReport["status"] {
	return plan.reviewRequired || failedMedia.length > 0
		? "completed_with_warnings"
		: "completed";
}

export function createAstropressWordPressImportSource(
	options: AstropressWordPressImportSourceOptions = {},
): ImportSource {
	return {
		async inspectWordPress(input) {
			const { inventory } = await parseImportInput({
				...input,
				sourceUrl: input.sourceUrl ?? options.sourceUrl,
			});
			return inventory;
		},
		async planWordPressImport(input) {
			return buildImportPlan(input.inventory, resolveImportOverrides(input));
		},
		async importWordPress(input) {
			const { bundle, inventory } = await parseImportInput({
				...input,
				sourceUrl: input.sourceUrl ?? options.sourceUrl,
			});
			const plan =
				input.plan ?? buildImportPlan(inventory, resolveImportOverrides(input));

			const artifactsOutcome = plan.artifactDir
				? await stageArtifacts(
						plan.artifactDir,
						inventory,
						plan,
						bundle,
						input.resumeFrom,
					)
				: { artifacts: undefined, downloadedMedia: 0, failedMedia: [] };

			const localApply = plan.applyLocal
				? await applyImportToLocalRuntime({
						bundle,
						artifactDir: plan.artifactDir,
						workspaceRoot: input.workspaceRoot ?? process.cwd(),
						adminDbPath: input.adminDbPath,
						plan,
					})
				: undefined;

			if (plan.applyLocal && plan.artifactDir) {
				const localApplyReportFile = path.join(
					plan.artifactDir,
					"wordpress.local-apply.json",
				);
				await writeJsonArtifact(localApplyReportFile, localApply);
				if (artifactsOutcome.artifacts)
					artifactsOutcome.artifacts.localApplyReportFile =
						localApplyReportFile;
			}

			if (plan.artifactDir && artifactsOutcome.artifacts) {
				const reportFile = path.join(plan.artifactDir, "import-report.json");
				await writeJsonArtifact(reportFile, {
					generatedAt: new Date().toISOString(),
					status: resolveImportStatus(plan, artifactsOutcome.failedMedia),
					counts: bundle.entityCounts,
					mediaErrors: artifactsOutcome.failedMedia.map((f) => ({
						id: f.id,
						sourceUrl: f.sourceUrl,
						reason: f.reason,
					})),
					manualReviewFlags: bundle.remediationCandidates,
					warnings: plan.manualTasks,
				});
				artifactsOutcome.artifacts.reportFile = reportFile;
			}

			return {
				status: resolveImportStatus(plan, artifactsOutcome.failedMedia),
				importedRecords: bundle.contentRecords.length,
				importedMedia: plan.includeMedia ? bundle.mediaAssets.length : 0,
				importedComments: plan.includeComments ? bundle.comments.length : 0,
				importedUsers: plan.includeUsers ? bundle.authors.length : 0,
				importedRedirects: bundle.redirects.length,
				downloadedMedia: artifactsOutcome.downloadedMedia,
				failedMedia: artifactsOutcome.failedMedia,
				reviewRequired: plan.reviewRequired,
				manualTasks: plan.manualTasks,
				plan,
				inventory,
				artifacts: artifactsOutcome.artifacts,
				localApply,
				warnings: [
					...new Set([
						...inventory.warnings,
						...plan.manualTasks,
						...(localApply
							? [
									`Applied WordPress import into local SQLite runtime at ${localApply.adminDbPath}.`,
								]
							: []),
						...artifactsOutcome.failedMedia.map(
							(e) => `Media download failed for ${e.id}: ${e.reason}`,
						),
					]),
				],
			} satisfies AstropressWordPressImportReport;
		},
		async resumeWordPressImport(input) {
			return this.importWordPress({
				...input,
				sourceUrl: input.sourceUrl ?? options.sourceUrl,
				artifactDir: input.artifactDir,
				resumeFrom: path.join(input.artifactDir, "download-state.json"),
			});
		},
	};
}

src/local-image-storage.ts.source:
import { existsSync, mkdirSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const workspaceRoot = process.cwd();
const defaultImageRoot = path.join(
	tmpdir(),
	"astropress",
	"local-images",
	path.basename(workspaceRoot),
);

export function getLocalImageRoot() {
	return (
		process.env.ASTROPRESS_LOCAL_IMAGE_ROOT?.trim() ||
		process.env.LOCAL_IMAGE_ROOT?.trim() ||
		defaultImageRoot
	);
}

export function getLocalUploadsDir() {
	return path.join(getLocalImageRoot(), "uploads");
}

export function ensureLocalUploadsDir() {
	mkdirSync(getLocalUploadsDir(), { recursive: true });
}

export function guessImageMimeType(pathname: string) {
	const lower = pathname.toLowerCase();
	if (lower.endsWith(".svg")) return "image/svg+xml";
	if (lower.endsWith(".png")) return "image/png";
	if (lower.endsWith(".webp")) return "image/webp";
	if (lower.endsWith(".gif")) return "image/gif";
	if (lower.endsWith(".avif")) return "image/avif";
	return "image/jpeg";
}

export function resolveLocalImageDiskPath(publicPath: string) {
	if (!publicPath.startsWith("/images/")) {
		throw new Error(`Expected image path under /images/: ${publicPath}`);
	}

	const relativePath = publicPath.slice("/images/".length);
	return path.join(getLocalImageRoot(), relativePath);
}

export function readLocalImageAsset(publicPath: string) {
	const diskPath = resolveLocalImageDiskPath(publicPath);
	if (!existsSync(diskPath)) {
		return { ok: false as const, error: "Image not found." };
	}

	const bytes = readFileSync(diskPath);
	const arrayBuffer = bytes.buffer.slice(
		bytes.byteOffset,
		bytes.byteOffset + bytes.byteLength,
	);

	return {
		ok: true as const,
		asset: {
			diskPath,
			bytes: arrayBuffer,
			mimeType: guessImageMimeType(diskPath),
		},
	};
}

/**
 * Generate responsive srcset variants (400, 800, 1200px WebP) for an image using Sharp.
 *
 * The `storeVariant` callback handles persistence — it receives a filename and bytes and
 * returns the public URL string, or null when storage fails. This abstraction lets the
 * caller use local disk, R2, or any other backend without this function knowing the
 * difference.
 *
 * Uses `withoutEnlargement: true` so images narrower than a breakpoint skip that variant.
 * Returns null when Sharp is unavailable (e.g. Cloudflare Workers) or on error.
 */
export async function generateSrcset(
	bytes: Uint8Array,
	originalPublicPath: string,
	storeVariant: (
		filename: string,
		variantBytes: Uint8Array,
	) => Promise<string | null>,
): Promise<string | null> {
	try {
		const sharp = (await import("sharp")).default;
		const widths = [400, 800, 1200] as const;
		const parts: string[] = [];

		const dot = originalPublicPath.lastIndexOf(".");
		const noExt =
			dot > 0 ? originalPublicPath.slice(0, dot) : originalPublicPath;
		const basename = noExt
			.replace(/^\/images\/uploads\//, "")
			.replace(/^\/images\//, "");

		for (const w of widths) {
			const variantBuffer = await sharp(Buffer.from(bytes))
				.resize({ width: w, withoutEnlargement: true })
				.webp()
				.toBuffer();
			const variantFilename = `${basename}-${w}w.webp`;
			const variantPath = await storeVariant(
				variantFilename,
				new Uint8Array(variantBuffer),
			);
			if (variantPath) {
				parts.push(`${variantPath} ${w}w`);
			}
		}

		return parts.length > 0 ? parts.join(", ") : null;
	} catch {
		return null;
	}
}

