import type { AstropressAppHost } from "./app-host-targets";
import type { AstropressDataServices } from "./data-service-targets";
import {
	getAstropressDeploymentMatrixEntry,
	resolveAstropressDeploymentSupportLevel,
} from "./deployment-matrix";
import {
	createCiFiles,
	createDeployDoc,
	createPackageScripts,
} from "./project-scaffold-ci";
import {
	appHostToDeployTarget,
	baseEnvExample,
	baseLocalEnv,
	buildAbTestingEnvExample,
	buildAnalyticsEnvExample,
	buildApiEnvExample,
	buildDataServiceExample,
	buildDonationsEnvExample,
	buildHeatmapEnvExample,
	deriveLegacyProvider,
} from "./project-scaffold-env";

export type AstropressScaffoldProvider = "sqlite" | "supabase";

export type AstropressAnalyticsProvider =
	| "umami"
	| "plausible"
	| "matomo"
	| "posthog"
	| "custom";
export type AstropressAbTestingProvider = "growthbook" | "unleash" | "custom";
export type AstropressHeatmapProvider = "openreplay" | "posthog" | "custom";

export interface AstropressDonationsProviders {
	giveLively?: boolean;
	liberapay?: boolean;
	pledgeCrypto?: boolean;
}

export interface AstropressProjectScaffoldInput {
	appHost?: AstropressAppHost;
	dataServices?: AstropressDataServices;
	legacyProvider?: AstropressScaffoldProvider;
	analytics?: AstropressAnalyticsProvider;
	abTesting?: AstropressAbTestingProvider;
	heatmap?: AstropressHeatmapProvider;
	enableApi?: boolean;
	donations?: AstropressDonationsProviders;
}

export interface AstropressProjectScaffold {
	provider: AstropressScaffoldProvider;
	appHost: AstropressAppHost;
	dataServices: AstropressDataServices;
	contentServices: AstropressDataServices;
	recommendedDeployTarget: string;
	recommendationRationale: string;
	supportLevel: string;
	localEnv: Record<string, string>;
	envExample: Record<string, string>;
	packageScripts: Record<string, string>;
	ciFiles: Record<string, string>;
	deployDoc: string;
	requiredEnvKeys: string[];
}

function resolveProfile(
	input: AstropressProjectScaffoldInput | AstropressScaffoldProvider,
): {
	appHost: AstropressAppHost;
	dataServices: AstropressDataServices;
	provider: AstropressScaffoldProvider;
} {
	if (typeof input === "string") {
		if (input === "supabase")
			return {
				appHost: "vercel",
				dataServices: "supabase",
				provider: "supabase",
			};
		return {
			appHost: "github-pages",
			dataServices: "none",
			provider: "sqlite",
		};
	}

	const dataServices =
		input.dataServices ??
		(input.legacyProvider === "supabase" ? "supabase" : "none");
	return {
		appHost:
			input.appHost ??
			(dataServices === "cloudflare"
				? "cloudflare-pages"
				: dataServices === "supabase"
					? "vercel"
					: dataServices === "appwrite" ||
							dataServices === "pocketbase" ||
							dataServices === "nhost" ||
							dataServices === "neon" ||
							dataServices === "turso"
						? "render-web"
						: "github-pages"),
		dataServices,
		provider: input.legacyProvider ?? deriveLegacyProvider(dataServices),
	};
}

/**
 * Generate a complete project scaffold configuration for the given deployment
 * profile, including environment variables, package scripts, CI files, and
 * deployment documentation.
 *
 * @example
 * ```ts
 * import { createAstropressProjectScaffold } from "@astropress-diy/astropress";
 *
 * const scaffold = createAstropressProjectScaffold({ appHost: "vercel", dataServices: "supabase" });
 * // scaffold.localEnv  — object of env vars to write to .env
 * // scaffold.envExample — object of env vars to write to .env.example
 * // scaffold.packageScripts — scripts to merge into package.json
 * ```
 */
export function createAstropressProjectScaffold(
	input: AstropressProjectScaffoldInput | AstropressScaffoldProvider = "sqlite",
): AstropressProjectScaffold {
	const profile = resolveProfile(input);
	const supportLevel = resolveAstropressDeploymentSupportLevel({
		appHost: profile.appHost,
		dataServices: profile.dataServices,
	});
	const matrixEntry = getAstropressDeploymentMatrixEntry({
		appHost: profile.appHost,
		dataServices: profile.dataServices,
	});
	const recommendationRationale =
		matrixEntry?.notes ??
		`Astropress does not yet mark ${profile.appHost} + ${profile.dataServices} as a first-class pair. Keep this combination in preview until you validate the missing runtime and operational pieces yourself.`;
	const requiredEnvKeys = matrixEntry?.requiredEnvKeys ?? [];

	const analyticsOpt = typeof input === "string" ? undefined : input.analytics;
	const abTestingOpt = typeof input === "string" ? undefined : input.abTesting;
	const heatmapOpt = typeof input === "string" ? undefined : input.heatmap;
	const enableApi =
		typeof input === "string" ? false : (input.enableApi ?? false);
	const donationsOpt = typeof input === "string" ? undefined : input.donations;

	const localEnv = baseLocalEnv(
		profile.provider,
		profile.appHost,
		profile.dataServices,
	);
	if (enableApi) localEnv.ASTROPRESS_API_ENABLED = "true";

	return {
		provider: profile.provider,
		appHost: profile.appHost,
		dataServices: profile.dataServices,
		contentServices: profile.dataServices,
		recommendedDeployTarget: appHostToDeployTarget(profile.appHost),
		recommendationRationale,
		supportLevel,
		localEnv,
		envExample: {
			...baseEnvExample(
				profile.provider,
				profile.appHost,
				profile.dataServices,
			),
			...buildDataServiceExample(profile.dataServices),
			...buildAnalyticsEnvExample(analyticsOpt),
			...buildAbTestingEnvExample(abTestingOpt),
			...buildHeatmapEnvExample(heatmapOpt),
			...(enableApi ? buildApiEnvExample() : {}),
			...buildDonationsEnvExample(donationsOpt),
		},
		packageScripts: createPackageScripts(profile.appHost),
		ciFiles: createCiFiles(profile.appHost, requiredEnvKeys, donationsOpt),
		deployDoc: createDeployDoc(
			profile.appHost,
			profile.dataServices,
			supportLevel,
			requiredEnvKeys,
		),
		requiredEnvKeys,
	};
}

src/provider-choice.ts.source:
import {
	type AstropressDeploymentSupportLevel,
	getAstropressDeploymentMatrixEntry,
	resolveAstropressDeploymentSupportLevel,
} from "./deployment-matrix";
import type {
	AstropressAppHostEnv,
	AstropressDataServicesEnv,
	AstropressDeployTargetEnv,
} from "./project-env";

export type AstropressProviderOpsComfort = "minimal" | "moderate" | "advanced";
export type AstropressExistingPlatform =
	| "none"
	| "cloudflare"
	| "supabase"
	| "appwrite";

export interface AstropressProviderChoiceInput {
	existingPlatform?: AstropressExistingPlatform;
	wantsHostedAdmin?: boolean;
	wantsStaticMirror?: boolean;
	opsComfort?: AstropressProviderOpsComfort;
}

export interface AstropressProviderChoiceRecommendation {
	appHost: AstropressAppHostEnv;
	dataServices: AstropressDataServicesEnv;
	supportLevel: AstropressDeploymentSupportLevel;
	rationale: string;
	requiredEnvKeys: string[];
	deployTarget: AstropressDeployTargetEnv;
	canonicalProvider: "cloudflare" | "supabase" | "appwrite";
	publicDeployTarget: AstropressDeployTargetEnv;
}

function appHostToDeployTarget(
	appHost: AstropressAppHostEnv,
): AstropressDeployTargetEnv {
	return appHost === "cloudflare-pages" ? "cloudflare" : appHost;
}

function finalizeRecommendation(
	appHost: AstropressAppHostEnv,
	dataServices: AstropressDataServicesEnv,
	rationale: string,
): AstropressProviderChoiceRecommendation {
	const entry = getAstropressDeploymentMatrixEntry({ appHost, dataServices });
	const deployTarget = appHostToDeployTarget(appHost);
	return {
		appHost,
		dataServices,
		supportLevel: resolveAstropressDeploymentSupportLevel({
			appHost,
			dataServices,
		}),
		rationale: entry?.notes ? `${rationale} ${entry.notes}` : rationale,
		requiredEnvKeys: entry?.requiredEnvKeys ?? [],
		deployTarget,
		canonicalProvider:
			dataServices === "cloudflare" ||
			dataServices === "supabase" ||
			dataServices === "appwrite"
				? dataServices
				: "cloudflare",
		publicDeployTarget: deployTarget,
	};
}

/**
 * Analyze user preferences and return a recommended provider combination with
 * rationale and required environment keys.
 *
 * @example
 * ```ts
 * import { recommendAstropressProvider } from "@astropress-diy/astropress";
 *
 * const rec = recommendAstropressProvider({ existingPlatform: "supabase" });
 * console.log(rec.appHost);       // "vercel"
 * console.log(rec.dataServices);  // "supabase"
 * console.log(rec.supportLevel);  // "supported"
 * ```
 */
export function recommendAstropressProvider(
	input: AstropressProviderChoiceInput = {},
): AstropressProviderChoiceRecommendation {
	const existingPlatform = input.existingPlatform ?? "none";
	const wantsHostedAdmin = input.wantsHostedAdmin ?? true;
	const wantsStaticMirror = input.wantsStaticMirror ?? false;
	const opsComfort = input.opsComfort ?? "minimal";

	if (existingPlatform === "supabase") {
		return finalizeRecommendation(
			wantsStaticMirror ? "github-pages" : "vercel",
			"supabase",
			"Supabase is already the content-services platform, so Astropress should keep Supabase for data, auth, storage, and the Astropress service API while using a separate Astro app host.",
		);
	}

	if (existingPlatform === "appwrite") {
		return finalizeRecommendation(
			wantsStaticMirror ? "github-pages" : "render-web",
			"appwrite",
			"Appwrite is already the content-services platform, so Astropress should keep Appwrite for data, auth, media, and the Astropress service API while choosing a separate Astro app host.",
		);
	}

	if (existingPlatform === "cloudflare" || opsComfort === "advanced") {
		return finalizeRecommendation(
			wantsStaticMirror ? "github-pages" : "cloudflare-pages",
			"cloudflare",
			"Cloudflare is the best fit for teams already comfortable with its edge/runtime model and wanting one provider to cover app hosting plus content services.",
		);
	}

	if (!wantsHostedAdmin && wantsStaticMirror) {
		return finalizeRecommendation(
			"github-pages",
			"none",
			"GitHub Pages is the clearest low-ops choice when the project only needs static Astro output and no hosted Astropress admin backend.",
		);
	}

	if (!wantsHostedAdmin) {
		return finalizeRecommendation(
			"github-pages",
			"none",
			"A static Astro deployment keeps the public site simple when hosted Astropress services are not required.",
		);
	}

	return finalizeRecommendation(
		"cloudflare-pages",
		"cloudflare",
		"Cloudflare is still the default recommendation for most Astropress users because it keeps the app host and the content-services layer aligned under one operational model.",
	);
}

