// ─── Structured Page Route Mutations ─────────────────────────────────────────
// Extracted from runtime-route-registry-pages.ts to keep that file under the 400-line limit.

import { normalizePath } from "./admin-normalizers";
import { recordD1Audit } from "./d1-audit";
import { getCloudflareBindings } from "./runtime-env";
import {
	type RuntimeStructuredPageRouteRecord,
	loadSafeLocalCmsRegistry,
	localeFromPath,
} from "./runtime-route-registry-dispatch";

interface Actor {
	email: string;
	role: "admin" | "editor";
	name: string;
}

type D1Like = ReturnType<typeof getCloudflareBindings>["DB"];

const SQL_CHECK_VARIANT_PATH =
	"SELECT v.id FROM cms_route_variants v WHERE v.path = ? LIMIT 1";
const SQL_FIND_STRUCTURED_ROUTE = `
  SELECT v.id
  FROM cms_route_variants v
  INNER JOIN cms_route_groups g ON g.id = v.group_id
  WHERE g.kind = 'page' AND g.render_strategy = 'structured_sections' AND v.path = ?
  LIMIT 1
`;
const SQL_UPDATE_ROUTE_VARIANT = `
  UPDATE cms_route_variants
  SET title = ?, summary = ?, seo_title = ?, meta_description = ?, canonical_url_override = ?, robots_directive = ?,
      og_image = ?, sections_json = ?, settings_json = ?, updated_at = CURRENT_TIMESTAMP, updated_by = ?
  WHERE id = ?
`;
const SQL_INSERT_ROUTE_REVISION = `
  INSERT INTO cms_route_revisions (id, variant_id, route_path, locale, snapshot_json, revision_note, created_by)
  VALUES (?, ?, ?, ?, ?, ?, ?)
`;
const SQL_INSERT_ROUTE_GROUP = `
  INSERT INTO cms_route_groups (id, kind, render_strategy, canonical_locale, canonical_path)
  VALUES (?, 'page', 'structured_sections', ?, ?)
`;
const SQL_INSERT_NEW_ROUTE_VARIANT = `
  INSERT INTO cms_route_variants (
    id, group_id, locale, path, status, title, summary, sections_json, settings_json,
    seo_title, meta_description, og_image, canonical_url_override, robots_directive, updated_by
  ) VALUES (?, ?, ?, ?, 'published', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
`;

/** Check if a variant path already exists. */
async function isVariantPathTaken(
	db: NonNullable<D1Like>,
	normalizedPath: string,
): Promise<boolean> {
	const existing = await db
		.prepare(SQL_CHECK_VARIANT_PATH)
		.bind(normalizedPath)
		.first<{ id: string }>();
	return !!existing;
}

/** Normalize optional route page input fields, centralising branchy fallback logic. */
function normalizeRoutePageInput(input: {
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks?: Array<{ hreflang: string; href: string }>;
	sections?: Record<string, unknown> | null;
}) {
	const title = input.title.trim();
	const summary = input.summary?.trim() || null;
	const seoTitle = input.seoTitle?.trim() || title;
	const metaDescription = input.metaDescription?.trim() || summary || title;
	const canonicalUrlOverride = input.canonicalUrlOverride?.trim() || null;
	const robotsDirective = input.robotsDirective?.trim() || null;
	const ogImage = input.ogImage?.trim() || null;
	const sectionsJson = input.sections ? JSON.stringify(input.sections) : null;
	const settingsJson = JSON.stringify({
		templateKey: input.templateKey,
		alternateLinks: input.alternateLinks ?? [],
	});
	return {
		title,
		summary,
		seoTitle,
		metaDescription,
		canonicalUrlOverride,
		robotsDirective,
		ogImage,
		sectionsJson,
		settingsJson,
	};
}

/** Build the route record returned to the caller after a save/create. */
function buildRouteResult(
	normalizedPath: string,
	fields: ReturnType<typeof normalizeRoutePageInput>,
	input: {
		templateKey: string;
		alternateLinks?: Array<{ hreflang: string; href: string }>;
		sections?: Record<string, unknown> | null;
	},
): RuntimeStructuredPageRouteRecord {
	return {
		path: normalizedPath,
		title: fields.title,
		summary: fields.summary ?? undefined,
		seoTitle: fields.seoTitle,
		metaDescription: fields.metaDescription,
		canonicalUrlOverride: fields.canonicalUrlOverride ?? undefined,
		robotsDirective: fields.robotsDirective ?? undefined,
		ogImage: fields.ogImage ?? undefined,
		templateKey: input.templateKey,
		alternateLinks: input.alternateLinks ?? [],
		sections: input.sections ?? null,
	};
}

/** Build the snapshot JSON for a route revision. */
function buildRouteSnapshot(
	normalizedPath: string,
	fields: ReturnType<typeof normalizeRoutePageInput>,
	input: {
		templateKey: string;
		alternateLinks?: Array<{ hreflang: string; href: string }>;
		sections?: Record<string, unknown> | null;
	},
) {
	return JSON.stringify({
		path: normalizedPath,
		title: fields.title,
		summary: fields.summary,
		seoTitle: fields.seoTitle,
		metaDescription: fields.metaDescription,
		canonicalUrlOverride: fields.canonicalUrlOverride,
		robotsDirective: fields.robotsDirective,
		ogImage: fields.ogImage,
		templateKey: input.templateKey,
		alternateLinks: input.alternateLinks ?? [],
		sections: input.sections ?? null,
	});
}

export async function saveRuntimeStructuredPageRoute(
	pathname: string,
	input: {
		title: string;
		summary?: string;
		seoTitle?: string;
		metaDescription?: string;
		canonicalUrlOverride?: string;
		robotsDirective?: string;
		ogImage?: string;
		templateKey: string;
		alternateLinks?: Array<{ hreflang: string; href: string }>;
		sections?: Record<string, unknown> | null;
		revisionNote?: string;
	},
	actor: Actor,
	locals?: App.Locals | null,
) {
	const normalizedPath = normalizePath(pathname);
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		if (!local) {
			return {
				ok: false as const,
				error: "The runtime content registry is unavailable.",
			};
		}
		/* v8 ignore next 2 */
		return local.saveStructuredPageRoute(normalizedPath, input, actor);
	}

	const route = await db
		.prepare(SQL_FIND_STRUCTURED_ROUTE)
		.bind(normalizedPath)
		.first<{ id: string }>();

	if (!route) {
		return {
			ok: false as const,
			error: "The selected route page could not be found.",
		};
	}

	const f = normalizeRoutePageInput(input);
	if (!f.title) {
		return { ok: false as const, error: "A title is required." };
	}

	await db
		.prepare(SQL_UPDATE_ROUTE_VARIANT)
		.bind(
			f.title,
			f.summary,
			f.seoTitle,
			f.metaDescription,
			f.canonicalUrlOverride,
			f.robotsDirective,
			f.ogImage,
			f.sectionsJson,
			f.settingsJson,
			actor.email,
			route.id,
		)
		.run();

	await db
		.prepare(SQL_INSERT_ROUTE_REVISION)
		.bind(
			`revision:${route.id}:${crypto.randomUUID()}`,
			route.id,
			normalizedPath,
			localeFromPath(normalizedPath),
			buildRouteSnapshot(normalizedPath, f, input),
			input.revisionNote?.trim() || null,
			actor.email,
		)
		.run();

	await recordD1Audit(
		locals,
		actor,
		"system.update",
		"content",
		normalizedPath,
		`Updated system route ${normalizedPath}.`,
	);
	return {
		ok: true as const,
		route: buildRouteResult(normalizedPath, f, input),
	};
}

export async function createRuntimeStructuredPageRoute(
	pathname: string,
	input: {
		title: string;
		summary?: string;
		seoTitle?: string;
		metaDescription?: string;
		canonicalUrlOverride?: string;
		robotsDirective?: string;
		ogImage?: string;
		templateKey: string;
		alternateLinks?: Array<{ hreflang: string; href: string }>;
		sections?: Record<string, unknown> | null;
		revisionNote?: string;
	},
	actor: Actor,
	locals?: App.Locals | null,
) {
	const normalizedPath = normalizePath(pathname);
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		if (!local) {
			return {
				ok: false as const,
				error: "The runtime content registry is unavailable.",
			};
		}
		/* v8 ignore next 2 */
		return local.createStructuredPageRoute(normalizedPath, input, actor);
	}

	if (await isVariantPathTaken(db, normalizedPath)) {
		return { ok: false as const, error: "That public path is already in use." };
	}

	const f = normalizeRoutePageInput(input);
	if (!f.title) {
		return { ok: false as const, error: "A title is required." };
	}

	const groupId = `route-group:${crypto.randomUUID()}`;
	const variantId = `route-variant:${crypto.randomUUID()}`;
	const locale = localeFromPath(normalizedPath);

	await db
		.prepare(SQL_INSERT_ROUTE_GROUP)
		.bind(groupId, locale, normalizedPath)
		.run();

	await db
		.prepare(SQL_INSERT_NEW_ROUTE_VARIANT)
		.bind(
			variantId,
			groupId,
			locale,
			normalizedPath,
			f.title,
			f.summary,
			f.sectionsJson,
			f.settingsJson,
			f.seoTitle,
			f.metaDescription,
			f.ogImage,
			f.canonicalUrlOverride,
			f.robotsDirective,
			actor.email,
		)
		.run();

	await db
		.prepare(SQL_INSERT_ROUTE_REVISION)
		.bind(
			`revision:${variantId}:${crypto.randomUUID()}`,
			variantId,
			normalizedPath,
			locale,
			buildRouteSnapshot(normalizedPath, f, input),
			input.revisionNote?.trim() || "Created route page.",
			actor.email,
		)
		.run();

	await recordD1Audit(
		locals,
		actor,
		"system.update",
		"content",
		normalizedPath,
		`Updated system route ${normalizedPath}.`,
	);
	return {
		ok: true as const,
		route: buildRouteResult(normalizedPath, f, input),
	};
}

src/runtime-route-registry-pages.ts.source:
import { normalizePath } from "./admin-normalizers";
import { getCmsConfig } from "./config";
import { getCloudflareBindings } from "./runtime-env";
import {
	type RuntimeStructuredPageRouteRecord,
	loadSafeLocalCmsRegistry,
	parseSettings,
	withSafeRouteRegistryFallback,
} from "./runtime-route-registry-dispatch";

// ─── Mutations — extracted to runtime-route-registry-pages-mutations.ts ──────
export {
	saveRuntimeStructuredPageRoute,
	createRuntimeStructuredPageRoute,
} from "./runtime-route-registry-pages-mutations";

function normalizeStructuredTemplateKey(value: unknown): string | null {
	if (typeof value !== "string" || !value) {
		return null;
	}
	return getCmsConfig().templateKeys.includes(value) ? value : null;
}

function mapStructuredPageRow(
	row:
		| {
				path: string;
				title: string;
				summary: string | null;
				seo_title: string | null;
				meta_description: string | null;
				canonical_url_override: string | null;
				robots_directive: string | null;
				og_image: string | null;
				sections_json: string | null;
				settings_json: string | null;
				updated_at: string;
		  }
		| null
		| undefined,
) {
	if (!row) {
		return null;
	}

	const settings = parseSettings(row.settings_json) ?? {};
	const templateKey = normalizeStructuredTemplateKey(settings.templateKey);
	if (!templateKey) {
		return null;
	}
	return {
		path: row.path,
		title: row.title,
		summary: row.summary ?? undefined,
		seoTitle: row.seo_title ?? undefined,
		metaDescription: row.meta_description ?? undefined,
		canonicalUrlOverride: row.canonical_url_override ?? undefined,
		robotsDirective: row.robots_directive ?? undefined,
		ogImage: row.og_image ?? undefined,
		templateKey,
		alternateLinks: Array.isArray(settings.alternateLinks)
			? (settings.alternateLinks as Array<{ hreflang: string; href: string }>)
			: [],
		sections: parseSettings(row.sections_json),
		updatedAt: row.updated_at,
	} satisfies RuntimeStructuredPageRouteRecord;
}

export async function listRuntimeStructuredPageRoutes(
	locals?: App.Locals | null,
) {
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		/* v8 ignore next 2 */
		return local ? local.listStructuredPageRoutes() : [];
	}

	return withSafeRouteRegistryFallback(
		(local) => local.listStructuredPageRoutes(),
		[],
		async () => {
			const rows = (
				await db
					.prepare(
						`
              SELECT v.path, v.title, v.summary, v.seo_title, v.meta_description, v.canonical_url_override, v.robots_directive,
                     v.og_image, v.sections_json, v.settings_json, v.updated_at
              FROM cms_route_variants v
              INNER JOIN cms_route_groups g ON g.id = v.group_id
              WHERE g.kind = 'page' AND g.render_strategy = 'structured_sections'
              ORDER BY v.path ASC
            `,
					)
					.all<{
						path: string;
						title: string;
						summary: string | null;
						seo_title: string | null;
						meta_description: string | null;
						canonical_url_override: string | null;
						robots_directive: string | null;
						og_image: string | null;
						sections_json: string | null;
						settings_json: string | null;
						updated_at: string;
					}>()
			).results;

			return rows.map((row) => mapStructuredPageRow(row)).filter(Boolean);
		},
	);
}

export async function getRuntimeStructuredPageRoute(
	pathname: string,
	locals?: App.Locals | null,
) {
	const normalizedPath = normalizePath(pathname);
	const db = getCloudflareBindings(locals).DB;
	/* v8 ignore start */
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		return local ? local.getStructuredPageRoute(normalizedPath) : null;
	}
	/* v8 ignore stop */

	return withSafeRouteRegistryFallback(
		(local) => local.getStructuredPageRoute(normalizedPath),
		null,
		async () => {
			const row = await db
				.prepare(
					`
            SELECT v.path, v.title, v.summary, v.seo_title, v.meta_description, v.canonical_url_override, v.robots_directive,
                   v.og_image, v.sections_json, v.settings_json, v.updated_at
            FROM cms_route_variants v
            INNER JOIN cms_route_groups g ON g.id = v.group_id
            WHERE g.kind = 'page' AND g.render_strategy = 'structured_sections' AND v.path = ?
            LIMIT 1
          `,
				)
				.bind(normalizedPath)
				.first<{
					path: string;
					title: string;
					summary: string | null;
					seo_title: string | null;
					meta_description: string | null;
					canonical_url_override: string | null;
					robots_directive: string | null;
					og_image: string | null;
					sections_json: string | null;
					settings_json: string | null;
					updated_at: string;
				}>();

			return mapStructuredPageRow(row);
		},
	);
}

src/runtime-route-registry-system.ts.source:
import { normalizePath } from "./admin-normalizers";
import { recordD1Audit } from "./d1-audit";
import type { D1DatabaseLike } from "./d1-database";
import { getCloudflareBindings } from "./runtime-env";
import {
	type RuntimeSystemRouteRecord,
	loadSafeLocalCmsRegistry,
	localeFromPath,
	parseSettings,
	withSafeRouteRegistryFallback,
} from "./runtime-route-registry-dispatch";

interface Actor {
	email: string;
	role: "admin" | "editor";
	name: string;
}

function mapSystemRow(
	row:
		| {
				path: string;
				title: string;
				summary: string | null;
				body_html: string | null;
				settings_json: string | null;
				updated_at: string;
				render_strategy: RuntimeSystemRouteRecord["renderStrategy"];
		  }
		| null
		| undefined,
): RuntimeSystemRouteRecord | null {
	if (!row) {
		return null;
	}

	return {
		path: row.path,
		title: row.title,
		summary: row.summary ?? undefined,
		bodyHtml: row.body_html ?? undefined,
		settings: parseSettings(row.settings_json),
		updatedAt: row.updated_at,
		renderStrategy: row.render_strategy,
	};
}

export async function listRuntimeSystemRoutes(locals?: App.Locals | null) {
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		/* v8 ignore next 2 */
		return local ? local.listSystemRoutes() : [];
	}

	return withSafeRouteRegistryFallback(
		(local) => local.listSystemRoutes(),
		[],
		async () => {
			const rows = (
				await db
					.prepare(
						`
              SELECT v.path, v.title, v.summary, v.body_html, v.settings_json, v.updated_at, g.render_strategy
              FROM cms_route_variants v
              INNER JOIN cms_route_groups g ON g.id = v.group_id
              WHERE g.kind = 'system'
              ORDER BY v.path ASC
            `,
					)
					.all<{
						path: string;
						title: string;
						summary: string | null;
						body_html: string | null;
						settings_json: string | null;
						updated_at: string;
						render_strategy: RuntimeSystemRouteRecord["renderStrategy"];
					}>()
			).results;

			return rows.map((row) => mapSystemRow(row)).filter(Boolean);
		},
	);
}

export async function getRuntimeSystemRoute(
	pathname: string,
	locals?: App.Locals | null,
) {
	const normalizedPath = normalizePath(pathname);
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		/* v8 ignore next 2 */
		return local ? local.getSystemRoute(normalizedPath) : null;
	}

	return withSafeRouteRegistryFallback(
		(local) => local.getSystemRoute(normalizedPath),
		null,
		async () => {
			const row = await db
				.prepare(
					`
            SELECT v.path, v.title, v.summary, v.body_html, v.settings_json, v.updated_at, g.render_strategy
            FROM cms_route_variants v
            INNER JOIN cms_route_groups g ON g.id = v.group_id
            WHERE g.kind = 'system' AND v.path = ?
            LIMIT 1
          `,
				)
				.bind(normalizedPath)
				.first<{
					path: string;
					title: string;
					summary: string | null;
					body_html: string | null;
					settings_json: string | null;
					updated_at: string;
					render_strategy: RuntimeSystemRouteRecord["renderStrategy"];
				}>();

			return mapSystemRow(row);
		},
	);
}

function validateSystemRouteInput(input: {
	title: string;
	summary?: string;
	bodyHtml?: string;
	settings?: Record<string, unknown> | null;
}) {
	const title = input.title.trim();
	if (!title) {
		return { ok: false as const, error: "A title is required." } as const;
	}

	const summary = input.summary?.trim() || null;
	const bodyHtml = input.bodyHtml?.trim() || null;
	const settingsJson = input.settings ? JSON.stringify(input.settings) : null;

	return { ok: true as const, title, summary, bodyHtml, settingsJson };
}

function buildSystemRouteSnapshot(
	normalizedPath: string,
	validated: { title: string; summary: string | null; bodyHtml: string | null },
	settings: Record<string, unknown> | null | undefined,
	renderStrategy: RuntimeSystemRouteRecord["renderStrategy"],
) {
	return JSON.stringify({
		path: normalizedPath,
		title: validated.title,
		summary: validated.summary,
		bodyHtml: validated.bodyHtml,
		settings: settings ?? null,
		renderStrategy,
	});
}

function buildSystemRouteResult(
	normalizedPath: string,
	validated: { title: string; summary: string | null; bodyHtml: string | null },
	settings: Record<string, unknown> | null | undefined,
	renderStrategy: RuntimeSystemRouteRecord["renderStrategy"],
) {
	return {
		ok: true as const,
		route: {
			path: normalizedPath,
			title: validated.title,
			summary: validated.summary ?? undefined,
			bodyHtml: validated.bodyHtml ?? undefined,
			settings: settings ?? null,
			renderStrategy,
		} satisfies RuntimeSystemRouteRecord,
	};
}

const UPDATE_SYSTEM_VARIANT_SQL = `
  UPDATE cms_route_variants
  SET
    title = ?,
    summary = ?,
    body_html = ?,
    settings_json = ?,
    seo_title = ?,
    meta_description = ?,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = ?
  WHERE id = ?
`;

const INSERT_SYSTEM_REVISION_SQL = `
  INSERT INTO cms_route_revisions (id, variant_id, route_path, locale, snapshot_json, revision_note, created_by)
  VALUES (?, ?, ?, ?, ?, ?, ?)
`;

async function persistSystemRouteChanges(
	db: D1DatabaseLike,
	routeId: string,
	renderStrategy: RuntimeSystemRouteRecord["renderStrategy"],
	normalizedPath: string,
	validated: {
		title: string;
		summary: string | null;
		bodyHtml: string | null;
		settingsJson: string | null;
	},
	settings: Record<string, unknown> | null | undefined,
	revisionNote: string | undefined,
	actor: Actor,
	locals: App.Locals | null | undefined,
) {
	const metaDescription = validated.summary ?? validated.title;
	await db
		.prepare(UPDATE_SYSTEM_VARIANT_SQL)
		.bind(
			validated.title,
			validated.summary,
			validated.bodyHtml,
			validated.settingsJson,
			validated.title,
			metaDescription,
			actor.email,
			routeId,
		)
		.run();

	await db
		.prepare(INSERT_SYSTEM_REVISION_SQL)
		.bind(
			`revision:${routeId}:${crypto.randomUUID()}`,
			routeId,
			normalizedPath,
			localeFromPath(normalizedPath),
			buildSystemRouteSnapshot(
				normalizedPath,
				validated,
				settings,
				renderStrategy,
			),
			revisionNote?.trim() || null,
			actor.email,
		)
		.run();

	await recordD1Audit(
		locals,
		actor,
		"system.update",
		"content",
		normalizedPath,
		`Updated system route ${normalizedPath}.`,
	);

	return buildSystemRouteResult(
		normalizedPath,
		validated,
		settings,
		renderStrategy,
	);
}

export async function saveRuntimeSystemRoute(
	pathname: string,
	input: {
		title: string;
		summary?: string;
		bodyHtml?: string;
		settings?: Record<string, unknown> | null;
		revisionNote?: string;
	},
	actor: Actor,
	locals?: App.Locals | null,
) {
	const normalizedPath = normalizePath(pathname);
	const db = getCloudflareBindings(locals).DB;
	if (!db) {
		const local = await loadSafeLocalCmsRegistry();
		if (!local) {
			return {
				ok: false as const,
				error: "The runtime content registry is unavailable.",
			};
		}
		/* v8 ignore next 2 */
		return local.saveSystemRoute(normalizedPath, input, actor);
	}

	const route = await db
		.prepare(
			`
        SELECT v.id, g.render_strategy
        FROM cms_route_variants v
        INNER JOIN cms_route_groups g ON g.id = v.group_id
        WHERE g.kind = 'system' AND v.path = ?
        LIMIT 1
      `,
		)
		.bind(normalizedPath)
		.first<{
			id: string;
			render_strategy: RuntimeSystemRouteRecord["renderStrategy"];
		}>();

	if (!route) {
		return {
			ok: false as const,
			error: "The selected system route could not be found.",
		};
	}

	const validated = validateSystemRouteInput(input);
	if (!validated.ok) {
		return validated;
	}

	return persistSystemRouteChanges(
		db,
		route.id,
		route.render_strategy,
		normalizedPath,
		validated,
		input.settings,
		input.revisionNote,
		actor,
		locals,
	);
}

src/security-headers.ts.source:
export type AstropressSecurityArea = "admin" | "auth" | "public" | "api";

export interface AstropressSecurityHeadersOptions {
	area?: AstropressSecurityArea;
	allowInlineStyles?: boolean;
	frameAncestors?: "'none'" | "'self'";
	forceHsts?: boolean;
	reportUri?: string;
}

function parseOrigin(value: string): URL | null {
	try {
		return new URL(value);
	} catch {
		return null;
	}
}

function buildContentSecurityPolicy(
	options: Required<AstropressSecurityHeadersOptions>,
) {
	const styleSource = options.allowInlineStyles
		? "style-src 'self' 'unsafe-inline'"
		: "style-src 'self'";
	const objectSource =
		options.area === "public" ? "object-src 'self'" : "object-src 'none'";
	const formAction =
		options.area === "public"
			? "form-action 'self' https:"
			: "form-action 'self'";

	const directives = [
		"default-src 'self'",
		"base-uri 'self'",
		`frame-ancestors ${options.frameAncestors}`,
		formAction,
		"img-src 'self' data: https:",
		"font-src 'self' data: https:",
		"connect-src 'self' https:",
		"media-src 'self' data: https:",
		"script-src 'self' https://challenges.cloudflare.com",
		styleSource,
		objectSource,
		"frame-src 'self' https://challenges.cloudflare.com",
		"worker-src 'self' blob:",
		"manifest-src 'self'",
		"upgrade-insecure-requests",
	];

	if (options.reportUri) {
		directives.push(
			`report-uri ${options.reportUri}`,
			"report-to csp-endpoint",
		);
	}

	return directives.join("; ");
}

export function createAstropressSecurityHeaders(
	options: AstropressSecurityHeadersOptions = {},
): Headers {
	const resolved: Required<AstropressSecurityHeadersOptions> = {
		area: options.area ?? "public",
		allowInlineStyles: options.allowInlineStyles ?? false,
		frameAncestors: options.frameAncestors ?? "'none'",
		forceHsts: options.forceHsts ?? false,
		reportUri: options.reportUri ?? "",
	};

	const headers = new Headers();
	headers.set("Content-Security-Policy", buildContentSecurityPolicy(resolved));
	headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
	headers.set("X-Content-Type-Options", "nosniff");
	headers.set(
		"X-Frame-Options",
		resolved.frameAncestors === "'none'" ? "DENY" : "SAMEORIGIN",
	);
	headers.set(
		"Permissions-Policy",
		"camera=(), geolocation=(), microphone=(), payment=(), usb=()",
	);
	headers.set("Cross-Origin-Opener-Policy", "same-origin");

	if (
		resolved.area === "admin" ||
		resolved.area === "api" ||
		resolved.area === "auth"
	) {
		headers.set("Cross-Origin-Resource-Policy", "same-site");
	}

	if (resolved.forceHsts) {
		headers.set(
			"Strict-Transport-Security",
			"max-age=31536000; includeSubDomains",
		);
	}

	if (resolved.reportUri) {
		headers.set(
			"Report-To",
			JSON.stringify({
				group: "csp-endpoint",
				max_age: 86400,
				endpoints: [{ url: resolved.reportUri }],
			}),
		);
	}

	return headers;
}

export function applyCacheHeaders(
	headers: Headers,
	area: AstropressSecurityArea = "public",
	publicCacheTtl?: number,
): void {
	if (area === "public") {
		// Public content: short browser cache, longer CDN cache, stale-while-revalidate for background refresh
		const browserTtl = publicCacheTtl ?? 300;
		const cdnTtl = publicCacheTtl != null ? publicCacheTtl * 12 : 3600;
		headers.set(
			"Cache-Control",
			`public, max-age=${browserTtl}, s-maxage=${cdnTtl}, stale-while-revalidate=86400`,
		);
	} else {
		// Admin, auth, and API responses must never be cached
		headers.set("Cache-Control", "private, no-store");
	}
}

export function applyAstropressSecurityHeaders(
	target: Headers,
	options: AstropressSecurityHeadersOptions = {},
): Headers {
	const generated = createAstropressSecurityHeaders(options);
	generated.forEach((value, key) => {
		target.set(key, value);
	});
	applyCacheHeaders(target, options.area ?? "public");
	return target;
}

export function createAstropressSecureRedirect(
	location: string,
	status = 302,
	options: AstropressSecurityHeadersOptions = {},
): Response {
	const headers = createAstropressSecurityHeaders({ area: "api", ...options });
	headers.set("Location", location);
	return new Response(null, { status, headers });
}

export function isTrustedRequestOrigin(request: Request): boolean {
	let requestOrigin: string;
	try {
		requestOrigin = new URL(request.url).origin;
	} catch {
		return false;
	}

	const rawOrigin = request.headers.get("origin");
	if (rawOrigin !== null) {
		const origin = parseOrigin(rawOrigin);
		if (origin === null) return false;
		return origin.origin === requestOrigin;
	}

	const rawReferer = request.headers.get("referer");
	if (rawReferer !== null) {
		const referer = parseOrigin(rawReferer);
		if (referer === null) return false;
		return referer.origin === requestOrigin;
	}

	return true;
}

export function isTrustedStrictRequestOrigin(request: Request): boolean {
	let requestOrigin: string;
	try {
		requestOrigin = new URL(request.url).origin;
	} catch {
		return false;
	}

	const origin = parseOrigin(request.headers.get("origin") ?? "");
	if (request.headers.get("origin") !== null) {
		if (!origin) return false;
		return origin.origin === requestOrigin;
	}

	const referer = parseOrigin(request.headers.get("referer") ?? "");
	if (request.headers.get("referer") !== null) {
		if (!referer) return false;
		return referer.origin === requestOrigin;
	}

	return false;
}

