import { createAstropressAdminStoreAdapter } from "./admin-store-adapter-factory";
import { peekCmsConfig } from "./config";
import type { AdminStoreAdapter, SessionUser } from "./persistence-types";
import { getAstropressRootSecret } from "./runtime-env";
import { createApiTokenStore } from "./sqlite-runtime/api-tokens";
import { createSqliteAssetsStore } from "./sqlite-runtime/assets";
import { recordAuditEvent } from "./sqlite-runtime/audit-log";
import { createSqliteAuthStore } from "./sqlite-runtime/auth";
import { createSqliteCatalogStore } from "./sqlite-runtime/catalog";
import { createSqliteContentStore } from "./sqlite-runtime/content";
import { createSqliteLocksOps } from "./sqlite-runtime/locks";
import { createSqlitePurgeOps } from "./sqlite-runtime/purge";
import { createSqliteRoutesStore } from "./sqlite-runtime/routes";
import { searchContentOverrides } from "./sqlite-runtime/search";
import { createSqliteSettingsStore } from "./sqlite-runtime/settings";
import type { AstropressSqliteDatabaseLike } from "./sqlite-runtime/utils";
import { createWebhookStore } from "./sqlite-runtime/webhooks";
import { ensureFts5SearchIndex } from "./sqlite-schema-compat";

type AdminRole = SessionUser["role"];

interface PasswordResetTokenRow {
	id: string;
	user_id: number;
	token_hash: string;
	expires_at: string;
	consumed_at: string | null;
	created_at: string;
}

interface UserInviteRow {
	id: string;
	user_id: number;
	token_hash: string;
	expires_at: string;
	accepted_at: string | null;
	created_at: string;
}

export type { AstropressSqliteDatabaseLike };

export interface AstropressSqliteAdminRuntimeOptions {
	getDatabase(): AstropressSqliteDatabaseLike;
	sessionTtlMs?: number;
	now?: () => number;
	randomId?: () => string;
	rootSecret?: string;
}

const DEFAULT_SESSION_TTL_MS = 12 * 60 * 60 * 1000;

export function createAstropressSqliteAdminRuntime(
	options: AstropressSqliteAdminRuntimeOptions,
) {
	const getDb = options.getDatabase;
	const sessionTtlMs = options.sessionTtlMs ?? DEFAULT_SESSION_TTL_MS;
	const now = options.now ?? (() => Date.now());
	const randomId = options.randomId ?? (() => crypto.randomUUID());
	const rootSecret = options.rootSecret ?? getAstropressRootSecret();

	const {
		sqliteUserRepository,
		sqliteAuthRepository,
		getPersistedAuditEvents,
	} = createSqliteAuthStore(getDb, { sessionTtlMs, now, randomId, rootSecret });
	const {
		sqliteRedirectRepository,
		sqliteCommentRepository,
		sqliteTranslationRepository,
		sqliteSettingsRepository,
	} = createSqliteSettingsStore(getDb);

	const {
		sqliteContentRepository,
		sqliteSubmissionRepository,
		sqliteSchedulingRepository,
	} = createSqliteContentStore(getDb, randomId);

	const { sqliteCmsRegistryModule } = createSqliteRoutesStore(getDb, randomId);

	const { sqliteAuthorRepository, sqliteTaxonomyRepository } =
		createSqliteCatalogStore(getDb);
	const { sqliteRateLimitRepository, sqliteMediaRepository } =
		createSqliteAssetsStore(getDb, now);
	const sqliteApiTokenStore = createApiTokenStore(getDb());
	const sqliteWebhookStore = createWebhookStore(getDb());
	const sqliteLocksOps = createSqliteLocksOps(getDb);
	const sqlitePurgeOps = createSqlitePurgeOps(getDb);

	const sqliteAdminStore: AdminStoreAdapter = createAstropressAdminStoreAdapter(
		"sqlite",
		{
			auth: {
				createSession: sqliteAuthRepository.createSession,
				getSessionUser: sqliteAuthRepository.getSessionUser,
				getCsrfToken: sqliteAuthRepository.getCsrfToken,
				revokeSession: sqliteAuthRepository.revokeSession,
				createPasswordResetToken: sqliteAuthRepository.createPasswordResetToken,
				getInviteRequest: sqliteAuthRepository.getInviteRequest,
				getPasswordResetRequest: sqliteAuthRepository.getPasswordResetRequest,
				consumeInviteToken: sqliteAuthRepository.consumeInviteToken,
				consumePasswordResetToken:
					sqliteAuthRepository.consumePasswordResetToken,
				recordSuccessfulLogin: sqliteAuthRepository.recordSuccessfulLogin,
				recordLogout: sqliteAuthRepository.recordLogout,
			},
			audit: {
				getAuditEvents: getPersistedAuditEvents,
				recordAuditEvent: (input) => recordAuditEvent(getDb(), input),
			},
			users: {
				listAdminUsers: sqliteUserRepository.listAdminUsers,
				inviteAdminUser: sqliteUserRepository.inviteAdminUser,
				suspendAdminUser: sqliteUserRepository.suspendAdminUser,
				unsuspendAdminUser: sqliteUserRepository.unsuspendAdminUser,
			},
			authors: {
				listAuthors: sqliteAuthorRepository.listAuthors,
				createAuthor: sqliteAuthorRepository.createAuthor,
				updateAuthor: sqliteAuthorRepository.updateAuthor,
				deleteAuthor: sqliteAuthorRepository.deleteAuthor,
			},
			taxonomies: {
				listCategories: sqliteTaxonomyRepository.listCategories,
				createCategory: sqliteTaxonomyRepository.createCategory,
				updateCategory: sqliteTaxonomyRepository.updateCategory,
				deleteCategory: sqliteTaxonomyRepository.deleteCategory,
				listTags: sqliteTaxonomyRepository.listTags,
				createTag: sqliteTaxonomyRepository.createTag,
				updateTag: sqliteTaxonomyRepository.updateTag,
				deleteTag: sqliteTaxonomyRepository.deleteTag,
			},
			redirects: {
				getRedirectRules: sqliteRedirectRepository.getRedirectRules,
				createRedirectRule: sqliteRedirectRepository.createRedirectRule,
				deleteRedirectRule: sqliteRedirectRepository.deleteRedirectRule,
			},
			comments: {
				getComments: sqliteCommentRepository.getComments,
				moderateComment: sqliteCommentRepository.moderateComment,
				submitPublicComment: sqliteCommentRepository.submitPublicComment,
				getApprovedCommentsForRoute:
					sqliteCommentRepository.getApprovedCommentsForRoute,
			},
			content: {
				listContentStates: sqliteContentRepository.listContentStates,
				getContentState: sqliteContentRepository.getContentState,
				getContentRevisions: sqliteContentRepository.getContentRevisions,
				createContentRecord: sqliteContentRepository.createContentRecord,
				saveContentState: sqliteContentRepository.saveContentState,
				restoreRevision: sqliteContentRepository.restoreRevision,
				schedulePublish: sqliteSchedulingRepository.schedulePublish,
				listScheduled: sqliteSchedulingRepository.listScheduled,
				cancelScheduledPublish:
					sqliteSchedulingRepository.cancelScheduledPublish,
				runScheduledPublishes: sqliteSchedulingRepository.runScheduledPublishes,
			},
			submissions: {
				submitContact: sqliteSubmissionRepository.submitContact,
				getContactSubmissions: sqliteSubmissionRepository.getContactSubmissions,
			},
			translations: {
				updateTranslationState:
					sqliteTranslationRepository.updateTranslationState,
				getEffectiveTranslationState:
					sqliteTranslationRepository.getEffectiveTranslationState,
			},
			settings: {
				getSettings: sqliteSettingsRepository.getSettings,
				saveSettings: sqliteSettingsRepository.saveSettings,
			},
			rateLimits: {
				checkRateLimit: sqliteRateLimitRepository.checkRateLimit,
				peekRateLimit: sqliteRateLimitRepository.peekRateLimit,
				recordFailedAttempt: sqliteRateLimitRepository.recordFailedAttempt,
			},
			media: {
				listMediaAssets: sqliteMediaRepository.listMediaAssets,
				createMediaAsset: sqliteMediaRepository.createMediaAsset,
				updateMediaAsset: sqliteMediaRepository.updateMediaAsset,
				deleteMediaAsset: sqliteMediaRepository.deleteMediaAsset,
			},
			apiTokens: sqliteApiTokenStore,
			webhooks: sqliteWebhookStore,
		},
	);

	if (peekCmsConfig()?.search?.enabled) {
		ensureFts5SearchIndex(getDb());
	}

	return {
		sqliteAdminStore,
		sqliteCmsRegistryModule,
		authenticatePersistedAdminUser:
			sqliteAuthRepository.authenticatePersistedAdminUser,
		sqliteLocksOps,
		sqlitePurgeOps,
		searchContentStates: (query: string) =>
			searchContentOverrides(getDb(), query),
	};
}

src/sqlite-bootstrap-helpers.ts.source:
import type { defaultSiteSettings } from "./site-settings";

export interface SqliteStatementLike {
	run(...params: unknown[]): { changes?: number | bigint };
	get(...params: unknown[]): unknown;
	all(...params: unknown[]): unknown[];
}

export interface SqliteDatabaseLike {
	exec(sql: string): void;
	prepare(sql: string): SqliteStatementLike;
	close(): void;
}

export type AdminRole = "admin" | "editor";

export interface MediaSeedRecord {
	id: string;
	sourceUrl?: string;
	localPath?: string;
	r2Key?: string;
}
export interface RedirectRuleSeed {
	sourcePath: string;
	targetPath: string;
	statusCode: 301 | 302;
}

export interface SeededComment {
	id: string;
	author: string;
	email?: string;
	body?: string;
	route: string;
	status: "pending" | "approved" | "rejected";
	policy: "legacy-readonly" | "disabled" | "open-moderated";
	submittedAt?: string;
}

export interface BootstrapUserSeed {
	email: string;
	password: string;
	role: AdminRole;
	name: string;
}

export interface SystemRouteSeed {
	groupId: string;
	variantId: string;
	path: string;
	title: string;
	summary?: string;
	bodyHtml?: string;
	renderStrategy: "structured_sections" | "generated_text" | "generated_xml";
	settingsJson?: string;
	metaDescription?: string;
	robotsDirective?: string;
}

export interface ArchiveSeedRecord {
	legacyUrl: string;
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
}

export interface MarketingRouteSeedRecord {
	path: string;
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks?: Array<{ hreflang: string; href: string }>;
	sections: Record<string, unknown> | null;
}

export interface SiteSettingsSeed {
	siteTitle: string;
	siteTagline: string;
	donationUrl: string;
	newsletterEnabled: boolean;
	commentsDefaultPolicy: (typeof defaultSiteSettings)["commentsDefaultPolicy"];
}

export interface SeedDatabaseOptions {
	db?: SqliteDatabaseLike;
	dbPath?: string;
	reset?: boolean;
	workspaceRoot?: string;
}

export interface SeedSummary {
	bootstrapUsers: number;
	mediaAssets: number;
	redirectRules: number;
	comments: number;
	siteSettings: number;
	systemRoutes: number;
	archiveRoutes: number;
	marketingRoutes: number;
}

export const defaultSeedImportTables = [
	"admin_users",
	"media_assets",
	"redirect_rules",
	"comments",
	"site_settings",
	"cms_route_groups",
	"cms_route_variants",
	"cms_route_aliases",
	"cms_route_revisions",
] as const;

export interface SeedImportStatement<
	TableName extends string = (typeof defaultSeedImportTables)[number],
> {
	table: TableName;
	statements: string[];
	sql: string;
}

export interface AstropressSqliteSeedToolkitOptions<
	TableName extends string = (typeof defaultSeedImportTables)[number],
> {
	readSchemaSql(): string;
	loadBootstrapUsers(): BootstrapUserSeed[];
	loadMediaSeeds(workspaceRoot: string): MediaSeedRecord[];
	redirectRules: RedirectRuleSeed[];
	comments: SeededComment[];
	systemRoutes: SystemRouteSeed[];
	archiveRoutes: ArchiveSeedRecord[];
	marketingRoutes: MarketingRouteSeedRecord[];
	siteSettings: SiteSettingsSeed;
	seedImportTables?: readonly TableName[];
	getDefaultAdminDbPath?(workspaceRoot?: string): string;
}

export interface AstropressSqliteSeedToolkit<
	TableName extends string = (typeof defaultSeedImportTables)[number],
> {
	getDefaultAdminDbPath(workspaceRoot?: string): string;
	applyCommittedSchema(db: SqliteDatabaseLike): void;
	openSeedDatabase(dbPath: string): SqliteDatabaseLike;
	seedDatabase(options?: SeedDatabaseOptions): SeedSummary;
	buildSeedImportSql(workspaceRoot?: string): string;
	buildSeedImportStatements(
		workspaceRoot?: string,
		seededDb?: SqliteDatabaseLike,
	): SeedImportStatement<TableName>[];
}

export type AstropressRollbackStatus =
	| "no_migrations"
	| "no_rollback_sql"
	| "dry_run"
	| "rolled_back";

export interface AstropressRollbackResult {
	migrationName: string | null;
	status: AstropressRollbackStatus;
	dryRun: boolean;
}

export type SqliteDatabaseConstructor = new (
	filename: string,
) => SqliteDatabaseLike;

export async function loadSqliteDatabase(): Promise<SqliteDatabaseConstructor> {
	if ("Bun" in globalThis) {
		const m = await import("bun:sqlite");
		return m.Database as unknown as SqliteDatabaseConstructor;
	}
	const m = await import("node:sqlite");
	return m.DatabaseSync as unknown as SqliteDatabaseConstructor;
}

// Checkpoint and truncate the WAL so a subsequent file copy is self-contained.
// Returns true when the WAL was fully flushed (log page count dropped to 0).
// On any failure, emits a warning via `warn` and returns false.
export async function checkpointSqliteWal(
	sqlitePath: string,
	warn: (msg: string) => void,
): Promise<boolean> {
	let DbClass: SqliteDatabaseConstructor;
	try {
		DbClass = await loadSqliteDatabase();
	} catch (err) {
		warn(`SQLite WAL checkpoint skipped for ${sqlitePath}: ${String(err)}`);
		return false;
	}
	let db: SqliteDatabaseLike | undefined;
	try {
		db = new DbClass(sqlitePath);
		const row = db.prepare("PRAGMA wal_checkpoint(TRUNCATE)").get() as {
			log: number;
			checkpointed: number;
		} | null;
		return row != null && row.log === 0;
	} catch (err) {
		warn(`SQLite WAL checkpoint failed for ${sqlitePath}: ${String(err)}`);
		return false;
	} finally {
		db?.close();
	}
}

src/sqlite-bootstrap-migrations.ts.source:
import { existsSync, readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import type {
	AstropressRollbackResult,
	SqliteDatabaseLike,
} from "./sqlite-bootstrap-helpers";

/**
 * Run incremental SQL migrations from a directory against a live SQLite database.
 *
 * Migration files must be named with a numeric prefix (e.g. `0001_add_column.sql`).
 * They are applied in lexicographic order. Applied migrations are recorded in
 * `schema_migrations` so they are never re-run.
 */
export function runAstropressMigrations(
	db: SqliteDatabaseLike,
	migrationsDir: string,
): { applied: string[]; skipped: string[] } {
	const applied: string[] = [];
	const skipped: string[] = [];

	db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    rollback_sql TEXT
  )`);

	const migrationCols = new Set(
		(
			db.prepare("PRAGMA table_info(schema_migrations)").all() as Array<{
				name: string;
			}>
		).map((r) => r.name),
	);
	if (!migrationCols.has("rollback_sql")) {
		db.exec("ALTER TABLE schema_migrations ADD COLUMN rollback_sql TEXT");
	}

	const alreadyApplied = new Set(
		(
			db.prepare("SELECT name FROM schema_migrations").all() as Array<{
				name: string;
			}>
		).map((r) => r.name),
	);

	if (!existsSync(migrationsDir)) return { applied, skipped };

	for (const file of readdirSync(migrationsDir)
		.filter((f) => f.endsWith(".sql"))
		.sort()) {
		if (alreadyApplied.has(file)) {
			skipped.push(file);
			continue;
		}
		const sql = readFileSync(path.join(migrationsDir, file), "utf8");
		db.exec(sql);

		const downFilePath = path.join(
			migrationsDir,
			file.replace(/\.sql$/, ".down.sql"),
		);
		const rollbackSql = existsSync(downFilePath)
			? readFileSync(downFilePath, "utf8")
			: null;
		db.prepare(
			"INSERT INTO schema_migrations (name, rollback_sql) VALUES (?, ?)",
		).run(file, rollbackSql);
		applied.push(file);
	}

	return { applied, skipped };
}

/**
 * The number of framework-owned migrations Astropress applies during bootstrapping.
 * Used by `checkSchemaVersionAhead` to detect host-app migrations.
 */
export const ASTROPRESS_FRAMEWORK_MIGRATION_BASELINE = 1;

/**
 * Checks whether the database `schema_migrations` table has more entries than the
 * framework's known baseline.
 */
export function checkSchemaVersionAhead(
	db: SqliteDatabaseLike,
	frameworkBaseline = ASTROPRESS_FRAMEWORK_MIGRATION_BASELINE,
): { isAhead: boolean; dbCount: number; frameworkCount: number } | null {
	try {
		const row = db
			.prepare("SELECT COUNT(*) as count FROM schema_migrations")
			.get() as { count: number } | undefined;
		if (!row) return null;
		return {
			isAhead: row.count > frameworkBaseline,
			dbCount: row.count,
			frameworkCount: frameworkBaseline,
		};
	} catch {
		return null;
	}
}

/**
 * Rolls back the most recently applied migration by executing its `rollback_sql` and
 * removing its record from `schema_migrations`. Returns the name of the rolled-back
 * migration, or `null` if there are no applied migrations or the last one has no rollback SQL.
 */
export function rollbackAstropressLastMigration(
	db: SqliteDatabaseLike,
): string | null {
	const last = db
		.prepare(
			"SELECT name, rollback_sql FROM schema_migrations ORDER BY id DESC LIMIT 1",
		)
		.get() as { name: string; rollback_sql: string | null } | undefined;

	if (!last) return null;
	if (last.rollback_sql) {
		db.exec(last.rollback_sql);
	}
	db.prepare("DELETE FROM schema_migrations WHERE name = ?").run(last.name);
	return last.name;
}

export function rollbackAstropressLastMigrationWithOptions(
	db: SqliteDatabaseLike,
	options: { dryRun?: boolean } = {},
): AstropressRollbackResult {
	const dryRun = options.dryRun ?? false;
	const row = db
		.prepare(
			"SELECT name, rollback_sql FROM schema_migrations ORDER BY id DESC LIMIT 1",
		)
		.get() as { name: string; rollback_sql: string | null } | undefined;

	if (!row) {
		return { migrationName: null, status: "no_migrations", dryRun };
	}
	if (!row.rollback_sql) {
		return { migrationName: row.name, status: "no_rollback_sql", dryRun };
	}
	if (dryRun) {
		return { migrationName: row.name, status: "dry_run", dryRun: true };
	}

	db.exec(row.rollback_sql);
	db.prepare("DELETE FROM schema_migrations WHERE name = ?").run(row.name);
	return { migrationName: row.name, status: "rolled_back", dryRun: false };
}

src/sqlite-bootstrap-seeders.ts.source:
import { getCmsConfig } from "./config.js";
import type {
	ArchiveSeedRecord,
	AstropressSqliteSeedToolkitOptions,
	MarketingRouteSeedRecord,
	SqliteDatabaseLike,
	SystemRouteSeed,
} from "./sqlite-bootstrap.js";
import { guessMimeType, hashPasswordSync } from "./sqlite-seed-helpers.js";

const SQL_SEED_SITE_SETTINGS = `
  INSERT INTO site_settings (
    id, site_title, site_tagline, donation_url, newsletter_enabled, comments_default_policy, updated_by
  ) VALUES (?, ?, ?, ?, ?, ?, ?)
  ON CONFLICT(id) DO NOTHING
`;
const SQL_SEED_SYSTEM_GROUP = `
  INSERT INTO cms_route_groups (id, kind, render_strategy, canonical_locale, canonical_path)
  VALUES (?, 'system', ?, 'en', ?)
  ON CONFLICT(id) DO UPDATE SET
    render_strategy = excluded.render_strategy,
    canonical_path = excluded.canonical_path,
    updated_at = CURRENT_TIMESTAMP
`;
const SQL_SEED_SYSTEM_VARIANT = `
  INSERT INTO cms_route_variants (
    id, group_id, locale, path, status, title, summary, body_html, sections_json, settings_json,
    seo_title, meta_description, og_title, og_description, og_image, canonical_url_override,
    robots_directive, updated_at, updated_by
  ) VALUES (?, ?, 'en', ?, 'published', ?, ?, ?, NULL, ?, ?, ?, NULL, NULL, NULL, NULL, ?, CURRENT_TIMESTAMP, ?)
  ON CONFLICT(id) DO UPDATE SET
    path = excluded.path, title = excluded.title, summary = excluded.summary,
    body_html = excluded.body_html, settings_json = excluded.settings_json,
    seo_title = excluded.seo_title, meta_description = excluded.meta_description,
    robots_directive = excluded.robots_directive,
    updated_at = CURRENT_TIMESTAMP, updated_by = excluded.updated_by
`;
const SQL_SEED_SYSTEM_REVISION = `
  INSERT INTO cms_route_revisions (id, variant_id, route_path, locale, snapshot_json, revision_note, created_by)
  VALUES (?, ?, ?, 'en', ?, ?, ?)
  ON CONFLICT(id) DO NOTHING
`;
const SQL_SEED_ARCHIVE_GROUP = `
  INSERT INTO cms_route_groups (id, kind, render_strategy, canonical_locale, canonical_path)
  VALUES (?, 'archive', 'archive_listing', 'en', ?)
  ON CONFLICT(id) DO UPDATE SET canonical_path = excluded.canonical_path, updated_at = CURRENT_TIMESTAMP
`;
const SQL_SEED_ARCHIVE_VARIANT = `
  INSERT INTO cms_route_variants (
    id, group_id, locale, path, status, title, summary, body_html, sections_json, settings_json,
    seo_title, meta_description, og_title, og_description, og_image, canonical_url_override,
    robots_directive, updated_at, updated_by
  ) VALUES (?, ?, 'en', ?, 'published', ?, ?, NULL, NULL, NULL, ?, ?, NULL, NULL, NULL, ?, ?, CURRENT_TIMESTAMP, ?)
  ON CONFLICT(id) DO UPDATE SET
    title = excluded.title, summary = excluded.summary, seo_title = excluded.seo_title,
    meta_description = excluded.meta_description, canonical_url_override = excluded.canonical_url_override,
    robots_directive = excluded.robots_directive, updated_at = CURRENT_TIMESTAMP, updated_by = excluded.updated_by
`;
const SQL_SEED_MARKETING_GROUP = `
  INSERT INTO cms_route_groups (id, kind, render_strategy, canonical_locale, canonical_path)
  VALUES (?, 'page', 'structured_sections', ?, ?)
  ON CONFLICT(id) DO UPDATE SET
    canonical_locale = excluded.canonical_locale, canonical_path = excluded.canonical_path, updated_at = CURRENT_TIMESTAMP
`;
const SQL_SEED_MARKETING_VARIANT = `
  INSERT INTO cms_route_variants (
    id, group_id, locale, path, status, title, summary, body_html, sections_json, settings_json,
    seo_title, meta_description, og_title, og_description, og_image, canonical_url_override,
    robots_directive, updated_at, updated_by
  ) VALUES (?, ?, ?, ?, 'published', ?, ?, NULL, ?, ?, ?, ?, NULL, NULL, ?, ?, ?, CURRENT_TIMESTAMP, ?)
  ON CONFLICT(id) DO UPDATE SET
    title = excluded.title, summary = excluded.summary, sections_json = excluded.sections_json,
    settings_json = excluded.settings_json, seo_title = excluded.seo_title,
    meta_description = excluded.meta_description, og_image = excluded.og_image,
    canonical_url_override = excluded.canonical_url_override, robots_directive = excluded.robots_directive,
    updated_at = CURRENT_TIMESTAMP, updated_by = excluded.updated_by
`;

/** Build bind params for a system route variant insert. */
function systemRouteVariantParams(route: SystemRouteSeed) {
	return [
		route.variantId,
		route.groupId,
		route.path,
		route.title,
		route.summary ?? null,
		route.bodyHtml ?? null,
		route.settingsJson ?? null,
		route.title,
		route.metaDescription ?? route.summary ?? route.title,
		route.robotsDirective ?? null,
		"seed-import",
	];
}

/** Build the revision snapshot JSON for a system route. */
function systemRouteSnapshot(route: SystemRouteSeed) {
	return JSON.stringify({
		path: route.path,
		title: route.title,
		summary: route.summary ?? "",
		bodyHtml: route.bodyHtml ?? "",
		settings: route.settingsJson ? JSON.parse(route.settingsJson) : null,
		renderStrategy: route.renderStrategy,
	});
}

/** Build bind params for an archive route variant insert. */
function archiveVariantParams(
	archive: ArchiveSeedRecord,
	variantId: string,
	groupId: string,
) {
	return [
		variantId,
		groupId,
		archive.legacyUrl,
		archive.title,
		archive.summary ?? null,
		archive.seoTitle ?? archive.title,
		archive.metaDescription ?? archive.summary ?? "",
		archive.canonicalUrlOverride ?? null,
		archive.robotsDirective ?? null,
		"seed-import",
	];
}

/** Resolve a marketing route's locale from config or fallback. */
function resolveMarketingLocale(pagePath: string): string {
	let configLocales: readonly string[];
	try {
		configLocales = getCmsConfig().locales ?? ["en", "es"];
	} catch {
		configLocales = ["en", "es"];
	}
	return (
		configLocales.find((l) => pagePath.startsWith(`/${l}/`)) ??
		configLocales[0] ??
		"en"
	);
}

/** Build bind params for a marketing route variant insert. */
function marketingVariantParams(
	page: MarketingRouteSeedRecord,
	variantId: string,
	groupId: string,
	locale: string,
) {
	return [
		variantId,
		groupId,
		locale,
		page.path,
		page.title,
		page.summary,
		JSON.stringify(page.sections),
		JSON.stringify({
			templateKey: page.templateKey,
			alternateLinks: page.alternateLinks ?? [],
		}),
		page.seoTitle,
		page.metaDescription,
		page.ogImage ?? null,
		page.canonicalUrlOverride ?? null,
		page.robotsDirective ?? null,
		"seed-import",
	];
}

export function seedBootstrapUsers(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const upsert = db.prepare(`
    INSERT INTO admin_users (email, password_hash, name, active, is_admin)
    VALUES (?, ?, ?, 1, ?)
    ON CONFLICT(email) DO UPDATE SET
      password_hash = excluded.password_hash,
      name = excluded.name,
      active = 1,
      is_admin = excluded.is_admin
  `);
	let count = 0;
	for (const user of options.loadBootstrapUsers()) {
		const result = upsert.run(
			user.email.toLowerCase(),
			hashPasswordSync(user.password),
			user.name,
			user.role === "admin" ? 1 : 0,
		) as { changes?: number };
		count += result.changes ?? 1;
	}
	return count;
}

export function seedMediaAssets(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
	workspaceRoot: string,
) {
	const insert = db.prepare(`
    INSERT INTO media_assets (
      id, source_url, local_path, r2_key, mime_type, file_size, alt_text, title, uploaded_by
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      source_url = excluded.source_url,
      local_path = excluded.local_path,
      r2_key = excluded.r2_key,
      mime_type = excluded.mime_type,
      uploaded_by = excluded.uploaded_by,
      deleted_at = NULL
  `);
	let count = 0;
	for (const asset of options.loadMediaSeeds(workspaceRoot)) {
		const result = insert.run(
			asset.id,
			asset.sourceUrl ?? null,
			asset.localPath ?? `/images/legacy/${asset.id}`,
			asset.r2Key ?? null,
			guessMimeType(asset.localPath ?? asset.sourceUrl ?? asset.id),
			null,
			"",
			asset.id,
			"seed-import",
		) as { changes?: number };
		count += result.changes ?? 1;
	}
	return count;
}

export function seedRedirects(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const insert = db.prepare(`
    INSERT INTO redirect_rules (source_path, target_path, status_code, created_by, deleted_at)
    VALUES (?, ?, ?, ?, NULL)
    ON CONFLICT(source_path) DO UPDATE SET
      target_path = excluded.target_path,
      status_code = excluded.status_code,
      created_by = excluded.created_by,
      deleted_at = NULL
  `);
	let count = 0;
	for (const rule of options.redirectRules) {
		const result = insert.run(
			rule.sourcePath,
			rule.targetPath,
			rule.statusCode,
			"seed-import",
		) as { changes?: number };
		count += result.changes ?? 1;
	}
	return count;
}

export function seedComments(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const insert = db.prepare(`
    INSERT INTO comments (id, author, email, body, route, status, policy, submitted_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, COALESCE(?, CURRENT_TIMESTAMP))
    ON CONFLICT(id) DO NOTHING
  `);
	let count = 0;
	for (const comment of options.comments) {
		const result = insert.run(
			comment.id,
			comment.author,
			comment.email ?? null,
			comment.body ?? null,
			comment.route,
			comment.status,
			comment.policy,
			comment.submittedAt ?? null,
		) as { changes?: number };
		count += result.changes ?? 0;
	}
	return count;
}

export function seedSiteSettings(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const result = db
		.prepare(SQL_SEED_SITE_SETTINGS)
		.run(
			1,
			options.siteSettings.siteTitle,
			options.siteSettings.siteTagline,
			options.siteSettings.donationUrl,
			options.siteSettings.newsletterEnabled ? 1 : 0,
			options.siteSettings.commentsDefaultPolicy,
			"seed-import",
		) as { changes?: number };
	return result.changes ?? 0;
}

export function seedSystemRoutes(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const insertGroup = db.prepare(SQL_SEED_SYSTEM_GROUP);
	const insertVariant = db.prepare(SQL_SEED_SYSTEM_VARIANT);
	const insertRevision = db.prepare(SQL_SEED_SYSTEM_REVISION);

	let count = 0;
	for (const route of options.systemRoutes) {
		insertGroup.run(route.groupId, route.renderStrategy, route.path);
		const result = insertVariant.run(...systemRouteVariantParams(route)) as {
			changes?: number;
		};
		count += result.changes ?? 1;
		insertRevision.run(
			`revision:${route.variantId}:seed`,
			route.variantId,
			route.path,
			systemRouteSnapshot(route),
			"Imported baseline",
			"seed-import",
		);
	}
	return count;
}

export function seedArchiveRoutes(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const insertGroup = db.prepare(SQL_SEED_ARCHIVE_GROUP);
	const insertVariant = db.prepare(SQL_SEED_ARCHIVE_VARIANT);

	let count = 0;
	for (const archive of options.archiveRoutes) {
		const baseId =
			archive.legacyUrl.replace(/^\//, "").replaceAll("/", ":") || "root";
		const groupId = `archive:${baseId}`;
		const variantId = `variant:archive:${baseId}:en`;
		insertGroup.run(groupId, archive.legacyUrl);
		const result = insertVariant.run(
			...archiveVariantParams(archive, variantId, groupId),
		) as { changes?: number };
		count += result.changes ?? 1;
	}
	return count;
}

export function seedMarketingRoutes(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const insertGroup = db.prepare(SQL_SEED_MARKETING_GROUP);
	const insertVariant = db.prepare(SQL_SEED_MARKETING_VARIANT);

	let count = 0;
	for (const page of options.marketingRoutes) {
		const locale = resolveMarketingLocale(page.path);
		const baseId = page.path.replace(/^\//, "").replaceAll("/", ":");
		const groupId = `page:${baseId}`;
		const variantId = `variant:page:${baseId}:${locale}`;
		insertGroup.run(groupId, locale, page.path);
		const result = insertVariant.run(
			...marketingVariantParams(page, variantId, groupId, locale),
		) as { changes?: number };
		count += result.changes ?? 1;
	}
	return count;
}

