import type { Actor } from "../persistence-types";
import { normalizeStructuredTemplateKey, parseSystemSettings } from "./utils";

export interface SystemRouteRecord {
	path: string;
	title: string;
	summary?: string;
	bodyHtml?: string;
	renderStrategy: "structured_sections" | "generated_text" | "generated_xml";
	settings: Record<string, unknown> | null;
	updatedAt?: string;
}
export interface ArchiveRouteRecord {
	path: string;
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	updatedAt?: string;
}
export interface StructuredPageRouteRecord {
	path: string;
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks: Array<{ hreflang: string; href: string }>;
	sections: Record<string, unknown> | null;
	updatedAt?: string;
}

export type SystemRouteRow = {
	path: string;
	title: string;
	summary: string | null;
	body_html: string | null;
	settings_json: string | null;
	updated_at: string | null;
	render_strategy: SystemRouteRecord["renderStrategy"];
};
export type ArchiveRouteRow = {
	path: string;
	title: string;
	summary: string | null;
	seo_title: string | null;
	meta_description: string | null;
	canonical_url_override: string | null;
	robots_directive: string | null;
	updated_at: string | null;
};
export type StructuredPageRow = {
	path: string;
	title: string;
	summary: string | null;
	seo_title: string | null;
	meta_description: string | null;
	canonical_url_override: string | null;
	robots_directive: string | null;
	og_image: string | null;
	sections_json: string | null;
	settings_json: string | null;
	updated_at: string | null;
};

export const SQL_LIST_SYSTEM = `SELECT v.path, v.title, v.summary, v.body_html, v.settings_json, v.updated_at, g.render_strategy FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'system' ORDER BY v.path ASC`;
export const SQL_LIST_STRUCTURED = `SELECT v.path, v.title, v.summary, v.seo_title, v.meta_description, v.canonical_url_override, v.robots_directive, v.og_image, v.sections_json, v.settings_json, v.updated_at FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'page' AND g.render_strategy = 'structured_sections' ORDER BY v.path ASC`;
export const SQL_GET_ARCHIVE = `SELECT v.path, v.title, v.summary, v.seo_title, v.meta_description, v.canonical_url_override, v.robots_directive, v.updated_at FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'archive' AND v.path = ? LIMIT 1`;
export const SQL_LIST_ARCHIVES = `SELECT v.path, v.title, v.summary, v.seo_title, v.meta_description, v.canonical_url_override, v.robots_directive, v.updated_at FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'archive' ORDER BY v.path ASC`;
export const SQL_FIND_SYSTEM_FOR_UPDATE = `SELECT v.id, g.render_strategy FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'system' AND v.path = ? LIMIT 1`;
export const SQL_PERSIST_SYSTEM =
	"UPDATE cms_route_variants SET title = ?, summary = ?, body_html = ?, settings_json = ?, seo_title = ?, meta_description = ?, updated_at = CURRENT_TIMESTAMP, updated_by = ? WHERE id = ?";
export const SQL_INSERT_REVISION =
	"INSERT INTO cms_route_revisions (id, variant_id, route_path, locale, snapshot_json, revision_note, created_by) VALUES (?, ?, ?, ?, ?, ?, ?)";
export const SQL_IS_PATH_TAKEN =
	"SELECT v.id FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE v.path = ? LIMIT 1";
export const SQL_FIND_STRUCTURED_FOR_UPDATE = `SELECT v.id FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'page' AND g.render_strategy = 'structured_sections' AND v.path = ? LIMIT 1`;
export const SQL_INSERT_ROUTE_GROUP = `INSERT INTO cms_route_groups (id, kind, render_strategy, canonical_locale, canonical_path) VALUES (?, 'page', 'structured_sections', ?, ?)`;
export const SQL_INSERT_ROUTE_VARIANT = `INSERT INTO cms_route_variants (id, group_id, locale, path, status, title, summary, sections_json, settings_json, seo_title, meta_description, og_image, canonical_url_override, robots_directive, updated_by) VALUES (?, ?, ?, ?, 'published', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
export const SQL_PERSIST_STRUCTURED =
	"UPDATE cms_route_variants SET title = ?, summary = ?, seo_title = ?, meta_description = ?, canonical_url_override = ?, robots_directive = ?, og_image = ?, sections_json = ?, settings_json = ?, updated_at = CURRENT_TIMESTAMP, updated_by = ? WHERE id = ?";
export const SQL_FIND_ARCHIVE_FOR_UPDATE = `SELECT v.id FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'archive' AND v.path = ? LIMIT 1`;
export const SQL_PERSIST_ARCHIVE =
	"UPDATE cms_route_variants SET title = ?, summary = ?, seo_title = ?, meta_description = ?, canonical_url_override = ?, robots_directive = ?, updated_at = CURRENT_TIMESTAMP, updated_by = ? WHERE id = ?";
export const SQL_INSERT_ARCHIVE_REVISION = `INSERT INTO cms_route_revisions (id, variant_id, route_path, locale, snapshot_json, revision_note, created_by) VALUES (?, ?, ?, 'en', ?, ?, ?)`;

export interface InsertStructuredInput {
	pathname: string;
	locale: string;
	title: string;
	summary: string;
	seoTitle: string;
	metaDescription: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks: Array<{ hreflang: string; href: string }>;
	sections: Record<string, unknown> | null;
	actor: Actor;
}
export interface PersistStructuredInput {
	routeId: string;
	title: string;
	summary: string;
	seoTitle: string;
	metaDescription: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks: Array<{ hreflang: string; href: string }>;
	sections: Record<string, unknown> | null;
	actor: Actor;
}
export interface AppendStructuredRevisionInput extends InsertStructuredInput {
	routeId: string;
	revisionNote: string;
}
export interface PersistArchiveInput {
	routeId: string;
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	actor: Actor;
}
export interface AppendArchiveRevisionInput {
	routeId: string;
	pathname: string;
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	revisionNote: string;
	actor: Actor;
}

export function mapArchiveRow(row: ArchiveRouteRow): ArchiveRouteRecord {
	return {
		path: row.path,
		title: row.title,
		summary: row.summary ?? undefined,
		seoTitle: row.seo_title ?? undefined,
		metaDescription: row.meta_description ?? undefined,
		canonicalUrlOverride: row.canonical_url_override ?? undefined,
		robotsDirective: row.robots_directive ?? undefined,
		updatedAt: row.updated_at ?? undefined,
	};
}

export function mapStructuredPageRow(
	row: StructuredPageRow,
): StructuredPageRouteRecord | null {
	const settings = parseSystemSettings(row.settings_json) ?? {};
	const templateKey = normalizeStructuredTemplateKey(settings.templateKey);
	if (!templateKey) return null;
	return {
		path: row.path,
		title: row.title,
		summary: row.summary ?? undefined,
		seoTitle: row.seo_title ?? undefined,
		metaDescription: row.meta_description ?? undefined,
		canonicalUrlOverride: row.canonical_url_override ?? undefined,
		robotsDirective: row.robots_directive ?? undefined,
		ogImage: row.og_image ?? undefined,
		templateKey,
		alternateLinks: Array.isArray(settings.alternateLinks)
			? (settings.alternateLinks as Array<{ hreflang: string; href: string }>)
			: [],
		sections: parseSystemSettings(row.sections_json),
		updatedAt: row.updated_at ?? undefined,
	} satisfies StructuredPageRouteRecord;
}

src/sqlite-runtime/routes.ts.source:
import { createAstropressCmsRouteRegistry } from "../cms-route-registry-factory";
import { createAstropressCmsRegistryModule } from "../host-runtime-factories";
import type { Actor } from "../persistence-types";
import { recordAudit } from "./audit-log";
import {
	type AppendArchiveRevisionInput,
	type AppendStructuredRevisionInput,
	type ArchiveRouteRow,
	type InsertStructuredInput,
	type PersistArchiveInput,
	type PersistStructuredInput,
	SQL_FIND_ARCHIVE_FOR_UPDATE,
	SQL_FIND_STRUCTURED_FOR_UPDATE,
	SQL_FIND_SYSTEM_FOR_UPDATE,
	SQL_GET_ARCHIVE,
	SQL_INSERT_ARCHIVE_REVISION,
	SQL_INSERT_REVISION,
	SQL_INSERT_ROUTE_GROUP,
	SQL_INSERT_ROUTE_VARIANT,
	SQL_IS_PATH_TAKEN,
	SQL_LIST_ARCHIVES,
	SQL_LIST_STRUCTURED,
	SQL_LIST_SYSTEM,
	SQL_PERSIST_ARCHIVE,
	SQL_PERSIST_STRUCTURED,
	SQL_PERSIST_SYSTEM,
	type StructuredPageRow,
	type SystemRouteRecord,
	type SystemRouteRow,
	mapArchiveRow,
	mapStructuredPageRow,
} from "./routes-helpers";
import {
	type AstropressSqliteDatabaseLike,
	localeFromPath,
	normalizeSystemRoutePath,
	parseSystemSettings,
} from "./utils";

function querySystemRoutes(
	getDb: () => AstropressSqliteDatabaseLike,
): SystemRouteRecord[] {
	const rows = getDb().prepare(SQL_LIST_SYSTEM).all() as SystemRouteRow[];
	return rows.map((row) => ({
		path: row.path,
		title: row.title,
		summary: row.summary ?? undefined,
		bodyHtml: row.body_html ?? undefined,
		settings: parseSystemSettings(row.settings_json),
		updatedAt: row.updated_at ?? undefined,
		renderStrategy: row.render_strategy,
	}));
}

function queryStructuredPageRoutes(getDb: () => AstropressSqliteDatabaseLike) {
	const rows = getDb()
		.prepare(SQL_LIST_STRUCTURED)
		.all() as StructuredPageRow[];
	return rows.map(mapStructuredPageRow).filter(Boolean) as ReturnType<
		typeof mapStructuredPageRow
	>[];
}

export function createSqliteRoutesStore(
	getDb: () => AstropressSqliteDatabaseLike,
	randomId: () => string,
) {
	function listSystemRoutes() {
		return querySystemRoutes(getDb);
	}

	function getSystemRoute(pathname: string) {
		const normalizedPath = normalizeSystemRoutePath(pathname);
		return (
			listSystemRoutes().find((route) => route.path === normalizedPath) ?? null
		);
	}

	function listStructuredPageRoutes() {
		return queryStructuredPageRoutes(getDb).filter(
			(r): r is NonNullable<typeof r> => r !== null,
		);
	}

	function getStructuredPageRoute(pathname: string) {
		const normalizedPath = normalizeSystemRoutePath(pathname);
		return (
			listStructuredPageRoutes().find(
				(route) => route.path === normalizedPath,
			) ?? null
		);
	}

	function getArchiveRoute(pathname: string) {
		const normalizedPath = normalizeSystemRoutePath(pathname);
		const row = getDb().prepare(SQL_GET_ARCHIVE).get(normalizedPath) as
			| ArchiveRouteRow
			| undefined;
		if (!row) return null;
		return mapArchiveRow(row);
	}

	function listArchiveRoutes() {
		const rows = getDb().prepare(SQL_LIST_ARCHIVES).all() as ArchiveRouteRow[];
		return rows.map(mapArchiveRow);
	}

	const sqliteCmsRouteRegistry = createAstropressCmsRouteRegistry({
		normalizePath: normalizeSystemRoutePath,
		localeFromPath,
		listSystemRoutes,
		getSystemRoute,
		listStructuredPageRoutes,
		getStructuredPageRoute,
		getArchiveRoute,
		listArchiveRoutes,
		findSystemRouteForUpdate(pathname) {
			const row = getDb().prepare(SQL_FIND_SYSTEM_FOR_UPDATE).get(pathname) as
				| { id: string; render_strategy: SystemRouteRecord["renderStrategy"] }
				| undefined;
			return row ? { id: row.id, renderStrategy: row.render_strategy } : null;
		},
		persistSystemRoute({
			routeId,
			title,
			summary,
			bodyHtml,
			settingsJson,
			actor,
		}: {
			routeId: string;
			title: string;
			summary: string;
			bodyHtml: string;
			settingsJson: string;
			actor: Actor;
		}) {
			getDb()
				.prepare(SQL_PERSIST_SYSTEM)
				.run(
					title,
					summary,
					bodyHtml,
					settingsJson,
					title,
					summary ?? title,
					actor.email,
					routeId,
				);
		},
		appendSystemRouteRevision({
			routeId,
			pathname,
			locale,
			title,
			summary,
			bodyHtml,
			settings,
			renderStrategy,
			revisionNote,
			actor,
		}: {
			routeId: string;
			pathname: string;
			locale: string;
			title: string;
			summary: string;
			bodyHtml: string;
			settings: Record<string, unknown> | null;
			renderStrategy: string;
			revisionNote: string;
			actor: Actor;
		}) {
			getDb()
				.prepare(SQL_INSERT_REVISION)
				.run(
					`revision:${routeId}:${randomId()}`,
					routeId,
					pathname,
					locale,
					JSON.stringify({
						path: pathname,
						title,
						summary,
						bodyHtml,
						settings: settings ?? null,
						renderStrategy,
					}),
					revisionNote,
					actor.email,
				);
		},
		isRoutePathTaken(pathname) {
			return Boolean(getDb().prepare(SQL_IS_PATH_TAKEN).get(pathname));
		},
		findStructuredRouteForUpdate(pathname) {
			return (
				(getDb().prepare(SQL_FIND_STRUCTURED_FOR_UPDATE).get(pathname) as
					| { id: string }
					| undefined) ?? null
			);
		},
		insertStructuredRoute({
			pathname,
			locale,
			title,
			summary,
			seoTitle,
			metaDescription,
			canonicalUrlOverride,
			robotsDirective,
			ogImage,
			templateKey,
			alternateLinks,
			sections,
			actor,
		}: InsertStructuredInput) {
			const groupId = `route-group:${randomId()}`;
			const variantId = `route-variant:${randomId()}`;
			getDb().prepare(SQL_INSERT_ROUTE_GROUP).run(groupId, locale, pathname);
			getDb()
				.prepare(SQL_INSERT_ROUTE_VARIANT)
				.run(
					variantId,
					groupId,
					locale,
					pathname,
					title,
					summary,
					sections ? JSON.stringify(sections) : null,
					JSON.stringify({ templateKey, alternateLinks }),
					seoTitle,
					metaDescription,
					ogImage,
					canonicalUrlOverride,
					robotsDirective,
					actor.email,
				);
		},
		persistStructuredRoute({
			routeId,
			title,
			summary,
			seoTitle,
			metaDescription,
			canonicalUrlOverride,
			robotsDirective,
			ogImage,
			templateKey,
			alternateLinks,
			sections,
			actor,
		}: PersistStructuredInput) {
			getDb()
				.prepare(SQL_PERSIST_STRUCTURED)
				.run(
					title,
					summary,
					seoTitle,
					metaDescription,
					canonicalUrlOverride,
					robotsDirective,
					ogImage,
					sections ? JSON.stringify(sections) : null,
					JSON.stringify({ templateKey, alternateLinks }),
					actor.email,
					routeId,
				);
		},
		appendStructuredRouteRevision({
			routeId,
			pathname,
			locale,
			title,
			summary,
			seoTitle,
			metaDescription,
			canonicalUrlOverride,
			robotsDirective,
			ogImage,
			templateKey,
			alternateLinks,
			sections,
			revisionNote,
			actor,
		}: AppendStructuredRevisionInput) {
			getDb()
				.prepare(SQL_INSERT_REVISION)
				.run(
					`revision:${routeId}:${randomId()}`,
					routeId,
					pathname,
					locale,
					JSON.stringify({
						path: pathname,
						title,
						summary,
						seoTitle,
						metaDescription,
						canonicalUrlOverride,
						robotsDirective,
						ogImage,
						templateKey,
						alternateLinks,
						sections,
					}),
					revisionNote,
					actor.email,
				);
		},
		findArchiveRouteForUpdate(pathname) {
			return (
				(getDb().prepare(SQL_FIND_ARCHIVE_FOR_UPDATE).get(pathname) as
					| { id: string }
					| undefined) ?? null
			);
		},
		persistArchiveRoute({
			routeId,
			title,
			summary,
			seoTitle,
			metaDescription,
			canonicalUrlOverride,
			robotsDirective,
			actor,
		}: PersistArchiveInput) {
			getDb()
				.prepare(SQL_PERSIST_ARCHIVE)
				.run(
					title,
					summary,
					seoTitle,
					metaDescription,
					canonicalUrlOverride,
					robotsDirective,
					actor.email,
					routeId,
				);
		},
		appendArchiveRouteRevision({
			routeId,
			pathname,
			title,
			summary,
			seoTitle,
			metaDescription,
			canonicalUrlOverride,
			robotsDirective,
			revisionNote,
			actor,
		}: AppendArchiveRevisionInput) {
			getDb()
				.prepare(SQL_INSERT_ARCHIVE_REVISION)
				.run(
					`revision:${routeId}:${randomId()}`,
					routeId,
					pathname,
					JSON.stringify({
						path: pathname,
						title,
						summary,
						seoTitle,
						metaDescription,
						canonicalUrlOverride,
						robotsDirective,
					}),
					revisionNote,
					actor.email,
				);
		},
		recordRouteAudit({
			actor,
			action,
			summary,
			targetId,
		}: { actor: Actor; action: string; summary: string; targetId: string }) {
			recordAudit(getDb(), actor, action, summary, "content", targetId);
		},
	});

	const sqliteCmsRegistryModule = createAstropressCmsRegistryModule({
		listSystemRoutes: sqliteCmsRouteRegistry.listSystemRoutes,
		getSystemRoute: sqliteCmsRouteRegistry.getSystemRoute,
		saveSystemRoute: sqliteCmsRouteRegistry.saveSystemRoute,
		listStructuredPageRoutes: sqliteCmsRouteRegistry.listStructuredPageRoutes,
		getStructuredPageRoute: sqliteCmsRouteRegistry.getStructuredPageRoute,
		saveStructuredPageRoute: sqliteCmsRouteRegistry.saveStructuredPageRoute,
		createStructuredPageRoute: sqliteCmsRouteRegistry.createStructuredPageRoute,
		getArchiveRoute: sqliteCmsRouteRegistry.getArchiveRoute,
		listArchiveRoutes: sqliteCmsRouteRegistry.listArchiveRoutes,
		saveArchiveRoute: sqliteCmsRouteRegistry.saveArchiveRoute,
	});

	return { sqliteCmsRouteRegistry, sqliteCmsRegistryModule };
}

src/sqlite-runtime/search.ts.source:
import type { ContentRecord } from "../persistence-types";
import type { AstropressSqliteDatabaseLike } from "./utils";

/**
 * Search content_overrides using the FTS5 virtual table.
 * Requires ensureFts5SearchIndex to have been called at boot.
 */
export function searchContentOverrides(
	db: AstropressSqliteDatabaseLike,
	query: string,
): ContentRecord[] {
	return db
		.prepare(
			`SELECT co.* FROM content_overrides co
       WHERE co.rowid IN (SELECT rowid FROM content_fts(?) ORDER BY rank)`,
		)
		.all(query) as ContentRecord[];
}

src/sqlite-runtime/settings.ts.source:
import { createAstropressCommentRepository } from "../comment-repository-factory";
import type { Actor, SessionUser } from "../persistence-types";
import { createAstropressRedirectRepository } from "../redirect-repository-factory";
import { createAstropressSettingsRepository } from "../settings-repository-factory";
import { type SiteSettings, defaultSiteSettings } from "../site-settings";
import { createAstropressTranslationRepository } from "../translation-repository-factory";
import { recordAudit } from "./audit-log";
import { type AstropressSqliteDatabaseLike, normalizePath } from "./utils";

type CommentStatus = "pending" | "approved" | "rejected";
type CommentPolicy = "legacy-readonly" | "disabled" | "open-moderated";

const SQL_GET_REDIRECT =
	"SELECT deleted_at FROM redirect_rules WHERE source_path = ? LIMIT 1";
const SQL_UPSERT_REDIRECT =
	"INSERT INTO redirect_rules (source_path, target_path, status_code, created_by, deleted_at) VALUES (?, ?, ?, ?, NULL) ON CONFLICT(source_path) DO UPDATE SET target_path = excluded.target_path, status_code = excluded.status_code, created_by = excluded.created_by, deleted_at = NULL";
const SQL_SOFT_DELETE_REDIRECT =
	"UPDATE redirect_rules SET deleted_at = CURRENT_TIMESTAMP WHERE source_path = ? AND deleted_at IS NULL";
const SQL_UPSERT_SETTINGS =
	"INSERT INTO site_settings (id, site_title, site_tagline, donation_url, newsletter_enabled, comments_default_policy, admin_slug, updated_at, updated_by) VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?) ON CONFLICT(id) DO UPDATE SET site_title = excluded.site_title, site_tagline = excluded.site_tagline, donation_url = excluded.donation_url, newsletter_enabled = excluded.newsletter_enabled, comments_default_policy = excluded.comments_default_policy, admin_slug = excluded.admin_slug, updated_at = CURRENT_TIMESTAMP, updated_by = excluded.updated_by";
const SQL_GET_COMMENT_ROUTE = "SELECT route FROM comments WHERE id = ? LIMIT 1";
const SQL_UPDATE_COMMENT_STATUS = "UPDATE comments SET status = ? WHERE id = ?";
const SQL_INSERT_COMMENT =
	"INSERT INTO comments (id, author, email, body, route, status, policy, submitted_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)";
const SQL_READ_TRANSLATION =
	"SELECT state FROM translation_overrides WHERE route = ? LIMIT 1";
const SQL_UPSERT_TRANSLATION =
	"INSERT INTO translation_overrides (route, state, updated_at, updated_by) VALUES (?, ?, CURRENT_TIMESTAMP, ?) ON CONFLICT(route) DO UPDATE SET state = excluded.state, updated_at = CURRENT_TIMESTAMP, updated_by = excluded.updated_by";

function queryRedirectRules(getDb: () => AstropressSqliteDatabaseLike) {
	const rows = getDb()
		.prepare(
			`
        SELECT source_path, target_path, status_code
        FROM redirect_rules
        WHERE deleted_at IS NULL
        ORDER BY source_path ASC
      `,
		)
		.all() as Array<{
		source_path: string;
		target_path: string;
		status_code: 301 | 302;
	}>;

	return rows.map((row) => ({
		sourcePath: row.source_path,
		targetPath: row.target_path,
		statusCode: row.status_code,
	}));
}

function queryComments(getDb: () => AstropressSqliteDatabaseLike) {
	const rows = getDb()
		.prepare(
			`
        SELECT id, author, email, body, route, status, policy, submitted_at
        FROM comments
        ORDER BY
          CASE status WHEN 'pending' THEN 0 WHEN 'approved' THEN 1 ELSE 2 END,
          datetime(submitted_at) DESC,
          id DESC
      `,
		)
		.all() as Array<{
		id: string;
		author: string;
		email: string | null;
		body: string | null;
		route: string;
		status: CommentStatus;
		policy: CommentPolicy;
		submitted_at: string;
	}>;

	return rows.map((row) => ({
		id: row.id,
		author: row.author,
		email: row.email ?? undefined,
		body: row.body ?? undefined,
		route: row.route,
		status: row.status,
		policy: row.policy,
		submittedAt: row.submitted_at,
	}));
}

function insertComment(
	getDb: () => AstropressSqliteDatabaseLike,
	comment: {
		id: string;
		author: string;
		email?: string;
		body?: string;
		route: string;
		status: CommentStatus;
		policy: CommentPolicy;
		submittedAt?: string;
	},
) {
	const submittedAt = comment.submittedAt ?? new Date().toISOString();
	getDb()
		.prepare(SQL_INSERT_COMMENT)
		.run(
			comment.id,
			comment.author,
			comment.email ?? null,
			comment.body ?? null,
			comment.route,
			comment.status,
			comment.policy,
			submittedAt,
		);
	return submittedAt;
}

export function createSqliteSettingsStore(
	getDb: () => AstropressSqliteDatabaseLike,
) {
	function getRedirectRules() {
		return queryRedirectRules(getDb);
	}

	const sqliteRedirectRepository = createAstropressRedirectRepository({
		getRedirectRules,
		normalizePath,
		getExistingRedirect(sourcePath: string) {
			const existing = getDb().prepare(SQL_GET_REDIRECT).get(sourcePath) as
				| { deleted_at: string | null }
				| undefined;
			return existing ? { deletedAt: existing.deleted_at } : null;
		},
		upsertRedirect({
			sourcePath,
			targetPath,
			statusCode,
			actor,
		}: {
			sourcePath: string;
			targetPath: string;
			statusCode: 301 | 302;
			actor: Actor;
		}) {
			getDb()
				.prepare(SQL_UPSERT_REDIRECT)
				.run(sourcePath, targetPath, statusCode, actor.email);
		},
		markRedirectDeleted(sourcePath: string) {
			return (
				getDb().prepare(SQL_SOFT_DELETE_REDIRECT).run(sourcePath).changes > 0
			);
		},
		recordRedirectAudit({
			actor,
			action,
			summary,
			targetId,
		}: { actor: Actor; action: string; summary: string; targetId: string }) {
			recordAudit(getDb(), actor, action, summary, "redirect", targetId);
		},
	});

	function getComments() {
		return queryComments(getDb);
	}

	const sqliteCommentRepository = createAstropressCommentRepository({
		getComments,
		getCommentRoute(commentId: string) {
			const comment = getDb().prepare(SQL_GET_COMMENT_ROUTE).get(commentId) as
				| { route: string }
				| undefined;
			return comment?.route ?? null;
		},
		updateCommentStatus(commentId: string, nextStatus: CommentStatus) {
			return (
				getDb().prepare(SQL_UPDATE_COMMENT_STATUS).run(nextStatus, commentId)
					.changes > 0
			);
		},
		insertPublicComment(comment: {
			id: string;
			author: string;
			email?: string;
			body?: string;
			route: string;
			status: CommentStatus;
			policy: CommentPolicy;
			submittedAt?: string;
		}) {
			return insertComment(getDb, comment);
		},
		recordCommentAudit({
			actor,
			action,
			summary,
			targetId,
		}: { actor: Actor; action: string; summary: string; targetId: string }) {
			recordAudit(getDb(), actor, action, summary, "comment", targetId);
		},
	});

	const sqliteTranslationRepository = createAstropressTranslationRepository({
		readTranslationState(route: string) {
			const row = getDb().prepare(SQL_READ_TRANSLATION).get(route) as
				| { state: string }
				| undefined;
			return row?.state;
		},
		persistTranslationState(route: string, state: string, actor: Actor) {
			getDb().prepare(SQL_UPSERT_TRANSLATION).run(route, state, actor.email);
		},
		recordTranslationAudit({
			actor,
			route,
			state,
		}: { actor: Actor; route: string; state: string }) {
			recordAudit(
				getDb(),
				actor,
				"translation.update",
				`Updated translation state for ${route} to ${state}.`,
				"content",
				route,
			);
		},
	});

	function getSettings(): SiteSettings {
		const row = getDb()
			.prepare(
				`
          SELECT site_title, site_tagline, donation_url, newsletter_enabled, comments_default_policy, admin_slug
          FROM site_settings
          WHERE id = 1
          LIMIT 1
        `,
			)
			.get() as
			| {
					site_title: string;
					site_tagline: string;
					donation_url: string;
					newsletter_enabled: number;
					comments_default_policy: SiteSettings["commentsDefaultPolicy"];
					admin_slug: string;
			  }
			| undefined;

		if (!row) {
			return { ...defaultSiteSettings };
		}

		return {
			siteTitle: row.site_title,
			siteTagline: row.site_tagline,
			donationUrl: row.donation_url,
			newsletterEnabled: row.newsletter_enabled === 1,
			commentsDefaultPolicy: row.comments_default_policy,
			adminSlug: row.admin_slug ?? "ap-admin",
		};
	}

	const sqliteSettingsRepository = createAstropressSettingsRepository({
		getSettings,
		persistSettings(updated: SiteSettings, actor: Actor) {
			getDb()
				.prepare(SQL_UPSERT_SETTINGS)
				.run(
					1,
					updated.siteTitle,
					updated.siteTagline,
					updated.donationUrl,
					updated.newsletterEnabled ? 1 : 0,
					updated.commentsDefaultPolicy,
					updated.adminSlug,
					actor.email,
				);
		},
		recordSettingsAudit(actor: Actor) {
			recordAudit(
				getDb(),
				actor,
				"settings.update",
				"Updated site settings.",
				"auth",
				"site-settings",
			);
		},
	});

	return {
		sqliteRedirectRepository,
		sqliteCommentRepository,
		sqliteTranslationRepository,
		sqliteSettingsRepository,
	};
}

mutants.replacement:
acceptLanguage.split(",").map(part => {
  const [tag, qPart] = part.trim().split(";");
  const q = qPart ? Number(qPart.trim().replace("q=", "")) : 1;
  return {
    tag: (tag ?? "").trim().toLowerCase(),
    q: Number.isFinite(q) ? q : 1
  };
})

src/sqlite-runtime/utils.ts.source:
import { getCmsConfig } from "../config";
import {
	createKmacDigest,
	hashPasswordArgon2id,
	verifyArgon2idPassword,
} from "../crypto-primitives";

type ContentStatus = "draft" | "review" | "published" | "archived";

interface SqliteStatementLike {
	run(...params: unknown[]): { changes?: number | bigint };
	get(...params: unknown[]): unknown;
	all(...params: unknown[]): unknown[];
}

export interface AstropressSqliteDatabaseLike {
	exec(sql: string): void;
	prepare(sql: string): SqliteStatementLike;
}

export interface PageRecord {
	slug: string;
	legacyUrl: string;
	title: string;
	templateKey: string;
	listingItems: Array<{
		title: string;
		href: string;
		excerpt: string;
		imageSrc: string;
		imageAlt: string;
	}>;
	paginationLinks: Array<{
		label: string;
		href: string;
		current: boolean;
	}>;
	sourceHtmlPath: string;
	updatedAt: string;
	body?: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	ogTitle?: string;
	ogDescription?: string;
	ogImage?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	kind?: string;
	status?: ContentStatus;
}

export function normalizeStructuredTemplateKey(value: unknown): string | null {
	if (typeof value !== "string" || !value) {
		return null;
	}
	try {
		return getCmsConfig().templateKeys.includes(value) ? value : null;
	} catch {
		return null;
	}
}

export function localeFromPath(pathname: string): string {
	let locales: readonly string[];
	try {
		locales = getCmsConfig().locales ?? ["en", "es"];
	} catch {
		locales = ["en", "es"];
	}
	for (const locale of locales) {
		if (pathname.startsWith(`/${locale}/`)) return locale;
	}
	// Default to the first locale (usually "en"), or "en" if the list is empty.
	return locales[0] ?? "en";
}

/**
 * Negotiate a locale from an `Accept-Language` request header against the
 * configured `locales` list (or the default `["en", "es"]` fallback).
 *
 * Returns the best-matching locale string, or the first configured locale when
 * no match is found.
 *
 * @example
 * ```ts
 * // Accept-Language: fr-CH, fr;q=0.9, en;q=0.8
 * localeFromAcceptLanguage("fr-CH, fr;q=0.9, en;q=0.8"); // "en" (if locales = ["en","es"])
 * localeFromAcceptLanguage("es;q=0.9, en;q=0.8");          // "es" (if locales = ["en","es"])
 * ```
 */
export function localeFromAcceptLanguage(
	acceptLanguage: string | null | undefined,
): string {
	let locales: readonly string[];
	try {
		locales = getCmsConfig().locales ?? ["en", "es"];
	} catch {
		locales = ["en", "es"];
	}

	if (!acceptLanguage) return locales[0] ?? "en";

	// Parse "lang-region;q=weight" entries, sorted by weight descending.
	const entries = acceptLanguage
		.split(",")
		.map((part) => {
			const [tag, qPart] = part.trim().split(";");
			const q = qPart ? Number(qPart.trim().replace("q=", "")) : 1;
			return {
				tag: (tag ?? "").trim().toLowerCase(),
				q: Number.isFinite(q) ? q : 1,
			};
		})
		.sort((a, b) => b.q - a.q);

	for (const { tag } of entries) {
		// Match exact locale or language prefix (e.g. "fr-CH" matches "fr")
		const matched = locales.find(
			(l) => l.toLowerCase() === tag || tag.startsWith(`${l.toLowerCase()}-`),
		);
		if (matched) return matched;
	}

	return locales[0] ?? "en";
}

export function getSeedPageRecords(): PageRecord[] {
	try {
		return getCmsConfig().seedPages as unknown as PageRecord[];
	} catch {
		return [];
	}
}

export function hashOpaqueToken(
	token: string,
	secret = "astropress-dev-root-secret",
) {
	return createKmacDigest(token, secret, "sqlite-opaque-token");
}

export function hashPasswordSync(password: string, iterations = 2) {
	return hashPasswordArgon2id(password, { iterations });
}

export function verifyPasswordSync(password: string, storedHash: string) {
	return verifyArgon2idPassword(password, storedHash);
}

export { normalizePath } from "../admin-normalizers";
export {
	normalizeSlug as slugifyTerm,
	normalizeContentStatus,
	parseIdList,
} from "../persistence-commons";

export function serializeIdList(values: number[] | undefined) {
	return JSON.stringify(
		(values ?? [])
			.filter((entry) => Number.isInteger(entry) && entry > 0)
			.sort((a, b) => a - b),
	);
}

export function parseSystemSettings(value: string | null) {
	if (!value) {
		return null;
	}

	try {
		const parsed = JSON.parse(value) as unknown;
		return parsed && typeof parsed === "object"
			? (parsed as Record<string, unknown>)
			: null;
	} catch {
		return null;
	}
}

export function normalizeSystemRoutePath(pathname: string) {
	const trimmed = pathname.trim();
	if (!trimmed) {
		return "";
	}
	return trimmed.startsWith("/") ? trimmed : `/${trimmed}`;
}

