import { hashPasswordArgon2id } from "./crypto-primitives";
import type { SqliteDatabaseLike } from "./sqlite-bootstrap.js";
import { getTableColumns } from "./sqlite-schema-compat.js";

export function hashPasswordSync(password: string, iterations = 2) {
	return hashPasswordArgon2id(password, { iterations });
}

export function guessMimeType(pathname: string) {
	const lower = pathname.toLowerCase();
	if (lower.endsWith(".png")) return "image/png";
	if (lower.endsWith(".webp")) return "image/webp";
	if (lower.endsWith(".gif")) return "image/gif";
	return "image/jpeg";
}

export function toSqlLiteral(value: unknown): string {
	if (value === null || value === undefined) return "NULL";
	if (typeof value === "number" || typeof value === "bigint")
		return String(value);
	if (typeof value === "boolean") return value ? "1" : "0";
	if (value instanceof Uint8Array)
		return `X'${Buffer.from(value).toString("hex")}'`;
	return `'${String(value).replaceAll("'", "''")}'`;
}

export function buildTableImportStatements(
	db: SqliteDatabaseLike,
	table: string,
) {
	const columns = getTableColumns(db, table);
	if (columns.length === 0) return [] as string[];

	const rows = db.prepare(`SELECT * FROM ${table}`).all() as Array<
		Record<string, unknown>
	>;
	const statements = [`DELETE FROM ${table};`];
	for (const row of rows) {
		const serializedValues = columns.map((column) => toSqlLiteral(row[column]));
		statements.push(
			`INSERT INTO ${table} (${columns.join(", ")}) VALUES (${serializedValues.join(", ")});`,
		);
	}
	return statements;
}

export function buildTableImportSql(db: SqliteDatabaseLike, table: string) {
	return buildTableImportStatements(db, table).join("\n");
}

src/submission-repository-factory.ts.source:
import type {
	ContactSubmission,
	SubmissionRepository,
	TestimonialSource,
	TestimonialStatus,
	TestimonialSubmission,
	TestimonialSubmissionInput,
} from "./persistence-types";

export interface AstropressSubmissionRepositoryInput {
	getContactSubmissions: SubmissionRepository["getContactSubmissions"];
	insertContactSubmission(submission: ContactSubmission): void;
	getTestimonials(status?: TestimonialStatus): TestimonialSubmission[];
	insertTestimonial(submission: TestimonialSubmission): void;
	updateTestimonialStatus(
		id: string,
		status: TestimonialStatus,
	): { ok: true } | { ok: false; error: string };
}

export function createAstropressSubmissionRepository(
	input: AstropressSubmissionRepositoryInput,
): SubmissionRepository {
	return {
		getContactSubmissions: (...args) => input.getContactSubmissions(...args),
		submitContact(rawInput) {
			const submission: ContactSubmission = {
				id: `contact-${crypto.randomUUID()}`,
				name: rawInput.name,
				email: rawInput.email,
				message: rawInput.message,
				submittedAt: rawInput.submittedAt,
			};

			input.insertContactSubmission(submission);
			return { ok: true as const, submission };
		},
		getTestimonials: (...args) => input.getTestimonials(...args),
		submitTestimonial(rawInput: TestimonialSubmissionInput) {
			const id = `testimonial-${crypto.randomUUID()}`;
			const submission: TestimonialSubmission = {
				id,
				name: rawInput.name,
				email: rawInput.email,
				company: rawInput.company,
				role: rawInput.role,
				beforeState: rawInput.beforeState,
				transformation: rawInput.transformation,
				specificResult: rawInput.specificResult,
				consentToPublish: rawInput.consentToPublish,
				status: "pending",
				source: rawInput.source as TestimonialSource,
				submittedAt: rawInput.submittedAt,
			};
			input.insertTestimonial(submission);
			return { ok: true as const, id };
		},
		moderateTestimonial(id: string, status: TestimonialStatus) {
			return input.updateTestimonialStatus(id, status);
		},
	};
}

src/sync/git.ts.source:
import {
	constants,
	copyFile,
	mkdir,
	readdir,
	rm,
	stat,
} from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import type { GitSyncAdapter } from "../platform-contracts";
import { checkpointSqliteWal } from "../sqlite-bootstrap-helpers";
import { runIntegrityCheck } from "../sqlite-integrity";

export interface AstropressGitSyncAdapterOptions {
	projectDir: string;
	include?: string[];
	logger?: { info: (msg: string) => void; warn: (msg: string) => void };
}

const defaultEntries = [
	"package.json",
	"astro.config.mjs",
	"src",
	"public",
	"content",
	"db",
	"tests",
];

async function pathExists(pathname: string) {
	try {
		await stat(pathname);
		return true;
	} catch {
		return false;
	}
}

async function copyFileWithReflink(
	src: string,
	dest: string,
): Promise<boolean> {
	try {
		await copyFile(src, dest, constants.COPYFILE_FICLONE);
		return true;
	} catch (err: unknown) {
		const code = (err as NodeJS.ErrnoException).code;
		if (code === "ENOTSUP" || code === "EOPNOTSUPP" || code === "EXDEV") {
			await copyFile(src, dest);
			return false;
		}
		throw err;
	}
}

// Recursive directory copy using COPYFILE_FICLONE (reflink) per file.
// For .sqlite files, checkpoints WAL first so the main file is self-contained.
async function copyTreeWithReflink(
	src: string,
	dest: string,
	warn: (msg: string) => void,
	options: { preCheckIntegrity?: boolean; postCheckIntegrity?: boolean } = {},
): Promise<{ fileCount: number; usedReflink: boolean }> {
	const metadata = await stat(src);

	if (!metadata.isDirectory()) {
		if (src.endsWith(".sqlite")) {
			if (options.preCheckIntegrity) {
				const check = await runIntegrityCheck(src, { mode: "quick" });
				if (check.status === "corrupt") {
					throw new Error(
						`Refusing to back up corrupt SQLite database at ${src}: ${check.messages.join("; ")}`,
					);
				}
				if (check.status === "unavailable") {
					warn(
						`SQLite integrity check unavailable for ${src} before backup: ${check.error}`,
					);
				}
			}
			await checkpointSqliteWal(src, warn);
		}
		const usedReflink = await copyFileWithReflink(src, dest);
		if (options.postCheckIntegrity && dest.endsWith(".sqlite")) {
			const check = await runIntegrityCheck(dest, { mode: "quick" });
			if (check.status !== "ok") {
				warn(
					`Restored SQLite database at ${dest} failed integrity check (${check.status}): ${
						check.messages.join("; ") || check.error || ""
					}`,
				);
			}
		}
		return { fileCount: 1, usedReflink };
	}

	await mkdir(dest, { recursive: true });
	const entries = await readdir(src, { withFileTypes: true });
	let fileCount = 0;
	let usedReflink = false;

	for (const entry of entries) {
		const r = await copyTreeWithReflink(
			join(src, entry.name),
			join(dest, entry.name),
			warn,
			options,
		);
		fileCount += r.fileCount;
		usedReflink = usedReflink || r.usedReflink;
	}

	return { fileCount, usedReflink };
}

async function processIncludes(
	includes: string[],
	srcBase: string,
	destBase: string,
	warn: (msg: string) => void,
	options: { preCheckIntegrity?: boolean; postCheckIntegrity?: boolean } = {},
): Promise<{ fileCount: number; anyReflink: boolean }> {
	let fileCount = 0;
	let anyReflink = false;
	for (const entry of includes) {
		const src = resolve(srcBase, entry);
		if (!(await pathExists(src))) continue;
		const dest = resolve(destBase, entry);
		await mkdir(dirname(dest), { recursive: true });
		const r = await copyTreeWithReflink(src, dest, warn, options);
		fileCount += r.fileCount;
		anyReflink = anyReflink || r.usedReflink;
	}
	return { fileCount, anyReflink };
}

export function createAstropressGitSyncAdapter(
	options: AstropressGitSyncAdapterOptions,
): GitSyncAdapter {
	const projectDir = resolve(options.projectDir);
	const include = options.include ?? defaultEntries;
	const log = options.logger?.info ?? (() => {});
	const warn = options.logger?.warn ?? (() => {});

	return {
		async exportSnapshot(targetDir) {
			const outputDir = resolve(targetDir);
			await rm(outputDir, { recursive: true, force: true });
			await mkdir(outputDir, { recursive: true });
			const { fileCount, anyReflink } = await processIncludes(
				include,
				projectDir,
				outputDir,
				warn,
				{ preCheckIntegrity: true },
			);
			log(
				anyReflink
					? `Snapshot exported using copy-on-write (reflink): ${fileCount} file(s)`
					: `Snapshot exported using standard copy: ${fileCount} file(s)`,
			);
			return { targetDir: outputDir, fileCount };
		},
		async importSnapshot(sourceDir) {
			const inputDir = resolve(sourceDir);
			// Remove existing entries before restoring, unlike export which starts fresh.
			for (const entry of include) {
				await rm(resolve(projectDir, entry), { recursive: true, force: true });
			}
			const { fileCount, anyReflink } = await processIncludes(
				include,
				inputDir,
				projectDir,
				warn,
				{
					postCheckIntegrity: true,
				},
			);
			log(
				anyReflink
					? `Snapshot imported using copy-on-write (reflink): ${fileCount} file(s)`
					: `Snapshot imported using standard copy: ${fileCount} file(s)`,
			);
			return { sourceDir: inputDir, fileCount };
		},
	};
}

