src/access/audit-deny.ts.source:
/**
 * Audit logging for access-control denies.
 *
 * Every `engine.can()` deny that flows through `requiresAccess` (page guard)
 * or `withAdminFormAction` (form action handler) writes a row to
 * `audit_events` so admins can review access denials post-mortem. The
 * resource_id is the requested action id; the summary is the engine's
 * matched-policy reason string.
 */

import { withLocalStoreFallback } from "../admin-store-dispatch";
import { recordD1Audit } from "../d1-audit";
import type { EvaluationResult } from "./types";

export interface LogAccessDenyInput {
	subjectEmail: string;
	action: string;
	decision: EvaluationResult;
}

/**
 * Records an `access:deny` audit row. Best-effort: failures are swallowed so
 * the deny path itself never throws.
 */
export async function logAccessDeny(
	locals: App.Locals | null | undefined,
	input: LogAccessDenyInput,
): Promise<void> {
	const summary = input.decision.reason || "Access denied";
	try {
		await withLocalStoreFallback<void>(
			locals,
			async () =>
				recordD1Audit(
					locals,
					{
						email: input.subjectEmail,
						role: "editor",
						name: input.subjectEmail,
					},
					"access:deny",
					"access",
					input.action,
					summary,
				),
			async (store) => {
				await store.recordAuditEvent({
					userEmail: input.subjectEmail,
					action: "access:deny",
					resourceType: "access",
					resourceId: input.action,
					summary,
				});
			},
		);
	} catch {
		// Audit logging is best-effort — never block a deny on a logging failure.
	}
}

src/access/engine.ts.source:
/**
 * Default JSON-condition policy engine.
 *
 * Construction:
 *   const engine = createPolicyEngine({ resolvePoliciesForSubject: ... });
 *
 * The engine is intentionally synchronous on the can() call — policies must
 * already be resolved for the subject (typically by a per-request middleware
 * that loads role + direct policies once and caches them on Astro.locals).
 *
 * Swap in a Rego or other implementation by writing your own object that
 * satisfies PolicyEngine; nothing in the call sites cares which engine it is.
 */

import { evaluate } from "./evaluator";
import type {
	Env,
	EvaluationResult,
	Policy,
	PolicyEngine,
	Resource,
	Subject,
} from "./types";

export interface JsonPolicyEngineOptions {
	/**
	 * Synchronous lookup — given a subject, return all policies the engine
	 * should consider. Typically the union of role policies + direct grants.
	 * The middleware that produces this list is the integration point with
	 * the access repository.
	 */
	resolvePoliciesForSubject: (subject: Subject) => readonly Policy[];
}

export function createPolicyEngine(
	options: JsonPolicyEngineOptions,
): PolicyEngine {
	return {
		can(
			subject: Subject,
			action: string,
			resource?: Resource,
			env?: Env,
		): EvaluationResult {
			const policies = options.resolvePoliciesForSubject(subject);
			return evaluate(subject, action, policies, resource, env);
		},
		policiesFor(subject: Subject): readonly Policy[] {
			return options.resolvePoliciesForSubject(subject);
		},
	};
}

src/access/page-guard.ts.source:
/**
 * Page-frontmatter access guard.
 *
 * Replaces the legacy `if (!adminUser || adminUser.role !== "admin") return
 * Astro.redirect(...)` block with a single `await requiresAccess(Astro,
 * "<action>")` call. The guard loads `Astro.locals.access` lazily, evaluates
 * the requested ABAC action, and returns:
 *
 *   - `null` when the subject is allowed (caller continues rendering)
 *   - a `Response` redirect when the subject is unauthenticated or denied
 *
 * Astro frontmatter pattern:
 *
 *   const guard = await requiresAccess(Astro, "settings:edit");
 *   if (guard) return guard;
 *
 * Server-side enforcement is the source of truth. Nav-level filtering is a
 * UI mirror — never rely on hiding a leaf as a security control.
 */

import { logAccessDeny } from "./audit-deny";
import { getAccessContext } from "./request-context";
import type { Env, Resource } from "./types";

const DEFAULT_FORBIDDEN_PATH = "/ap-admin?error=insufficient-permissions";
const DEFAULT_LOGIN_PATH = "/ap-admin/login";

export interface RequiresAccessOptions {
	resource?: Resource;
	env?: Env;
	/** Override the redirect target on deny. Defaults to /ap-admin?error=insufficient-permissions. */
	forbiddenPath?: string;
	/** Override the redirect target when there is no authenticated user. Defaults to /ap-admin/login. */
	loginPath?: string;
}

type AstroLike = {
	locals: App.Locals;
	redirect: (path: string, status?: number) => Response;
};

export async function requiresAccess(
	astro: AstroLike,
	action: string,
	options: RequiresAccessOptions = {},
): Promise<Response | null> {
	const access = await getAccessContext(astro);

	if (!access) {
		return astro.redirect(options.loginPath ?? DEFAULT_LOGIN_PATH);
	}

	const decision = access.can(action, options.resource, options.env);
	if (decision.decision === "deny") {
		await logAccessDeny(astro.locals, {
			subjectEmail: access.subject.email,
			action,
			decision,
		});
		const reason = encodeURIComponent(decision.reason);
		const fallback = `${DEFAULT_FORBIDDEN_PATH}&reason=${reason}`;
		return astro.redirect(options.forbiddenPath ?? fallback);
	}

	return null;
}

