describe("buildImportPlan branches", () => {
	it("produces a manual task when downloadMedia is true but no artifactDir is given", async () => {
		await writeFile(
			exportFile,
			makeWxr([
				makePost({
					id: "201",
					name: "hero-image",
					status: "inherit",
					type: "attachment",
				}),
			]),
			"utf8",
		);
		const inventory = await importer.inspectWordPress?.({ exportFile });
		const plan = await importer.planWordPressImport?.({
			inventory: inventory as NonNullable<typeof inventory>,
			downloadMedia: true,
			// no artifactDir
		});
		expect(
			plan?.manualTasks.some((t) =>
				t.includes(
					"Media download was requested without an artifact directory",
				),
			),
