	it("handles items with no link and no guid (triggers normalizePathname(!value) branch)", async () => {
		const item = [
			"<item>",
			"<title><![CDATA[No Link]]></title>",
			"<link></link>",
			"<wp:post_id>402</wp:post_id>",
			"<wp:post_name>no-link-post</wp:post_name>",
