import type { DatabaseSync } from "node:sqlite";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { registerCms } from "../src/config.js";
import { createAstropressSqliteAdminRuntime } from "../src/sqlite-admin-runtime.js";
import { STANDARD_CMS_CONFIG, makeDb } from "./helpers/make-db.js";
import {
	type RuntimeFixture,
	createRuntimeFixture,
	makePasswordHash,
} from "./helpers/sqlite-admin-runtime-fixture.js";

let fixture: RuntimeFixture;

beforeAll(() => {
	registerCms(STANDARD_CMS_CONFIG);
	fixture = createRuntimeFixture();
});

afterAll(() => {
	fixture.db.close();
});

// ─── Media helpers ────────────────────────────────────────────────────────────

/** Minimal 1-pixel transparent PNG (67 bytes) */
function makePngBytes(): Buffer {
	return Buffer.from(
		"89504e470d0a1a0a0000000d49484452000000010000000108060000001f15c489000000" +
			"0a49444154789c6260000000000200010e0221630000000049454e44ae426082",
		"hex",
	);
}

// ─── Media ────────────────────────────────────────────────────────────────────

describe("media", () => {
	it("listMediaAssets returns empty initially", () => {
		expect(fixture.store.media.listMediaAssets()).toBeInstanceOf(Array);
	});

	it("updateMediaAsset returns error for empty id (empty-id branch)", () => {
		const result = fixture.store.media.updateMediaAsset(
			{ id: "  " },
			fixture.actor,
		);
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/id is required/i);
	});

	it("updateMediaAsset returns error for non-existent asset (not-found branch)", () => {
		const result = fixture.store.media.updateMediaAsset(
			{ id: "does-not-exist", title: "New Title" },
			fixture.actor,
		);
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/could not be updated/i);
	});

	it("updateMediaAsset succeeds for an existing asset (success branch)", () => {
		fixture.db
			.prepare(
				"INSERT INTO media_assets (id, local_path, mime_type, file_size, alt_text, title, uploaded_by) VALUES (?, ?, ?, ?, ?, ?, ?)",
			)
			.run(
				"media-test-1",
				"/uploads/img.png",
				"image/png",
				1024,
				"old alt",
				"Old Title",
				"seed",
			);

		const result = fixture.store.media.updateMediaAsset(
			{ id: "media-test-1", title: "New Title", altText: "new alt" },
			fixture.actor,
		);
		expect(result.ok).toBe(true);
		const asset = fixture.store.media
			.listMediaAssets()
			.find((a) => a.id === "media-test-1");
		expect(asset?.title).toBe("New Title");
		expect(asset?.altText).toBe("new alt");
	});

	it("createMediaAsset: empty filename returns error (buildLocalMediaDescriptor !filename branch)", () => {
		const result = fixture.store.media.createMediaAsset(
			{ filename: "", bytes: makePngBytes() },
			fixture.actor,
		);
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/select a file/i);
	});

	it("createMediaAsset: zero-byte file returns error (byteLength === 0 branch)", () => {
		const result = fixture.store.media.createMediaAsset(
			{ filename: "empty.png", bytes: Buffer.alloc(0) },
			fixture.actor,
		);
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/select a file/i);
	});

	it("createMediaAsset: file too large returns error (> maxUploadBytes branch)", () => {
		const result = fixture.store.media.createMediaAsset(
			{ filename: "big.png", bytes: Buffer.alloc(11 * 1024 * 1024) },
			fixture.actor,
		);
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/10 MB/i);
	});

	it("createMediaAsset: invalid extension returns error (!allowedExtensions branch)", () => {
		const result = fixture.store.media.createMediaAsset(
			{ filename: "script.exe", bytes: makePngBytes() },
			fixture.actor,
		);
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/not allowed/i);
	});

	it("createMediaAsset: .png file succeeds (covers guessImageMimeType png branch, insertStoredMediaAsset, recordMediaAudit)", () => {
		const result = fixture.store.media.createMediaAsset(
			{
				filename: "photo.png",
				bytes: makePngBytes(),
				title: "Test Photo",
				altText: "A photo",
			},
			fixture.actor,
		);
		expect(result.ok).toBe(true);
		if (!result.ok) throw new Error("unreachable");
		expect(
			fixture.store.media.listMediaAssets().some((a) => a.id === result.id),
		).toBe(true);
	});

	it("createMediaAsset: .jpg file succeeds (covers guessImageMimeType jpeg fallback branch)", () => {
		expect(
			fixture.store.media.createMediaAsset(
				{ filename: "photo.jpg", bytes: makePngBytes() },
				fixture.actor,
			).ok,
		).toBe(true);
	});

	it("createMediaAsset: .svg file succeeds — no mimeType forces guessImageMimeType svg branch", () => {
		const svgBytes = Buffer.from(
			"<svg xmlns='http://www.w3.org/2000/svg'><rect/></svg>",
		);
		expect(
			fixture.store.media.createMediaAsset(
				{ filename: "icon.svg", bytes: svgBytes },
				fixture.actor,
			).ok,
		).toBe(true);
	});

	it("createMediaAsset: .webp file succeeds — no mimeType forces guessImageMimeType webp branch", () => {
		expect(
			fixture.store.media.createMediaAsset(
				{ filename: "img.webp", bytes: makePngBytes() },
				fixture.actor,
			).ok,
		).toBe(true);
	});

	it("createMediaAsset: .gif file succeeds — no mimeType forces guessImageMimeType gif branch", () => {
		const gifBytes = Buffer.from(
			"47494638396101000100800000ffffff00000021f90400000000002c00000000010001000002024401003b",
			"hex",
		);
		expect(
			fixture.store.media.createMediaAsset(
				{ filename: "anim.gif", bytes: gifBytes },
				fixture.actor,
			).ok,
		).toBe(true);
	});

	it("createMediaAsset: .avif file succeeds — no mimeType forces guessImageMimeType avif branch", () => {
		expect(
			fixture.store.media.createMediaAsset(
				{ filename: "img.avif", bytes: makePngBytes() },
				fixture.actor,
			).ok,
		).toBe(true);
	});

	it("createMediaAsset: .jpeg file succeeds (covers jpeg extension alias)", () => {
		expect(
			fixture.store.media.createMediaAsset(
				{ filename: "photo.jpeg", bytes: makePngBytes() },
				fixture.actor,
			).ok,
		).toBe(true);
	});

	it("createMediaAsset: explicit mimeType provided (covers guessedMime = mimeType branch)", () => {
		expect(
			fixture.store.media.createMediaAsset(
				{
					filename: "explicit.png",
					bytes: makePngBytes(),
					mimeType: "image/png",
				},
				fixture.actor,
			).ok,
		).toBe(true);
	});

	it("createMediaAsset: invalid explicit mimeType with valid extension returns error", () => {
		const result = fixture.store.media.createMediaAsset(
			{
				filename: "bad-mime.png",
				bytes: makePngBytes(),
				mimeType: "application/octet-stream",
			},
			fixture.actor,
		);
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/not allowed/i);
	});

	it("createMediaAsset: filename with no extension (covers .bin fallback branch)", () => {
		const result = fixture.store.media.createMediaAsset(
			{ filename: "noextension", bytes: makePngBytes() },
			fixture.actor,
		);
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/not allowed/i);
	});

	it("createMediaAsset: filename with special-chars-only base uses 'upload' as the base name", () => {
		expect(
			fixture.store.media.createMediaAsset(
				{ filename: "----.png", bytes: makePngBytes() },
				fixture.actor,
			).ok,
		).toBe(true);
	});

	it("deleteMediaAsset: empty id returns error", () => {
		const result = fixture.store.media.deleteMediaAsset("  ", fixture.actor);
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/id is required/i);
	});

	it("deleteMediaAsset: non-existent asset returns error", () => {
		const result = fixture.store.media.deleteMediaAsset(
			"does-not-exist",
			fixture.actor,
		);
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/could not be deleted/i);
	});

	it("deleteMediaAsset: /images/uploads/ path deleted via createMediaAsset flow (covers markStoredMediaDeleted, recordMediaAudit, deleteLocalMediaUpload)", () => {
		const created = fixture.store.media.createMediaAsset(
			{ filename: "to-delete.png", bytes: makePngBytes() },
			fixture.actor,
		);
		expect(created.ok).toBe(true);
		if (!created.ok) throw new Error("unreachable");
		const result = fixture.store.media.deleteMediaAsset(
			created.id,
			fixture.actor,
		);
		expect(result.ok).toBe(true);
		expect(
			fixture.store.media.listMediaAssets().some((a) => a.id === created.id),
		).toBe(false);
	});

	it("deleteMediaAsset: non-uploads local_path skips file deletion (deleteLocalMediaUpload !startsWith branch)", () => {
		fixture.db
			.prepare(
				"INSERT INTO media_assets (id, local_path, mime_type, file_size, alt_text, title, uploaded_by) VALUES (?, ?, ?, ?, ?, ?, ?)",
			)
			.run(
				"media-other-path",
				"/some/other/path.png",
				"image/png",
				512,
				"",
				"Other Path",
				"seed",
			);
		expect(
			fixture.store.media.deleteMediaAsset("media-other-path", fixture.actor)
				.ok,
		).toBe(true);
	});

	it("getLocalImageRoot uses ASTROPRESS_LOCAL_IMAGE_ROOT env var (branch 1)", () => {
		const prev = process.env.ASTROPRESS_LOCAL_IMAGE_ROOT;
		process.env.ASTROPRESS_LOCAL_IMAGE_ROOT = "/tmp/test-astropress-uploads";
		try {
			const testDb = makeDb();
			testDb
				.prepare(
					"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?2, ?4, 1, CASE WHEN ?3 = 'admin' THEN 1 ELSE 0 END)",
				)
				.run(
					"env@test.local",
					makePasswordHash("password"),
					"admin",
					"Env Test",
				);
			const rt = createAstropressSqliteAdminRuntime({
				getDatabase: () => testDb,
			});
			expect(
				rt.sqliteAdminStore.media.createMediaAsset(
					{ filename: "env-test.png", bytes: makePngBytes() },
					fixture.actor,
				).ok,
			).toBe(true);
			testDb.close();
		} finally {
			if (prev === undefined)
				// biome-ignore lint/performance/noDelete: = undefined keeps the key in Bun, causing getLocalUploadsDir to return "undefined/uploads" and create a stray directory
				delete process.env.ASTROPRESS_LOCAL_IMAGE_ROOT;
			else process.env.ASTROPRESS_LOCAL_IMAGE_ROOT = prev;
		}
	});
});

