				'{"hero":"full content"}',
				"seed",
			);
		cmsDb
			.prepare(
				"INSERT INTO cms_route_groups (id, kind, render_strategy, canonical_locale, canonical_path) VALUES (?, ?, ?, ?, ?)",
			)
			.run(
				"group-rich-archive",
				"archive",
				"archive_listing",
				"en",
				"/rich-blog",
			);
		cmsDb
			.prepare(
