	createRuntimeFixture,
} from "./helpers/sqlite-admin-runtime-fixture.js";

function unwrap<T>(v: T | undefined | null): NonNullable<T> {
	if (v == null) throw new Error("unexpected nullish in test fixture");
	return v as NonNullable<T>;
}

