					body: "Updated body",
					excerpt: "Updated excerpt",
					ogTitle: "Updated OG Title",
					ogDescription: "Updated OG Desc",
					ogImage: "/updated-og.png",
					canonicalUrlOverride: "https://example.com/updated",
					robotsDirective: "noindex",
					scheduledAt: new Date(Date.now() + 86400000).toISOString(),
					revisionNote: "Updated with all fields",
				},
				fixture.actor,
			).ok,
		).toBe(true);
	});

	it("createContentRecord: uses summary as excerpt when no explicit excerpt is given", () => {
		expect(
			fixture.store.content.createContentRecord(
				{
					title: "Summary Post",
					slug: "summary-post-test",
					status: "draft",
					seoTitle: "Summary Post SEO",
					metaDescription: "Summary meta",
					summary: "Post summary text",
				},
				fixture.actor,
			).ok,
		).toBe(true);
	});
});

// ─── Content restoreRevision optional assignment branches ────────────────────

describe("content restoreRevision optional assignment branches", () => {
	it("restoreRevision from a revision with authorIds/categoryIds/tagIds", () => {
		fixture.store.content.createContentRecord(
			{
				title: "Revision Post",
				slug: "revision-post-for-restore",
				status: "draft",
				seoTitle: "Revision SEO",
				metaDescription: "Revision meta",
			},
			fixture.actor,
		);
		fixture.store.taxonomies.createCategory({ name: "Rev Cat" }, fixture.actor);
		const catId = fixture.store.taxonomies
			.listCategories()
			.find((c) => c.name === "Rev Cat")?.id;
		fixture.store.content.saveContentState(
			"revision-post-for-restore",
			{
				title: "Revision Post",
				status: "draft",
				seoTitle: "Revision SEO",
				metaDescription: "Revision meta",
				categoryIds: [catId],
			},
			fixture.actor,
		);
		const revisions = unwrap(
			fixture.store.content.getContentRevisions("revision-post-for-restore"),
		);
		expect(
			fixture.store.content.restoreRevision(
				"revision-post-for-restore",
				revisions[0].id,
				fixture.actor,
			).ok,
		).toBe(true);
	});
});

// ─── Content entry optional fields in DB ─────────────────────────────────────

describe("content entry optional fields in DB", () => {
	it("listContentStates: content_entries with body and summary return non-null values", () => {
		fixture.db
			.prepare(`
      INSERT INTO content_entries (slug, legacy_url, title, kind, template_key, source_html_path, body, summary, seo_title, meta_description)
      VALUES (?, ?, ?, 'post', 'content', ?, ?, ?, ?, ?)
    `)
			.run(
				"custom-entry-with-body",
				"/custom-entry-with-body",
				"Custom Entry",
				"runtime://content/custom-entry-with-body",
				"Body content here",
				"Summary here",
				"Custom SEO",
				"Custom meta",
			);
		expect(
			fixture.store.content
				.listContentStates()
				.find((s) => s.slug === "custom-entry-with-body"),
		).toBeDefined();
	});
});

// ─── Submissions ──────────────────────────────────────────────────────────────

describe("submissions", () => {
	it("submitContact stores a submission and getContactSubmissions returns it", () => {
		const result = fixture.store.submissions.submitContact({
			name: "Alice",
			email: "alice@example.com",
			message: "Hello from form",
			submittedAt: new Date().toISOString(),
		});
		expect(result.ok).toBe(true);
		expect(
			fixture.store.submissions
				.getContactSubmissions()
				.some((s) => s.name === "Alice"),
		).toBe(true);
	});
});

// ─── Translations ─────────────────────────────────────────────────────────────

describe("translations", () => {
	it("getEffectiveTranslationState returns default when no override exists", () => {
		expect(
			fixture.store.translations.getEffectiveTranslationState(
				"/blog/no-override",
			),
		).toBe("not_started");
	});

	it("updateTranslationState persists state and getEffectiveTranslationState reads it back", () => {
		expect(
			fixture.store.translations.updateTranslationState(
				"/blog/translatable",
				"partial",
				fixture.actor,
			).ok,
		).toBe(true);
		expect(
			fixture.store.translations.getEffectiveTranslationState(
				"/blog/translatable",
			),
		).toBe("partial");
	});

	it("updateTranslationState returns error for invalid state", () => {
		expect(
			fixture.store.translations.updateTranslationState(
				"/blog/x",
				"invalid-state" as string,
				fixture.actor,
			).ok,
		).toBe(false);
	});
});

