describe("mapContactRow", () => {
	it("renames submitted_at → submittedAt and preserves all other fields", () => {
		expect(
			mapContactRow({
				id: "c-1",
				name: "Ada",
				email: "ada@example.test",
				message: "Hello",
				submitted_at: "2026-04-25T00:00:00Z",
