		expect(scaffold.envExample.PUBLIC_PLAUSIBLE_DOMAIN).toBeDefined();
		expect(scaffold.envExample.PUBLIC_PLAUSIBLE_SCRIPT_URL).toBeDefined();
	});

	it("matomo analytics produces correct env example keys", () => {
