import { mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";

import { describe, expect, it, vi } from "vitest";
import { createAstropressWordPressImportSource } from "../src/import/wordpress.js";

// SVG passes through downloadMedia without sharp transcoding, so no real
// image data is needed — the contract test verifies pipeline flow, not format.
const SVG_BYTES = new TextEncoder().encode(
	"<svg xmlns='http://www.w3.org/2000/svg'/>",
);

describe("wordpress import contract", () => {
	it("parses WXR content into staged import artifacts and redirects", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(async (url: string) => {
				if (typeof url === "string" && url.startsWith("https://example.org/")) {
					return new Response(SVG_BYTES, {
						status: 200,
						headers: { "content-type": "image/svg+xml" },
					});
				}
				throw new Error(`Unexpected fetch in test: ${url}`);
			}),
		);
		const workspace = await mkdtemp(
			join(tmpdir(), "astropress-wordpress-import-"),
		);
		const artifactDir = join(workspace, "artifacts");
		const exportFile = join(workspace, "export.xml");
		await writeFile(
			exportFile,
			[
				"<rss>",
				"<channel>",
				"<wp:author>",
				"<wp:author_id>7</wp:author_id>",
				"<wp:author_login><![CDATA[admin]]></wp:author_login>",
				"<wp:author_email><![CDATA[admin@example.org]]></wp:author_email>",
				"<wp:author_display_name><![CDATA[Admin Person]]></wp:author_display_name>",
				"</wp:author>",
				"<item>",
				"<title><![CDATA[Hello World]]></title>",
				"<link>https://example.org/blog/hello-world/</link>",
				'<content:encoded><![CDATA[<p>Intro</p>[gallery ids="1,2"]]]></content:encoded>',
				"<excerpt:encoded><![CDATA[A short summary]]></excerpt:encoded>",
				"<wp:post_id>101</wp:post_id>",
				"<wp:post_date>2024-01-01 12:00:00</wp:post_date>",
				"<wp:post_name>hello-world</wp:post_name>",
				"<wp:status>publish</wp:status>",
				"<wp:post_type>post</wp:post_type>",
				'<category domain="category" nicename="news"><![CDATA[News]]></category>',
				'<category domain="post_tag" nicename="featured"><![CDATA[Featured]]></category>',
				"<wp:postmeta><wp:meta_key>_wp_old_slug</wp:meta_key><wp:meta_value>hello-old</wp:meta_value></wp:postmeta>",
				"<wp:comment><wp:comment_id>1</wp:comment_id><wp:comment_author><![CDATA[Pat Reader]]></wp:comment_author><wp:comment_author_email><![CDATA[pat@example.org]]></wp:comment_author_email><wp:comment_date>2024-01-02 10:00:00</wp:comment_date><wp:comment_approved>1</wp:comment_approved><wp:comment_content><![CDATA[Nice post]]></wp:comment_content></wp:comment>",
				"</item>",
				"<item>",
				"<title><![CDATA[About]]></title>",
				"<link>https://example.org/about/</link>",
				"<content:encoded><![CDATA[<p>About us</p>]]></content:encoded>",
				"<wp:post_id>102</wp:post_id>",
				"<wp:post_name>about</wp:post_name>",
				"<wp:status>draft</wp:status>",
				"<wp:post_type>page</wp:post_type>",
				"</item>",
				"<item>",
				"<title><![CDATA[Hero Image]]></title>",
				"<link>https://example.org/wp-content/uploads/2024/01/hero.png</link>",
				"<wp:post_id>201</wp:post_id>",
				"<wp:post_name>hero-image</wp:post_name>",
				"<wp:status>inherit</wp:status>",
				"<wp:post_type>attachment</wp:post_type>",
				"<wp:post_parent>101</wp:post_parent>",
				"<wp:attachment_url>https://example.org/wp-content/uploads/2024/01/hero.png</wp:attachment_url>",
				"</item>",
				"</channel>",
				"</rss>",
			].join(""),
			"utf8",
		);

		const importer = createAstropressWordPressImportSource();
		const inventory = await importer.inspectWordPress?.({ exportFile });
		const plan = await importer.planWordPressImport?.({
			inventory: inventory as NonNullable<typeof inventory>,
			downloadMedia: true,
			artifactDir,
		});
		const report = await importer.importWordPress({
			exportFile,
			artifactDir,
			downloadMedia: true,
			plan,
		});

		expect(inventory).toMatchObject({
			exportFile,
			detectedRecords: 3,
			detectedMedia: 1,
			detectedComments: 1,
			detectedUsers: 1,
			detectedShortcodes: 1,
			entityCounts: {
				posts: 1,
				pages: 1,
				attachments: 1,
				redirects: 1,
				comments: 1,
				users: 1,
				categories: 1,
				tags: 1,
			},
			remediationCandidates: ["post-101"],
		});
		expect(plan).toMatchObject({
			artifactDir,
			downloadMedia: true,
			resumeSupported: true,
			permalinkStrategy: "preserve-wordpress-links",
			entityCounts: {
				redirects: 1,
			},
		});
		expect(report).toMatchObject({
			status: "completed_with_warnings",
			importedRecords: 2,
			importedMedia: 1,
			importedComments: 1,
			importedUsers: 1,
			importedRedirects: 1,
			downloadedMedia: 1,
			artifacts: {
				artifactDir,
			},
		});

		const contentRecords = JSON.parse(
			await readFile(join(artifactDir, "content-records.json"), "utf8"),
		) as Array<Record<string, unknown>>;
		const redirectRecords = JSON.parse(
			await readFile(join(artifactDir, "redirect-records.json"), "utf8"),
		) as Array<Record<string, unknown>>;
		const mediaManifest = JSON.parse(
			await readFile(join(artifactDir, "media-manifest.json"), "utf8"),
		) as Array<Record<string, unknown>>;
		const downloadState = JSON.parse(
			await readFile(join(artifactDir, "download-state.json"), "utf8"),
		) as { completed: string[]; failed: unknown[] };

		expect(contentRecords).toHaveLength(2);
		expect(contentRecords[0]).toMatchObject({
			id: "post-101",
			slug: "hello-world",
			legacyUrl: "/blog/hello-world/",
			categorySlugs: ["news"],
			tagSlugs: ["featured"],
		});
		expect(redirectRecords).toEqual([
			expect.objectContaining({
				sourcePath: "/blog/hello-old/",
				targetPath: "/blog/hello-world/",
			}),
		]);
		expect(mediaManifest).toEqual([
			expect.objectContaining({
				id: "media-201",
				parentLegacyId: "101",
			}),
		]);
		expect(downloadState.completed).toContain("media-201");
		expect(downloadState.failed).toEqual([]);

		const importReport = JSON.parse(
			await readFile(join(artifactDir, "import-report.json"), "utf8"),
		) as Record<string, unknown>;
		expect(importReport).toMatchObject({
			counts: { posts: 1 },
			mediaErrors: [],
		});
		expect(
			importReport.status === "completed" ||
				importReport.status === "completed_with_warnings",
		).toBe(true);

		const resumed = await importer.resumeWordPressImport?.({
			exportFile,
			artifactDir,
			downloadMedia: true,
		});
		expect(resumed?.downloadedMedia).toBe(0);
		expect(resumed?.artifacts?.downloadStateFile).toBe(
			join(artifactDir, "download-state.json"),
		);

		await rm(workspace, { recursive: true, force: true });
		vi.unstubAllGlobals();
	});

	it("can apply staged imports into the local sqlite runtime idempotently", async () => {
		const workspace = await mkdtemp(
			join(tmpdir(), "astropress-wordpress-apply-"),
		);
		const artifactDir = join(workspace, "artifacts");
		const adminDbPath = join(workspace, ".data", "admin.sqlite");
		const exportFile = join(workspace, "export.xml");
		await writeFile(
			exportFile,
			[
				"<rss>",
				"<channel>",
				"<wp:author><wp:author_id>7</wp:author_id><wp:author_login><![CDATA[admin]]></wp:author_login><wp:author_display_name><![CDATA[Admin Person]]></wp:author_display_name></wp:author>",
				'<item><title><![CDATA[Hello World]]></title><link>https://example.org/blog/hello-world/</link><content:encoded><![CDATA[<p>Intro</p>]]></content:encoded><excerpt:encoded><![CDATA[A short summary]]></excerpt:encoded><wp:post_id>101</wp:post_id><wp:post_name>hello-world</wp:post_name><wp:status>publish</wp:status><wp:post_type>post</wp:post_type><category domain="category" nicename="news"><![CDATA[News]]></category><category domain="post_tag" nicename="featured"><![CDATA[Featured]]></category><wp:postmeta><wp:meta_key>_wp_old_slug</wp:meta_key><wp:meta_value>hello-old</wp:meta_value></wp:postmeta><wp:comment><wp:comment_id>1</wp:comment_id><wp:comment_author><![CDATA[Pat Reader]]></wp:comment_author><wp:comment_content><![CDATA[Nice post]]></wp:comment_content><wp:comment_approved>1</wp:comment_approved></wp:comment></item>',
				"<item><title><![CDATA[Hero Image]]></title><link>https://example.org/wp-content/uploads/2024/01/hero.png</link><wp:post_id>201</wp:post_id><wp:post_name>hero-image</wp:post_name><wp:status>inherit</wp:status><wp:post_type>attachment</wp:post_type><wp:post_parent>101</wp:post_parent><wp:attachment_url>https://example.org/wp-content/uploads/2024/01/hero.png</wp:attachment_url></item>",
				"</channel>",
				"</rss>",
			].join(""),
			"utf8",
		);

		const importer = createAstropressWordPressImportSource();
		const first = await importer.importWordPress({
			exportFile,
			artifactDir,
			downloadMedia: true,
			applyLocal: true,
			workspaceRoot: workspace,
			adminDbPath,
		});
		const second = await importer.importWordPress({
			exportFile,
			artifactDir,
			downloadMedia: true,
			applyLocal: true,
			workspaceRoot: workspace,
			adminDbPath,
		});

		expect(first.localApply).toMatchObject({
			runtime: "sqlite-local",
			adminDbPath,
			appliedRecords: 1,
			appliedMedia: 1,
			appliedComments: 1,
			appliedUsers: 1,
			appliedRedirects: 1,
		});
		expect(second.localApply?.adminDbPath).toBe(adminDbPath);
		expect(first.artifacts?.localApplyReportFile).toBe(
			join(artifactDir, "wordpress.local-apply.json"),
		);

		const db = new DatabaseSync(adminDbPath);
		expect(
			(
				db.prepare("SELECT COUNT(*) AS count FROM content_entries").get() as {
					count: number;
				}
			).count,
		).toBe(1);
		expect(
			(
				db
					.prepare(
						"SELECT COUNT(*) AS count FROM authors WHERE deleted_at IS NULL",
					)
					.get() as { count: number }
			).count,
		).toBe(1);
		expect(
			(
				db
					.prepare(
						"SELECT COUNT(*) AS count FROM categories WHERE deleted_at IS NULL",
					)
					.get() as { count: number }
			).count,
		).toBe(1);
		expect(
			(
				db
					.prepare(
						"SELECT COUNT(*) AS count FROM tags WHERE deleted_at IS NULL",
					)
					.get() as { count: number }
			).count,
		).toBe(1);
		expect(
			(
				db.prepare("SELECT COUNT(*) AS count FROM comments").get() as {
					count: number;
				}
			).count,
		).toBe(1);
		expect(
			(
				db
					.prepare(
						"SELECT COUNT(*) AS count FROM media_assets WHERE deleted_at IS NULL",
					)
					.get() as { count: number }
			).count,
		).toBe(1);
		expect(
			(
				db
					.prepare(
						"SELECT COUNT(*) AS count FROM redirect_rules WHERE deleted_at IS NULL",
					)
					.get() as { count: number }
			).count,
		).toBe(1);
		db.close();

		await rm(workspace, { recursive: true, force: true });
	});

	it("skips local apply when applyLocal is false", async () => {
		const workspace = await mkdtemp(
			join(tmpdir(), "astropress-wordpress-noapply-"),
		);
		const artifactDir = join(workspace, "artifacts");
		const exportFile = join(workspace, "export.xml");
		await writeFile(
			exportFile,
			[
				"<rss><channel>",
				"<item><title><![CDATA[Hello]]></title><link>https://example.org/blog/hello/</link><content:encoded><![CDATA[<p>Hi</p>]]></content:encoded><wp:post_id>1</wp:post_id><wp:post_name>hello</wp:post_name><wp:status>publish</wp:status><wp:post_type>post</wp:post_type></item>",
				"</channel></rss>",
			].join(""),
			"utf8",
		);

		const importer = createAstropressWordPressImportSource();
		const report = await importer.importWordPress({
			exportFile,
			artifactDir,
			downloadMedia: false,
			applyLocal: false,
		});

		// localApply must be undefined when applyLocal: false
		expect(report.localApply).toBeUndefined();
		expect(report.importedRecords).toBe(1);

		await rm(workspace, { recursive: true, force: true });
	});
});

tests/sync-git.test.ts.source:
import {
	existsSync,
	mkdirSync,
	mkdtempSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import { createAstropressGitSyncAdapter } from "../src/sync/git";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

let testRoot: string;

function makeDir(name: string): string {
	const dir = join(testRoot, name);
	mkdirSync(dir, { recursive: true });
	return dir;
}

function writeFiles(dir: string, files: Record<string, string>) {
	for (const [rel, content] of Object.entries(files)) {
		const fullPath = join(dir, rel);
		mkdirSync(join(dir, rel, ".."), { recursive: true });
		writeFileSync(fullPath, content, "utf8");
	}
}

beforeEach(() => {
	testRoot = mkdtempSync(join(tmpdir(), "astropress-git-sync-test-"));
});

afterEach(() => {
	rmSync(testRoot, { recursive: true, force: true });
});

// ---------------------------------------------------------------------------
// exportSnapshot
// ---------------------------------------------------------------------------

describe("createAstropressGitSyncAdapter — exportSnapshot", () => {
	it("copies included entries to target dir and returns file count", async () => {
		const projectDir = makeDir("project-export");
		writeFiles(projectDir, {
			"package.json": '{"name":"test"}',
			"src/index.ts": "export {}",
			"src/utils.ts": "export const x = 1;",
		});

		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["package.json", "src"],
		});

		const targetDir = makeDir("snapshot-export");
		const result = await adapter.exportSnapshot(targetDir);

		expect(existsSync(join(targetDir, "package.json"))).toBe(true);
		expect(existsSync(join(targetDir, "src", "index.ts"))).toBe(true);
		expect(existsSync(join(targetDir, "src", "utils.ts"))).toBe(true);
		expect(result.fileCount).toBe(3); // package.json + 2 src files
		expect(result.targetDir).toContain("snapshot-export");
	});

	it("skips missing entries without error", async () => {
		const projectDir = makeDir("project-missing");
		writeFiles(projectDir, { "package.json": "{}" });

		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["package.json", "does-not-exist"],
		});

		const targetDir = makeDir("snapshot-missing");
		const result = await adapter.exportSnapshot(targetDir);

		expect(result.fileCount).toBe(1);
		expect(existsSync(join(targetDir, "does-not-exist"))).toBe(false);
	});

	it("overwrites an existing snapshot (idempotent)", async () => {
		const projectDir = makeDir("project-idem");
		writeFiles(projectDir, { "package.json": '{"v":1}' });

		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["package.json"],
		});
		const targetDir = makeDir("snapshot-idem");

		await adapter.exportSnapshot(targetDir);
		// Second export should not throw
		await expect(adapter.exportSnapshot(targetDir)).resolves.toBeDefined();
		expect(existsSync(join(targetDir, "package.json"))).toBe(true);
	});

	it("uses default include entries when not specified", async () => {
		const projectDir = makeDir("project-default");
		writeFiles(projectDir, {
			"package.json": "{}",
			"astro.config.mjs": "export default {}",
		});

		const adapter = createAstropressGitSyncAdapter({ projectDir });
		const targetDir = makeDir("snapshot-default");
		const result = await adapter.exportSnapshot(targetDir);

		// Only entries that exist in projectDir should be copied
		expect(existsSync(join(targetDir, "package.json"))).toBe(true);
		expect(result.fileCount).toBeGreaterThanOrEqual(2);
	});
});

// ---------------------------------------------------------------------------
// importSnapshot
// ---------------------------------------------------------------------------

describe("createAstropressGitSyncAdapter — importSnapshot", () => {
	it("copies snapshot entries back to project dir", async () => {
		const projectDir = makeDir("project-import");
		const snapshotDir = makeDir("snapshot-for-import");

		writeFiles(snapshotDir, {
			"package.json": '{"restored":true}',
			"src/index.ts": "// restored",
		});

		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["package.json", "src"],
		});

		const result = await adapter.importSnapshot(snapshotDir);

		expect(existsSync(join(projectDir, "package.json"))).toBe(true);
		expect(existsSync(join(projectDir, "src", "index.ts"))).toBe(true);
		expect(result.fileCount).toBe(2);
		expect(result.sourceDir).toContain("snapshot-for-import");
	});

	it("replaces existing files in project dir", async () => {
		const projectDir = makeDir("project-replace");
		writeFiles(projectDir, { "package.json": '{"old":true}' });

		const snapshotDir = makeDir("snapshot-replace");
		writeFiles(snapshotDir, { "package.json": '{"new":true}' });

		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["package.json"],
		});

		await adapter.importSnapshot(snapshotDir);

		const content = require("node:fs").readFileSync(
			join(projectDir, "package.json"),
			"utf8",
		);
		expect(JSON.parse(content).new).toBe(true);
	});

	it("skips missing entries in snapshot without error", async () => {
		const projectDir = makeDir("project-skip");
		const snapshotDir = makeDir("snapshot-skip");
		writeFiles(snapshotDir, { "package.json": "{}" });

		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["package.json", "missing-entry"],
		});

		const result = await adapter.importSnapshot(snapshotDir);
		expect(result.fileCount).toBe(1);
	});

	it("removes entries that exist in project but are absent from snapshot", async () => {
		const projectDir = makeDir("project-extra");
		writeFiles(projectDir, {
			"src/stale.ts": "// stale",
			"src/keep.ts": "// keep",
		});

		const snapshotDir = makeDir("snapshot-extra");
		writeFiles(snapshotDir, { "src/keep.ts": "// keep" });

		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["src"],
		});

		await adapter.importSnapshot(snapshotDir);

		expect(existsSync(join(projectDir, "src", "keep.ts"))).toBe(true);
		expect(existsSync(join(projectDir, "src", "stale.ts"))).toBe(false);
	});

	it("returns sourceDir in the result", async () => {
		const projectDir = makeDir("project-result");
		const snapshotDir = makeDir("snapshot-result");
		writeFiles(snapshotDir, { "package.json": "{}" });

		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["package.json"],
		});

		const result = await adapter.importSnapshot(snapshotDir);
		expect(result.sourceDir).toContain("snapshot-result");
		expect(result.fileCount).toBe(1);
	});
});

// ---------------------------------------------------------------------------
// SQLite WAL checkpoint + reflink logging
// ---------------------------------------------------------------------------

describe("createAstropressGitSyncAdapter — SQLite + reflink", () => {
	it("copies a .sqlite file without throwing, warning on checkpoint failure", async () => {
		// A plain text file named .sqlite exercises the checkpoint path without
		// a real database — checkpoint will fail gracefully and warn, then the
		// copy proceeds normally.
		const projectDir = makeDir("project-sqlite");
		writeFiles(projectDir, { "db/admin.sqlite": "not-a-real-db" });

		const warnings: string[] = [];
		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["db"],
			logger: { info: () => {}, warn: (msg) => warnings.push(msg) },
		});

		const targetDir = makeDir("snapshot-sqlite");
		const result = await adapter.exportSnapshot(targetDir);

		expect(result.fileCount).toBe(1);
		expect(existsSync(join(targetDir, "db", "admin.sqlite"))).toBe(true);
		// A warning should have been emitted because the file is not a real SQLite DB
		expect(warnings.length).toBeGreaterThan(0);
		expect(warnings[0]).toContain("admin.sqlite");
	});

	it("logs whether reflink was used via the logger", async () => {
		const projectDir = makeDir("project-log");
		writeFiles(projectDir, { "src/index.ts": "export {}" });

		const infos: string[] = [];
		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["src"],
			logger: { info: (msg) => infos.push(msg), warn: () => {} },
		});

		const targetDir = makeDir("snapshot-log");
		await adapter.exportSnapshot(targetDir);

		expect(infos.length).toBe(1);
		// Should mention either reflink or standard copy
		expect(infos[0]).toMatch(/copy-on-write|standard copy/);
	});

	it("does not warn for non-.sqlite files", async () => {
		const projectDir = makeDir("project-nosqlite");
		writeFiles(projectDir, {
			"src/index.ts": "export {}",
			"src/data.json": "{}",
		});

		const warnings: string[] = [];
		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["src"],
			logger: { info: () => {}, warn: (msg) => warnings.push(msg) },
		});

		const targetDir = makeDir("snapshot-nosqlite");
		await adapter.exportSnapshot(targetDir);

		expect(warnings).toHaveLength(0);
	});

	it("warns before export when a .sqlite file fails its integrity check", async () => {
		// A file named .sqlite that isn't a real DB: the integrity check returns
		// "unavailable" and git.ts's pre-export gate emits a warning (distinct
		// from the checkpoint warning).
		const projectDir = makeDir("project-integrity-export");
		writeFiles(projectDir, { "db/admin.sqlite": "garbage-not-a-db" });

		const warnings: string[] = [];
		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["db"],
			logger: { info: () => {}, warn: (msg) => warnings.push(msg) },
		});
		const targetDir = makeDir("snapshot-integrity-export");
		await adapter.exportSnapshot(targetDir);

		expect(
			warnings.some((w) =>
				w.startsWith("SQLite integrity check unavailable for"),
			),
		).toBe(true);
	});

	it("warns after import when the restored .sqlite file fails its integrity check", async () => {
		const projectDir = makeDir("project-integrity-import");
		const snapshotDir = makeDir("snapshot-integrity-import");
		writeFiles(snapshotDir, { "db/admin.sqlite": "garbage-not-a-db" });

		const warnings: string[] = [];
		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["db"],
			logger: { info: () => {}, warn: (msg) => warnings.push(msg) },
		});
		await adapter.importSnapshot(snapshotDir);

		expect(
			warnings.some((w) => w.startsWith("Restored SQLite database at")),
		).toBe(true);
	});

	it("logs importSnapshot copy method", async () => {
		const projectDir = makeDir("project-import-log");
		const snapshotDir = makeDir("snapshot-import-log");
		writeFiles(snapshotDir, { "src/index.ts": "export {}" });

		const infos: string[] = [];
		const adapter = createAstropressGitSyncAdapter({
			projectDir,
			include: ["src"],
			logger: { info: (msg) => infos.push(msg), warn: () => {} },
		});

		await adapter.importSnapshot(snapshotDir);

		expect(infos.length).toBe(1);
		expect(infos[0]).toMatch(/copy-on-write|standard copy/);
	});
});

