import { describe, expect, it } from "vitest";

import {
	applyAstropressSecurityHeaders,
	applyCacheHeaders,
	createAstropressSecureRedirect,
	createAstropressSecurityHeaders,
	isTrustedRequestOrigin,
	isTrustedStrictRequestOrigin,
} from "../src/security-headers.js";
import { resolveAstropressSecurityArea } from "../src/security-middleware.js";

describe("security headers", () => {
	it("builds a CSP that forbids inline scripts and framing by default", () => {
		// allowInlineStyles defaults to false — callers that need it must opt in explicitly
		const headers = createAstropressSecurityHeaders({
			area: "admin",
			allowInlineStyles: true,
		});
		const csp = headers.get("Content-Security-Policy") ?? "";

		expect(csp).toContain(
			"script-src 'self' https://challenges.cloudflare.com",
		);
		expect(csp).not.toContain("script-src 'self' 'unsafe-inline'");
		expect(csp).toContain("style-src 'self' 'unsafe-inline'");
		expect(csp).toContain("frame-ancestors 'none'");
		expect(headers.get("X-Frame-Options")).toBe("DENY");
		expect(headers.get("X-Content-Type-Options")).toBe("nosniff");
		expect(headers.get("Referrer-Policy")).toBe(
			"strict-origin-when-cross-origin",
		);
	});

	it("defaults allowInlineStyles to false — style-src excludes unsafe-inline without explicit opt-in", () => {
		const headers = createAstropressSecurityHeaders({ area: "admin" });
		const csp = headers.get("Content-Security-Policy") ?? "";
		expect(csp).toContain("style-src 'self'");
		expect(csp).not.toContain("'unsafe-inline'");
	});

	it("sets Cross-Origin-Resource-Policy: same-site for admin, auth, and api areas", () => {
		for (const area of ["admin", "auth", "api"] as const) {
			const headers = createAstropressSecurityHeaders({ area });
			expect(headers.get("Cross-Origin-Resource-Policy"), `area: ${area}`).toBe(
				"same-site",
			);
		}
		// Public area does NOT get CORP
		const publicHeaders = createAstropressSecurityHeaders({ area: "public" });
		expect(publicHeaders.has("Cross-Origin-Resource-Policy")).toBe(false);
	});

	it("adds HSTS only when explicitly requested", () => {
		const withoutHsts = createAstropressSecurityHeaders({ area: "auth" });
		const withHsts = createAstropressSecurityHeaders({
			area: "auth",
			forceHsts: true,
		});

		expect(withoutHsts.has("Strict-Transport-Security")).toBe(false);
		expect(withHsts.get("Strict-Transport-Security")).toContain(
			"max-age=31536000",
		);
	});

	it("applies headers onto an existing collection and secures redirects", () => {
		const target = new Headers({ "Cache-Control": "no-store" });
		applyAstropressSecurityHeaders(target, { area: "api" });

		// applyAstropressSecurityHeaders sets Cache-Control to 'private, no-store' for api area
		expect(target.get("Cache-Control")).toBe("private, no-store");
		expect(target.get("Permissions-Policy")).toContain("camera=()");

		const response = createAstropressSecureRedirect("/ap-admin/login", 302);
		expect(response.status).toBe(302);
		expect(response.headers.get("Location")).toBe("/ap-admin/login");
		expect(response.headers.get("Content-Security-Policy")).toContain(
			"default-src 'self'",
		);
		expect(response.headers.get("Cross-Origin-Resource-Policy")).toBe(
			"same-site",
		);
	});

	it("CSP includes all required default directives with proper separators", () => {
		const csp =
			createAstropressSecurityHeaders().get("Content-Security-Policy") ?? "";
		expect(csp).toContain("base-uri 'self'");
		expect(csp).toContain("img-src 'self' data: https:");
		expect(csp).toContain("font-src 'self' data: https:");
		expect(csp).toContain("connect-src 'self' https:");
		expect(csp).toContain("media-src 'self' data: https:");
		expect(csp).toContain("frame-src 'self' https://challenges.cloudflare.com");
		expect(csp).toContain("worker-src 'self' blob:");
		expect(csp).toContain("manifest-src 'self'");
		expect(csp).toContain("upgrade-insecure-requests");
		expect(csp).toContain("; base-uri 'self'");
	});

	it("default area is public — object-src self and COOP same-origin", () => {
		const headers = createAstropressSecurityHeaders();
		const csp = headers.get("Content-Security-Policy") ?? "";
		expect(csp).toContain("object-src 'self'");
		expect(headers.get("Cross-Origin-Opener-Policy")).toBe("same-origin");
	});

	it("accepts same-origin form posts and rejects cross-origin origins", () => {
		expect(
			isTrustedRequestOrigin(
				new Request("https://example.com/ap-admin/actions/content-save", {
					method: "POST",
					headers: { origin: "https://example.com" },
				}),
			),
		).toBe(true);

		expect(
			isTrustedRequestOrigin(
				new Request("https://example.com/ap-admin/actions/content-save", {
					method: "POST",
					headers: { origin: "https://attacker.example" },
				}),
			),
		).toBe(false);
	});

	it("adds report-uri and Report-To header when reportUri option is set", () => {
		const reportUri = "/ap-admin/actions/csp-report";
		const headers = createAstropressSecurityHeaders({
			area: "admin",
			reportUri,
		});
		const csp = headers.get("Content-Security-Policy") ?? "";

		expect(csp).toContain(`report-uri ${reportUri}`);
		expect(csp).toContain("report-to csp-endpoint");
		expect(headers.get("Report-To")).toContain("csp-endpoint");
		expect(headers.get("Report-To")).toContain(reportUri);
	});

	it("omits report-uri and Report-To when reportUri is not set", () => {
		const headers = createAstropressSecurityHeaders({ area: "admin" });
		const csp = headers.get("Content-Security-Policy") ?? "";

		expect(csp).not.toContain("report-uri");
		expect(csp).not.toContain("report-to");
		expect(headers.has("Report-To")).toBe(false);
	});

	it("rejects cross-origin requests and handles no-origin/no-referer (returns true)", () => {
		// referer check branch (origin absent, referer present)
		expect(
			isTrustedRequestOrigin(
				new Request("https://example.com/ap-admin/save", {
					method: "POST",
					headers: { referer: "https://example.com/ap-admin/page" },
				}),
			),
		).toBe(true); // same-origin referer → truthy

		expect(
			isTrustedRequestOrigin(
				new Request("https://example.com/ap-admin/save", {
					method: "POST",
					headers: { referer: "https://attacker.com/page" },
				}),
			),
		).toBe(false); // cross-origin referer → false

		// Lines 35-36: parseOrigin catch branch — invalid URL string in origin header
		expect(
			isTrustedRequestOrigin(
				new Request("https://example.com/ap-admin/save", {
					method: "POST",
					headers: { origin: "not-a-valid-url" },
				}),
			),
		).toBe(false); // origin header present but unparseable → return false (stricter: no fallback to referer)
	});

	it("uses SAMEORIGIN when frameAncestors option is not 'none'", () => {
		const headers = createAstropressSecurityHeaders({
			frameAncestors: "'self'",
		});
		expect(headers.get("X-Frame-Options")).toBe("SAMEORIGIN");
	});

	it("public area uses object-src self and form-action self https:", () => {
		const headers = createAstropressSecurityHeaders({ area: "public" });
		const csp = headers.get("Content-Security-Policy") ?? "";

		expect(csp).toContain("object-src 'self'");
		expect(csp).toContain("form-action 'self' https:");
	});

	it("admin/auth/api areas use object-src none and restricted form-action", () => {
		for (const area of ["admin", "auth", "api"] as const) {
			const csp =
				createAstropressSecurityHeaders({ area }).get(
					"Content-Security-Policy",
				) ?? "";
			expect(csp).toContain("object-src 'none'");
			expect(csp).toContain("form-action 'self'");
			expect(csp).not.toContain("form-action 'self' https:");
		}
	});

	it("disables inline styles when allowInlineStyles is false", () => {
		const csp =
			createAstropressSecurityHeaders({ allowInlineStyles: false }).get(
				"Content-Security-Policy",
			) ?? "";
		expect(csp).toContain("style-src 'self'");
		expect(csp).not.toContain("'unsafe-inline'");
	});

	it("applyCacheHeaders uses default 300/3600 TTL for public area", () => {
		const headers = new Headers();
		applyCacheHeaders(headers, "public");
		expect(headers.get("Cache-Control")).toBe(
			"public, max-age=300, s-maxage=3600, stale-while-revalidate=86400",
		);
	});

	it("applyCacheHeaders respects publicCacheTtl override for public area", () => {
		const headers = new Headers();
		applyCacheHeaders(headers, "public", 600);
		expect(headers.get("Cache-Control")).toBe(
			"public, max-age=600, s-maxage=7200, stale-while-revalidate=86400",
		);
	});

	it("applyCacheHeaders sets no-store for non-public areas regardless of publicCacheTtl", () => {
		for (const area of ["admin", "auth", "api"] as const) {
			const headers = new Headers();
			applyCacheHeaders(headers, area, 600);
			expect(headers.get("Cache-Control"), `area: ${area}`).toBe(
				"private, no-store",
			);
		}
	});

	it("isTrustedStrictRequestOrigin accepts same-origin origin header", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/accept-invite", {
					method: "POST",
					headers: { origin: "https://example.com" },
				}),
			),
		).toBe(true);
	});

	it("isTrustedStrictRequestOrigin rejects cross-origin origin header", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/accept-invite", {
					method: "POST",
					headers: { origin: "https://attacker.example" },
				}),
			),
		).toBe(false);
	});

	it("isTrustedStrictRequestOrigin accepts same-origin referer when origin absent", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/reset-password", {
					method: "POST",
					headers: { referer: "https://example.com/ap-admin/reset-password" },
				}),
			),
		).toBe(true);
	});

	it("isTrustedStrictRequestOrigin rejects cross-origin referer", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/reset-password", {
					method: "POST",
					headers: { referer: "https://attacker.example/page" },
				}),
			),
		).toBe(false);
	});

	it("isTrustedStrictRequestOrigin rejects requests with neither origin nor referer", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/accept-invite", {
					method: "POST",
				}),
			),
		).toBe(false);
	});

	it("isTrustedStrictRequestOrigin rejects invalid URL in origin header", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/accept-invite", {
					method: "POST",
					headers: { origin: "not-a-valid-url" },
				}),
			),
		).toBe(false);
	});

	it("classifies public, auth, admin, and action routes for middleware application", () => {
		expect(resolveAstropressSecurityArea(new URL("https://example.com/"))).toBe(
			"public",
		);
		expect(
			resolveAstropressSecurityArea(
				new URL("https://example.com/ap-admin/login"),
			),
		).toBe("auth");
		expect(
			resolveAstropressSecurityArea(new URL("https://example.com/ap-admin")),
		).toBe("admin");
		expect(
			resolveAstropressSecurityArea(
				new URL("https://example.com/ap-admin/actions/comment-moderate"),
			),
		).toBe("api");
	});
});

tests/download-media.test.ts.source:
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
	downloadMedia,
	validateMediaSourceUrl,
} from "../src/import/download-media.js";
import * as sharpTranscode from "../src/import/sharp-transcode.js";

// ---------------------------------------------------------------------------
// Use vi.spyOn() rather than vi.mock() so the patch works regardless of test
// file ordering under isolate:false. vi.mock() cannot replace a module that
// was already loaded by a prior test file in the shared registry; vi.spyOn()
// patches the live export on the already-loaded module object, which works
// no matter when the module was first imported.
// ---------------------------------------------------------------------------

let transcodeViaSharpSpy: ReturnType<
	typeof vi.spyOn<typeof sharpTranscode, "transcodeViaSharp">
>;

beforeEach(() => {
	transcodeViaSharpSpy = vi
		.spyOn(sharpTranscode, "transcodeViaSharp")
		.mockResolvedValue(Buffer.from([0xaa, 0xbb]));
});

afterEach(() => {
	transcodeViaSharpSpy.mockRestore();
});

describe("validateMediaSourceUrl", () => {
	it("accepts http URLs", () => {
		expect(() =>
			validateMediaSourceUrl("http://example.com/image.jpg"),
		).not.toThrow();
	});

	it("accepts https URLs", () => {
		expect(() =>
			validateMediaSourceUrl("https://example.com/image.png"),
		).not.toThrow();
	});

	it("blocks data: URLs", () => {
		expect(() => validateMediaSourceUrl("data:image/png;base64,abc")).toThrow(
			"Blocked non-HTTP URL scheme: data:",
		);
	});

	it("blocks file: URLs", () => {
		expect(() => validateMediaSourceUrl("file:///etc/passwd")).toThrow(
			"Blocked non-HTTP URL scheme: file:",
		);
	});

	it("blocks javascript: URLs", () => {
		expect(() => validateMediaSourceUrl("javascript:alert(1)")).toThrow(
			"Blocked non-HTTP URL scheme: javascript:",
		);
	});

	it("blocks localhost", () => {
		expect(() => validateMediaSourceUrl("http://localhost/secret")).toThrow(
			"Blocked request to private/loopback host",
		);
	});

	it("blocks 127.0.0.1", () => {
		expect(() => validateMediaSourceUrl("http://127.0.0.1/secret")).toThrow(
			"Blocked request to private/loopback host",
		);
	});

	it("blocks 10.x private range", () => {
		expect(() => validateMediaSourceUrl("http://10.0.0.1/secret")).toThrow(
			"Blocked request to private/loopback host",
		);
	});

	it("blocks 192.168.x private range", () => {
		expect(() => validateMediaSourceUrl("http://192.168.1.1/secret")).toThrow(
			"Blocked request to private/loopback host",
		);
	});

	it("blocks 172.16-31.x private range", () => {
		expect(() => validateMediaSourceUrl("http://172.16.0.1/secret")).toThrow(
			"Blocked request to private/loopback host",
		);
	});

	it("blocks 169.254.x link-local range", () => {
		expect(() =>
			validateMediaSourceUrl("http://169.254.169.254/latest/meta-data"),
		).toThrow("Blocked request to private/loopback host");
	});

	it("rejects invalid URLs", () => {
		expect(() => validateMediaSourceUrl("not a url")).toThrow("Invalid URL");
	});

	it("returns parsed URL for valid input", () => {
		const url = validateMediaSourceUrl("https://cdn.example.com/img.jpg");
		expect(url.hostname).toBe("cdn.example.com");
	});
});

describe("downloadMedia", () => {
	it("rejects non-media content-type", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response("<html></html>", {
						status: 200,
						headers: { "content-type": "text/html" },
					}),
			),
		);
		await expect(downloadMedia("https://example.com/page")).rejects.toThrow(
			'Blocked: unexpected media content-type "text/html"',
		);
		vi.unstubAllGlobals();
	});

	it("rejects responses exceeding size limit via content-length", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array(10), {
						status: 200,
						headers: {
							"content-type": "image/jpeg",
							"content-length": String(60 * 1024 * 1024),
						},
					}),
			),
		);
		await expect(downloadMedia("https://example.com/huge.jpg")).rejects.toThrow(
			"exceeds",
		);
		vi.unstubAllGlobals();
	});

	it("rejects non-OK HTTP responses", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(async () => new Response(null, { status: 404 })),
		);
		await expect(
			downloadMedia("https://example.com/missing.jpg"),
		).rejects.toThrow("HTTP 404");
		vi.unstubAllGlobals();
	});

	it("transcodes image/jpeg through sharp and returns its output", async () => {
		const rawJpeg = new Uint8Array([0xff, 0xd8, 0xff, 0xe0]);
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(rawJpeg, {
						status: 200,
						headers: { "content-type": "image/jpeg" },
					}),
			),
		);
		const bytes = await downloadMedia("https://example.com/photo.jpg");
		expect(transcodeViaSharpSpy).toHaveBeenCalledOnce();
		expect(bytes).toBeInstanceOf(Uint8Array);
		// Returns sharp's re-encoded output, not the raw HTTP bytes
		expect(Array.from(bytes)).toEqual([0xaa, 0xbb]);
		vi.unstubAllGlobals();
	});

	it("transcodes image/png through sharp", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array([0x89, 0x50, 0x4e, 0x47]), {
						status: 200,
						headers: { "content-type": "image/png" },
					}),
			),
		);
		await downloadMedia("https://example.com/photo.png");
		expect(transcodeViaSharpSpy).toHaveBeenCalledOnce();
		vi.unstubAllGlobals();
	});

	it("sanitizes image/svg+xml without calling sharp", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						'<svg xmlns="http://www.w3.org/2000/svg"><circle r="5"/></svg>',
						{
							status: 200,
							headers: { "content-type": "image/svg+xml" },
						},
					),
			),
		);
		const bytes = await downloadMedia("https://example.com/icon.svg");
		expect(transcodeViaSharpSpy).not.toHaveBeenCalled();
		const text = new TextDecoder().decode(bytes);
		expect(text).toContain("circle");
		vi.unstubAllGlobals();
	});

	it("strips script tags from SVG", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						'<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script><circle r="5"/></svg>',
						{ status: 200, headers: { "content-type": "image/svg+xml" } },
					),
			),
		);
		const bytes = await downloadMedia("https://example.com/malicious.svg");
		const text = new TextDecoder().decode(bytes);
		expect(text).not.toContain("<script");
		expect(text).not.toContain("alert(1)");
		expect(text).toContain("circle");
		vi.unstubAllGlobals();
	});

	it("strips on* event handlers from SVG", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						'<svg xmlns="http://www.w3.org/2000/svg"><circle r="5" onload="alert(1)"/></svg>',
						{ status: 200, headers: { "content-type": "image/svg+xml" } },
					),
			),
		);
		const bytes = await downloadMedia("https://example.com/handler.svg");
		const text = new TextDecoder().decode(bytes);
		expect(text).not.toContain("onload");
		expect(text).not.toContain("alert(1)");
		vi.unstubAllGlobals();
	});

	it("strips foreignObject from SVG", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(
						'<svg xmlns="http://www.w3.org/2000/svg"><foreignObject><div>hi</div></foreignObject></svg>',
						{ status: 200, headers: { "content-type": "image/svg+xml" } },
					),
			),
		);
		const bytes = await downloadMedia("https://example.com/foreign.svg");
		const text = new TextDecoder().decode(bytes);
		expect(text).not.toContain("foreignObject");
		expect(text).not.toContain("<div>");
		vi.unstubAllGlobals();
	});

	it("passes video/mp4 through without transcoding", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array(8), {
						status: 200,
						headers: { "content-type": "video/mp4" },
					}),
			),
		);
		const bytes = await downloadMedia("https://example.com/clip.mp4");
		expect(transcodeViaSharpSpy).not.toHaveBeenCalled();
		expect(bytes.length).toBe(8);
		vi.unstubAllGlobals();
	});

	it("passes application/pdf through without transcoding", async () => {
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array(16), {
						status: 200,
						headers: { "content-type": "application/pdf" },
					}),
			),
		);
		const bytes = await downloadMedia("https://example.com/doc.pdf");
		expect(transcodeViaSharpSpy).not.toHaveBeenCalled();
		expect(bytes.length).toBe(16);
		vi.unstubAllGlobals();
	});

	it("propagates sharp decode errors for corrupt image data", async () => {
		transcodeViaSharpSpy.mockRejectedValueOnce(
			new Error("Input buffer contains unsupported image format"),
		);
		vi.stubGlobal(
			"fetch",
			vi.fn(
				async () =>
					new Response(new Uint8Array([0x00, 0x00]), {
						status: 200,
						headers: { "content-type": "image/jpeg" },
					}),
			),
		);
		await expect(
			downloadMedia("https://example.com/corrupt.jpg"),
		).rejects.toThrow("Input buffer contains unsupported image format");
		vi.unstubAllGlobals();
	});

	it("rejects private IP before making any network call", async () => {
		const fetchSpy = vi.fn();
		vi.stubGlobal("fetch", fetchSpy);
		await expect(downloadMedia("http://192.168.0.1/secret")).rejects.toThrow(
			"Blocked request to private/loopback host",
		);
		expect(fetchSpy).not.toHaveBeenCalled();
		vi.unstubAllGlobals();
	});
});

