import { existsSync, mkdirSync, rmSync, statSync } from "node:fs";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

// ---------------------------------------------------------------------------
// vi.mock is hoisted above all let/const initializers, so any variable used
// inside the factory must be defined via vi.hoisted(). The module also captures
// getLocalUploadsDir() once at init time, so we use a fixed path and clean the
// directory between tests rather than creating a new path per run.
// ---------------------------------------------------------------------------

const { testUploadsDir } = vi.hoisted(() => {
	// eslint-disable-next-line @typescript-eslint/no-require-imports
	const { mkdtempSync } = require("node:fs") as typeof import("node:fs");
	// eslint-disable-next-line @typescript-eslint/no-require-imports
	const { join } = require("node:path") as typeof import("node:path");
	// eslint-disable-next-line @typescript-eslint/no-require-imports
	const { tmpdir } = require("node:os") as typeof import("node:os");
	return { testUploadsDir: mkdtempSync(join(tmpdir(), "astropress-media-")) };
});

vi.mock("../src/local-image-storage", () => ({
	ensureLocalUploadsDir: vi.fn(),
	getLocalUploadsDir: vi.fn(() => testUploadsDir),
	guessImageMimeType: vi.fn((path: string) => {
		if (path.endsWith(".png")) return "image/png";
		if (path.endsWith(".jpg") || path.endsWith(".jpeg")) return "image/jpeg";
		if (path.endsWith(".webp")) return "image/webp";
		if (path.endsWith(".gif")) return "image/gif";
		if (path.endsWith(".avif")) return "image/avif";
		if (path.endsWith(".svg")) return "image/svg+xml";
		return "application/octet-stream";
	}),
}));

import {
	buildLocalMediaDescriptor,
	createLocalMediaUpload,
	deleteLocalMediaUpload,
	guessMediaMimeType,
} from "../src/local-media-storage";

const validPng = new Uint8Array(1024); // 1 KB image bytes (fake PNG)
const oversizedFile = new Uint8Array(11 * 1024 * 1024); // 11 MB — exceeds limit

beforeEach(() => {
	rmSync(testUploadsDir, { recursive: true, force: true });
	mkdirSync(testUploadsDir, { recursive: true });
});

afterEach(() => {
	rmSync(testUploadsDir, { recursive: true, force: true });
});

// ---------------------------------------------------------------------------
// guessMediaMimeType
// ---------------------------------------------------------------------------

describe("guessMediaMimeType", () => {
	it("delegates to guessImageMimeType from local-image-storage", () => {
		expect(guessMediaMimeType("photo.png")).toBe("image/png");
		expect(guessMediaMimeType("photo.jpg")).toBe("image/jpeg");
		expect(guessMediaMimeType("photo.webp")).toBe("image/webp");
	});
});

// ---------------------------------------------------------------------------
// buildLocalMediaDescriptor
// ---------------------------------------------------------------------------

describe("buildLocalMediaDescriptor", () => {
	it("returns a valid descriptor for a PNG upload", () => {
		const result = buildLocalMediaDescriptor({
			filename: "photo.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.mimeType).toBe("image/png");
		expect(result.asset.fileSize).toBe(1024);
		expect(result.asset.publicPath).toMatch(/^\/images\/uploads\//);
		expect(result.asset.r2Key).toMatch(/^uploads\//);
		expect(result.asset.storedFilename).toMatch(/^media-[0-9a-f-]{36}$/);
	});

	it("uses provided title and altText", () => {
		const result = buildLocalMediaDescriptor({
			filename: "banner.png",
			bytes: validPng,
			title: "My Banner",
			altText: "A colourful banner",
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.title).toBe("My Banner");
		expect(result.asset.altText).toBe("A colourful banner");
	});

	it("falls back to sanitised basename as title", () => {
		const result = buildLocalMediaDescriptor({
			filename: "my awesome photo.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(result.asset.title).toBe("my-awesome-photo");
	});

	it("rejects empty filename", () => {
		const result = buildLocalMediaDescriptor({ filename: "", bytes: validPng });
		expect(result).toMatchObject({ ok: false });
		expect((result as { error: string }).error).toContain("Select a file");
	});

	it("rejects zero-byte file", () => {
		const result = buildLocalMediaDescriptor({
			filename: "empty.png",
			bytes: new Uint8Array(0),
		});
		expect(result).toMatchObject({ ok: false });
	});

	it("rejects file exceeding 10 MB", () => {
		const result = buildLocalMediaDescriptor({
			filename: "huge.png",
			bytes: oversizedFile,
		});
		expect(result).toMatchObject({ ok: false });
		expect((result as { error: string }).error).toContain("10 MB");
	});

	it("rejects disallowed extension (.php)", () => {
		const result = buildLocalMediaDescriptor({
			filename: "malicious.php",
			bytes: validPng,
		});
		expect(result).toMatchObject({ ok: false });
		expect((result as { error: string }).error).toContain("not allowed");
	});

	it("rejects disallowed extension (.exe)", () => {
		const result = buildLocalMediaDescriptor({
			filename: "evil.exe",
			bytes: validPng,
		});
		expect(result).toMatchObject({ ok: false });
	});

	it("accepts all allowed extensions", () => {
		const allowed = [
			"photo.jpg",
			"photo.jpeg",
			"photo.png",
			"photo.webp",
			"photo.gif",
			"photo.avif",
			"photo.svg",
		];
		for (const filename of allowed) {
			const result = buildLocalMediaDescriptor({ filename, bytes: validPng });
			expect(result.ok, `Expected ok for ${filename}`).toBe(true);
		}
	});

	it("generates a unique id on each call", () => {
		const r1 = buildLocalMediaDescriptor({
			filename: "a.png",
			bytes: validPng,
		});
		const r2 = buildLocalMediaDescriptor({
			filename: "b.png",
			bytes: validPng,
		});
		expect(r1.ok && r2.ok).toBe(true);
		if (!r1.ok || !r2.ok) return;
		expect(r1.asset.id).not.toBe(r2.asset.id);
	});
});

// ---------------------------------------------------------------------------
// createLocalMediaUpload
// ---------------------------------------------------------------------------

describe("createLocalMediaUpload", () => {
	it("writes the file to disk and returns descriptor", () => {
		const result = createLocalMediaUpload({
			filename: "test.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		expect(existsSync(result.asset.diskPath)).toBe(true);
	});

	it("writes file with owner-only permissions (mode 0o600)", () => {
		const result = createLocalMediaUpload({
			filename: "perm.png",
			bytes: validPng,
		});
		expect(result.ok).toBe(true);
		if (!result.ok) return;
		const stat = statSync(result.asset.diskPath);
		// Mode includes file type bits; mask to permission bits only
		expect(stat.mode & 0o777).toBe(0o600);
	});

	it("propagates validation errors without writing to disk", () => {
		const result = createLocalMediaUpload({
			filename: "bad.exe",
			bytes: validPng,
		});
		expect(result).toMatchObject({ ok: false });
	});
});

// ---------------------------------------------------------------------------
// deleteLocalMediaUpload
// ---------------------------------------------------------------------------

describe("deleteLocalMediaUpload", () => {
	it("deletes a file written to the uploads dir", () => {
		const result = createLocalMediaUpload({
			filename: "del.png",
			bytes: validPng,
		});
		if (!result.ok) return;
		expect(existsSync(result.asset.diskPath)).toBe(true);
		deleteLocalMediaUpload(result.asset.publicPath);
		expect(existsSync(result.asset.diskPath)).toBe(false);
	});

	it("is a no-op for paths outside the uploads dir", () => {
		// Should not throw
		expect(() => deleteLocalMediaUpload("/etc/passwd")).not.toThrow();
		expect(() =>
			deleteLocalMediaUpload("relative/path/file.png"),
		).not.toThrow();
	});

	it("is a no-op for non-existent files (no throw)", () => {
		expect(() =>
			deleteLocalMediaUpload("/images/uploads/does-not-exist-12345.png"),
		).not.toThrow();
	});
});

tests/honesty-invariants.test.ts.source:
/**
 * System honesty invariant tests
 *
 * These structural tests enforce that Astropress never tells the user an
 * operation succeeded when it hasn't — a set of "don't lie" guarantees.
 *
 * Honesty invariants enforced here:
 *   H1. EmailResult always has a `delivered` field; it is true only when
 *       Resend confirmed delivery.
 *   H2. Success-redirect params (?saved=1, ?scheduled=1, ?ok=1) appear only
 *       after a successful-result check in action handlers.
 *   H3. schedule-publish reads the content state before confirming
 *       `?scheduled=1` — prevents phantom schedule confirmations.
 *   H4. `delivered: true` appears only in explicit provider-success branches
 *       of transactional-email.ts.
 *   H5. releaseLock returns a boolean (or Promise<boolean>), not void — callers
 *       can inspect the result rather than assuming success.
 */

import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { findRepoRoot } from "./_helpers/repo-root";

// These are structural source-text invariants — they assert the source code is
// written a particular way. They must read the canonical repo source, NOT the
// Stryker-instrumented sandbox copy (where, e.g., `delivered: true` is rewritten
// for branch tracking and the regex no longer matches).
const repoRoot = findRepoRoot();
const srcRoot = path.join(repoRoot, "packages/astropress/src");
const actionsRoot = path.join(
	repoRoot,
	"packages/astropress/pages/ap-admin/actions",
);

function readSource(filePath: string): string {
	return readFileSync(filePath, "utf8");
}

function listFiles(root: string, ext: string): string[] {
	const results: string[] = [];
	for (const entry of readdirSync(root)) {
		const full = path.join(root, entry);
		const stat = statSync(full);
		if (stat.isDirectory()) {
			results.push(...listFiles(full, ext));
		} else if (full.endsWith(ext)) {
			results.push(full);
		}
	}
	return results.sort();
}

// ---------------------------------------------------------------------------
// H1 — EmailResult has a `delivered` boolean field
// ---------------------------------------------------------------------------

describe("H1: EmailResult has a delivered field", () => {
	it("transactional-email.ts defines `delivered: boolean` on EmailResult", () => {
		const src = readSource(path.join(srcRoot, "transactional-email.ts"));
		// The interface must declare `delivered: boolean`
		expect(src).toMatch(/delivered:\s*boolean/);
	});

	it("transactional-email.ts EmailResult interface includes both ok and delivered", () => {
		const src = readSource(path.join(srcRoot, "transactional-email.ts"));
		expect(src).toMatch(/interface EmailResult/);
		expect(src).toMatch(/ok:\s*boolean/);
		expect(src).toMatch(/delivered:\s*boolean/);
	});
});

// ---------------------------------------------------------------------------
// H2 — ?saved=1 / ?scheduled=1 / ?ok=1 redirects follow a success check
// ---------------------------------------------------------------------------

describe("H2: success-redirect params only appear after success checks", () => {
	const SUCCESS_PARAMS = ["?saved=1", "?scheduled=1", "?ok=1"];

	it("every action file containing a success redirect also contains a fail/error guard", () => {
		const actionFiles = listFiles(actionsRoot, ".ts");
		const violations: string[] = [];

		for (const file of actionFiles) {
			const src = readSource(file);
			const hasSuccessRedirect = SUCCESS_PARAMS.some((param) =>
				src.includes(param),
			);
			if (!hasSuccessRedirect) continue;

			// Must also have a failure path (fail(), return fail, or early return before the redirect)
			const hasFail =
				src.includes("fail(") ||
				src.includes("return fail") ||
				src.includes('fail("');
			const hasGuard =
				hasFail ||
				src.includes("if (!") || // early-return guard pattern
				src.includes("withAdminFormAction") || // withAdminFormAction wraps fail
				src.includes("requireAdminFormAction");

			if (!hasGuard) {
				violations.push(path.basename(file));
			}
		}

		expect(
			violations,
			`Action files with success redirects but no failure guards: ${violations.join(", ")}`,
		).toHaveLength(0);
	});
});

// ---------------------------------------------------------------------------
// H3 — schedule-publish reads content state before confirming ?scheduled=1
// ---------------------------------------------------------------------------

describe("H3: schedule-publish validates content exists before scheduling", () => {
	it("schedule-publish.ts calls getContentState before the ?scheduled=1 redirect", () => {
		const src = readSource(path.join(actionsRoot, "schedule-publish.ts"));

		// Both calls must exist
		expect(src, "must call getContentState to verify content exists").toMatch(
			/getContentState\(/,
		);
		expect(src, "must redirect to ?scheduled=1 on success").toMatch(
			/\?scheduled=1/,
		);

		// getContentState must appear before the redirect
		const getContentStatePos = src.indexOf("getContentState(");
		const scheduledRedirectPos = src.indexOf("?scheduled=1");
		expect(
			getContentStatePos,
			"getContentState must precede ?scheduled=1 redirect",
		).toBeLessThan(scheduledRedirectPos);
	});

	it("schedule-publish.ts returns early when content is not found", () => {
		const src = readSource(path.join(actionsRoot, "schedule-publish.ts"));
		// Must fail if existing is falsy — prevents phantom confirmations
		expect(src).toMatch(/if\s*\(!existing\)/);
	});
});

// ---------------------------------------------------------------------------
// H4 — `delivered: true` only in explicit provider-success branches
// ---------------------------------------------------------------------------

describe("H4: delivered: true set only in provider success branches", () => {
	it("transactional-email.ts sets `delivered: true` only in Resend and SMTP success branches", () => {
		const src = readSource(path.join(srcRoot, "transactional-email.ts"));

		const matches = [...src.matchAll(/delivered:\s*true/g)];
		expect(matches.length).toBe(2);

		const resendDeliveredPos = src.indexOf("delivered: true");
		const smtpDeliveredPos = src.indexOf(
			"delivered: true",
			resendDeliveredPos + 1,
		);
		const responseOkPos = src.lastIndexOf("response.ok", resendDeliveredPos);
		const smtpSendPos = src.lastIndexOf(
			"transporter.sendMail",
			smtpDeliveredPos,
		);

		expect(
			responseOkPos,
			"first delivered: true must be inside the response.ok success branch",
		).toBeGreaterThan(-1);
		expect(
			smtpSendPos,
			"second delivered: true must follow transporter.sendMail success",
		).toBeGreaterThan(-1);
	});

	it("non-Resend code paths set delivered: false", () => {
		const src = readSource(path.join(srcRoot, "transactional-email.ts"));
		// mock-mode path and error paths all use `delivered: false`
		const falseCounts = [...src.matchAll(/delivered:\s*false/g)].length;
		expect(falseCounts).toBeGreaterThanOrEqual(3); // mock, error, unconfigured
	});
});

// ---------------------------------------------------------------------------
// H5 — releaseLock returns boolean (not void)
// ---------------------------------------------------------------------------

describe("H5: releaseLock returns boolean, not void", () => {
	it("sqlite locks releaseLock returns boolean (not void)", () => {
		const src = readSource(path.join(srcRoot, "sqlite-runtime/locks.ts"));
		// Must declare return type boolean or Promise<boolean>
		expect(src).toMatch(/releaseLock[^:]*:[^{]*boolean/);
		// Must NOT use void return type for releaseLock
		expect(src).not.toMatch(/releaseLock[^:]*:[^{]*void/);
	});

	it("d1 locks releaseLock returns Promise<boolean> (not void)", () => {
		const src = readSource(path.join(srcRoot, "d1-locks.ts"));
		expect(src).toMatch(/releaseLock[^:]*:[^{]*Promise<boolean>/);
		expect(src).not.toMatch(/releaseLock[^:]*:[^{]*Promise<void>/);
	});
});

