import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { describe, expect, it } from "vitest";
import { createAstropressAdminAppIntegration } from "../src/admin-app-integration";
import {
	ASTROPRESS_ADMIN_BASE_PATH,
	createAstropressAdminRouteInjectionPlan,
	injectAstropressAdminRoutes,
	listAstropressAdminRoutes,
} from "../src/admin-routes";
import { defineAstropressHostRuntimeModules } from "../src/host-runtime-modules";
import { createAstropressViteIntegration } from "../src/vite-integration";
import { createAstropressLocalRuntimeModulePlugin } from "../src/vite-runtime-alias";
import { createAstropressVitestLocalRuntimePlugins } from "../src/vitest-runtime-alias";
import { findRepoRoot } from "./_helpers/repo-root";

const pagesDirectory = path.resolve(import.meta.dirname, "../pages/ap-admin");

describe("tooling integration", () => {
	it("ships page files for the canonical admin route inventory and injects them through the Astro integration", () => {
		const routeEntrypoints =
			createAstropressAdminRouteInjectionPlan(pagesDirectory);
		const injectedRoutes: Array<{ pattern: string; entrypoint: string }> = [];
		const integration = createAstropressAdminAppIntegration();

		for (const route of routeEntrypoints) {
			expect(
				existsSync(route.entrypoint),
				`missing file for ${route.pattern}: ${route.entrypoint}`,
			).toBe(true);
		}

		integration.hooks["astro:config:setup"]({
			injectRoute(route) {
				injectedRoutes.push(route);
			},
			addMiddleware: () => {},
		} as never);
		const callbackInjectedRoutes: Array<{
			pattern: string;
			entrypoint: string;
		}> = [];

		expect(ASTROPRESS_ADMIN_BASE_PATH).toBe("/ap-admin");
		expect(listAstropressAdminRoutes()).toHaveLength(routeEntrypoints.length);
		// The integration injects admin routes plus additional system routes (health, sitemap, robots, llms, metrics, og-image).
		// Filter to only the admin routes before comparing against the plan.
		const adminInjectedRoutes = injectedRoutes.filter((r) =>
			r.pattern.startsWith("/ap-admin"),
		);
		expect(adminInjectedRoutes).toEqual(routeEntrypoints);
		expect(
			injectAstropressAdminRoutes(pagesDirectory, (route) =>
				callbackInjectedRoutes.push(route),
			),
		).toEqual(routeEntrypoints);
		expect(callbackInjectedRoutes).toEqual(routeEntrypoints);
	});

	it("registers security middleware via addMiddleware in astro:config:setup", () => {
		const integration = createAstropressAdminAppIntegration();
		const registered: unknown[] = [];
		integration.hooks["astro:config:setup"]?.({
			injectRoute: () => {},
			addMiddleware: (m) => registered.push(m),
		} as never);
		expect(registered).toHaveLength(1);
		expect(registered[0]).toMatchObject({ order: "pre" });
	});

	it("exposes Vite, Vitest, and host runtime helpers from one coherent boundary", async () => {
		const localRuntimeModulesPath =
			"/tmp/site/src/astropress/local-runtime-modules.ts";
		const vite = createAstropressViteIntegration({
			localRuntimeModulesPath,
			cloudflareWorkersStubPath:
				"/tmp/site/src/astropress/cloudflare-workers-stub.ts",
		});
		const [replacePlugin, rewritePlugin] =
			createAstropressVitestLocalRuntimePlugins(localRuntimeModulesPath);
		const runtimePlugin = createAstropressLocalRuntimeModulePlugin(
			localRuntimeModulesPath,
		);
		const hostRuntimeModules = defineAstropressHostRuntimeModules({
			async loadLocalAdminStore() {
				return {} as never;
			},
			async loadLocalAdminAuth() {
				return {} as never;
			},
			async loadLocalCmsRegistry() {
				return {} as never;
			},
			async loadLocalMediaStorage() {
				return {} as never;
			},
			async loadLocalImageStorage() {
				return {} as never;
			},
		});

		expect(vite.plugins[0]?.name).toBe("astropress-local-runtime-modules");
		expect(vite.aliases).toHaveLength(3);
		expect(replacePlugin.name).toBe(
			"astropress-local-runtime-modules-replacer",
		);
		expect(rewritePlugin.name).toBe("astropress-external-source-rewriter");
		expect(runtimePlugin.resolveId("./local-runtime-modules")).toBe(
			localRuntimeModulesPath,
		);
		await expect(hostRuntimeModules.loadLocalAdminAuth()).resolves.toEqual({});
	});

	it("admin-harness astro config declares ssr.noExternal for @astropress-diy/astropress", () => {
		// Regression guard for the SSR-externalization bug fixed in ci/audit-scripts-and-workflow-hardening.
		//
		// When output:"server" is set, Vite SSR-externalizes workspace packages by
		// default, which means the astropress-local-runtime-modules Vite plugin is
		// never called for imports inside the package. As a result,
		// `./local-runtime-modules` in admin-store-dispatch.ts resolves to the dist
		// stub that throws `unavailable()`, breaking all admin CRUD form submissions.
		//
		// The fix is ssr.noExternal:["@astropress-diy/astropress"] in the harness
		// Vite config. This test prevents accidental removal.
		const configPath = path.join(
			findRepoRoot(),
			"examples/admin-harness/astro.config.mjs",
		);
		const source = readFileSync(configPath, "utf8");
		expect(
			source,
			"examples/admin-harness/astro.config.mjs must declare ssr.noExternal for @astropress-diy/astropress " +
				"so the Vite plugin pipeline intercepts ./local-runtime-modules imports inside the package. " +
				"Without this, admin CRUD form submissions silently fail with 'Local runtime modules are only available…'.",
		).toMatch(/noExternal[^}]*@astropress-diy\/astropress/s);
	});

	it("loads the emitted runtime js entrypoints cleanly", async () => {
		const runtimeEntryPoints = [
			"../src/platform-contracts.js",
			"../src/project-env.js",
			"../src/project-runtime.js",
			"../src/project-launch.js",
			"../src/provider-choice.js",
			"../src/admin-routes.js",
			"../src/admin-ui.js",
			"../src/config.js",
			"../src/hosted-api-adapter.js",
			"../src/d1-admin-store.js",
			"../src/hosted-platform-adapter.js",
			"../src/sqlite-bootstrap.js",
			"../src/sqlite-admin-runtime.js",
			"../src/adapters/sqlite.js",
			"../src/adapters/hosted.js",
			"../src/adapters/cloudflare.js",
			"../src/adapters/supabase.js",
			"../src/adapters/supabase-sqlite.js",
			"../src/adapters/local.js",
			"../src/adapters/project.js",
			"../src/admin-app-integration.js",
			"../src/integration.js",
			"../src/cloudflare-vite-integration.js",
			"../src/deploy/github-pages.js",
			"../src/deploy/cloudflare-pages.js",
			"../src/deploy/vercel.js",
			"../src/deploy/netlify.js",
			"../src/deploy/render.js",
			"../src/deploy/gitlab-pages.js",
			"../src/deploy/custom.js",
			"../src/content-services-ops.js",
			"../src/db-migrate-ops.js",
			"../src/import/wordpress.js",
			"../src/sync/git.js",
			"../src/newsletter-adapter.js",
			"../src/api-middleware.js",
		] as const;

		for (const entryPoint of runtimeEntryPoints) {
			const module = await import(
				pathToFileURL(new URL(entryPoint, import.meta.url).pathname).href
			);
			expect(module).toBeTruthy();
		}
	});
});

tests/cloudflare-provider.integration.te.source:
import {
	createAstropressCloudflareAdapter,
	registerCms,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";
import { makeDb } from "./helpers/make-db.js";
import {
	SqliteBackedD1Database,
	createSeededCloudflareDatabase,
} from "./helpers/provider-test-fixtures.js";

describe("cloudflare provider integration", () => {
	it("creates a D1-backed Cloudflare adapter surface", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = await createSeededCloudflareDatabase();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		expect(cloudflare.capabilities.name).toBe("cloudflare");
		expect(cloudflare.capabilities.database).toBe(true);
		expect(cloudflare.capabilities.objectStorage).toBe(true);

		const user = await cloudflare.auth.signIn("admin@example.com", "password");
		expect(user?.isAdmin).toBe(true);
		expect(user?.id).toHaveLength(36);
		const storedSession = db
			.prepare("SELECT id FROM admin_sessions LIMIT 1")
			.get() as { id: string };
		expect(storedSession.id).not.toBe(user?.id);
		expect(await cloudflare.auth.getSession(user?.id)).toMatchObject({
			email: "admin@example.com",
			isAdmin: true,
		});
		expect(await cloudflare.content.get("cloudflare-post")).toMatchObject({
			slug: "cloudflare-post",
			kind: "post",
			title: "Cloudflare post",
		});
		expect(await cloudflare.media.get("cloudflare-media-1")).toMatchObject({
			id: "cloudflare-media-1",
			mimeType: "image/png",
		});
		expect(await cloudflare.revisions.list("cloudflare-post")).toMatchObject([
			{
				id: "revision-cloudflare-1",
				recordId: "cloudflare-post",
			},
		]);
		await cloudflare.auth.signOut(user?.id);
		expect(await cloudflare.auth.getSession(user?.id)).toBeNull();

		db.close();
	});

	it("persists writable records through the D1-backed Cloudflare adapter", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = makeDb();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		const savedPost = await cloudflare.content.save({
			id: "cloudflare-write-post",
			kind: "post",
			slug: "cloudflare-write-post",
			status: "published",
			title: "Cloudflare write post",
			body: "<p>Writable Cloudflare body</p>",
			metadata: {
				metaDescription: "Writable Cloudflare record",
				seoTitle: "Cloudflare write post",
				legacyUrl: "/cloudflare-write-post",
			},
		});
		expect(savedPost.slug).toBe("cloudflare-write-post");
		expect(await cloudflare.content.get("cloudflare-write-post")).toMatchObject(
			{
				slug: "cloudflare-write-post",
				kind: "post",
				title: "Cloudflare write post",
			},
		);

		const translation = await cloudflare.content.save({
			id: "/es/cloudflare-write-post",
			kind: "translation",
			slug: "/es/cloudflare-write-post",
			status: "draft",
			metadata: {
				state: "translated",
			},
		});
		expect(translation.metadata).toMatchObject({
			state: "translated",
		});

		const redirect = await cloudflare.content.save({
			id: "/legacy-cloudflare-write-post",
			kind: "redirect",
			slug: "/legacy-cloudflare-write-post",
			status: "published",
			metadata: {
				targetPath: "/cloudflare-write-post",
				statusCode: 301,
			},
		});
		expect(redirect.metadata).toMatchObject({
			targetPath: "/cloudflare-write-post",
			statusCode: 301,
		});

		const settings = await cloudflare.content.save({
			id: "site-settings",
			kind: "settings",
			slug: "site-settings",
			status: "published",
			metadata: {
				siteTitle: "Cloudflare Writable Site",
			},
		});
		expect(settings.title).toBe("Cloudflare Writable Site");

		await cloudflare.media.put({
			id: "cloudflare-upload",
			filename: "cloudflare-upload.png",
			mimeType: "image/png",
			publicUrl: "https://cdn.example.com/cloudflare-upload.png",
			metadata: {
				altText: "Cloudflare upload",
				title: "cloudflare-upload.png",
			},
		});
		expect(await cloudflare.media.get("cloudflare-upload")).toMatchObject({
			id: "cloudflare-upload",
			mimeType: "image/png",
		});

		await cloudflare.revisions.append({
			id: "cloudflare-write-revision",
			recordId: "cloudflare-write-post",
			createdAt: "2026-01-01T00:00:00.000Z",
			actorId: "admin@example.com",
			summary: "Cloudflare write revision",
			snapshot: {
				title: "Cloudflare write post",
				status: "published",
				body: "<p>Writable Cloudflare body</p>",
				seoTitle: "Cloudflare write post",
				metaDescription: "Writable Cloudflare record",
			},
		});
		expect(await cloudflare.revisions.list("cloudflare-write-post")).toEqual(
			expect.arrayContaining([
				expect.objectContaining({
					id: "cloudflare-write-revision",
					recordId: "cloudflare-write-post",
				}),
			]),
		);

		await cloudflare.content.delete("/legacy-cloudflare-write-post");
		await cloudflare.media.delete("cloudflare-upload");

		expect(
			await cloudflare.content.get("/legacy-cloudflare-write-post"),
		).toBeNull();
		expect(await cloudflare.media.get("cloudflare-upload")).toBeNull();

		db.close();
	});

	it("throws when saving an unsupported record kind", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = makeDb();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		await expect(
			cloudflare.content.save({
				id: "comment-1",
				kind: "comment",
				slug: "comment-1",
				status: "published",
				metadata: {},
			} as Parameters<typeof cloudflare.content.save>[0]),
		).rejects.toThrow("does not support saving comment records yet");

		db.close();
	});

	it("returns without throwing when deleting an unsupported record kind", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = await createSeededCloudflareDatabase();

		// Insert a comment record — the Cloudflare adapter lists comments via readStore
		// and surfaces them through content.get(). The delete path now degrades gracefully.
		db.prepare(
			`INSERT INTO comments (id, author, email, body, route, status, policy, submitted_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		).run(
			"comment-del-1",
			"Test Author",
			"test@example.com",
			"Test comment",
			"/blog",
			"pending",
			"open-moderated",
			"2026-01-01T00:00:00.000Z",
		);

		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Unsupported record kind — adapter degrades gracefully (no-op) rather than throwing
		await expect(
			cloudflare.content.delete("comment-del-1"),
		).resolves.toBeUndefined();

		db.close();
	});
});

tests/deploy-trigger.test.ts.source:
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
	type DeployHookConfig,
	resolveDeployHookFromEnv,
	triggerPublish,
} from "../src/admin-action-publish";

// Capture fetch calls without hitting real endpoints
function mockFetch(status: number, body: unknown = {}) {
	return vi.fn().mockResolvedValue({
		ok: status >= 200 && status < 300,
		status,
		json: async () => body,
	});
}

describe("resolveDeployHookFromEnv", () => {
	it("returns cloudflare-pages when CF_PAGES_DEPLOY_HOOK_URL is set", () => {
		const env = { CF_PAGES_DEPLOY_HOOK_URL: "https://api.cloudflare.com/hook" };
		const config = resolveDeployHookFromEnv(env);
		expect(config?.type).toBe("cloudflare-pages");
	});

	it("returns vercel when VERCEL_DEPLOY_HOOK_URL is set", () => {
		const env = { VERCEL_DEPLOY_HOOK_URL: "https://api.vercel.com/hook" };
		const config = resolveDeployHookFromEnv(env);
		expect(config?.type).toBe("vercel");
	});

	it("returns netlify when NETLIFY_BUILD_HOOK_URL is set", () => {
		const env = {
			NETLIFY_BUILD_HOOK_URL: "https://api.netlify.com/build_hooks/abc",
		};
		const config = resolveDeployHookFromEnv(env);
		expect(config?.type).toBe("netlify");
	});

	it("returns render when RENDER_DEPLOY_HOOK_URL is set", () => {
		const env = {
			RENDER_DEPLOY_HOOK_URL: "https://api.render.com/deploy/srv-abc",
		};
		const config = resolveDeployHookFromEnv(env);
		expect(config?.type).toBe("render");
	});

	it("returns github-actions when GH_TOKEN and GH_REPO are set", () => {
		const env = { GH_TOKEN: "ghp_abc123", GH_REPO: "owner/repo" };
		const config = resolveDeployHookFromEnv(env);
		expect(config?.type).toBe("github-actions");
	});

	it("returns null when no deploy hook env vars are set", () => {
		const config = resolveDeployHookFromEnv({});
		expect(config).toBeNull();
	});

	it("prefers cloudflare-pages over vercel when both are set", () => {
		const env = {
			CF_PAGES_DEPLOY_HOOK_URL: "https://api.cloudflare.com/hook",
			VERCEL_DEPLOY_HOOK_URL: "https://api.vercel.com/hook",
		};
		const config = resolveDeployHookFromEnv(env);
		expect(config?.type).toBe("cloudflare-pages");
	});
});

describe("triggerPublish — cloudflare-pages", () => {
	let originalFetch: typeof fetch;

	beforeEach(() => {
		originalFetch = globalThis.fetch;
	});

	afterEach(() => {
		globalThis.fetch = originalFetch;
	});

	it("returns ok:true when deploy hook responds 200", async () => {
		globalThis.fetch = mockFetch(200, { id: "build-123" });

		const config: DeployHookConfig = {
			type: "cloudflare-pages",
			env: { CF_PAGES_DEPLOY_HOOK_URL: "https://api.cloudflare.com/mock-hook" },
		};

		const result = await triggerPublish(config);
		expect(result.ok).toBe(true);
	});

	it("returns ok:false when CF_PAGES_DEPLOY_HOOK_URL is missing", async () => {
		const config: DeployHookConfig = {
			type: "cloudflare-pages",
			env: {},
		};

		const result = await triggerPublish(config);
		expect(result.ok).toBe(false);
		expect(result.error).toContain("CF_PAGES_DEPLOY_HOOK_URL");
	});

	it("sends a POST to the deploy hook URL", async () => {
		const fetchSpy = mockFetch(200, {});
		globalThis.fetch = fetchSpy;

		const hookUrl = "https://api.cloudflare.com/mock-hook";
		const config: DeployHookConfig = {
			type: "cloudflare-pages",
			env: { CF_PAGES_DEPLOY_HOOK_URL: hookUrl },
		};

		await triggerPublish(config);

		expect(fetchSpy).toHaveBeenCalledWith(
			hookUrl,
			expect.objectContaining({ method: "POST" }),
		);
	});
});

describe("triggerPublish — github-actions", () => {
	let originalFetch: typeof fetch;

	beforeEach(() => {
		originalFetch = globalThis.fetch;
	});

	afterEach(() => {
		globalThis.fetch = originalFetch;
	});

	it("sends repository_dispatch to the correct GitHub API endpoint", async () => {
		const fetchSpy = mockFetch(204);
		globalThis.fetch = fetchSpy;

		const config: DeployHookConfig = {
			type: "github-actions",
			env: { GH_TOKEN: "ghp_test", GH_REPO: "myorg/mysite" },
		};

		const result = await triggerPublish(config);

		expect(result.ok).toBe(true);
		expect(fetchSpy).toHaveBeenCalledWith(
			"https://api.github.com/repos/myorg/mysite/dispatches",
			expect.objectContaining({ method: "POST" }),
		);

		// Verify the event_type is correct
		const callArgs = fetchSpy.mock.calls[0];
		const body = JSON.parse(callArgs[1].body as string);
		expect(body.event_type).toBe("astropress-publish");
	});

	it("returns ok:false when GH_TOKEN is missing", async () => {
		const config: DeployHookConfig = {
			type: "github-actions",
			env: { GH_REPO: "myorg/mysite" },
		};

		const result = await triggerPublish(config);
