import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { createAstropressCloudflareAdapter } from "../src/adapters/cloudflare.js";
import { createSessionTokenDigest, hashPassword } from "../src/crypto-utils.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

describe("cloudflare adapter security defaults", () => {
	it("does not allow insecure fallback sign-in unless explicitly enabled", async () => {
		const adapter = createAstropressCloudflareAdapter({
			users: [
				{
					id: "admin-1",
					email: "admin@example.com",
					isAdmin: true,
					password: "password",
				},
			],
		});

		await expect(
			adapter.auth.signIn("admin@example.com", "password"),
		).resolves.toBeNull();
	});

	it("supports explicit insecure fallback auth only for test-style callers", async () => {
		const adapter = createAstropressCloudflareAdapter({
			allowInsecureFallbackAuth: true,
			users: [
				{
					id: "admin-1",
					email: "admin@example.com",
					isAdmin: true,
					password: "password",
				},
			],
		});

		await expect(
			adapter.auth.signIn("admin@example.com", "password"),
		).resolves.toMatchObject({
			email: "admin@example.com",
			isAdmin: true,
		});
	});
});

describe("cloudflare session secret", () => {
	beforeEach(() => {
		vi.spyOn(console, "warn").mockImplementation(() => {});
		// biome-ignore lint/performance/noDelete: = undefined sets the string "undefined", not actual unset
		delete process.env.CLOUDFLARE_SESSION_SECRET;
	});

	afterEach(() => {
		vi.restoreAllMocks();
		// biome-ignore lint/performance/noDelete: = undefined sets the string "undefined", not actual unset
		delete process.env.CLOUDFLARE_SESSION_SECRET;
	});

	it("emits console.warn when using the default hardcoded secret", async () => {
		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?3, 'Admin', 1, CASE WHEN ?2='admin' THEN 1 ELSE 0 END)",
		).run("admin@example.com", "admin", await hashPassword("correctpass"));
		const d1 = new SqliteBackedD1Database(db);
		const adapter = createAstropressCloudflareAdapter({ db: d1 });
		await adapter.auth.signIn("admin@example.com", "correctpass");
		expect(console.warn).toHaveBeenCalledWith(
			expect.any(String),
			expect.stringContaining(
				"CLOUDFLARE_SESSION_SECRET is using the insecure default",
			),
		);
		db.close();
	});

	it("suppresses console.warn when CLOUDFLARE_SESSION_SECRET is set to a custom value", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "my-long-random-secret-value";
		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?3, 'Admin', 1, CASE WHEN ?2='admin' THEN 1 ELSE 0 END)",
		).run("admin@example.com", "admin", await hashPassword("correctpass"));
		const d1 = new SqliteBackedD1Database(db);
		const adapter = createAstropressCloudflareAdapter({ db: d1 });
		await adapter.auth.signIn("admin@example.com", "correctpass");
		expect(console.warn).not.toHaveBeenCalled();
		db.close();
	});

	it("session sign-in/lookup round-trips correctly with a custom secret", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "custom-test-secret-xyz";

		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?3, 'Admin', 1, CASE WHEN ?2='admin' THEN 1 ELSE 0 END)",
		).run("admin@example.com", "admin", await hashPassword("correctpass"));

		const d1 = new SqliteBackedD1Database(db);
		const adapter = createAstropressCloudflareAdapter({ db: d1 });

		const session = await adapter.auth.signIn(
			"admin@example.com",
			"correctpass",
		);
		expect(session).not.toBeNull();
		expect(session?.email).toBe("admin@example.com");

		const looked = await adapter.auth.getSession(session?.id);
		expect(looked).toMatchObject({ email: "admin@example.com" });

		await adapter.auth.signOut(session?.id);
		expect(await adapter.auth.getSession(session?.id)).toBeNull();

		db.close();
	});

	it("keeps sessions valid when CLOUDFLARE_SESSION_SECRET_PREV is present during rotation", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "old-cloudflare-secret";

		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?3, 'Admin', 1, CASE WHEN ?2='admin' THEN 1 ELSE 0 END)",
		).run("admin@example.com", "admin", await hashPassword("correctpass"));

		const d1 = new SqliteBackedD1Database(db);
		const adapter = createAstropressCloudflareAdapter({ db: d1 });

		const session = await adapter.auth.signIn(
			"admin@example.com",
			"correctpass",
		);
		expect(session).not.toBeNull();

		process.env.CLOUDFLARE_SESSION_SECRET = "new-cloudflare-secret";
		process.env.CLOUDFLARE_SESSION_SECRET_PREV = "old-cloudflare-secret";

		await expect(adapter.auth.getSession(session?.id)).resolves.toMatchObject({
			email: "admin@example.com",
			isAdmin: true,
		});

		await adapter.auth.signOut(session?.id);
		expect(await adapter.auth.getSession(session?.id)).toBeNull();

		db.close();
	});

	it("signs rotated Cloudflare sessions with the current secret, not the previous one", async () => {
		process.env.CLOUDFLARE_SESSION_SECRET = "new-cloudflare-secret";
		process.env.CLOUDFLARE_SESSION_SECRET_PREV = "old-cloudflare-secret";

		const db = makeDb();
		db.prepare(
			"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?1, ?3, 'Admin', 1, CASE WHEN ?2='admin' THEN 1 ELSE 0 END)",
		).run("admin@example.com", "admin", await hashPassword("correctpass"));

		const d1 = new SqliteBackedD1Database(db);
		const adapter = createAstropressCloudflareAdapter({ db: d1 });

		const session = await adapter.auth.signIn(
			"admin@example.com",
			"correctpass",
		);
		expect(session).not.toBeNull();

		const stored = db
			.prepare("SELECT id FROM admin_sessions LIMIT 1")
			.get() as { id: string };
		expect(stored.id).toBe(
			await createSessionTokenDigest(session?.id, "new-cloudflare-secret"),
		);
		expect(stored.id).not.toBe(
			await createSessionTokenDigest(session?.id, "old-cloudflare-secret"),
		);

		db.close();
	});
});

tests/web-components/html-editor.test.ts.source:
// @vitest-environment jsdom
import { afterEach, describe, expect, it } from "vitest";
import "../../web-components/html-editor";
import type { ApHtmlEditor } from "../../web-components/html-editor";

function stubDialog(dialog: HTMLDialogElement) {
	dialog.showModal = () => dialog.setAttribute("open", "");
	dialog.close = () => dialog.removeAttribute("open");
}

function makeEditor(initialBody = "<p>Hello</p>") {
	const el = document.createElement("ap-html-editor") as ApHtmlEditor;
	// Dialogs are siblings of the main form — not children — to avoid nested-form
	// parsing issues (HTML disallows <form> inside <form>).
	el.innerHTML = `
    <form method="post">
      <div role="toolbar" aria-label="Format body">
        <button type="button" data-cmd="bold">Bold</button>
        <button type="button" data-cmd="italic">Italic</button>
        <button type="button" data-cmd="insertUnorderedList">List</button>
        <button type="button" data-cmd="createLink">Link</button>
        <button type="button" class="insert-media-btn">Media</button>
      </div>
      <textarea data-body-editor name="body" rows="10">${initialBody}</textarea>
      <div class="preview-frame">
        <iframe title="Preview" sandbox=""></iframe>
      </div>
    </form>
    <dialog id="url-input-dialog" aria-labelledby="url-title">
      <h2 id="url-title">Insert link</h2>
      <form id="url-input-form" method="dialog">
        <input id="url-input-field" type="url" name="url" />
        <button type="submit">Insert</button>
        <button type="button" data-dialog-close>Cancel</button>
      </form>
    </dialog>
    <dialog id="media-library-dialog" aria-labelledby="media-title">
      <h2 id="media-title">Media</h2>
      <button id="media-dialog-close" type="button">Close</button>
    </dialog>
  `;
	const urlDialog = el.querySelector("#url-input-dialog") as HTMLDialogElement;
	const mediaDialog = el.querySelector(
		"#media-library-dialog",
	) as HTMLDialogElement;
	stubDialog(urlDialog);
	stubDialog(mediaDialog);

	document.body.appendChild(el);
	return {
		el,
		editor: el.querySelector("[data-body-editor]") as HTMLTextAreaElement,
		iframe: el.querySelector("iframe") as HTMLIFrameElement,
		toolbar: el.querySelector('[role="toolbar"]') as HTMLElement,
		urlDialog,
		mediaDialog,
		urlField: el.querySelector("#url-input-field") as HTMLInputElement,
		urlForm: el.querySelector("#url-input-form") as HTMLFormElement,
		mediaButton: el.querySelector(".insert-media-btn") as HTMLButtonElement,
		mediaClose: el.querySelector("#media-dialog-close") as HTMLButtonElement,
	};
}

describe("ApHtmlEditor", () => {
	afterEach(() => {
		document.body.innerHTML = "";
	});

	it("is registered as a custom element", () => {
		expect(customElements.get("ap-html-editor")).toBeDefined();
	});

	it("syncs initial body to iframe srcdoc on connect", () => {
		const { iframe } = makeEditor("<p>Hello</p>");
		expect(iframe.srcdoc).toContain("<p>Hello</p>");
		expect(iframe.srcdoc).toContain("<!doctype html>");
	});

	it("updates iframe srcdoc on textarea input", () => {
		const { editor, iframe } = makeEditor("");
		editor.value = "<p>Updated</p>";
		editor.dispatchEvent(new Event("input"));
		expect(iframe.srcdoc).toContain("<p>Updated</p>");
	});

	it("wraps selected text with bold tags on bold button click", () => {
		const { editor, toolbar } = makeEditor("Hello world");
		editor.setSelectionRange(6, 11); // select "world"
		toolbar.querySelector<HTMLButtonElement>('[data-cmd="bold"]')?.click();
		expect(editor.value).toBe("Hello <strong>world</strong>");
	});

	it("wraps selected text with italic tags on italic button click", () => {
		const { editor, toolbar } = makeEditor("Hello world");
		editor.setSelectionRange(0, 5); // select "Hello"
		toolbar.querySelector<HTMLButtonElement>('[data-cmd="italic"]')?.click();
		expect(editor.value).toBe("<em>Hello</em> world");
	});

	it("inserts a list placeholder when no text is selected", () => {
		const { editor, toolbar } = makeEditor("");
		editor.setSelectionRange(0, 0);
		toolbar
			.querySelector<HTMLButtonElement>('[data-cmd="insertUnorderedList"]')
			?.click();
		expect(editor.value).toContain("<ul>");
		expect(editor.value).toContain("<li>");
		expect(editor.value).toContain("List item");
	});

	it("opens URL dialog instead of window.prompt on createLink", () => {
		const { toolbar, urlDialog } = makeEditor("");
		toolbar
			.querySelector<HTMLButtonElement>('[data-cmd="createLink"]')
			?.click();
		expect(urlDialog.getAttribute("open")).toBe("");
	});

	it("inserts link wrapping selection after URL dialog submit", () => {
		const { editor, toolbar, urlField, urlForm } = makeEditor("click here");
		editor.setSelectionRange(0, 10); // select "click here"
		toolbar
			.querySelector<HTMLButtonElement>('[data-cmd="createLink"]')
			?.click();

		urlField.value = "https://example.com";
		urlForm.dispatchEvent(new Event("submit"));

		expect(editor.value).toBe('<a href="https://example.com">click here</a>');
	});

	it("does not insert link when URL field is empty", () => {
		const { editor, toolbar, urlField, urlForm } = makeEditor("click here");
		editor.setSelectionRange(0, 10);
		toolbar
			.querySelector<HTMLButtonElement>('[data-cmd="createLink"]')
			?.click();

		urlField.value = "";
		urlForm.dispatchEvent(new Event("submit"));

		expect(editor.value).toBe("click here");
	});

	it("opens media dialog on media button click", () => {
		const { mediaButton, mediaDialog } = makeEditor("");
		mediaButton.click();
		expect(mediaDialog.getAttribute("open")).toBe("");
	});

	it("closes media dialog on media close button click", () => {
		const { mediaButton, mediaDialog, mediaClose } = makeEditor("");
		mediaButton.click();
		mediaClose.click();
		expect(mediaDialog.getAttribute("open")).toBeNull();
	});

	it("removes event listeners after disconnectedCallback", () => {
		const { el, editor, iframe } = makeEditor("<p>Original</p>");
		document.body.removeChild(el);

		// After disconnect, input events should not update srcdoc
		const previousSrcdoc = iframe.srcdoc;
		editor.value = "<p>Changed after disconnect</p>";
		editor.dispatchEvent(new Event("input"));
		expect(iframe.srcdoc).toBe(previousSrcdoc);
	});
});

tests/locale-links.test.ts.source:
import {
	canonicalUrlForRoute,
	getAlternateLinksForEnglishRoute,
	getLocaleSwitchTargets,
	registerCms,
	sanitizeCanonicalUrl,
} from "@astropress-diy/astropress";
import { beforeEach, describe, expect, it } from "vitest";

beforeEach(() => {
	registerCms({
		siteUrl: "https://example.com",
		templateKeys: [],
		seedPages: [],
		archives: [],
		translationStatus: [
			{
				route: "/es/impacto",
				locale: "es",
				englishSourceUrl: "/impact",
				translationState: "published",
			},
			{
				route: "/es",
				locale: "es",
				englishSourceUrl: "/",
				translationState: "published",
			},
			{
				route: "/es/paisajes-comestibles",
				locale: "es",
				englishSourceUrl: "/en/edible-landscapes",
				translationState: "published",
			},
			{
				route: "/es/contacto",
				locale: "es",
				englishSourceUrl: "/en/contact",
				translationState: "published",
			},
		],
	});
});

describe("canonicalUrlForRoute()", () => {
	it("returns the full absolute URL for a given route", () => {
		expect(canonicalUrlForRoute("/impact")).toBe("https://example.com/impact/");
	});

	it("handles the root route without double slash", () => {
		expect(canonicalUrlForRoute("/")).toBe("https://example.com/");
	});

	it("appends a trailing slash to non-root routes", () => {
		expect(canonicalUrlForRoute("/en/education")).toBe(
			"https://example.com/en/education/",
		);
	});
});

describe("getAlternateLinksForEnglishRoute()", () => {
	it("returns EN + ES alternates for a known translated route (/impact → /es/impacto)", () => {
		const links = getAlternateLinksForEnglishRoute("/impact");
		expect(links).toHaveLength(2);
		const hreflangs = links.map((l) => l.hreflang);
		expect(hreflangs).toContain("en");
		expect(hreflangs).toContain("es");
		const esLink = links.find((l) => l.hreflang === "es");
		expect(esLink?.href).toContain("/es/impacto");
	});

	it("returns EN + ES alternates for the root route (/ → /es)", () => {
		const links = getAlternateLinksForEnglishRoute("/");
		expect(links).toHaveLength(2);
		const esLink = links.find((l) => l.hreflang === "es");
		expect(esLink?.href).toContain("/es");
	});

	it("returns EN + ES alternates for a core service route", () => {
		const links = getAlternateLinksForEnglishRoute("/en/edible-landscapes");
		expect(links).toHaveLength(2);
		const esLink = links.find((l) => l.hreflang === "es");
		expect(esLink?.href).toContain("/es/paisajes-comestibles");
	});

	it("returns empty array for an unknown route", () => {
		const links = getAlternateLinksForEnglishRoute("/non-existent-page");
		expect(links).toHaveLength(0);
	});
});

describe("sanitizeCanonicalUrl()", () => {
	it("returns absolute URL for a known route when no override is provided", () => {
		const url = sanitizeCanonicalUrl(undefined, "/en/impact");
		expect(url).toBe("https://example.com/en/impact/");
	});

	it("strips query string and hash from an override URL", () => {
		const url = sanitizeCanonicalUrl(
			"https://example.com/en/impact?utm_source=test#section",
			"/en/impact",
		);
		expect(url).not.toContain("utm_source");
		expect(url).not.toContain("#section");
		expect(url).toContain("example.com/en/impact");
	});

	it("normalizes trailing slash on override URL", () => {
		const url = sanitizeCanonicalUrl(
			"https://example.com/en/impact",
			"/en/impact",
		);
		expect(url).toMatch(/\/en\/impact\/$/);
	});

	it("preserves '/' without adding extra slash when override URL is the site root", () => {
		// Covers the `parsed.pathname === "/"` ternary true branch on line 46
		const url = sanitizeCanonicalUrl("https://example.com/", "/");
		expect(url).toBe("https://example.com/");
	});
});

describe("getLocaleSwitchTargets()", () => {
	it("uses explicit alternate links for reviewed EN/ES route pairs", () => {
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/contact",
			alternateLinks: [
				{ hreflang: "en", href: "https://example.com/en/contact/" },
				{ hreflang: "es", href: "https://example.com/es/contacto/" },
			],
		});

		expect(targets).toEqual({
			en: "/en/contact/",
			es: "/es/contacto/",
		});
	});

	it("falls back to locale homes when no reviewed alternate exists", () => {
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/about",
			alternateLinks: [],
		});

		expect(targets).toEqual({
			en: "/en/about",
			es: "/es",
		});
	});

	it("sets the current path for the es locale when on an es route (isLocalePath es branch)", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es/impacto",
			alternateLinks: [],
		});
		expect(targets.es).toBe("/es/impacto");
		expect(targets.en).toBe("/en");
	});

	it("uses empty array fallback when alternateLinks is omitted (?? [] branch)", () => {
		const targets = getLocaleSwitchTargets({ lang: "en" });
		expect(targets).toEqual({ en: "/en", es: "/es" });
	});

	it("redirects root path '/' to '/en' when viewed from es locale", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es/inicio",
			alternateLinks: [{ hreflang: "en", href: "https://example.com/" }],
		});
		expect(targets.en).toBe("/en");
	});

	it("skips alternate links with non-standard hreflang (fr is ignored)", () => {
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/about",
			alternateLinks: [
				{ hreflang: "fr", href: "https://example.com/fr/about/" },
				{ hreflang: "es", href: "https://example.com/es/sobre/" },
			],
		});
		// fr link ignored; es link used
		expect(targets.es).toBe("/es/sobre/");
		expect(targets).not.toHaveProperty("fr");
	});

	it("falls back to returning href as-is when URL parse fails (pathFromHref catch branch)", () => {
		const badHref = "http://[invalid-host]/path/";
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/about",
			alternateLinks: [{ hreflang: "es", href: badHref }],
		});
		// The catch branch returns the raw href string as the path
		expect(targets.es).toBe(badHref);
	});
});

tests/runtime-actions-taxonomies.test.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { beforeEach, describe, expect, it } from "vitest";

import { registerCms } from "../src/config";
import {
	createRuntimeAuthor,
	createRuntimeCategory,
	createRuntimeTag,
	deleteRuntimeAuthor,
	deleteRuntimeCategory,
	deleteRuntimeTag,
	updateRuntimeAuthor,
	updateRuntimeCategory,
	updateRuntimeTag,
} from "../src/runtime-actions-taxonomies";
import {
	STANDARD_ACTOR,
	STANDARD_CMS_CONFIG,
	makeDb,
} from "./helpers/make-db.js";
import { makeLocals } from "./helpers/make-locals.js";

const actor = STANDARD_ACTOR;

let db: DatabaseSync;
let locals: App.Locals;

beforeEach(() => {
	db = makeDb();
	locals = makeLocals(db);
	registerCms(STANDARD_CMS_CONFIG);

	db.prepare("INSERT INTO authors (name, slug, bio) VALUES (?, ?, ?)").run(
		"Existing Author",
		"existing-author",
		"Bio",
	);
	db.prepare("INSERT INTO categories (name, slug) VALUES (?, ?)").run(
		"Existing Cat",
		"existing-cat",
	);
	db.prepare("INSERT INTO tags (name, slug) VALUES (?, ?)").run(
		"Existing Tag",
		"existing-tag",
	);
});

describe("createRuntimeAuthor", () => {
	it("creates an author", async () => {
		const result = await createRuntimeAuthor(
			{ name: "New Author" },
			actor,
			locals,
		);
		expect(result).toMatchObject({ ok: true });
		const row = db
			.prepare("SELECT name FROM authors WHERE slug = 'new-author'")
			.get() as { name: string } | undefined;
		expect(row?.name).toBe("New Author");
	});

	it("rejects duplicate slug", async () => {
		const result = await createRuntimeAuthor(
			{ name: "Existing Author" },
			actor,
			locals,
		);
		expect(result).toMatchObject({ ok: false });
	});

	it("rejects empty name", async () => {
		const result = await createRuntimeAuthor({ name: "   " }, actor, locals);
		expect(result).toMatchObject({ ok: false });
	});
});

