import { afterEach, describe, expect, it } from "vitest";

import { buildAstropressAdminDocumentTitle } from "../src/admin-branding";
import {
	adminLabels,
	getAdminLabel,
	resolveAstropressAdminUiConfig,
} from "../src/admin-ui";
import { getCmsConfig, type peekCmsConfig, registerCms } from "../src/config";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

function restoreConfig(config: ReturnType<typeof peekCmsConfig>) {
	(globalThis as typeof globalThis & { [CMS_CONFIG_KEY]?: unknown })[
		CMS_CONFIG_KEY
	] = config ?? null;
}

afterEach(() => {
	restoreConfig(null);
});

describe("getCmsConfig — uninitialized state", () => {
	it("throws when getCmsConfig is called before registerCms", () => {
		restoreConfig(null);
		expect(() => getCmsConfig()).toThrow("Astropress not initialized");
	});
});

describe("admin ui", () => {
	it("exposes generic defaults when no admin customization is registered", () => {
		restoreConfig(null);

		const adminUi = resolveAstropressAdminUiConfig();

		expect(adminUi.branding.productName).toBe("Astropress Admin");
		expect(adminUi.branding.logoSrc).toBeNull();
		expect(adminUi.branding.stylesheetHref).toBeNull();
		expect(adminUi.labels.sidebarTitle).toBe("Workspace");
		expect(adminUi.navigation.routePages).toBe("Route Table");
		expect(buildAstropressAdminDocumentTitle("Dashboard")).toBe(
			"Dashboard | Astropress Admin",
		);
	});

	it("merges host branding, labels, navigation, and assets from registerCms()", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["home"],
			seedPages: [],
			archives: [],
			translationStatus: [],
			admin: {
				branding: {
					appName: "Client Console",
					productName: "Client Console Admin",
					shellName: "Client Workspace",
					logoSrc: "/brand/admin-mark.svg",
					faviconHref: "/brand/favicon.ico",
					stylesheetHref: "/brand/admin.css",
				},
				labels: {
					sidebarTitle: "Operations",
					signOut: "Log out",
					loginHeading: "Client sign in",
					loginSubmit: "Continue",
				},
				navigation: {
					routePages: "Page Routes",
					media: "Asset Library",
				},
			},
		});

		const adminUi = resolveAstropressAdminUiConfig();

		expect(adminUi.branding.appName).toBe("Client Console");
		expect(adminUi.branding.productName).toBe("Client Console Admin");
		expect(adminUi.branding.shellName).toBe("Client Workspace");
		expect(adminUi.branding.logoSrc).toBe("/brand/admin-mark.svg");
		expect(adminUi.branding.faviconHref).toBe("/brand/favicon.ico");
		expect(adminUi.branding.stylesheetHref).toBe("/brand/admin.css");
		expect(adminUi.labels.sidebarTitle).toBe("Operations");
		expect(adminUi.labels.signOut).toBe("Log out");
		expect(adminUi.labels.loginHeading).toBe("Client sign in");
		expect(adminUi.labels.loginSubmit).toBe("Continue");
		expect(adminUi.navigation.routePages).toBe("Page Routes");
		expect(adminUi.navigation.media).toBe("Asset Library");
		expect(buildAstropressAdminDocumentTitle("Dashboard")).toBe(
			"Dashboard | Client Console Admin",
		);
	});

	it("exposes locale-aware admin labels in Spanish when locale is es", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "es")).toBe("Guardar");
		expect(getAdminLabel("publishButton", "es")).toBe("Publicar");
		expect(getAdminLabel("signOut", "es")).toBe("Cerrar sesión");
		expect(getAdminLabel("loginHeading", "es")).toBe(
			"Acceder al panel de administración",
		);
		expect(getAdminLabel("sidebarTitle", "es")).toBe("Espacio de trabajo");
	});

	it("exposes locale-aware admin labels in French when locale is fr", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "fr")).toBe("Enregistrer");
		expect(getAdminLabel("deleteButton", "fr")).toBe("Supprimer");
		expect(getAdminLabel("cancelButton", "fr")).toBe("Annuler");
	});

	it("exposes locale-aware admin labels in Japanese when locale is ja", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "ja")).toBe("保存");
		expect(getAdminLabel("publishButton", "ja")).toBe("公開");
		expect(getAdminLabel("signOut", "ja")).toBe("サインアウト");
	});

	it("falls back to English when locale is unknown", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "zz")).toBe(adminLabels.en.saveButton);
		expect(getAdminLabel("publishButton", "xx")).toBe(
			adminLabels.en.publishButton,
		);
	});

	it("falls back to English when locale is undefined (no cms config)", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton")).toBe("Save");
		expect(getAdminLabel("sidebarTitle")).toBe("Workspace");
	});

	it("uses site configured locale from registerCms when no explicit locale is passed", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: [],
			seedPages: [],
			archives: [],
			translationStatus: [],
			locales: ["de"],
		});
		expect(getAdminLabel("saveButton")).toBe("Speichern");
		expect(getAdminLabel("signOut")).toBe("Abmelden");
	});

	it("BCP-47 tags with region (e.g. es-MX) resolve to the base locale (es)", () => {
		restoreConfig(null);
		expect(getAdminLabel("saveButton", "es-MX")).toBe("Guardar");
		expect(getAdminLabel("saveButton", "pt-BR")).toBe("Salvar");
	});

	it("falls back to productName for shellName/logoAlt and to /ap-admin for logoHref when overrides are empty strings", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: [],
			seedPages: [],
			archives: [],
			translationStatus: [],
			admin: {
				branding: {
					productName: "Fallback Admin",
					shellName: "",
					logoAlt: "",
					logoHref: "",
				},
			},
		});

		const adminUi = resolveAstropressAdminUiConfig();
		// shellName falls back to productName when empty
		expect(adminUi.branding.shellName).toBe("Fallback Admin");
		// logoAlt falls back to productName when empty
		expect(adminUi.branding.logoAlt).toBe("Fallback Admin");
		// logoHref falls back to "/ap-admin" when empty
		expect(adminUi.branding.logoHref).toBe("/ap-admin");
	});
});

tests/plugin-api.test.ts.source:
import { describe, expect, it } from "vitest";

import {
	dispatchPluginContentEvent,
	dispatchPluginMediaEvent,
	peekCmsConfig,
	registerCms,
} from "../src/config.js";
import type { AstropressPlugin } from "../src/config.js";

function makeMinimalConfig(plugins?: AstropressPlugin[]) {
	return {
		templateKeys: ["home"],
		siteUrl: "https://example.com",
		seedPages: [],
		archives: [],
		translationStatus: [],
		plugins,
	};
}

describe("AstropressPlugin API", () => {
	it("dispatchPluginContentEvent calls onContentSave on registered plugins", async () => {
		const events: string[] = [];
		const plugin: AstropressPlugin = {
			name: "test-plugin",
			onContentSave: ({ slug }) => {
				events.push(`save:${slug}`);
			},
		};
		registerCms(makeMinimalConfig([plugin]));

		await dispatchPluginContentEvent("onContentSave", {
			slug: "my-post",
			kind: "post",
			status: "draft",
			actor: "admin@example.com",
		});

		expect(events).toEqual(["save:my-post"]);
	});

	it("dispatchPluginContentEvent calls onContentPublish only for published status", async () => {
		const events: string[] = [];
		const plugin: AstropressPlugin = {
			name: "publish-plugin",
			onContentPublish: ({ slug }) => {
				events.push(`publish:${slug}`);
			},
		};
		registerCms(makeMinimalConfig([plugin]));

		await dispatchPluginContentEvent("onContentPublish", {
			slug: "my-post",
			kind: "post",
			status: "published",
			actor: "admin@example.com",
		});
		await dispatchPluginContentEvent("onContentSave", {
			slug: "draft-post",
			kind: "post",
			status: "draft",
			actor: "admin@example.com",
		});

		expect(events).toEqual(["publish:my-post"]);
	});

	it("dispatchPluginContentEvent catches errors thrown by plugin hooks", async () => {
		const errorPlugin: AstropressPlugin = {
			name: "broken-plugin",
			onContentSave: () => {
				throw new Error("plugin error");
			},
		};
		registerCms(makeMinimalConfig([errorPlugin]));

		// Should not throw
		await expect(
			dispatchPluginContentEvent("onContentSave", {
				slug: "post",
				kind: "post",
				status: "draft",
				actor: "admin@example.com",
			}),
		).resolves.toBeUndefined();
	});

	it("dispatchPluginContentEvent is a no-op when no plugins are registered", async () => {
		registerCms(makeMinimalConfig([]));
		await expect(
			dispatchPluginContentEvent("onContentSave", {
				slug: "post",
				kind: "post",
				status: "draft",
				actor: "admin@example.com",
			}),
		).resolves.toBeUndefined();
	});

	it("dispatchPluginMediaEvent calls onMediaUpload on registered plugins", async () => {
		const uploads: string[] = [];
		const plugin: AstropressPlugin = {
			name: "media-plugin",
			onMediaUpload: ({ id, mimeType }) => {
				uploads.push(`${id}:${mimeType}`);
			},
		};
		registerCms(makeMinimalConfig([plugin]));

		await dispatchPluginMediaEvent({
			id: "asset-1",
			filename: "photo.jpg",
			mimeType: "image/jpeg",
			size: 1024,
			actor: "admin@example.com",
		});

		expect(uploads).toEqual(["asset-1:image/jpeg"]);
	});

	it("dispatchPluginMediaEvent catches errors thrown by onMediaUpload hooks", async () => {
		const brokenPlugin: AstropressPlugin = {
			name: "broken-media-plugin",
			onMediaUpload: () => {
				throw new Error("media plugin error");
			},
		};
		registerCms(makeMinimalConfig([brokenPlugin]));

		await expect(
			dispatchPluginMediaEvent({
				id: "a",
				filename: "f.jpg",
				mimeType: "image/jpeg",
				size: 0,
				actor: "x@y.com",
			}),
		).resolves.toBeUndefined();
	});

	it("plugins with navItems expose them via getCmsConfig", () => {
		const navPlugin: AstropressPlugin = {
			name: "nav-plugin",
			navItems: [{ label: "My Tool", href: "/ap-admin/my-tool" }],
		};
		registerCms(makeMinimalConfig([navPlugin]));
		const config = peekCmsConfig();
		expect(config?.plugins?.[0]?.navItems?.[0]?.label).toBe("My Tool");
	});

	it("plugin adminRoutes are stored in config and accessible via peekCmsConfig", () => {
		const routePlugin: AstropressPlugin = {
			name: "route-plugin",
			adminRoutes: [
				{
					pattern: "/ap-admin/my-plugin",
					entrypoint: "./src/pages/my-plugin-admin.astro",
				},
				{
					pattern: "/ap-admin/my-plugin/settings",
					entrypoint: "./src/pages/my-plugin-settings.astro",
				},
			],
		};
		registerCms(makeMinimalConfig([routePlugin]));
		const config = peekCmsConfig();
		const routes = config?.plugins?.[0]?.adminRoutes;
		expect(routes).toHaveLength(2);
		expect(routes?.[0]?.pattern).toBe("/ap-admin/my-plugin");
		expect(routes?.[0]?.entrypoint).toBe("./src/pages/my-plugin-admin.astro");
		expect(routes?.[1]?.pattern).toBe("/ap-admin/my-plugin/settings");
	});

	it("plugin with no adminRoutes does not break config access", () => {
		const plainPlugin: AstropressPlugin = { name: "plain-plugin" };
		registerCms(makeMinimalConfig([plainPlugin]));
		const config = peekCmsConfig();
		expect(config?.plugins?.[0]?.adminRoutes).toBeUndefined();
	});
});

describe("createSitemapPlugin", () => {
	it("source file exists and exports createSitemapPlugin", async () => {
		const { createSitemapPlugin: fn } = await import(
			"../src/plugins/sitemap-plugin.js"
		);
		expect(typeof fn).toBe("function");
	});

	it("returned plugin has name 'astropress-sitemap' and onContentPublish hook", async () => {
		const { createSitemapPlugin: fn } = await import(
			"../src/plugins/sitemap-plugin.js"
		);
		const plugin = fn();
		expect(plugin.name).toBe("astropress-sitemap");
		expect(typeof plugin.onContentPublish).toBe("function");
	});

	it("onContentPublish calls onPublish callback with slug", async () => {
		const { createSitemapPlugin: fn } = await import(
			"../src/plugins/sitemap-plugin.js"
		);
		const slugs: string[] = [];
		const plugin = fn({
			onPublish: (slug: string) => {
				slugs.push(slug);
			},
		});
		await plugin.onContentPublish?.({
			slug: "my-post",
			kind: "post",
			status: "published",
			actor: "admin@example.com",
		});
		expect(slugs).toEqual(["my-post"]);
	});
});

tests/access-evaluator.test.ts.source:
import { describe, expect, test } from "vitest";

import {
	actionMatches,
	createPolicyEngine,
	evaluate,
	evaluateCondition,
	resolvePath,
	substituteString,
} from "../src/access";
import type { BindingContext, Policy, Subject } from "../src/access";

function subject(overrides: Partial<Subject> = {}): Subject {
	return {
		id: "u1",
		email: "u1@example.com",
		isAdmin: false,
		roles: [],
		attributes: {},
		...overrides,
	};
}

function rolePolicy(overrides: Partial<Policy> = {}): Policy {
	return {
		id: "p1",
		effect: "allow",
		action: "posts:edit",
		priority: 0,
		source: { kind: "role", roleId: "r1", roleName: "Editor" },
		...overrides,
	};
}

describe("actionMatches", () => {
	test("exact match", () => {
		expect(actionMatches("posts:edit", "posts:edit")).toBe(true);
		expect(actionMatches("posts:edit", "posts:delete")).toBe(false);
	});
	test("namespace wildcard", () => {
		expect(actionMatches("posts:*", "posts:edit")).toBe(true);
		expect(actionMatches("posts:*", "pages:edit")).toBe(false);
	});
	test("global wildcard", () => {
		expect(actionMatches("*", "anything:goes")).toBe(true);
	});
});

describe("resolvePath", () => {
	const ctx: BindingContext = {
		user: subject({ attributes: { team: "alpha" } }),
		resource: { type: "post", ownerId: "u1", attributes: { tier: 2 } },
		env: { mfaUsed: true },
	};
	test("resolves direct fields", () => {
		expect(resolvePath("user.id", ctx)).toBe("u1");
		expect(resolvePath("resource.ownerId", ctx)).toBe("u1");
		expect(resolvePath("env.mfaUsed", ctx)).toBe(true);
	});
	test("resolves attribute submap", () => {
		expect(resolvePath("user.attributes.team", ctx)).toBe("alpha");
		expect(resolvePath("resource.attributes.tier", ctx)).toBe(2);
	});
	test("missing path returns undefined", () => {
		expect(resolvePath("user.attributes.missing", ctx)).toBeUndefined();
		expect(resolvePath("nonexistent.x", ctx)).toBeUndefined();
	});
});

describe("substituteString", () => {
	test("replaces ${path} tokens", () => {
		const ctx: BindingContext = { user: subject({ id: "abc" }) };
		expect(substituteString("owner-${user.id}", ctx)).toBe("owner-abc");
	});
	test("missing values become empty", () => {
		const ctx: BindingContext = { user: subject() };
		expect(substituteString("x-${user.attributes.team}-y", ctx)).toBe("x--y");
	});
});

describe("evaluateCondition", () => {
	const ctx: BindingContext = {
		user: subject({ id: "u1", attributes: { team: "alpha" } }),
		resource: { type: "post", ownerId: "u1" },
	};

	test("stringEquals with substitution", () => {
		expect(
			evaluateCondition(
				{ op: "stringEquals", left: "resource.ownerId", right: "${user.id}" },
				ctx,
			),
		).toBe(true);
	});
	test("stringIn", () => {
		expect(
			evaluateCondition(
				{
					op: "stringIn",
					left: "user.attributes.team",
					right: ["alpha", "beta"],
				},
				ctx,
			),
		).toBe(true);
	});
	test("not + anyOf + allOf compose", () => {
		expect(
			evaluateCondition(
				{
					op: "not",
					condition: {
						op: "anyOf",
						conditions: [
							{ op: "stringEquals", left: "user.id", right: "u9" },
							{ op: "bool", left: "user.isAdmin", right: true },
						],
					},
				},
				ctx,
			),
		).toBe(true);
	});
	test("missing left fails by default", () => {
		expect(
			evaluateCondition(
				{ op: "stringEquals", left: "user.attributes.missing", right: "x" },
				ctx,
			),
		).toBe(false);
	});
});

describe("evaluate", () => {
	test("admin bypasses everything", () => {
		const r = evaluate(subject({ isAdmin: true }), "anything:goes", []);
		expect(r.decision).toBe("allow");
		expect(r.reason).toContain("Admin");
	});

	test("no matching policy → deny by default", () => {
		const r = evaluate(subject(), "posts:edit", []);
		expect(r.decision).toBe("deny");
		expect(r.reason).toContain("Default is deny");
	});

	test("matching allow grants", () => {
		const r = evaluate(subject(), "posts:edit", [rolePolicy()]);
		expect(r.decision).toBe("allow");
		expect(r.matchedPolicy?.id).toBe("p1");
	});

	test("DENY beats ALLOW regardless of priority", () => {
		const r = evaluate(subject(), "posts:edit", [
			rolePolicy({ id: "allow1", effect: "allow", priority: 100 }),
			rolePolicy({ id: "deny1", effect: "deny", priority: 1 }),
		]);
		expect(r.decision).toBe("deny");
		expect(r.matchedPolicy?.id).toBe("deny1");
	});

	test("condition gates policy applicability", () => {
		const subj = subject({ id: "u1" });
		const ownerOnly = rolePolicy({
			condition: {
				op: "stringEquals",
				left: "resource.ownerId",
				right: "${user.id}",
			},
		});
		const ownResource = { type: "post", ownerId: "u1" };
		const otherResource = { type: "post", ownerId: "u9" };

		expect(
			evaluate(subj, "posts:edit", [ownerOnly], ownResource).decision,
		).toBe("allow");
		expect(
			evaluate(subj, "posts:edit", [ownerOnly], otherResource).decision,
		).toBe("deny");
	});

	test("namespace wildcard policy matches sub-actions", () => {
		const r = evaluate(subject(), "posts:delete", [
			rolePolicy({ action: "posts:*" }),
		]);
		expect(r.decision).toBe("allow");
	});

	test("highest-priority allow is reported when multiple allow", () => {
		const r = evaluate(subject(), "posts:edit", [
			rolePolicy({ id: "low", priority: 1 }),
			rolePolicy({ id: "high", priority: 10 }),
		]);
		expect(r.matchedPolicy?.id).toBe("high");
	});
});

describe("createPolicyEngine", () => {
	test("delegates to evaluate with loader-supplied policies", () => {
		const policies = [rolePolicy()];
		const engine = createPolicyEngine({
			resolvePoliciesForSubject: () => policies,
		});
		const r = engine.can(subject(), "posts:edit");
		expect(r.decision).toBe("allow");
	});

	test("policiesFor returns the resolved set", () => {
		const policies = [rolePolicy()];
		const engine = createPolicyEngine({
			resolvePoliciesForSubject: () => policies,
		});
		expect(engine.policiesFor(subject())).toBe(policies);
	});
});

