import { describe, expect, it } from "vitest";
import {
	createAstropressPocketbaseAdapter,
	createAstropressPocketbaseHostedAdapter,
	readAstropressPocketbaseHostedConfig,
} from "../src/adapters/pocketbase.js";
import { createHostedStores } from "./helpers/provider-test-fixtures.js";

describe("readAstropressPocketbaseHostedConfig", () => {
	it("reads all required env vars", () => {
		const config = readAstropressPocketbaseHostedConfig({
			POCKETBASE_URL: "https://pb.example.com",
			POCKETBASE_EMAIL: "admin@example.com",
			POCKETBASE_PASSWORD: "secret123",
		});
		expect(config.url).toBe("https://pb.example.com");
		expect(config.email).toBe("admin@example.com");
		expect(config.password).toBe("secret123");
		expect(config.apiBaseUrl).toBe("https://pb.example.com/api/astropress");
		expect(config.previewBaseUrl).toBe("https://pb.example.com");
	});

	it("strips trailing slash from url before building apiBaseUrl", () => {
		const config = readAstropressPocketbaseHostedConfig({
			POCKETBASE_URL: "https://pb.example.com/",
			POCKETBASE_EMAIL: "admin@example.com",
			POCKETBASE_PASSWORD: "secret123",
		});
		expect(config.apiBaseUrl).toBe("https://pb.example.com/api/astropress");
		expect(config.previewBaseUrl).toBe("https://pb.example.com");
	});

	it("throws when POCKETBASE_URL is missing", () => {
		expect(() =>
			readAstropressPocketbaseHostedConfig({
				POCKETBASE_EMAIL: "admin@example.com",
				POCKETBASE_PASSWORD: "secret123",
			}),
		).toThrow(/POCKETBASE_URL/);
	});

	it("throws when POCKETBASE_EMAIL is missing", () => {
		expect(() =>
			readAstropressPocketbaseHostedConfig({
				POCKETBASE_URL: "https://pb.example.com",
				POCKETBASE_PASSWORD: "secret123",
			}),
		).toThrow(/POCKETBASE_EMAIL/);
	});

	it("throws when POCKETBASE_PASSWORD is missing", () => {
		expect(() =>
			readAstropressPocketbaseHostedConfig({
				POCKETBASE_URL: "https://pb.example.com",
				POCKETBASE_EMAIL: "admin@example.com",
			}),
		).toThrow(/POCKETBASE_PASSWORD/);
	});
});

describe("createAstropressPocketbaseAdapter", () => {
	it("reports providerName as pocketbase", () => {
		const adapter = createAstropressPocketbaseAdapter({
			...createHostedStores(),
		});
		expect(adapter.capabilities.name).toBe("pocketbase");
	});

	it("has database and objectStorage capabilities", () => {
		const adapter = createAstropressPocketbaseAdapter({
			...createHostedStores(),
		});
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(true);
		expect(adapter.capabilities.serverRuntime).toBe(true);
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});

	it("stores and retrieves content via backing adapter", async () => {
		const adapter = createAstropressPocketbaseAdapter({
			...createHostedStores(),
		});
		await adapter.content.save({
			id: "pb-test-post",
			kind: "post",
			slug: "pb-test-post",
			status: "published",
			title: "PocketBase test post",
		});
		const record = await adapter.content.get("pb-test-post");
		expect(record).toMatchObject({
			slug: "pb-test-post",
			title: "PocketBase test post",
		});
	});

	it("auth signIn works via backing adapter", async () => {
		const adapter = createAstropressPocketbaseAdapter({
			...createHostedStores(),
		});
		const user = await adapter.auth.signIn("admin@example.com", "password");
		expect(user).toMatchObject({ email: "admin@example.com", role: "admin" });
	});
});

describe("createAstropressPocketbaseHostedAdapter", () => {
	const env = {
		POCKETBASE_URL: "https://pb.example.com",
		POCKETBASE_EMAIL: "admin@example.com",
		POCKETBASE_PASSWORD: "secret123",
	};

	it("creates an adapter with pocketbase providerName", () => {
		const adapter = createAstropressPocketbaseHostedAdapter({
			env,
			...createHostedStores(),
		});
		expect(adapter.capabilities.name).toBe("pocketbase");
	});

	it("has all required capabilities", () => {
		const adapter = createAstropressPocketbaseHostedAdapter({
			env,
			...createHostedStores(),
		});
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(true);
		expect(adapter.capabilities.serverRuntime).toBe(true);
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});

	it("preview URL uses the previewBaseUrl path", async () => {
		const adapter = createAstropressPocketbaseHostedAdapter({
			env,
			...createHostedStores(),
		});
		const preview = await adapter.preview?.create({ recordId: "my-post" });
		expect(preview?.url).toContain("pb.example.com");
		expect(preview?.url).toContain("preview");
	});

	it("uses hosted API adapter when no stores are provided", () => {
		const adapter = createAstropressPocketbaseHostedAdapter({
			config: {
				url: "https://pb.example.com",
				email: "admin@example.com",
				password: "secret123",
				apiBaseUrl: "https://pb.example.com/api/astropress",
				previewBaseUrl: "https://pb.example.com",
			},
			fetchImpl: async () => new Response(JSON.stringify([]), { status: 200 }),
		});
		expect(adapter.capabilities.name).toBe("pocketbase");
		expect(adapter.capabilities.database).toBe(true);
	});

	it("respects backing adapter stores when provided", async () => {
		const stores = createHostedStores();
		const adapter = createAstropressPocketbaseHostedAdapter({ env, ...stores });
		await adapter.content.save({
			id: "pb-hosted-post",
			kind: "post",
			slug: "pb-hosted-post",
			status: "published",
			title: "Hosted post",
		});
		expect(await adapter.content.get("pb-hosted-post")).toMatchObject({
			slug: "pb-hosted-post",
		});
	});
});

tests/access-page-model.test.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { createAccessRepository, seedStarterRoles } from "../src/access";
import {
	type AccessPageTab,
	buildAccessPageModel,
} from "../src/admin-page-models-access";
import { makeDb } from "./helpers/make-db.js";
import { makeLocals } from "./helpers/make-locals.js";

// BDD: /ap-admin/access — three-tab Access page (Users / Roles / My Permissions)
//
// Tabs share a single page-model builder so the shell can switch tabs by
// reading ?tab=... without refetching unrelated data. Server-side guard
// is the source of truth: anything reachable here is gated by
// requiresAccess(Astro, "users:list") at the page level and per-action
// requiresAccess on each form action.

const adminUser = {
	id: "1",
	email: "admin@test.local",
	role: "admin" as const,
	isAdmin: true,
};
const editorUser = {
	id: "2",
	email: "editor@test.local",
	role: "editor" as const,
	isAdmin: false,
};

let db: DatabaseSync;
let locals: App.Locals;

beforeEach(() => {
	db = makeDb();
	locals = makeLocals(db);
	db.prepare(
		"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?, ?, ?, ?, ?)",
	).run("admin@test.local", "hash", "Admin", 1, 1);
	db.prepare(
		"INSERT INTO admin_users (email, password_hash, name, active, is_admin) VALUES (?, ?, ?, ?, ?)",
	).run("editor@test.local", "hash", "Editor", 1, 0);
	const repo = createAccessRepository(db as never);
	seedStarterRoles(repo);
});

afterEach(() => {
	vi.restoreAllMocks();
});

describe("buildAccessPageModel", () => {
	it("returns forbidden for non-admin subject — admin-only break-glass guard", async () => {
		const result = await buildAccessPageModel(locals, editorUser);
		expect(result.status).toBe("forbidden");
	});

	it("returns ok with the active tab defaulting to 'users' — users come from listAdminUsers, roles from access repo", async () => {
		const result = await buildAccessPageModel(locals, adminUser);
		expect(result.status).toBe("ok");
		expect(result.data.activeTab).toBe<AccessPageTab>("users");
		expect(result.data.users.length).toBeGreaterThanOrEqual(2);
		const seededRoleNames = result.data.roles.map((r) => r.name).sort();
		expect(seededRoleNames).toEqual([
			"Author",
			"Editor",
			"Moderator",
			"Translator",
		]);
	});

	it("respects the requested tab — 'roles' selects roles tab, 'my-permissions' selects perms tab", async () => {
		const r1 = await buildAccessPageModel(locals, adminUser, { tab: "roles" });
		expect(r1.data.activeTab).toBe("roles");
		const r2 = await buildAccessPageModel(locals, adminUser, {
			tab: "my-permissions",
		});
		expect(r2.data.activeTab).toBe("my-permissions");
	});

	it("falls back to 'users' for an unrecognized tab — query string is untrusted input", async () => {
		const result = await buildAccessPageModel(locals, adminUser, {
			tab: "garbage" as AccessPageTab,
		});
		expect(result.data.activeTab).toBe("users");
	});

	it("counts active admins for the last-admin safeguard — drives the demote/delete UI guard", async () => {
		const result = await buildAccessPageModel(locals, adminUser);
		expect(result.data.activeAdminCount).toBe(1);
	});

	it("returns the user→role assignment map — the Users tab renders one row of checkboxes per user", async () => {
		const repo = createAccessRepository(db as never);
		const editor = repo.listRoles().find((r) => r.name === "Editor");
		if (!editor) throw new Error("Editor role missing in seed");
		const editorRow = db
			.prepare("SELECT id FROM admin_users WHERE email = ?")
			.get("editor@test.local") as { id: number };
		repo.assignRole({ userId: editorRow.id, roleId: editor.id });

		const result = await buildAccessPageModel(locals, adminUser);
		expect(result.data.userRoleMap[editorRow.id]).toContain(editor.id);
	});

	it("flags users that hold direct grants — so the UI can badge sprawl beyond their roles", async () => {
		const repo = createAccessRepository(db as never);
		const editorRow = db
			.prepare("SELECT id FROM admin_users WHERE email = ?")
			.get("editor@test.local") as { id: number };
		repo.addUserPolicy({
			userId: editorRow.id,
			effect: "allow",
			action: "settings:edit",
		});

		const result = await buildAccessPageModel(locals, adminUser);
		expect(result.data.userDirectGrantCounts[editorRow.id]).toBe(1);
	});

	it("returns each role's policies grouped by role id — the Roles tab renders them inline", async () => {
		const repo = createAccessRepository(db as never);
		const editor = repo.listRoles().find((r) => r.name === "Editor");
		if (!editor) throw new Error("Editor role missing in seed");
		const result = await buildAccessPageModel(locals, adminUser, {
			tab: "roles",
		});
		expect(result.data.activeTab).toBe("roles");
		expect(result.data.rolePoliciesMap[editor.id]).toBeDefined();
		expect(result.data.rolePoliciesMap[editor.id]?.length ?? 0).toBeGreaterThan(
			0,
		);
	});

	it("computes the active subject's effective policies for the My Permissions tab", async () => {
		const result = await buildAccessPageModel(locals, adminUser, {
			tab: "my-permissions",
		});
		expect(result.data.activeTab).toBe("my-permissions");
		// The viewer is admin — admins bypass policy evaluation, but the
		// computed list should still expose the policy snapshot for transparency.
		expect(Array.isArray(result.data.viewerPolicies)).toBe(true);
	});
});

tests/api-token-store.test.ts.source:
import { describe, expect, it } from "vitest";

import type {
	ApiScope,
	ApiTokenRecord,
	ApiTokenStore,
} from "../src/platform-contracts";
import { createApiTokenStore } from "../src/sqlite-runtime/api-tokens.js";
import { hashOpaqueToken } from "../src/sqlite-runtime/utils.js";
import { makeDb } from "./helpers/make-db.js";

// ─── ApiTokenRecord shape ─────────────────────────────────────────────────────

describe("ApiTokenRecord shape", () => {
	it("has all required fields", () => {
		const record: ApiTokenRecord = {
			id: "tok_01",
			label: "AI assistant",
			scopes: ["content:read"],
			createdAt: new Date().toISOString(),
		};

		expect(record.id).toBe("tok_01");
		expect(record.label).toBe("AI assistant");
		expect(record.scopes).toContain("content:read");
		expect(record.revokedAt).toBeUndefined();
	});

	it("supports all defined scopes", () => {
		const allScopes: ApiScope[] = [
			"content:read",
			"content:write",
			"media:read",
			"media:write",
			"settings:read",
			"webhooks:manage",
			"import:write",
		];
		const record: ApiTokenRecord = {
			id: "tok_02",
			label: "Full access",
			scopes: allScopes,
			createdAt: new Date().toISOString(),
		};
		expect(record.scopes).toHaveLength(7);
	});

	it("optional fields are truly optional", () => {
		const minimal: ApiTokenRecord = {
			id: "tok_03",
			label: "Minimal",
			scopes: ["settings:read"],
			createdAt: "2026-01-01T00:00:00Z",
		};
		expect(minimal.expiresAt).toBeUndefined();
		expect(minimal.lastUsedAt).toBeUndefined();
		expect(minimal.revokedAt).toBeUndefined();
	});
});

describe("ApiTokenStore SQLite implementation", () => {
	it("create: stores hashed token and returns raw token once", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);

		const { record, rawToken } = await store.create({
			label: "test",
			scopes: ["content:read"],
		});

		expect(rawToken.length).toBeGreaterThanOrEqual(32);
		expect(record.label).toBe("test");
		expect(record.scopes).toEqual(["content:read"]);
		expect(record.revokedAt).toBeNull();

		// Hash stored, not raw token
		const row = db
			.prepare("SELECT token_hash FROM api_tokens WHERE id = ?")
			.get(record.id) as { token_hash: string };
		expect(row.token_hash).toBe(hashOpaqueToken(rawToken));
		expect(row.token_hash).not.toBe(rawToken);
	});

	it("list: returns tokens without token_hash", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		await store.create({ label: "alpha", scopes: ["content:read"] });
		await store.create({ label: "beta", scopes: ["media:read"] });

		const tokens = await store.list();
		expect(tokens).toHaveLength(2);
		const labels = tokens.map((t) => t.label);
		expect(labels).toContain("alpha");
		expect(labels).toContain("beta");
		// No hash exposed
		for (const token of tokens) {
			expect((token as Record<string, unknown>).token_hash).toBeUndefined();
		}
	});

	it("verify: valid unrevoked token succeeds and updates lastUsedAt", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { rawToken } = await store.create({
			label: "agent",
			scopes: ["content:read"],
		});

		const result = await store.verify(rawToken);
		expect(result.valid).toBe(true);
		if (!result.valid) throw new Error("expected valid");

		expect(result.record.label).toBe("agent");
		expect(result.record.lastUsedAt).not.toBeNull();
	});

	it("verify: revoked token returns { valid: false }", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record, rawToken } = await store.create({
			label: "short-lived",
			scopes: ["settings:read"],
		});

		await store.revoke(record.id);
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(false);
	});

	it("verify: unknown token returns { valid: false }", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const result = await store.verify("completely-unknown-token");
		expect(result.valid).toBe(false);
	});

	it("revoke: sets revokedAt timestamp", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record } = await store.create({
			label: "revoke-me",
			scopes: ["content:write"],
		});

		await store.revoke(record.id);
		const tokens = await store.list();
		const revoked = tokens.find((t) => t.id === record.id);
		expect(revoked?.revokedAt).not.toBeNull();
	});

	it("list: revoked tokens still appear in list (for admin display)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record } = await store.create({
			label: "revocable",
			scopes: ["content:read"],
		});
		await store.revoke(record.id);

		const tokens = await store.list();
		expect(tokens.some((t) => t.id === record.id)).toBe(true);
	});
});

// Type-level smoke test: ensure the interface is structurally correct
function assertApiTokenStoreShape(store: ApiTokenStore) {
	const _create = store.create;
	const _list = store.list;
	const _verify = store.verify;
	const _revoke = store.revoke;
	return { _create, _list, _verify, _revoke };
}

// Unused reference satisfies TypeScript without needing a real implementation
void assertApiTokenStoreShape;

tests/web-components/theme-toggle.test.t.source:
// @vitest-environment jsdom
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import "../../web-components/theme-toggle";
import type { ApThemeToggle } from "../../web-components/theme-toggle";

// jsdom does not implement window.matchMedia — stub it for all tests in this file
Object.defineProperty(window, "matchMedia", {
	writable: true,
	value: vi.fn((query: string) => ({
		matches: false,
		media: query,
		onchange: null,
		addEventListener: vi.fn(),
		removeEventListener: vi.fn(),
		dispatchEvent: vi.fn(),
	})),
});

function makeToggle(
	labelDark = "Switch to dark mode",
	labelLight = "Switch to light mode",
) {
	const el = document.createElement("ap-theme-toggle") as ApThemeToggle;
	el.setAttribute("label-dark", labelDark);
	el.setAttribute("label-light", labelLight);
	el.innerHTML = `
    <button type="button" class="theme-toggle-admin" aria-pressed="false" aria-label="${labelDark}">
      <span class="theme-toggle-icon" aria-hidden="true"></span>
    </button>
  `;
	return el;
}

describe("ApThemeToggle", () => {
	beforeEach(() => {
		document.documentElement.removeAttribute("data-theme");
		try {
			localStorage.removeItem("theme");
		} catch {}
	});

	afterEach(() => {
		document.documentElement.removeAttribute("data-theme");
		document.body.innerHTML = "";
	});

	it("is registered as a custom element", () => {
		expect(customElements.get("ap-theme-toggle")).toBeDefined();
	});

	it("applies a theme to documentElement on connectedCallback", () => {
		const el = makeToggle();
		document.body.appendChild(el);
		const theme = document.documentElement.getAttribute("data-theme");
		expect(theme === "dark" || theme === "light").toBe(true);
	});

	it("toggles theme on button click", () => {
		const el = makeToggle();
		document.body.appendChild(el);

		// Force a known starting state
		document.documentElement.setAttribute("data-theme", "light");
		const button = el.querySelector("button") as HTMLButtonElement;

		button.click();
		expect(document.documentElement.getAttribute("data-theme")).toBe("dark");

		button.click();
		expect(document.documentElement.getAttribute("data-theme")).toBe("light");
	});

	it("updates aria-pressed on toggle", () => {
		const el = makeToggle();
		document.body.appendChild(el);
		document.documentElement.setAttribute("data-theme", "light");
		const button = el.querySelector("button") as HTMLButtonElement;

		button.click(); // → dark
		expect(button.getAttribute("aria-pressed")).toBe("true");

		button.click(); // → light
		expect(button.getAttribute("aria-pressed")).toBe("false");
	});

	it("updates icon SVG on toggle", () => {
		const el = makeToggle();
		document.body.appendChild(el);
		document.documentElement.setAttribute("data-theme", "light");
		const button = el.querySelector("button") as HTMLButtonElement;
		const icon = el.querySelector(".theme-toggle-icon") as HTMLElement;

		button.click(); // → dark — shows sun SVG (click to go light)
		expect(icon.innerHTML).toContain("<svg");
		expect(icon.innerHTML).toContain("circle cx");

		button.click(); // → light — shows moon SVG (click to go dark)
		expect(icon.innerHTML).toContain("<svg");
		expect(icon.innerHTML).toContain("12.79");
	});

	it("persists theme to localStorage on toggle", () => {
		const spy = vi.spyOn(Storage.prototype, "setItem");
		const el = makeToggle();
		document.body.appendChild(el);
		document.documentElement.setAttribute("data-theme", "light");

		(el.querySelector("button") as HTMLButtonElement).click(); // → dark
		expect(spy).toHaveBeenCalledWith("theme", "dark");
		expect(window.localStorage.getItem("theme")).toBe("dark");
		spy.mockRestore();
	});

	it("updates aria-label to reflect the opposite action", () => {
		const el = makeToggle("Go dark", "Go light");
		document.body.appendChild(el);
		document.documentElement.setAttribute("data-theme", "light");
		const button = el.querySelector("button") as HTMLButtonElement;

		// When light: clicking will go dark, so label should say "Go dark"
		expect(button.getAttribute("aria-label")).toBe("Go dark");

		button.click(); // → dark
		// When dark: clicking will go light, so label should say "Go light"
		expect(button.getAttribute("aria-label")).toBe("Go light");
	});

	it("syncs all toggles on the page when one is clicked", () => {
		const el1 = makeToggle();
		const el2 = makeToggle();
		document.body.appendChild(el1);
		document.body.appendChild(el2);

		document.documentElement.setAttribute("data-theme", "light");
		// Manually re-sync since we set attribute after connectedCallback
		(el1.querySelector("button") as HTMLButtonElement).click(); // → dark

		const btn2 = el2.querySelector("button") as HTMLButtonElement;
		expect(btn2.getAttribute("aria-pressed")).toBe("true");
	});

	it("removes click listener on disconnectedCallback", () => {
		const el = makeToggle();
		document.body.appendChild(el);
		document.documentElement.setAttribute("data-theme", "light");

		document.body.removeChild(el);

		// After disconnect, clicking the (now detached) button should not change theme
		// We can only verify no errors are thrown; the handler is removed
		expect(() =>
			(el.querySelector("button") as HTMLButtonElement).click(),
		).not.toThrow();
	});
});

