import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

// Admin shell invariants: AdminLayout.astro + admin.css + theme toggle.
// Page-specific concerns (breadcrumbs, confirm dialogs, post editor) live
// in their own focused test files so changes to a single page's markup
// only invalidate the relevant suite under stryker incremental.

const root = path.resolve(import.meta.dirname, "..");
const adminLayout = readFileSync(
	path.join(root, "components", "AdminLayout.astro"),
	"utf8",
);
const adminCss = readFileSync(path.join(root, "public", "admin.css"), "utf8");

describe("admin shell ux invariants", () => {
	it("ships a viewport meta tag and keyboard shortcuts popover in the shared admin layout", () => {
		expect(adminLayout).toContain(
			'<meta name="viewport" content="width=device-width, initial-scale=1" />',
		);
		expect(adminLayout).toContain('popovertarget="admin-keyboard-shortcuts"');
		expect(adminLayout).toContain(
			'<h2>{tLayout("layout.keyboardShortcuts")}</h2>',
		);
		expect(adminLayout).toContain("<kbd>Ctrl</kbd>+<kbd>K</kbd>");
	});

	it("has collapsible utility panel using native details/summary", () => {
		expect(adminLayout).toContain('class="topbar-panel-details"');
		expect(adminLayout).toContain('class="topbar-panel-toggle"');
		expect(adminLayout).toContain('id="topbar-utility-panel"');
		// <details>/<summary> gives native toggle without JS; panel stays inline in topbar flex
		expect(adminLayout).toContain("<details");
		expect(adminLayout).toContain("<summary");
	});

	it("utility panel sits inline in the topbar, not as a fixed overlay", () => {
		// No position:fixed on the panel — it flows inside the topbar flex row
		expect(adminCss).not.toMatch(
			/\.topbar-utility-panel\s*\{[^}]*position:\s*fixed/,
		);
	});

	it("has a scroll-to-top/bottom button in the utility panel", () => {
		expect(adminLayout).toContain('id="scroll-to-bottom-btn"');
		expect(adminLayout).toContain('id="scroll-to-top-fab"');
		expect(adminLayout).toContain('tLayout("layout.scrollToBottom")');
	});

	it("uses CSS animation for undo toast auto-dismiss instead of JS setTimeout", () => {
		expect(adminCss).toContain("ap-toast-out");
		expect(adminCss).toContain("animation:");

		const authorsPage = readFileSync(
			path.join(root, "pages", "ap-admin", "authors.astro"),
			"utf8",
		);
		const taxonomiesPage = readFileSync(
			path.join(root, "pages", "ap-admin", "taxonomies.astro"),
			"utf8",
		);
		expect(authorsPage).not.toContain("setTimeout");
		expect(taxonomiesPage).not.toContain("setTimeout");
	});

	it("sets scroll-behavior: smooth on html element", () => {
		expect(adminCss).toContain("scroll-behavior: smooth");
	});

	it("theme toggle uses SVG icons instead of Unicode", () => {
		const themeToggle = readFileSync(
			path.join(root, "web-components", "theme-toggle.ts"),
			"utf8",
		);
		expect(themeToggle).toContain("<svg");
		expect(themeToggle).not.toContain('"\\u2600"');
		expect(themeToggle).not.toContain('"☀"');
		expect(themeToggle).not.toContain('"☾"');
	});

	it("keeps reduced-motion handling in the shared stylesheet", () => {
		expect(adminCss).toContain("@media (prefers-reduced-motion: reduce)");
		expect(adminCss).toMatch(/\.skeleton\s*\{\s*animation:\s*none/);
		expect(adminCss).toMatch(/\.undo-toast\s*\{\s*animation:\s*none/);
	});

	it("keeps shared touch targets at 44px or larger", () => {
		expect(adminCss).toContain("min-height: 2.75rem;");
		expect(adminCss).toContain("min-width: 2.75rem;");
	});

	it("ships shared confirm-dialog styles in admin.css", () => {
		expect(adminCss).toContain(".confirm-modal");
		expect(adminCss).toContain(".modal-content");
		expect(adminCss).toContain(".modal-actions");
		expect(adminCss).toContain(".dialog-warning");
	});

	it("wires generic form submit loading state in admin layout", () => {
		expect(adminLayout).toContain("btn.disabled = true");
		expect(adminLayout).toContain('button[type="submit"]');
		expect(adminLayout).toContain("\\u2026");
	});
});

tests/image-srcset.test.ts.source:
import { describe, expect, it } from "vitest";
import { generateSrcset } from "../src/local-image-storage.js";
import {
	ensureLegacySchemaCompatibility,
	getTableColumns,
} from "../src/sqlite-schema-compat.js";
import { makeDb } from "./helpers/make-db.js";

// ─── generateSrcset ───────────────────────────────────────────────────────────

describe("generateSrcset() — basic output format", () => {
	it("returns null when Sharp is unavailable (storeVariant never called)", async () => {
		// In the test environment Sharp may or may not be available.
		// We test the null-return path by injecting a storeVariant that always returns null.
		// If Sharp IS available this exercises the full path but still returns null due to storeVariant.
		const result = await generateSrcset(
			new Uint8Array([0xff, 0xd8, 0xff]), // minimal JPEG magic bytes
			"/images/uploads/test.jpg",
			async () => null,
		);
		expect(result).toBeNull();
	});

	it("builds a srcset string from stored variant paths", async () => {
		// Inject a mock storeVariant that returns deterministic paths
		const stored: string[] = [];
		const storeVariant = async (
			filename: string,
			_bytes: Uint8Array,
		): Promise<string | null> => {
			const path = `/images/uploads/${filename}`;
			stored.push(path);
			return path;
		};

		// Use a 1×1 white PNG as minimal image data that Sharp can process
		// (base64: iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==)
		const pngBase64 =
			"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==";
		let pngBytes: Uint8Array;
		try {
			pngBytes = new Uint8Array(Buffer.from(pngBase64, "base64"));
		} catch {
			pngBytes = new Uint8Array(0);
		}

		if (pngBytes.length === 0) {
			return; // Skip if Buffer not available
		}

		const result = await generateSrcset(
			pngBytes,
			"/images/uploads/photo.jpg",
			storeVariant,
		);

		if (result === null) {
			// Sharp not available in this environment — null is the correct graceful fallback
			expect(result).toBeNull();
			return;
		}

		// When Sharp is available, result should be a space-separated srcset string
		expect(typeof result).toBe("string");
		const parts = result.split(", ");
		// Each part must end with a width descriptor like "400w"
		for (const part of parts) {
			expect(part).toMatch(/\d+w$/);
		}
	});
});

// ─── Structural: srcset field on MediaAssetRecord ─────────────────────────────

describe("MediaAssetRecord.srcset field", () => {
	it("is defined as an optional string on the MediaAssetRecord interface", async () => {
		const { platform_contracts } = await import(
			"../src/platform-contracts.js"
		).catch(() => ({ platform_contracts: null }));
		// Structural test: TypeScript compilation catches type errors.
		// At runtime we verify the shape is valid by constructing a conforming object.
		const record = {
			id: "media-1",
			filename: "photo.jpg",
			mimeType: "image/jpeg",
			srcset: "/images/photo-400w.webp 400w, /images/photo-800w.webp 800w",
		};
		expect(record.srcset).toContain("400w");
		expect(record.srcset).toContain("800w");
		void platform_contracts;
	});

	it("srcset is optional — record without it is valid", () => {
		const record = {
			id: "media-2",
			filename: "icon.png",
			mimeType: "image/png",
		};
		expect((record as Record<string, unknown>).srcset).toBeUndefined();
	});
});

// ─── sqlite-schema-compat: srcset column migration ───────────────────────────

describe("srcset column migration (ensureLegacySchemaCompatibility)", () => {
	it("adds srcset column to media_assets when missing", () => {
		const db = makeDb();
		ensureLegacySchemaCompatibility(db);
		expect(getTableColumns(db, "media_assets")).toContain("srcset");
	});
});

