import { beforeAll, describe, expect, it } from "vitest";
import { registerCms } from "../src/config.js";
import {
	listAuditEvents,
	recordAuditEvent,
} from "../src/sqlite-runtime/audit-log.js";
import { makeDb } from "./helpers/make-db.js";

let db: ReturnType<typeof makeDb>;

beforeAll(() => {
	db = makeDb();
});

describe("audit log", () => {
	it("records an audit event and retrieves it", () => {
		recordAuditEvent(db, {
			userEmail: "editor@example.com",
			action: "content.published",
			resourceType: "post",
			resourceId: "my-post",
			summary: "Published post my-post",
		});

		const events = listAuditEvents(db, { limit: 10 });
		expect(events.length).toBeGreaterThanOrEqual(1);

		const event = events.find((e) => e.resourceId === "my-post");
		expect(event).toBeDefined();
		expect(event?.userEmail).toBe("editor@example.com");
		expect(event?.action).toBe("content.published");
		expect(event?.resourceType).toBe("post");
		expect(event?.summary).toBe("Published post my-post");
		expect(event?.details).toBeNull();
	});

	it("stores and retrieves structured details JSON", () => {
		recordAuditEvent(db, {
			userEmail: "admin@example.com",
			action: "user.invited",
			resourceType: "user",
			resourceId: "new@example.com",
			summary: "Invited new@example.com",
			details: { role: "editor", invitedBy: "admin@example.com" },
		});

		const events = listAuditEvents(db, { resourceId: "new@example.com" });
		expect(events.length).toBe(1);
		expect(events[0].details).toEqual({
			role: "editor",
			invitedBy: "admin@example.com",
		});
	});

	it("filters by resourceId", () => {
		recordAuditEvent(db, {
			userEmail: "admin@example.com",
			action: "content.deleted",
			resourceType: "post",
			resourceId: "another-post",
			summary: "Deleted another-post",
		});

		const filtered = listAuditEvents(db, { resourceId: "my-post" });
		expect(filtered.every((e) => e.resourceId === "my-post")).toBe(true);
	});

	it("prunes audit events older than auditRetentionDays on write", () => {
		const freshDb = makeDb();
		registerCms({
			templateKeys: [],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
			auditRetentionDays: 30,
		});

		// Insert a very old event by manipulating created_at directly
		freshDb
			.prepare(
				`INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary, created_at)
       VALUES ('old@test.local', 'content.published', 'post', 'old-post', 'Old post', datetime('now', '-31 days'))`,
			)
			.run();

		const before = (
			freshDb.prepare("SELECT COUNT(*) as n FROM audit_events").get() as {
				n: number;
			}
		).n;
		expect(before).toBe(1);

		// Writing a new event should trigger pruning
		recordAuditEvent(freshDb, {
			userEmail: "new@test.local",
			action: "content.published",
			resourceType: "post",
			resourceId: "new-post",
			summary: "New post",
		});

		const after = (
			freshDb.prepare("SELECT COUNT(*) as n FROM audit_events").get() as {
				n: number;
			}
		).n;
		// Old event should be pruned; new event should remain
		expect(after).toBe(1);
		const remaining = freshDb
			.prepare("SELECT resource_id FROM audit_events")
			.get() as { resource_id: string };
		expect(remaining.resource_id).toBe("new-post");
	});

	it("respects limit and offset", () => {
		// Insert several events
		for (let i = 0; i < 5; i++) {
			recordAuditEvent(db, {
				userEmail: "editor@example.com",
				action: "content.updated",
				resourceType: "post",
				resourceId: `post-${i}`,
				summary: `Updated post-${i}`,
			});
		}

		const page1 = listAuditEvents(db, { limit: 3, offset: 0 });
		const page2 = listAuditEvents(db, { limit: 3, offset: 3 });

		expect(page1.length).toBe(3);
		// Page 2 should have different events than page 1
		const page1Ids = page1.map((e) => e.id);
		const page2Ids = page2.map((e) => e.id);
		expect(page1Ids.some((id) => page2Ids.includes(id))).toBe(false);
	});
});

tests/deploy-and-sync.contract.test.ts.source:
import { mkdir, mkdtemp, readFile, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { describe, expect, it } from "vitest";
import { createAstropressCloudflarePagesDeployTarget } from "../src/deploy/cloudflare-pages.js";
import { createAstropressGitHubPagesDeployTarget } from "../src/deploy/github-pages.js";
import { createAstropressGitLabPagesDeployTarget } from "../src/deploy/gitlab-pages.js";
import { createAstropressNetlifyDeployTarget } from "../src/deploy/netlify.js";
import { createAstropressRenderDeployTarget } from "../src/deploy/render.js";
import { createAstropressVercelDeployTarget } from "../src/deploy/vercel.js";
import { createAstropressGitSyncAdapter } from "../src/sync/git.js";

describe("deploy and sync contracts", () => {
	it("deploys a build directory to the github pages target", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-gh-pages-"));
		const buildDir = join(workspace, "dist");
		const outputDir = join(workspace, "deployments");
		await mkdir(buildDir, { recursive: true });
		await writeFile(join(buildDir, "index.html"), "<h1>Astropress</h1>");

		const target = createAstropressGitHubPagesDeployTarget({
			outputDir,
			baseUrl: "https://example.com/docs",
		});

		const result = await target.deploy({
			buildDir,
			projectName: "demo-site",
		});

		expect(result.url).toBe("https://example.com/docs/demo-site/");
		expect(
			await readFile(join(outputDir, "demo-site", "index.html"), "utf8"),
		).toContain("Astropress");
		expect(
			await readFile(
				join(outputDir, "demo-site", ".astropress-deploy.json"),
				"utf8",
			),
		).toContain('"provider": "github-pages"');

		await rm(workspace, { recursive: true, force: true });
	});

	it("prepares build directories for the other app-host deploy targets", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-host-deploys-"));
		const buildDir = join(workspace, "dist");
		await mkdir(buildDir, { recursive: true });
		await writeFile(join(buildDir, "index.html"), "<h1>Astropress</h1>");

		for (const [factory, provider] of [
			[createAstropressCloudflarePagesDeployTarget, "cloudflare-pages"],
			[createAstropressVercelDeployTarget, "vercel"],
			[createAstropressNetlifyDeployTarget, "netlify"],
			[createAstropressRenderDeployTarget, "render-web"],
			[createAstropressGitLabPagesDeployTarget, "gitlab-pages"],
		] as const) {
			const outputDir = join(workspace, provider);
			const target = factory({ outputDir } as never);
			const result = await target.deploy({
				buildDir,
				projectName: "demo-site",
			});

			expect(result.deploymentId).toContain("demo-site");
			expect(
				await readFile(
					join(outputDir, "demo-site", ".astropress-deploy.json"),
					"utf8",
				),
			).toContain(provider);
		}

		await rm(workspace, { recursive: true, force: true });
	});

	it("round-trips a project snapshot through git sync", async () => {
		const workspace = await mkdtemp(join(tmpdir(), "astropress-sync-"));
		const projectDir = join(workspace, "project");
		const snapshotDir = join(workspace, "snapshot");
		await mkdir(join(projectDir, "src"), { recursive: true });
		await writeFile(join(projectDir, "package.json"), '{"name":"demo"}');
		await writeFile(
			join(projectDir, "src", "index.ts"),
			"export const demo = true;",
		);

		const sync = createAstropressGitSyncAdapter({ projectDir });
		const exported = await sync.exportSnapshot(snapshotDir);
		await writeFile(
			join(projectDir, "src", "index.ts"),
			"export const demo = false;",
		);
		const imported = await sync.importSnapshot(snapshotDir);

		expect(exported.fileCount).toBeGreaterThan(0);
		expect(imported.fileCount).toBe(exported.fileCount);
		expect(
			await readFile(join(projectDir, "src", "index.ts"), "utf8"),
		).toContain("demo = true");

		await rm(workspace, { recursive: true, force: true });
	});
});

tests/d1-local-integration.test.ts.source:
/**
 * D1 local integration tests — exercises the Cloudflare adapter through a real
 * SQLite-backed D1 shim (SqliteBackedD1Database).
 *
 * These tests use a local SQLite-backed D1 shim. Cloudflare D1 uses SQLite under
 * the hood and the shim is functionally equivalent for integration testing purposes.
 * No Cloudflare account or credentials required.
 */

import {
	createAstropressCloudflareAdapter,
	registerCms,
} from "@astropress-diy/astropress";
import { beforeEach, describe, expect, it } from "vitest";
import { STANDARD_CMS_CONFIG, makeDb } from "./helpers/make-db.js";
import {
	SqliteBackedD1Database,
	createSeededCloudflareDatabase,
} from "./helpers/provider-test-fixtures.js";

beforeEach(() => {
	registerCms(STANDARD_CMS_CONFIG);
});

describe("D1 adapter: auth round-trip via SQLite shim", () => {
	it("creates a session, retrieves it, and revokes it", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Sign in
		const session = await adapter.auth.signIn("admin@example.com", "password");
		expect(session).not.toBeNull();
		expect(session?.email).toBe("admin@example.com");
		expect(session?.isAdmin).toBe(true);

		// Retrieve session
		const retrieved = await adapter.auth.getSession(session?.id);
		expect(retrieved?.email).toBe("admin@example.com");

		// Revoke session
		await adapter.auth.signOut(session?.id);
		const revoked = await adapter.auth.getSession(session?.id);
		expect(revoked).toBeNull();
	});
});

describe("D1 adapter: content CRUD via SQLite shim", () => {
	it("creates a content record, reads it back, updates it, and deletes it", async () => {
		const db = await createSeededCloudflareDatabase();
		const adapter = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Create
		const saved = await adapter.content.save({
			id: "d1-test-slug",
			slug: "d1-test-slug",
			kind: "post",
			title: "D1 Test Post",
			status: "draft",
			body: "<p>Initial body</p>",
			metadata: {
				seoTitle: "D1 Test Post",
				metaDescription: "Testing D1",
				legacyUrl: "/d1-test-slug",
				templateKey: "content",
				updatedAt: new Date().toISOString(),
				summary: "",
			},
		});
		expect(saved.slug).toBe("d1-test-slug");

		// Read back
		const fetched = await adapter.content.get("d1-test-slug");
		expect(fetched?.title).toBe("D1 Test Post");
		expect(fetched?.status).toBe("draft");

		// Update
		const updated = await adapter.content.save({
			...saved,
			title: "D1 Updated Post",
			status: "published",
		});
		expect(updated.title).toBe("D1 Updated Post");
		expect(updated.status).toBe("published");

		// Delete (soft delete — archives the record)
		await adapter.content.delete("d1-test-slug");
		const afterDelete = await adapter.content.get("d1-test-slug");
		// The Cloudflare adapter soft-deletes posts by setting status to "archived"
		expect(afterDelete?.status).toBe("archived");
	});
});

describe("D1 adapter: schema bootstrap via SQLite shim", () => {
	it("bootstraps the schema and confirms schema_migrations table exists", () => {
		const db = makeDb();

		const tableRow = db
			.prepare(
				"SELECT name FROM sqlite_master WHERE type='table' AND name='schema_migrations'",
			)
			.get() as { name: string } | undefined;

		expect(tableRow?.name).toBe("schema_migrations");
	});

	it("D1 shim executes SQL statements via prepare().all()", async () => {
		const db = await createSeededCloudflareDatabase();
		const d1 = new SqliteBackedD1Database(db);

		const result = await d1
			.prepare("SELECT COUNT(*) as count FROM admin_users")
			.first<{ count: number }>();
		expect(result).not.toBeNull();
		expect(result?.count).toBeGreaterThan(0);
	});
});

