import { describe, expect, it } from "vitest";
import {
	createAstropressTursoAdapter,
	createAstropressTursoHostedAdapter,
	readAstropressTursoHostedConfig,
} from "../src/adapters/turso.js";

describe("readAstropressTursoHostedConfig", () => {
	it("reads TURSO_DATABASE_URL and TURSO_AUTH_TOKEN from env", () => {
		const config = readAstropressTursoHostedConfig({
			TURSO_DATABASE_URL: "libsql://astropress-prod.turso.io",
			TURSO_AUTH_TOKEN: "token-abc",
		});
		expect(config.databaseUrl).toBe("libsql://astropress-prod.turso.io");
		expect(config.authToken).toBe("token-abc");
		expect(config.apiBaseUrl).toContain("astropress-prod");
	});

	it("accepts https:// connection strings", () => {
		const config = readAstropressTursoHostedConfig({
			TURSO_DATABASE_URL: "https://astropress-prod.turso.io",
			TURSO_AUTH_TOKEN: "token-abc",
		});
		expect(config.databaseUrl).toBe("https://astropress-prod.turso.io");
	});

	it("throws when TURSO_DATABASE_URL is missing", () => {
		expect(() =>
			readAstropressTursoHostedConfig({ TURSO_AUTH_TOKEN: "token-abc" }),
		).toThrow(/TURSO_DATABASE_URL/);
	});

	it("throws when TURSO_DATABASE_URL is not a libsql:// or https:// URL", () => {
		expect(() =>
			readAstropressTursoHostedConfig({
				TURSO_DATABASE_URL: "mysql://host/db",
				TURSO_AUTH_TOKEN: "token-abc",
			}),
		).toThrow(/libsql/);
	});

	it("throws when TURSO_AUTH_TOKEN is missing", () => {
		expect(() =>
			readAstropressTursoHostedConfig({
				TURSO_DATABASE_URL: "libsql://astropress-prod.turso.io",
			}),
		).toThrow(/TURSO_AUTH_TOKEN/);
	});
});

describe("createAstropressTursoAdapter", () => {
	it("creates an adapter with database-only capabilities", () => {
		const adapter = createAstropressTursoAdapter();
		expect(adapter.capabilities.name).toBe("turso");
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(false);
		expect(adapter.capabilities.serverRuntime).toBe(true);
		expect(adapter.capabilities.hostedAdmin).toBe(false);
		expect(adapter.capabilities.previewEnvironments).toBe(false);
	});

	it("accepts custom backing adapter options", () => {
		const adapter = createAstropressTursoAdapter({
			defaultCapabilities: { gitSync: true },
		});
		expect(adapter.capabilities.gitSync).toBe(true);
		expect(adapter.capabilities.database).toBe(true);
	});
});

describe("createAstropressTursoHostedAdapter", () => {
	const validEnv = {
		TURSO_DATABASE_URL: "libsql://astropress-prod.turso.io",
		TURSO_AUTH_TOKEN: "token-abc",
	};

	it("creates an adapter with database-only capabilities", () => {
		const adapter = createAstropressTursoHostedAdapter({ env: validEnv });
		expect(adapter.capabilities.name).toBe("turso");
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(false);
		expect(adapter.capabilities.hostedAdmin).toBe(false);
	});

	it("sets the Turso Dashboard hostPanel link", () => {
		const adapter = createAstropressTursoHostedAdapter({ env: validEnv });
		const panel = adapter.capabilities.hostPanel;
		expect(panel).toBeTruthy();
		expect((panel as { url: string }).url).toContain("astropress-prod");
		expect((panel as { label: string }).label).toBe("Turso Dashboard");
	});

	it("accepts explicit config bypassing env read", () => {
		const adapter = createAstropressTursoHostedAdapter({
			config: {
				databaseUrl: "libsql://astropress-prod.turso.io",
				authToken: "token-abc",
				apiBaseUrl: "https://app.turso.tech/databases/astropress-prod",
			},
		});
		expect(adapter.capabilities.name).toBe("turso");
	});

	it("throws when TURSO_DATABASE_URL is missing and no explicit config", () => {
		expect(() => createAstropressTursoHostedAdapter({ env: {} })).toThrow(
			/TURSO_DATABASE_URL/,
		);
	});
});

tests/content-search.test.ts.source:
/**
 * Content search tests — verifies FTS5 virtual table creation, trigger-based sync,
 * and search query behavior.
 *
 * All tests run in-process using DatabaseSync with the real schema.
 */

import { describe, expect, it, vi } from "vitest";

import { searchContentOverrides } from "../src/sqlite-runtime/search.js";
import {
	ensureFts5SearchIndex,
	getTableSql,
} from "../src/sqlite-schema-compat.js";
import { makeDb } from "./helpers/make-db.js";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

function setCmsConfig(search?: { enabled?: boolean }) {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[
		CMS_CONFIG_KEY
	] = {
		siteName: "Test Site",
		siteUrl: "https://example.com",
		templateKeys: [],
		seedPages: [],
		archives: [],
		translationStatus: [],
		search,
	};
}

function clearCmsConfig() {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[
		CMS_CONFIG_KEY
	] = null;
}

describe("FTS5 search index creation", () => {
	it("ensureFts5SearchIndex creates content_fts virtual table", () => {
		const db = makeDb();
		expect(getTableSql(db, "content_fts")).toBeUndefined();

		ensureFts5SearchIndex(db);

		// FTS5 virtual tables appear in sqlite_master as type 'table'
		const row = db
			.prepare("SELECT name FROM sqlite_master WHERE name = 'content_fts'")
			.get() as { name: string } | undefined;
		expect(row?.name).toBe("content_fts");
		db.close();
	});

	it("ensureFts5SearchIndex is idempotent — calling twice does not throw", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);
		expect(() => ensureFts5SearchIndex(db)).not.toThrow();
		db.close();
	});
});

describe("FTS5 search query", () => {
	it("returns a record whose body matches a unique phrase", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by, body)
       VALUES ('fts-test-post', 'FTS Test Post', 'published', 'admin@example.com', 'uniqueftstestphrase searchable content')`,
		).run();

		const results = searchContentOverrides(db, "uniqueftstestphrase");
		expect(results.length).toBeGreaterThan(0);
		expect(results[0].slug).toBe("fts-test-post");
		db.close();
	});

	it("returns updated content after an UPDATE trigger fires", () => {
		const db = makeDb();
		ensureFts5SearchIndex(db);

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by, body)
       VALUES ('fts-update-test', 'Update Test', 'draft', 'admin@example.com', 'originalbodycontent')`,
		).run();

		// Update the body — the AFTER UPDATE trigger should sync the FTS index
		db.prepare(
			`UPDATE content_overrides SET body = 'replacedftsbodyphrase' WHERE slug = 'fts-update-test'`,
		).run();

		const results = searchContentOverrides(db, "replacedftsbodyphrase");
		expect(results.length).toBeGreaterThan(0);
		expect(results[0].slug).toBe("fts-update-test");

		// Original phrase should no longer match
		const oldResults = searchContentOverrides(db, "originalbodycontent");
		expect(oldResults).toHaveLength(0);
		db.close();
	});
});

describe("searchRuntimeContentStates gating", () => {
	it("returns empty array with a warning when search.enabled is false", async () => {
		setCmsConfig({ enabled: false });
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});

		// Import after setting config to ensure peekCmsConfig resolves correctly
		const { searchRuntimeContentStates } = await import(
			"../src/runtime-page-store.js"
		);
		const results = await searchRuntimeContentStates("hello");

		expect(results).toEqual([]);
		expect(warnSpy).toHaveBeenCalledWith(
			expect.stringContaining("search.enabled"),
		);
		warnSpy.mockRestore();
		clearCmsConfig();
	});
});

tests/admin-preview.test.ts.source:
import { describe, expect, it } from "vitest";
import {
	buildPreviewLoginRedirect,
	resolvePreviewPath,
} from "../src/admin-preview-middleware";

describe("resolvePreviewPath", () => {
	it("returns the slug for a valid preview path", () => {
		const url = new URL(
			"http://admin.example.com/ap-admin/preview/blog/my-draft-post",
		);
		const result = resolvePreviewPath(url);
		expect(result).toEqual({ slug: "blog/my-draft-post" });
	});

	it("returns the slug for a simple single-segment preview path", () => {
		const url = new URL(
			"http://admin.example.com/ap-admin/preview/coming-soon",
		);
		const result = resolvePreviewPath(url);
		expect(result).toEqual({ slug: "coming-soon" });
	});

	it("returns null for a non-preview admin path", () => {
		const url = new URL("http://admin.example.com/ap-admin/posts");
		const result = resolvePreviewPath(url);
		expect(result).toBeNull();
	});

	it("returns null for the root admin path", () => {
		const url = new URL("http://admin.example.com/ap-admin");
		const result = resolvePreviewPath(url);
		expect(result).toBeNull();
	});

	it("returns null for a public path", () => {
		const url = new URL("http://admin.example.com/blog/my-post");
		const result = resolvePreviewPath(url);
		expect(result).toBeNull();
	});

	it("handles deeply nested slugs", () => {
		const url = new URL(
			"http://admin.example.com/ap-admin/preview/2024/01/15/my-post-title",
		);
		const result = resolvePreviewPath(url);
		expect(result).toEqual({ slug: "2024/01/15/my-post-title" });
	});
});

describe("buildPreviewLoginRedirect", () => {
	it("builds a login redirect with the return path encoded", () => {
		const url = new URL(
			"http://admin.example.com/ap-admin/preview/coming-soon",
		);
		const redirect = buildPreviewLoginRedirect(url);
		expect(redirect).toBe(
			"/ap-admin/login?return=%2Fap-admin%2Fpreview%2Fcoming-soon",
		);
	});

	it("preserves query parameters in the return path", () => {
		const url = new URL(
			"http://admin.example.com/ap-admin/preview/post?draft=1",
		);
		const redirect = buildPreviewLoginRedirect(url);
		expect(redirect).toContain("/ap-admin/login?return=");
		expect(redirect).toContain("draft");
	});

	it("returns a path starting with /ap-admin/login", () => {
		const url = new URL("http://admin.example.com/ap-admin/preview/test");
		const redirect = buildPreviewLoginRedirect(url);
		expect(redirect.startsWith("/ap-admin/login")).toBe(true);
	});
});

describe("preview route isolation from production build", () => {
	it("preview routes exist only in the admin route list", async () => {
		const { listAstropressAdminRoutes } = await import("../src/admin-routes");
		const routes = listAstropressAdminRoutes();

		const previewRoutes = routes.filter((r) => r.pattern.includes("preview"));
		expect(previewRoutes.length).toBeGreaterThan(0);
		expect(previewRoutes.every((r) => r.pattern.startsWith("/ap-admin/"))).toBe(
			true,
		);
	});

	it("createAstropressPublicSiteIntegration injects zero preview routes", async () => {
		const { createAstropressPublicSiteIntegration } = await import(
			"../src/public-site-integration"
		);
		const integration = createAstropressPublicSiteIntegration();
		const injected: string[] = [];

		const hook = integration.hooks["astro:config:setup"];
		if (typeof hook !== "function") throw new Error("Expected hook");

		hook({
			_config: {},
			injectRoute: (route: { pattern: string }) => {
				injected.push(route.pattern);
			},
			addMiddleware: () => {},
		} as never);

		expect(injected.filter((p) => p.includes("preview"))).toHaveLength(0);
		expect(injected.filter((p) => p.includes("ap-admin"))).toHaveLength(0);
	});
});

