import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

// Source-level invariants for the <ap-stale-tab-warning> web component.
// Single-target test: only reads the component source + the package.json
// subpath export entry. Mutations to other files do not invalidate this
// suite's stryker cache.

const wcPath = path.resolve(
	import.meta.dirname,
	"../web-components/ap-stale-tab-warning.ts",
);
const pkgPath = path.resolve(import.meta.dirname, "../package.json");

describe("ap-stale-tab-warning web component", () => {
	it("source file exists and exports ApStaleTabWarning class", () => {
		const source = readFileSync(wcPath, "utf8");
		expect(source).toContain("export class ApStaleTabWarning");
		expect(source).toContain("BroadcastChannel");
		expect(source).toContain("astropress-editor");
		expect(source).toContain("customElements.define");
		expect(source).toContain('"ap-stale-tab-warning"');
	});

	it("broadcasts editing message on connectedCallback with unique tab id", () => {
		const source = readFileSync(wcPath, "utf8");
		// Must post { type: "editing", slug, id } on connect
		expect(source).toContain('"editing"');
		expect(source).toContain("crypto.randomUUID()");
		// Must post { type: "left", slug, id } on disconnect
		expect(source).toContain('"left"');
		expect(source).toContain("disconnectedCallback");
	});

	it("shows stale-tab warning when another editing message arrives for the same slug", () => {
		const source = readFileSync(wcPath, "utf8");
		// Must render a role="alert" warning element
		expect(source).toContain('role", "alert"');
		expect(source).toContain("Another tab is editing this post");
	});

	it("shows stale-session warning when page open time exceeds TTL", () => {
		const source = readFileSync(wcPath, "utf8");
		expect(source).toContain("This page has been open over an hour");
		expect(source).toContain("session-ttl-ms");
	});

	it("subpath export exists in package.json", () => {
		const pkg = JSON.parse(readFileSync(pkgPath, "utf8"));
		expect(pkg.exports["./web-components/ap-stale-tab-warning"]).toBeDefined();
	});
});

tests/admin-locale.test.ts.source:
import { describe, expect, test } from "vitest";

import {
	pickAdminLocaleFromAcceptLanguage,
	resolveAdminLocale,
} from "../src/admin-locale";

describe("pickAdminLocaleFromAcceptLanguage", () => {
	test("returns null for empty input", () => {
		expect(pickAdminLocaleFromAcceptLanguage(null)).toBeNull();
		expect(pickAdminLocaleFromAcceptLanguage("")).toBeNull();
	});

	test("matches the highest q-weighted supported locale", () => {
		expect(
			pickAdminLocaleFromAcceptLanguage("fr-CA;q=0.5,de-DE;q=0.9,en;q=0.1"),
		).toBe("de");
	});

	test("strips region subtags so pt-BR matches pt", () => {
		expect(pickAdminLocaleFromAcceptLanguage("pt-BR")).toBe("pt");
	});

	test("returns null when no entry is supported", () => {
		expect(pickAdminLocaleFromAcceptLanguage("ko,zh-Hant")).toBeNull();
	});

	test("supports newly added locales", () => {
		expect(pickAdminLocaleFromAcceptLanguage("te-IN")).toBe("te");
		expect(pickAdminLocaleFromAcceptLanguage("hi")).toBe("hi");
		expect(pickAdminLocaleFromAcceptLanguage("ny-MW")).toBe("ny");
	});
});

describe("resolveAdminLocale", () => {
	function makeAstro({
		cookie,
		acceptLanguage,
	}: {
		cookie?: string;
		acceptLanguage?: string;
	}) {
		return {
			cookies: {
				get: (name: string) =>
					cookie && name === "astropress_admin_locale"
						? { value: cookie }
						: undefined,
			},
			request: {
				headers: {
					get: (name: string) =>
						name === "accept-language" ? (acceptLanguage ?? null) : null,
				},
			},
		};
	}

	test("cookie wins over Accept-Language", () => {
		expect(
			resolveAdminLocale(makeAstro({ cookie: "ja", acceptLanguage: "fr-FR" })),
		).toBe("ja");
	});

	test("Accept-Language is used when no cookie is set", () => {
		expect(resolveAdminLocale(makeAstro({ acceptLanguage: "es-MX" }))).toBe(
			"es",
		);
	});

	test("falls back to en when nothing matches", () => {
		expect(resolveAdminLocale(makeAstro({ acceptLanguage: "ko-KR" }))).toBe(
			"en",
		);
	});

	test("ignores invalid cookie values", () => {
		expect(
			resolveAdminLocale(makeAstro({ cookie: "xx", acceptLanguage: "hi-IN" })),
		).toBe("hi");
	});
});

