tests/web-components/notice.test.ts.source:
// @vitest-environment jsdom
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import "../../web-components/notice";

describe("ap-notice", () => {
	beforeEach(() => {
		document.body.innerHTML = "";
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	it("renders with role=status and aria-live=polite", () => {
		const el = document.createElement("ap-notice") as HTMLElement;
		el.textContent = "Saved!";
		document.body.appendChild(el);
		expect(el.getAttribute("role")).toBe("status");
		expect(el.getAttribute("aria-live")).toBe("polite");
	});

	it("removes itself after dismiss-after milliseconds", () => {
		const el = document.createElement("ap-notice") as HTMLElement;
		el.setAttribute("dismiss-after", "3000");
		el.textContent = "Will go away";
		document.body.appendChild(el);
		expect(document.body.contains(el)).toBe(true);
		vi.advanceTimersByTime(3001);
		expect(document.body.contains(el)).toBe(false);
	});

	it("does not auto-dismiss when dismiss-after is not set", () => {
		const el = document.createElement("ap-notice") as HTMLElement;
		el.textContent = "Stays";
		document.body.appendChild(el);
		vi.advanceTimersByTime(60000);
		expect(document.body.contains(el)).toBe(true);
	});

	it("clears the timer on disconnection", () => {
		const el = document.createElement("ap-notice") as HTMLElement;
		el.setAttribute("dismiss-after", "3000");
		document.body.appendChild(el);
		el.remove();
		// Should not throw after removal
		expect(() => vi.advanceTimersByTime(5000)).not.toThrow();
	});

	it("ignores non-numeric dismiss-after values", () => {
		const el = document.createElement("ap-notice") as HTMLElement;
		el.setAttribute("dismiss-after", "notanumber");
		document.body.appendChild(el);
		vi.advanceTimersByTime(10000);
		expect(document.body.contains(el)).toBe(true);
	});
});

tests/access-action-registry.test.ts.source:
import { afterEach, describe, expect, test } from "vitest";

import {
	_resetAccessActionRegistryForTests,
	getAccessAction,
	listAccessActions,
	registerAccessAction,
} from "../src/access";

afterEach(() => {
	_resetAccessActionRegistryForTests();
});

describe("access action registry", () => {
	test("built-in actions are registered at module load", () => {
		const all = listAccessActions();
		expect(all.length).toBeGreaterThan(20);
		expect(getAccessAction("posts:edit")?.pluginId).toBe("core");
		expect(getAccessAction("roles:manage")?.pluginId).toBe("core");
	});

	test("plugin can register a new action", () => {
		registerAccessAction({
			id: "myplugin:doThing",
			description: "Do the thing",
			pluginId: "my-plugin",
		});
		expect(getAccessAction("myplugin:doThing")?.pluginId).toBe("my-plugin");
	});

	test("re-registering same id by same plugin is allowed (idempotent setup)", () => {
		registerAccessAction({
			id: "myplugin:thing",
			description: "v1",
			pluginId: "my-plugin",
		});
		expect(() =>
			registerAccessAction({
				id: "myplugin:thing",
				description: "v2 (updated)",
				pluginId: "my-plugin",
			}),
		).not.toThrow();
		expect(getAccessAction("myplugin:thing")?.description).toBe("v2 (updated)");
	});

	test("a different plugin cannot hijack an existing action id", () => {
		registerAccessAction({
			id: "myplugin:thing",
			description: "owned by my-plugin",
			pluginId: "my-plugin",
		});
		expect(() =>
			registerAccessAction({
				id: "myplugin:thing",
				description: "stolen",
				pluginId: "other-plugin",
			}),
		).toThrow(/already registered/);
	});

	test("listAccessActions returns alphabetically sorted IDs", () => {
		const ids = listAccessActions().map((a) => a.id);
		const sorted = [...ids].sort();
		expect(ids).toEqual(sorted);
	});
});

